// ---- merged from attribution_cgroup.go ----

// cgroupAttribution maps cgroup IDs to agent execution context.
// This enables attribution of all child processes and flows within a cgroup
// to the originating agent run and tool call.
type cgroupAttributionEntry struct {
	CgroupID     uint64
	AgentRunID   string
	TaskID       string
	ToolCallID   string
	RootAgentPID uint32
	CreatedAt    time.Time
}

type cgroupAttributionStore struct {
	mu    sync.RWMutex
	items map[uint64]cgroupAttributionEntry
}

func newCgroupAttributionStore() *cgroupAttributionStore {
	return &cgroupAttributionStore{
		items: make(map[uint64]cgroupAttributionEntry),
	}
}

func (s *cgroupAttributionStore) Set(cgroupID uint64, entry cgroupAttributionEntry) {
	if s == nil || cgroupID == 0 {
		return
	}
	entry.CgroupID = cgroupID
	if entry.CreatedAt.IsZero() {
		entry.CreatedAt = time.Now().UTC()
	}
	s.mu.Lock()
	s.items[cgroupID] = entry
	s.mu.Unlock()
}

func (s *cgroupAttributionStore) Get(cgroupID uint64) (cgroupAttributionEntry, bool) {
	if s == nil || cgroupID == 0 {
		return cgroupAttributionEntry{}, false
	}
	s.mu.RLock()
	entry, ok := s.items[cgroupID]
	s.mu.RUnlock()
	return entry, ok
}

func (s *cgroupAttributionStore) EvictOlderThan(maxAge time.Duration) {
	if s == nil {
		return
	}
	cutoff := time.Now().UTC().Add(-maxAge)
	s.mu.Lock()
	for id, entry := range s.items {
		if entry.CreatedAt.Before(cutoff) {
			delete(s.items, id)
		}
	}
	s.mu.Unlock()
}

var cgroupAttribution = newCgroupAttributionStore()

// attachCgroupToAgent associates a cgroup ID with the agent context from a register payload.
func attachCgroupToAgent(cgroupID uint64, payload registerPayload) {
	if cgroupID == 0 {
		return
	}
	cgroupAttribution.Set(cgroupID, cgroupAttributionEntry{
		AgentRunID:   payload.AgentRunID,
		TaskID:       payload.TaskID,
		ToolCallID:   payload.ToolCallID,
		RootAgentPID: payload.PID,
	})
}

// enrichEventWithCgroupContext adds agent context from cgroup attribution to an event.
func enrichEventWithCgroupContext(cgroupID uint64) (agentRunID, taskID, toolCallID string) {
	entry, ok := cgroupAttribution.Get(cgroupID)
	if !ok {
		return "", "", ""
	}
	return entry.AgentRunID, entry.TaskID, entry.ToolCallID
}

// ── Per-tool baseline and drift detection ────────────────────────────

type toolBaselineSample struct {
	ToolName  string
	Comm      string
	EventType string
	Path      string
	Count     int
	LastSeen  time.Time
}

type toolBaselineStore struct {
	mu      sync.RWMutex
	samples map[string]map[string]*toolBaselineSample // toolName -> (comm+eventType)
}

func newToolBaselineStore() *toolBaselineStore {
	return &toolBaselineStore{
		samples: make(map[string]map[string]*toolBaselineSample),
	}
}

func (s *toolBaselineStore) Record(toolName, comm, eventType, path string) {
	if s == nil || toolName == "" {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	toolSamples, ok := s.samples[toolName]
	if !ok {
		toolSamples = make(map[string]*toolBaselineSample)
		s.samples[toolName] = toolSamples
	}

	key := comm + ":" + eventType
	sample, ok := toolSamples[key]
	if !ok {
		sample = &toolBaselineSample{
			ToolName:  toolName,
			Comm:      comm,
			EventType: eventType,
			Path:      path,
			Count:     1,
			LastSeen:  time.Now().UTC(),
		}
		toolSamples[key] = sample
	} else {
		sample.Count++
		sample.LastSeen = time.Now().UTC()
	}
}

// detectDrift checks if a current behavior deviates from the tool's baseline.
// Returns a drift reason if the behavior is anomalous for this tool.
func (s *toolBaselineStore) detectDrift(toolName, comm, eventType string) (string, bool) {
	if s == nil || toolName == "" {
		return "", false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()

	toolSamples, ok := s.samples[toolName]
	if !ok {
		// No baseline yet - this is a new tool, not drift
		return "", false
	}

	key := comm + ":" + eventType
	_, ok = toolSamples[key]
	if ok {
		// This behavior is in the baseline - no drift
		return "", false
	}

	// This behavior is NOT in the baseline for this tool
	// Check if we have enough samples to have a meaningful baseline
	if len(toolSamples) < 3 {
		return "", false
	}

	return fmt.Sprintf("tool %q baseline drift: unexpected behavior %s/%s",
		toolName, comm, eventType), true
}

var toolBaseline = newToolBaselineStore()

// ── Sampling and rate limiting hints ─────────────────────────────────

type collectorRateLimitHint struct {
	PID       uint32
	Comm      string
	EventType string
	RatePerS  float64
	Suggested string // "sample", "throttle", "drop"
}

type collectorRateLimitState struct {
	mu        sync.RWMutex
	lastCheck time.Time
	hints     []collectorRateLimitHint
}

var collectorRateLimits = &collectorRateLimitState{}

func (s *collectorRateLimitState) computeHints(metrics collectorMetricsSnapshot) []collectorRateLimitHint {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := time.Now().UTC()
	if now.Sub(s.lastCheck) < 5*time.Second {
		return s.hints
	}
	s.lastCheck = now

	hints := make([]collectorRateLimitHint, 0)

	// Find high-volume PIDs (>1000 events/sec equivalent)
	totalEvents := uint64(0)
	for _, count := range metrics.EventsByTypeTotal {
		totalEvents += count
	}

	for pidKey, count := range metrics.EventsByPIDTotal {
		// Simple threshold: if a single PID contributes >30% of total events
		if totalEvents > 0 && float64(count)/float64(totalEvents) > 0.30 {
			hints = append(hints, collectorRateLimitHint{
				PID:       pidKey.PID,
				Comm:      pidKey.Comm,
				RatePerS:  float64(count) / 5.0, // rough estimate
				Suggested: "throttle",
			})
		}
	}

	s.hints = hints
	return hints
}

// cleanupCgroupAttribution periodically evicts old cgroup entries
func startCgroupAttributionGC() {
	ticker := time.NewTicker(5 * time.Minute)
	go func() {
		for range ticker.C {
			cgroupAttribution.EvictOlderThan(30 * time.Minute)
		}
	}()
}

// ---- merged from audit_network.go ----

type NetworkAuditFinding struct {
	Type        string `json:"type"`
	Severity    string `json:"severity"`
	Description string `json:"description"`
}

type NetworkAuditFlags struct {
	SuspiciousPort bool `json:"suspiciousPort"`
	ReverseShell   bool `json:"reverseShell"`
	DataExfil      bool `json:"dataExfil"`
	DNSTunnel      bool `json:"dnsTunnel"`
	ClearTextProto bool `json:"clearTextProto"`
	UnusualTarget  bool `json:"unusualTarget"`
	PortScan       bool `json:"portScan"`
	FirewallManip  bool `json:"firewallManip"`
}

type NetworkAuditResult struct {
	RiskScore float64               `json:"riskScore"`
	RiskLevel string                `json:"riskLevel"`
	Findings  []NetworkAuditFinding `json:"findings"`
	Flags     NetworkAuditFlags     `json:"flags"`
}

func AuditNetworkBehavior(comm, cmdline string) NetworkAuditResult {
	result := NetworkAuditResult{Findings: []NetworkAuditFinding{}}
	lower := strings.ToLower(cmdline)
	fullCmd := strings.ToLower(comm + " " + cmdline)

	// Reverse shell patterns
	if strings.Contains(fullCmd, "nc -e") || strings.Contains(fullCmd, "nc.traditional -e") ||
		strings.Contains(fullCmd, "bash -i >& /dev/tcp") || strings.Contains(fullCmd, "bash -i > /dev/tcp") ||
		strings.Contains(fullCmd, "python -c 'import socket") || strings.Contains(fullCmd, `python -c "import socket`) ||
		strings.Contains(fullCmd, "socat exec:") || strings.Contains(fullCmd, "perl -e 'use socket") {
		result.Flags.ReverseShell = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "reverse_shell",
			Severity:    "critical",
			Description: "Reverse shell pattern detected",
		})
	}

	// Data exfiltration patterns
	if (strings.Contains(fullCmd, "curl -d @") || strings.Contains(fullCmd, "curl --data @") ||
		strings.Contains(fullCmd, "wget --post-file") || strings.Contains(fullCmd, "nc <")) &&
		(strings.Contains(lower, "/etc/passwd") || strings.Contains(lower, "/etc/shadow") ||
			strings.Contains(lower, "~/.ssh") || strings.Contains(lower, "~/.aws")) {
		result.Flags.DataExfil = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "data_exfil",
			Severity:    "critical",
			Description: "Data exfiltration pattern detected",
		})
	}

	// DNS tunnel patterns
	if strings.Contains(comm, "iodine") || strings.Contains(comm, "dnscat") ||
		(strings.Contains(comm, "dig") && strings.Contains(lower, "+tcp")) {
		result.Flags.DNSTunnel = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "dns_tunnel",
			Severity:    "high",
			Description: "DNS tunneling tool detected",
		})
	}

	// Port scanning patterns
	if (strings.Contains(comm, "nmap") && (strings.Contains(lower, "-ss") || strings.Contains(lower, "-st"))) ||
		(strings.Contains(comm, "nc") && strings.Contains(lower, "-zv")) ||
		strings.Contains(comm, "masscan") {
		result.Flags.PortScan = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "port_scan",
			Severity:    "high",
			Description: "Port scanning activity detected",
		})
	}

	// Suspicious ports (C2 common ports)
	suspiciousPorts := []string{"4444", "1337", "31337", "6666", "6667", "6668", "6669", "8888", "9999"}
	for _, port := range suspiciousPorts {
		if strings.Contains(cmdline, ":"+port) || strings.Contains(cmdline, " "+port+" ") {
			result.Flags.SuspiciousPort = true
			result.Findings = append(result.Findings, NetworkAuditFinding{
				Type:        "suspicious_port",
				Severity:    "high",
				Description: "Connection to suspicious port " + port,
			})
			break
		}
	}

	// Cleartext protocols
	if (strings.Contains(comm, "ftp") || strings.Contains(comm, "telnet")) &&
		!strings.Contains(lower, "-i") {
		result.Flags.ClearTextProto = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "cleartext",
			Severity:    "medium",
			Description: "Cleartext protocol usage detected",
		})
	}

	// Firewall manipulation
	if (strings.Contains(comm, "iptables") && (strings.Contains(lower, "-f") || strings.Contains(lower, "-x"))) ||
		(strings.Contains(comm, "ufw") && strings.Contains(lower, "disable")) ||
		(strings.Contains(comm, "firewall-cmd") && strings.Contains(lower, "--remove-service")) {
		result.Flags.FirewallManip = true
		result.Findings = append(result.Findings, NetworkAuditFinding{
			Type:        "firewall_manipulation",
			Severity:    "critical",
			Description: "Firewall manipulation detected",
		})
	}

	// Compute risk score and level
	score := 0.0
	maxSeverity := "safe"
	for _, f := range result.Findings {
		switch f.Severity {
		case "critical":
			score += 25.0
			maxSeverity = "critical"
		case "high":
			score += 15.0
			if maxSeverity != "critical" {
				maxSeverity = "high"
			}
		case "medium":
			score += 10.0
			if maxSeverity != "critical" && maxSeverity != "high" {
				maxSeverity = "medium"
			}
		case "low":
			score += 5.0
			if maxSeverity == "safe" {
				maxSeverity = "low"
			}
		}
	}
	if score > 100 {
		score = 100
	}
	result.RiskScore = score
	result.RiskLevel = strings.ToUpper(maxSeverity)

	return result
}

// ---- merged from auto_tune.go ----

// AutoTune runs a grid search over hyperparameters and returns the best configuration.
func (t *ModelTrainer) AutoTune(store *TrainingDataStore, req MLAutoTuneRequest, progressCb func(completed, total int, message string)) (*MLAutoTuneResponse, error) {
	select {
	case t.mu <- struct{}{}:
		defer func() { <-t.mu }()
	default:
		return nil, errors.New("training already in progress")
	}

	xAxis := normalizeAutoTuneAxis(req.XAxis)
	yAxis := normalizeAutoTuneAxis(req.YAxis)
	if xAxis == "" {
		xAxis = "numTrees"
	}
	if yAxis == "" {
		yAxis = "maxDepth"
	}
	if xAxis == yAxis {
		return nil, fmt.Errorf("xAxis and yAxis must be different")
	}

	gridSize := normalizeAutoTuneGridSize(req.GridSize)
	granularity := normalizeAutoTuneGranularity(req.Granularity)
	metric := normalizeAutoTuneMetric(req.Metric)
	if metric == "" {
		metric = "validationAccuracy"
	}

	effectiveCfg := applyBuiltinModelPreset(mlConfig)
	baseNumTrees := effectiveCfg.NumTrees
	if baseNumTrees <= 0 {
		baseNumTrees = 31
	}
	baseMaxDepth := effectiveCfg.MaxDepth
	if baseMaxDepth <= 0 {
		baseMaxDepth = 8
	}
	baseMinSamplesLeaf := effectiveCfg.MinSamplesLeaf
	if baseMinSamplesLeaf <= 0 {
		baseMinSamplesLeaf = 5
	}

	validationRatio := req.ValidationSplitRatio
	if validationRatio <= 0 || validationRatio >= 0.5 {
		validationRatio = effectiveCfg.ValidationSplitRatio
	}
	if validationRatio <= 0 || validationRatio >= 0.5 {
		validationRatio = 0.20
	}

	labeled := store.LabeledSamples()
	if len(labeled) < baseMinSamplesLeaf*10 {
		msg := fmt.Sprintf("Insufficient labeled samples: need >=%d, have %d", baseMinSamplesLeaf*10, len(labeled))
		return nil, errors.New(msg)
	}

	trainSet, validationSet, _, validationRaw, err := prepareAutoTuneSplit(labeled, validationRatio)
	if err != nil {
		return nil, err
	}

	xValues := autoTuneAxisValuesWithRange(xAxis, gridSize, granularity, baseNumTrees, baseMaxDepth, baseMinSamplesLeaf, req.MinX, req.MaxX)
	yValues := autoTuneAxisValuesWithRange(yAxis, gridSize, granularity, baseNumTrees, baseMaxDepth, baseMinSamplesLeaf, req.MinY, req.MaxY)
	maxRequiredLeaf := autoTuneMaxInt(baseMinSamplesLeaf, maxAxisValue(xAxis, xValues, yAxis, yValues, "minSamplesLeaf"))
	if len(labeled) < maxRequiredLeaf*10 {
		msg := fmt.Sprintf("Insufficient labeled samples for tuning: need >=%d, have %d", maxRequiredLeaf*10, len(labeled))
		return nil, errors.New(msg)
	}

	totalCombos := len(xValues) * len(yValues)
	if totalCombos <= 0 {
		return nil, errors.New("no valid parameter combinations found for tuning")
	}
	requestedModelType := mlConfig.ModelType
	if requestedModelType == "" {
		requestedModelType = ModelRandomForest
	}
	mt := effectiveCfg.ModelType
	if mt == "" {
		mt = ModelRandomForest
	}
	globalTrainer.logf("══════ 自动调参开始 ══════")
	globalTrainer.logf("模型类型: %s, 方阵: %dx%d, 轴: %s×%s", modelName(requestedModelType), gridSize, gridSize, xAxis, yAxis)
	if cuda.IsAvailable() {
		globalTrainer.logf("CUDA 加速已启用: %s", cuda.DeviceInfo())
	} else {
		globalTrainer.logf("CPU 模式（无 CUDA 设备）")
	}

	if progressCb != nil {
		startMsg := "开始评估自动调参方阵"
		if cuda.IsAvailable() {
			startMsg += fmt.Sprintf(" [CUDA: %s]", cuda.DeviceInfo())
		}
		progressCb(0, totalCombos, startMsg)
	}

	start := time.Now()
	cells := make([]MLAutoTuneCell, 0, totalCombos)
	var best *MLAutoTuneCell
	bestScore := math.Inf(-1)

	cudaLog := ""
	if cuda.IsAvailable() {
		cudaLog = fmt.Sprintf(" [CUDA: %s]", cuda.DeviceInfo())
	}

	done := 0
	for yi, yValue := range yValues {
		for xi, xValue := range xValues {
			if globalTrainer.IsCancelled() {
				globalTrainer.logf("自动调参已中止: %d/%d 格完成", done, totalCombos)
				return nil, errors.New("cancelled")
			}
			numTrees, maxDepth, minLeaf := baseNumTrees, baseMaxDepth, baseMinSamplesLeaf
			numTrees, maxDepth, minLeaf = setAutoTuneAxisValue(xAxis, xValue, numTrees, maxDepth, minLeaf)
			numTrees, maxDepth, minLeaf = setAutoTuneAxisValue(yAxis, yValue, numTrees, maxDepth, minLeaf)

			cellStart := time.Now()
			var trainAccuracy, validationAccuracy, throughput, msPerSample float64
			var evalDuration time.Duration
			var evalStart time.Time

			switch mt {
			case ModelRandomForest:
				if len(labeled) < minLeaf*10 {
					done++
					if progressCb != nil {
						progressCb(done, totalCombos, fmt.Sprintf("跳过 %d/%d (RF 样本不足)", done, totalCombos))
					}
					continue
				}
				seed := int64((yi+1)*100000 + (xi+1)*1000 + numTrees*31 + maxDepth*17 + minLeaf*13)
				forest := buildAutoTuneForest(trainSet, numTrees, maxDepth, minLeaf, seed)
				trainAccuracy = evaluateForest(forest, trainSet)
				evalStart = time.Now()
				validationAccuracy = evaluateForest(forest, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelKNN:
				k := numTrees
				if k < 1 {
					k = 5
				}
				if k > len(trainSet) {
					k = len(trainSet)
				}
				model := NewKNNModel(k, "euclidean", "uniform")
				model.NumClasses = 4
				model.Samples = make([][FeatureDim]float64, len(trainSet))
				model.Labels = make([]int32, len(trainSet))
				for i, s := range trainSet {
					model.Samples[i] = s.features
					model.Labels[i] = s.label
				}
				trainAccuracy = evalKNNModel(model, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalKNNModel(model, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelLogisticRegression:
				lr := float64(numTrees) / 1000.0
				if lr < 0.001 {
					lr = 0.01
				}
				reg := "l2"
				if maxDepth == 12 {
					reg = "l1"
				} else if maxDepth == 4 {
					reg = "none"
				}
				maxIter := minLeaf
				if maxIter < 100 {
					maxIter = 1000
				}
				trainS, trainL := extractTrainData(trainSet)
				lrModel := NewLogisticModel(lr, reg, maxIter)
				lrModel.NumClasses = 4
				lrModel.Train(trainS, trainL)
				trainAccuracy = evalLogisticModel(lrModel, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalLogisticModel(lrModel, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelNaiveBayes:
				nb := NewNaiveBayes()
				nb.Means = make([][FeatureDim]float64, 4)
				nb.Vars = make([][FeatureDim]float64, 4)
				nb.Priors = make([]float64, 4)
				counts := make([]int, 4)
				for _, s := range trainSet {
					c := s.label
					counts[c]++
					for d := 0; d < FeatureDim; d++ {
						nb.Means[c][d] += s.features[d]
					}
				}
				for c := 0; c < 4; c++ {
					nb.Priors[c] = float64(counts[c]) / float64(len(trainSet))
					if counts[c] > 0 {
						for d := 0; d < FeatureDim; d++ {
							nb.Means[c][d] /= float64(counts[c])
						}
					}
				}
				for _, s := range trainSet {
					c := s.label
					for d := 0; d < FeatureDim; d++ {
						diff := s.features[d] - nb.Means[c][d]
						nb.Vars[c][d] += diff * diff
					}
				}
				for c := 0; c < 4; c++ {
					if counts[c] > 1 {
						for d := 0; d < FeatureDim; d++ {
							nb.Vars[c][d] /= float64(counts[c] - 1)
						}
					}
				}
				trainAccuracy = evalModelSamples(nb, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalModelSamples(nb, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelExtraTrees:
				seed := int64((yi+1)*100000 + (xi+1)*1000 + numTrees*31 + maxDepth*17 + minLeaf*13)
				et := buildExtraTrees(trainSet, numTrees, maxDepth, minLeaf, seed)
				trainAccuracy = evalModelSamples(&ExtraTreesModel{Forest: et}, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalModelSamples(&ExtraTreesModel{Forest: et}, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelAdaBoost:
				trainS, trainL := extractTrainData(trainSet)
				ab := trainAdaBoostFromData(trainS, trainL, numTrees)
				trainAccuracy = evalModelSamples(ab, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalModelSamples(ab, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelEnsemble:
				tmpStore := newTrainingDataStore(len(trainSet))
				for i := range trainSet {
					tmpStore.samples[i] = TrainingSample{
						Features: trainSet[i].features,
						Label:    trainSet[i].label,
					}
				}
				tmpStore.nextWrite = len(trainSet)
				ens := buildEnsembleFromStore(tmpStore)
				if ens == nil {
					done++
					if progressCb != nil {
						progressCb(done, totalCombos, fmt.Sprintf("跳过 %d/%d (ensemble 样本不足)", done, totalCombos))
					}
					continue
				}
				trainAccuracy = evalModelSamples(ens, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalModelSamples(ens, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelNearestCentroid:
				metric := "euclidean"
				switch {
				case numTrees <= 24:
					metric = "cosine"
				case numTrees >= 36:
					metric = "manhattan"
				}
				balanced := maxDepth >= 8
				model := NewNearestCentroid(metric, balanced)
				model.Classes = 4
				model.Centroids = make([][FeatureDim]float64, model.Classes)
				model.Priors = make([]float64, model.Classes)
				counts := make([]int, model.Classes)
				for _, s := range trainSet {
					if s.label < 0 || int(s.label) >= model.Classes {
						continue
					}
					c := int(s.label)
					counts[c]++
					for d := 0; d < FeatureDim; d++ {
						model.Centroids[c][d] += s.features[d]
					}
				}
				nonEmpty := 0
				for _, count := range counts {
					if count > 0 {
						nonEmpty++
					}
				}
				for c := 0; c < model.Classes; c++ {
					if counts[c] > 0 {
						for d := 0; d < FeatureDim; d++ {
							model.Centroids[c][d] /= float64(counts[c])
						}
					}
					if balanced && nonEmpty > 0 && counts[c] > 0 {
						model.Priors[c] = 1.0 / float64(nonEmpty)
					} else if len(trainSet) > 0 {
						model.Priors[c] = float64(counts[c]) / float64(len(trainSet))
					}
				}
				trainAccuracy = evalModelSamples(model, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalModelSamples(model, validationSet)
				evalDuration = time.Since(evalStart)

			case ModelSVM, ModelPerceptron, ModelPassiveAggressive, ModelRidge:
				W := make([][FeatureDim + 1]float64, 4)
				for c := range W {
					for d := range W[c] {
						W[c][d] = (rand.Float64() - 0.5) * 0.01
					}
				}
				lr := float64(numTrees) / 1000.0
				if lr < 0.001 {
					lr = 0.01
				}
				C := float64(numTrees) / 10.0
				if C < 0.1 {
					C = 1.0
				}
				maxIter := minLeaf
				if maxIter < 100 {
					maxIter = 1000
				}
				loss := "hinge"
				if mt == ModelPerceptron {
					loss = "perceptron"
				}
				if mt == ModelPassiveAggressive {
					loss = "pa"
				}
				if mt == ModelRidge {
					ridgeFit(W, 4, labeled[:len(trainSet)], float64(numTrees)/100.0+0.1)
				} else {
					labeledSubset := make([]TrainingSample, len(trainSet))
					for i, s := range trainSet {
						labeledSubset[i] = TrainingSample{Features: s.features, Label: s.label}
					}
					trainSGD(W, 4, labeledSubset, lr, maxIter, C, loss, nil, globalTrainer)
				}
				trainAccuracy = evalLinearModel(W, 4, trainSet)
				evalStart = time.Now()
				validationAccuracy = evalLinearModel(W, 4, validationSet)
				evalDuration = time.Since(evalStart)
			}

			cellDuration := time.Since(cellStart)
			if len(validationSet) > 0 && evalDuration > 0 {
				throughput = float64(len(validationSet)) / evalDuration.Seconds()
				msPerSample = evalDuration.Seconds() * 1000 / float64(len(validationSet))
			}

			score := validationAccuracy
			if metric == "inferenceThroughput" {
				score = throughput
			}

			cell := MLAutoTuneCell{
				XIndex:               xi,
				YIndex:               yi,
				XValue:               xValue,
				YValue:               yValue,
				NumTrees:             numTrees,
				MaxDepth:             maxDepth,
				MinSamplesLeaf:       minLeaf,
				TrainAccuracy:        trainAccuracy,
				ValidationAccuracy:   validationAccuracy,
				InferenceThroughput:  throughput,
				InferenceMsPerSample: msPerSample,
				TrainDuration:        cellDuration.Seconds(),
				EvalDuration:         evalDuration.Seconds(),
				Score:                score,
			}
			cells = append(cells, cell)
			if score > bestScore {
				copyCell := cell
				best = &copyCell
				bestScore = score
			}

			done++
			if done%3 == 0 || done == totalCombos {
				globalTrainer.logf("%s 调优: %d/%d 格 (准确率 %.1f%%)", modelName(requestedModelType), done, totalCombos, validationAccuracy*100)
			}
			if progressCb != nil {
				progressCb(done, totalCombos, fmt.Sprintf("%s 评估 %d/%d%s", modelName(requestedModelType), done, totalCombos, cudaLog))
			}
		}
	}

	if len(cells) == 0 {
		return nil, errors.New("no valid parameter combinations found for tuning")
	}

	if progressCb != nil {
		progressCb(totalCombos, totalCombos, "自动调参完成")
	}

	return &MLAutoTuneResponse{
		XAxis:           xAxis,
		YAxis:           yAxis,
		Metric:          metric,
		Granularity:     granularity,
		GridSize:        gridSize,
		XValues:         xValues,
		YValues:         yValues,
		SampleCount:     len(labeled),
		ValidationCount: len(validationRaw),
		TotalDuration:   time.Since(start).Seconds(),
		Cells:           cells,
		Best:            best,
	}, nil
}

func prepareAutoTuneSplit(labeled []TrainingSample, validationRatio float64) ([]trainSample, []trainSample, []TrainingSample, []TrainingSample, error) {
	if len(labeled) < 2 {
		return nil, nil, nil, nil, errors.New("need at least 2 labeled samples for tuning")
	}
	if validationRatio <= 0 || validationRatio >= 0.5 {
		validationRatio = 0.20
	}

	samples := make([]trainSample, len(labeled))
	for i, s := range labeled {
		samples[i] = trainSample{features: s.Features, label: s.Label}
	}

	shuffledRaw := append([]TrainingSample(nil), labeled...)
	rand.Shuffle(len(samples), func(i, j int) {
		samples[i], samples[j] = samples[j], samples[i]
		shuffledRaw[i], shuffledRaw[j] = shuffledRaw[j], shuffledRaw[i]
	})

	validationCount := int(math.Round(float64(len(samples)) * validationRatio))
	if validationCount < 1 {
		validationCount = 1
	}
	if validationCount >= len(samples) {
		validationCount = len(samples) - 1
	}

	trainCount := len(samples) - validationCount
	trainSet := append([]trainSample(nil), samples[:trainCount]...)
	validationSet := append([]trainSample(nil), samples[trainCount:]...)
	trainRaw := append([]TrainingSample(nil), shuffledRaw[:trainCount]...)
	validationRaw := append([]TrainingSample(nil), shuffledRaw[trainCount:]...)
	return trainSet, validationSet, trainRaw, validationRaw, nil
}

func buildAutoTuneForest(trainSet []trainSample, numTrees, maxDepth, minSamplesLeaf int, seed int64) *DecisionForest {
	if numTrees < 1 {
		numTrees = 1
	}
	if maxDepth < 1 {
		maxDepth = 1
	}
	if minSamplesLeaf < 1 {
		minSamplesLeaf = 1
	}

	rng := rand.New(rand.NewSource(seed))
	forest := NewDecisionForest(numTrees, maxDepth, 4)
	featureSampleCount := int(math.Sqrt(float64(FeatureDim)))
	if featureSampleCount < 1 {
		featureSampleCount = 1
	}

	for ti := 0; ti < numTrees; ti++ {
		bootstrap := make([]trainSample, len(trainSet))
		for i := range bootstrap {
			bootstrap[i] = trainSet[rng.Intn(len(trainSet))]
		}
		nodes := buildAutoTuneTree(bootstrap, 0, maxDepth, minSamplesLeaf, featureSampleCount, rng)
		forest.Trees[ti] = DecisionTree{Nodes: nodes}
	}

	forest.IsTrained = true
	return forest
}

func buildAutoTuneTree(samples []trainSample, depth, maxDepth, minSamplesLeaf, featureSampleCount int, rng *rand.Rand) []DecisionNode {
	if depth >= maxDepth || len(samples) < minSamplesLeaf*2 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	allSame := true
	firstLabel := samples[0].label
	for _, s := range samples[1:] {
		if s.label != firstLabel {
			allSame = false
			break
		}
	}
	if allSame {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: float32(firstLabel)}}
	}

	best := findAutoTuneBestSplit(samples, featureSampleCount, rng)
	if best.giniGain <= 0 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	var leftSamples, rightSamples []trainSample
	for _, s := range samples {
		if s.features[best.featureIdx] < best.threshold {
			leftSamples = append(leftSamples, s)
		} else {
			rightSamples = append(rightSamples, s)
		}
	}
	if len(leftSamples) == 0 || len(rightSamples) == 0 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	leftNodes := buildAutoTuneTree(leftSamples, depth+1, maxDepth, minSamplesLeaf, featureSampleCount, rng)
	rightNodes := buildAutoTuneTree(rightSamples, depth+1, maxDepth, minSamplesLeaf, featureSampleCount, rng)

	leftOffset := 1
	rightOffset := 1 + len(leftNodes)

	root := DecisionNode{
		FeatureIndex: uint8(best.featureIdx),
		Threshold:    float32(best.threshold),
		LeftChild:    int16(leftOffset),
		RightChild:   int16(rightOffset),
		LeafValue:    0,
	}
	nodes := []DecisionNode{root}

	for i := range leftNodes {
		n := &leftNodes[i]
		if !n.IsLeaf() {
			n.LeftChild += int16(leftOffset)
			n.RightChild += int16(leftOffset)
		}
	}
	nodes = append(nodes, leftNodes...)

	for i := range rightNodes {
		n := &rightNodes[i]
		if !n.IsLeaf() {
			n.LeftChild += int16(rightOffset)
			n.RightChild += int16(rightOffset)
		}
	}
	nodes = append(nodes, rightNodes...)
	return nodes
}

func findAutoTuneBestSplit(samples []trainSample, featureSampleCount int, rng *rand.Rand) splitPoint {
	best := splitPoint{giniGain: -1}
	parentGini := giniImpurity(samples)

	features := make([]int, FeatureDim)
	for i := range features {
		features[i] = i
	}
	rng.Shuffle(len(features), func(i, j int) { features[i], features[j] = features[j], features[i] })
	if featureSampleCount > len(features) {
		featureSampleCount = len(features)
	}
	selectedFeatures := features[:featureSampleCount]

	for _, fi := range selectedFeatures {
		sorted := append([]trainSample(nil), samples...)
		sort.Slice(sorted, func(i, j int) bool {
			return sorted[i].features[fi] < sorted[j].features[fi]
		})

		for i := 1; i < len(sorted); i++ {
			if sorted[i].features[fi] == sorted[i-1].features[fi] {
				continue
			}
			threshold := (sorted[i].features[fi] + sorted[i-1].features[fi]) / 2.0
			leftSamples := sorted[:i]
			rightSamples := sorted[i:]
			if len(leftSamples) < 1 || len(rightSamples) < 1 {
				continue
			}

			leftWeight := float64(len(leftSamples)) / float64(len(sorted))
			gain := parentGini - leftWeight*giniImpurity(leftSamples) - (1-leftWeight)*giniImpurity(rightSamples)
			if gain > best.giniGain {
				best = splitPoint{
					featureIdx: fi,
					threshold:  threshold,
					giniGain:   gain,
				}
			}
		}
	}

	return best
}

// ---- merged from autotunehandlers.go ----

func handleMLTunePost(c *gin.Context) {
	if !mlEnabled {
		c.JSON(400, gin.H{"error": "ML engine is not enabled on this node"})
		return
	}
	if globalTrainingStore == nil {
		c.JSON(400, gin.H{"error": "ML training store not initialized"})
		return
	}

	var req MLAutoTuneRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(400, gin.H{"error": "invalid request"})
		return
	}

	if globalAutoTuneState.snapshot().Running {
		c.JSON(409, gin.H{"error": "auto tuning already in progress"})
		return
	}
	if globalTrainer.isRunning {
		c.JSON(409, gin.H{"error": "training already in progress"})
		return
	}

	jobID := fmt.Sprintf("tune-%d", time.Now().UnixNano())
	if !globalAutoTuneState.tryBegin(jobID, 0, "自动调参任务已接收") {
		c.JSON(409, gin.H{"error": "auto tuning already in progress"})
		return
	}

	go func(jobID string, req MLAutoTuneRequest) {
		defer func() {
			if r := recover(); r != nil {
				log.Printf("[ML] Auto-tune panic: %v", r)
				globalAutoTuneState.setError(jobID, fmt.Sprintf("panic: %v", r))
			}
		}()
		log.Printf("[ML] Auto-tune started: jobID=%s, model=%s, grid=%dx%d, x=%s, y=%s",
			jobID, mlConfig.ModelType, req.GridSize, req.GridSize, req.XAxis, req.YAxis)
		resp, err := globalTrainer.AutoTune(globalTrainingStore, req, func(completed, total int, message string) {
			if completed%5 == 0 || completed == total {
				log.Printf("[ML] Auto-tune progress: %d/%d — %s", completed, total, message)
			}
			globalAutoTuneState.update(jobID, completed, total, message)
		})
		if err != nil {
			log.Printf("[ML] Auto-tune error: %v", err)
		} else {
			log.Printf("[ML] Auto-tune done: %d cells, best score=%.4f", len(resp.Cells), autoTuneBestScore(resp))
		}
		globalAutoTuneState.finish(jobID, resp, err)
	}(jobID, req)

	c.JSON(202, gin.H{
		"jobId":   jobID,
		"started": true,
		"message": "自动调参已开始",
	})
}

func handleMLTuneModelsPost(c *gin.Context) {
	if !mlEnabled {
		c.JSON(400, gin.H{"error": "ML engine is not enabled on this node"})
		return
	}
	if globalTrainingStore == nil {
		c.JSON(400, gin.H{"error": "ML training store not initialized"})
		return
	}

	var req MLModelTuneRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(400, gin.H{"error": "invalid request"})
		return
	}

	if globalAutoTuneState.snapshot().Running {
		c.JSON(409, gin.H{"error": "auto tuning already in progress"})
		return
	}
	if globalTrainer.isRunning {
		c.JSON(409, gin.H{"error": "training already in progress"})
		return
	}

	modelTypes := normalizeModelTuneTypes(req.ModelTypes)
	if len(modelTypes) == 0 {
		c.JSON(400, gin.H{"error": "no valid model types selected"})
		return
	}

	jobID := fmt.Sprintf("tune-models-%d", time.Now().UnixNano())
	if !globalAutoTuneState.tryBeginMode(jobID, "models", len(modelTypes), "模型调优任务已接收") {
		c.JSON(409, gin.H{"error": "auto tuning already in progress"})
		return
	}

	go func(jobID string, req MLModelTuneRequest, modelTypes []ModelType) {
		defer func() {
			if r := recover(); r != nil {
				log.Printf("[ML] Model auto-tune panic: %v", r)
				globalAutoTuneState.setError(jobID, fmt.Sprintf("panic: %v", r))
			}
		}()
		resp, err := runModelAutoTune(globalTrainingStore, req, modelTypes, func(completed, total int, message string) {
			globalAutoTuneState.update(jobID, completed, total, message)
		})
		if err != nil {
			log.Printf("[ML] Model auto-tune error: %v", err)
		} else {
			best := ""
			if resp.Best != nil {
				best = resp.Best.ModelType
			}
			log.Printf("[ML] Model auto-tune done: %d candidates, best=%s", len(resp.Candidates), best)
		}
		globalAutoTuneState.finishModelTune(jobID, resp, err)
	}(jobID, req, modelTypes)

	c.JSON(202, gin.H{
		"jobId":   jobID,
		"started": true,
		"mode":    "models",
		"message": "模型调优已开始",
	})
}

func normalizeModelTuneTypes(raw []string) []ModelType {
	seen := make(map[ModelType]bool)
	out := make([]ModelType, 0, len(raw))
	add := func(t ModelType) {
		if t == "" || seen[t] {
			return
		}
		if _, ok := modelRegistry[t]; !ok {
			return
		}
		seen[t] = true
		out = append(out, t)
	}
	for _, value := range raw {
		add(ModelType(strings.TrimSpace(value)))
	}
	if len(out) == 0 {
		for _, item := range BuiltinModelCatalog() {
			if item.Recommended {
				add(ModelType(item.Value))
			}
		}
	}
	if len(out) == 0 {
		add(ModelRandomForest)
	}
	return out
}

func modelTuneCatalogInfo(t ModelType) (label, base string, recommended bool) {
	for _, item := range BuiltinModelCatalog() {
		if item.Value == string(t) {
			return item.Label, item.Base, item.Recommended
		}
	}
	return modelName(t), string(baseModelType(t)), false
}

// ---- merged from autotunehelpers.go ----

func normalizeAutoTuneAxis(axis string) string {
	switch strings.ToLower(strings.TrimSpace(axis)) {
	case "numtrees", "trees", "num_trees", "k", "learningrate", "learning_rate", "alpha", "nestimators", "n_estimators":
		return "numTrees"
	case "maxdepth", "depth", "max_depth", "distance", "regularization":
		return "maxDepth"
	case "minsamplesleaf", "min_samples_leaf", "leaf", "weight", "weights", "maxiterations", "max_iterations", "iterations":
		return "minSamplesLeaf"
	default:
		return ""
	}
}

func normalizeAutoTuneMetric(metric string) string {
	switch strings.ToLower(strings.TrimSpace(metric)) {
	case "", "validationaccuracy", "accuracy", "backtestaccuracy", "backtest", "validation":
		return "validationAccuracy"
	case "inferencethroughput", "throughput", "speed", "inferencespeed":
		return "inferenceThroughput"
	default:
		return ""
	}
}

func normalizeAutoTuneGridSize(size int) int {
	if size < 3 {
		size = 3
	}
	if size > 11 {
		size = 11
	}
	if size%2 == 0 {
		size++
		if size > 11 {
			size -= 2
		}
	}
	if size < 3 {
		size = 3
	}
	return size
}

func normalizeAutoTuneGranularity(granularity float64) float64 {
	switch {
	case granularity >= 3:
		return 4
	case granularity >= 1.5:
		return 2
	default:
		return 1
	}
}

func autoTuneAxisValues(axis string, gridSize int, granularity float64, numTrees, maxDepth, minSamplesLeaf int) []int {
	center := axisCenter(axis, numTrees, maxDepth, minSamplesLeaf)
	minValue, maxValue := autoTuneAxisRange(axis, center, gridSize, granularity)
	return linspaceInt(minValue, maxValue, gridSize)
}

func autoTuneAxisValuesWithRange(axis string, gridSize int, granularity float64, numTrees, maxDepth, minSamplesLeaf int, minOverride, maxOverride *int) []int {
	if minOverride != nil && maxOverride != nil && *minOverride > 0 && *maxOverride >= *minOverride {
		return linspaceInt(*minOverride, *maxOverride, gridSize)
	}
	center := axisCenter(axis, numTrees, maxDepth, minSamplesLeaf)
	minValue, maxValue := autoTuneAxisRange(axis, center, gridSize, granularity)
	return linspaceInt(minValue, maxValue, gridSize)
}

func axisCenter(axis string, numTrees, maxDepth, minSamplesLeaf int) int {
	switch axis {
	case "maxDepth":
		return maxDepth
	case "minSamplesLeaf":
		return minSamplesLeaf
	default:
		return numTrees
	}
}

func autoTuneAxisRange(axis string, center, gridSize int, granularity float64) (int, int) {
	minBound, maxBound := autoTuneAxisBounds(axis)
	step := autoTuneAxisStep(axis, granularity)
	radius := gridSize / 2

	minValue := center - step*radius
	maxValue := center + step*radius

	if minValue < minBound {
		maxValue += minBound - minValue
		minValue = minBound
	}
	if maxValue > maxBound {
		minValue -= maxValue - maxBound
		maxValue = maxBound
	}

	minValue = autoTuneClampInt(minValue, minBound, maxBound)
	maxValue = autoTuneClampInt(maxValue, minBound, maxBound)
	if maxValue < minValue {
		maxValue = minValue
	}
	return minValue, maxValue
}

func autoTuneAxisStep(axis string, granularity float64) int {
	if granularity <= 0 {
		granularity = 1
	}
	base := 1
	if axis == "numTrees" {
		base = 5
	}
	step := int(math.Round(float64(base) / granularity))
	if step < 1 {
		step = 1
	}
	return step
}

func autoTuneAxisBounds(axis string) (int, int) {
	switch axis {
	case "maxDepth":
		return 3, 20
	case "minSamplesLeaf":
		return 1, 50
	default:
		return 5, 200
	}
}

func setAutoTuneAxisValue(axis string, value int, numTrees, maxDepth, minSamplesLeaf int) (int, int, int) {
	switch axis {
	case "numTrees":
		return value, maxDepth, minSamplesLeaf
	case "maxDepth":
		return numTrees, value, minSamplesLeaf
	case "minSamplesLeaf":
		return numTrees, maxDepth, value
	default:
		return numTrees, maxDepth, minSamplesLeaf
	}
}

func maxAxisValue(axisA string, valuesA []int, axisB string, valuesB []int, target string) int {
	maxValue := 0
	if axisA == target {
		for _, v := range valuesA {
			if v > maxValue {
				maxValue = v
			}
		}
	}
	if axisB == target {
		for _, v := range valuesB {
			if v > maxValue {
				maxValue = v
			}
		}
	}
	return maxValue
}

func linspaceInt(minValue, maxValue, count int) []int {
	if count <= 1 {
		return []int{minValue}
	}
	if maxValue < minValue {
		minValue, maxValue = maxValue, minValue
	}
	if minValue == maxValue {
		values := make([]int, count)
		for i := range values {
			values[i] = minValue
		}
		return values
	}

	values := make([]int, count)
	step := float64(maxValue-minValue) / float64(count-1)
	for i := 0; i < count; i++ {
		values[i] = int(math.Round(float64(minValue) + step*float64(i)))
	}
	for i := 1; i < len(values); i++ {
		if values[i] < values[i-1] {
			values[i] = values[i-1]
		}
	}
	return values
}

func autoTuneClampInt(v, minValue, maxValue int) int {
	if v < minValue {
		return minValue
	}
	if v > maxValue {
		return maxValue
	}
	return v
}

func extractTrainData(samples []trainSample) ([][FeatureDim]float64, []int32) {
	X := make([][FeatureDim]float64, len(samples))
	Y := make([]int32, len(samples))
	for i, s := range samples {
		X[i] = s.features
		Y[i] = s.label
	}
	return X, Y
}

func trainAdaBoostFromData(X [][FeatureDim]float64, Y []int32, nEst int) *AdaBoostModel {
	n := len(X)
	if nEst < 10 {
		nEst = 50
	}
	m := NewAdaBoost(nEst)
	weights := make([]float64, n)
	for i := range weights {
		weights[i] = 1.0 / float64(n)
	}
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	for e := 0; e < nEst; e++ {
		cum := make([]float64, n)
		cum[0] = weights[0]
		for i := 1; i < n; i++ {
			cum[i] = cum[i-1] + weights[i]
		}
		totalW := cum[n-1]
		bestStump := adaboostStump{Feature: -1}
		bestErr := 1e9
		for tries := 0; tries < 30; tries++ {
			fi := rng.Intn(FeatureDim)
			thresh := X[rng.Intn(n)][fi]
			var lErr, rErr, lW, rW float64
			for i := 0; i < n; i++ {
				cl := 0
				if Y[i] == 1 {
					cl = 1
				}
				if X[i][fi] < thresh {
					if cl != 1 {
						lErr += weights[i]
					}
					lW += weights[i]
				} else {
					if cl != 0 {
						rErr += weights[i]
					}
					rW += weights[i]
				}
			}
			err := (lErr + rErr) / totalW
			if err < bestErr {
				bestErr = err
				bestStump = adaboostStump{Feature: fi, Threshold: thresh, LeftVote: 1, RightVote: 0}
				if lErr/lW > rErr/rW {
					bestStump.LeftVote = 0
					bestStump.RightVote = 1
				}
			}
		}
		if bestStump.Feature < 0 {
			continue
		}
		err := math.Max(bestErr, 1e-10)
		alpha := 0.5 * math.Log((1-err)/err)
		if alpha <= 0 {
			continue
		}
		for i := 0; i < n; i++ {
			pred := 0
			if X[i][bestStump.Feature] < bestStump.Threshold {
				pred = int(bestStump.LeftVote)
			} else {
				pred = int(bestStump.RightVote)
			}
			cl := int(Y[i])
			if pred != cl {
				weights[i] *= math.Exp(alpha)
			}
		}
		m.Stumps = append(m.Stumps, bestStump)
		m.Alphas = append(m.Alphas, alpha)
	}
	return m
}

func autoTuneMaxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// evalKNNModel evaluates a KNN model on a set of samples.
func evalKNNModel(model *KNNModel, samples []trainSample) float64 {
	if len(samples) == 0 {
		return 0
	}
	correct := 0
	for _, s := range samples {
		pred := model.Predict(s.features)
		if pred.Action == s.label {
			correct++
		}
	}
	return float64(correct) / float64(len(samples))
}

// evalLogisticModel evaluates a logistic regression model on a set of samples.
func evalLogisticModel(model *LogisticModel, samples []trainSample) float64 {
	if len(samples) == 0 {
		return 0
	}
	correct := 0
	for _, s := range samples {
		pred := model.Predict(s.features)
		if pred.Action == s.label {
			correct++
		}
	}
	return float64(correct) / float64(len(samples))
}

// ---- merged from autotunemodel.go ----

func runModelAutoTune(store *TrainingDataStore, req MLModelTuneRequest, modelTypes []ModelType, progressCb func(completed, total int, message string)) (*MLModelTuneResponse, error) {
	labeled := store.LabeledSamples()
	if len(labeled) < 2 {
		return nil, errors.New("need at least 2 labeled samples for model tuning")
	}
	metric := normalizeAutoTuneMetric(req.Metric)
	if metric == "" {
		metric = "validationAccuracy"
	}
	validationRatio := req.ValidationSplitRatio
	if validationRatio <= 0 || validationRatio >= 0.5 {
		validationRatio = currentMLConfig().ValidationSplitRatio
	}
	if validationRatio <= 0 || validationRatio >= 0.5 {
		validationRatio = 0.20
	}

	start := time.Now()
	candidates := make([]MLModelTuneCandidate, 0, len(modelTypes))
	var best *MLModelTuneCandidate
	var bestModel Model
	bestScore := math.Inf(-1)
	benchmarkSamples := selectBenchmarkSamples(labeled, 64)
	baseCfg := currentMLConfig()

	if progressCb != nil {
		progressCb(0, len(modelTypes), "开始跨模型自动调优")
	}

	for i, modelType := range modelTypes {
		if globalTrainer.IsCancelled() {
			return nil, errors.New("cancelled")
		}
		label, base, recommended := modelTuneCatalogInfo(modelType)
		cfg := baseCfg
		cfg.ModelType = modelType
		cfg.ValidationSplitRatio = validationRatio
		effectiveCfg := applyBuiltinModelPreset(cfg)
		candidate := MLModelTuneCandidate{
			ModelType:   string(modelType),
			Label:       label,
			Base:        base,
			Recommended: recommended,
			HyperParams: map[string]int{
				"numTrees":       effectiveCfg.NumTrees,
				"maxDepth":       effectiveCfg.MaxDepth,
				"minSamplesLeaf": effectiveCfg.MinSamplesLeaf,
			},
			SampleCount: len(labeled),
		}
		if progressCb != nil {
			progressCb(i, len(modelTypes), fmt.Sprintf("训练 %s", label))
		}

		trainStart := time.Now()
		model, result := globalTrainer.TrainWithConfig(store, cfg)
		candidate.TrainDuration = time.Since(trainStart).Seconds()
		if result.Error != "" {
			candidate.Error = result.Error
			candidates = append(candidates, candidate)
			if progressCb != nil {
				progressCb(i+1, len(modelTypes), fmt.Sprintf("跳过 %s: %s", label, result.Error))
			}
			continue
		}

		candidate.TrainAccuracy = result.TrainAccuracy
		candidate.ValidationAccuracy = result.ValidationAccuracy
		candidate.ValidationCount = result.ValidationSamples
		if candidate.ValidationCount == 0 {
			candidate.ValidationCount = len(globalTrainer.LastValidationSamples())
		}

		if req.TuneParams {
			paramReq := MLAutoTuneRequest{
				XAxis:                req.XAxis,
				YAxis:                req.YAxis,
				GridSize:             req.GridSize,
				Granularity:          req.Granularity,
				Metric:               metric,
				ValidationSplitRatio: validationRatio,
				MinX:                 req.MinX,
				MaxX:                 req.MaxX,
				MinY:                 req.MinY,
				MaxY:                 req.MaxY,
			}
			origConfig, origType := mlConfig, currentModelType
			mlConfig = cfg
			currentModelType = modelType
			paramResp, err := globalTrainer.AutoTune(store, paramReq, nil)
			mlConfig, currentModelType = origConfig, origType
			if err == nil && paramResp != nil && paramResp.Best != nil {
				candidate.ParamTune = paramResp
				cfg.NumTrees = paramResp.Best.NumTrees
				cfg.MaxDepth = paramResp.Best.MaxDepth
				cfg.MinSamplesLeaf = paramResp.Best.MinSamplesLeaf
				candidate.HyperParams["numTrees"] = cfg.NumTrees
				candidate.HyperParams["maxDepth"] = cfg.MaxDepth
				candidate.HyperParams["minSamplesLeaf"] = cfg.MinSamplesLeaf
				trainStart = time.Now()
				model, result = globalTrainer.TrainWithConfig(store, cfg)
				candidate.TrainDuration += time.Since(trainStart).Seconds()
				if result.Error == "" {
					candidate.TrainAccuracy = result.TrainAccuracy
					candidate.ValidationAccuracy = result.ValidationAccuracy
					candidate.ValidationCount = result.ValidationSamples
				} else {
					candidate.Error = result.Error
				}
			}
		}

		evalDuration, throughput, latencyMs, _ := benchmarkModelInference(model, benchmarkSamples)
		candidate.EvalDuration = evalDuration
		candidate.InferenceThroughput = throughput
		candidate.InferenceMsPerSample = latencyMs
		candidate.Score = candidate.ValidationAccuracy
		if metric == "inferenceThroughput" {
			candidate.Score = candidate.InferenceThroughput
		}
		candidates = append(candidates, candidate)
		if candidate.Error == "" && candidate.Score > bestScore {
			copyCandidate := candidate
			best = &copyCandidate
			bestModel = model
			bestScore = candidate.Score
		}
		globalTrainer.logf("模型调优: %s 验证准确率 %.1f%% 推理 %.0f/s", label, candidate.ValidationAccuracy*100, candidate.InferenceThroughput)
		if progressCb != nil {
			progressCb(i+1, len(modelTypes), fmt.Sprintf("完成 %s (%d/%d)", label, i+1, len(modelTypes)))
		}
	}

	if best == nil {
		return &MLModelTuneResponse{Metric: metric, SampleCount: len(labeled), TotalDuration: time.Since(start).Seconds(), Candidates: candidates}, errors.New("no model candidate trained successfully")
	}
	if req.ApplyBest {
		if err := applyModelTuneBest(*best, bestModel, validationRatio); err != nil {
			return nil, err
		}
		best.Applied = true
		for i := range candidates {
			if candidates[i].ModelType == best.ModelType {
				candidates[i].Applied = true
			}
		}
	}

	return &MLModelTuneResponse{
		Metric:          metric,
		SampleCount:     len(labeled),
		ValidationCount: best.ValidationCount,
		TotalDuration:   time.Since(start).Seconds(),
		Candidates:      candidates,
		Best:            best,
	}, nil
}

func applyModelTuneBest(best MLModelTuneCandidate, model Model, validationRatio float64) error {
	if model == nil {
		return errors.New("best model is not available")
	}
	settings := runtimeSettingsStore.Snapshot()
	settings.MLConfig.ModelType = ModelType(best.ModelType)
	settings.MLConfig.ValidationSplitRatio = validationRatio
	if v, ok := best.HyperParams["numTrees"]; ok && v > 0 {
		settings.MLConfig.NumTrees = v
	}
	if v, ok := best.HyperParams["maxDepth"]; ok && v > 0 {
		settings.MLConfig.MaxDepth = v
	}
	if v, ok := best.HyperParams["minSamplesLeaf"]; ok && v > 0 {
		settings.MLConfig.MinSamplesLeaf = v
	}
	if _, err := runtimeSettingsStore.Replace(settings); err != nil {
		return err
	}
	currentModelType = settings.MLConfig.ModelType
	mlEngine = model
	mlModelLoaded = true
	modelPath := settings.MLConfig.ModelPath
	if modelPath == "" {
		modelPath = defaultMLModelPath()
	}
	if err := model.Serialize(modelPath); err != nil {
		return fmt.Errorf("model selected but failed to save: %w", err)
	}
	return nil
}

