// MLAutoTuneState is the serialisable progress snapshot for auto-tune jobs.
type MLAutoTuneState struct {
	JobID       string               `json:"jobId"`
	Mode        string               `json:"mode,omitempty"`
	Running     bool                 `json:"running"`
	Progress    float64              `json:"progress"`
	Completed   int                  `json:"completed"`
	Total       int                  `json:"total"`
	Message     string               `json:"message,omitempty"`
	Error       string               `json:"error,omitempty"`
	StartedAt   string               `json:"startedAt,omitempty"`
	FinishedAt  string               `json:"finishedAt,omitempty"`
	Result      *MLAutoTuneResponse  `json:"result,omitempty"`
	ModelResult *MLModelTuneResponse `json:"modelResult,omitempty"`
}

// autoTuneRuntime holds the mutable state for the current auto-tune job.
type autoTuneRuntime struct {
	mu          sync.RWMutex
	state       MLAutoTuneState
	result      *MLAutoTuneResponse
	modelResult *MLModelTuneResponse
}

var globalAutoTuneState = &autoTuneRuntime{}

func (s *autoTuneRuntime) begin(jobID string, total int, message string) {
	s.beginMode(jobID, "params", total, message)
}

func (s *autoTuneRuntime) beginMode(jobID, mode string, total int, message string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.state = MLAutoTuneState{
		JobID:     jobID,
		Mode:      mode,
		Running:   true,
		Progress:  0,
		Completed: 0,
		Total:     total,
		Message:   message,
		StartedAt: time.Now().Format(time.RFC3339),
	}
	s.result = nil
	s.modelResult = nil
}

func (s *autoTuneRuntime) tryBegin(jobID string, total int, message string) bool {
	return s.tryBeginMode(jobID, "params", total, message)
}

func (s *autoTuneRuntime) tryBeginMode(jobID, mode string, total int, message string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.state.Running {
		return false
	}
	s.state = MLAutoTuneState{
		JobID:     jobID,
		Mode:      mode,
		Running:   true,
		Progress:  0,
		Completed: 0,
		Total:     total,
		Message:   message,
		StartedAt: time.Now().Format(time.RFC3339),
	}
	s.result = nil
	s.modelResult = nil
	return true
}

func (s *autoTuneRuntime) update(jobID string, completed, total int, message string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if jobID != "" && s.state.JobID != "" && s.state.JobID != jobID {
		return
	}
	s.state.JobID = jobID
	s.state.Running = true
	s.state.Completed = completed
	s.state.Total = total
	if total > 0 {
		s.state.Progress = mathMax0Min1(float64(completed) / float64(total))
	} else {
		s.state.Progress = 0
	}
	s.state.Message = message
	s.state.Error = ""
}

func (s *autoTuneRuntime) setError(jobID string, errMsg string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.state.Running = false
	s.state.Error = errMsg
	if s.state.Mode == "models" {
		s.state.Message = "模型调优失败"
	} else {
		s.state.Message = "调优失败"
	}
}

func autoTuneBestScore(resp *MLAutoTuneResponse) float64 {
	if resp == nil || resp.Best == nil {
		return 0
	}
	return resp.Best.Score
}

func (s *autoTuneRuntime) finish(jobID string, result *MLAutoTuneResponse, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if jobID != "" && s.state.JobID != "" && s.state.JobID != jobID {
		return
	}
	s.state.Running = false
	s.state.FinishedAt = time.Now().Format(time.RFC3339)
	if err != nil {
		s.state.Error = err.Error()
		s.state.Message = "自动调参失败"
		s.result = nil
		s.state.Result = nil
		return
	}
	s.state.Mode = "params"
	s.state.Progress = 1
	if result != nil {
		s.result = result
		s.state.Result = result
	}
	s.state.Error = ""
	if s.state.Message == "" {
		s.state.Message = "自动调参完成"
	}
}

func (s *autoTuneRuntime) finishModelTune(jobID string, result *MLModelTuneResponse, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if jobID != "" && s.state.JobID != "" && s.state.JobID != jobID {
		return
	}
	s.state.Mode = "models"
	s.state.Running = false
	s.state.FinishedAt = time.Now().Format(time.RFC3339)
	if err != nil {
		s.state.Error = err.Error()
		s.state.Message = "模型调优失败"
		s.modelResult = nil
		s.state.ModelResult = nil
		return
	}
	s.state.Progress = 1
	if result != nil {
		s.modelResult = result
		s.state.ModelResult = result
	}
	s.state.Error = ""
	if s.state.Message == "" {
		s.state.Message = "模型调优完成"
	}
}

func (s *autoTuneRuntime) snapshot() MLAutoTuneState {
	s.mu.RLock()
	defer s.mu.RUnlock()
	state := s.state
	if s.result != nil {
		state.Result = s.result
	}
	if s.modelResult != nil {
		state.ModelResult = s.modelResult
	}
	return state
}

// mathMax0Min1 clamps v to [0, 1].
func mathMax0Min1(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 1 {
		return 1
	}
	return v
}

// ---- merged from capturecontrollertls.go ----

type TLSCaptureController struct {
	mu                 sync.Mutex
	manager            *TLSProbeManager
	store              *TLSCaptureStore
	rules              *TLSCaptureRuleStore
	broadcaster        *tlsCaptureBroadcaster
	readStarted        bool
	goDiscoveryStarted bool
	lastError          string
}

func NewTLSCaptureController(store *TLSCaptureStore, rules *TLSCaptureRuleStore, broadcaster *tlsCaptureBroadcaster) *TLSCaptureController {
	if store == nil {
		store = NewTLSCaptureStore(2000)
	}
	if rules == nil {
		rules = NewTLSCaptureRuleStore()
	}
	if broadcaster == nil {
		broadcaster = newTLSCaptureBroadcaster()
	}
	return &TLSCaptureController{store: store, rules: rules, broadcaster: broadcaster}
}

func (c *TLSCaptureController) Manager() *TLSProbeManager {
	if c == nil {
		return nil
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.manager
}

func (c *TLSCaptureController) EnsureStarted() (*TLSProbeManager, error) {
	if c == nil {
		return nil, errors.New("TLS capture controller is unavailable")
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.manager != nil {
		return c.manager, nil
	}
	manager, err := NewTLSProbeManager(c.store, c.broadcaster, c.rules)
	if err != nil {
		c.lastError = err.Error()
		return nil, err
	}
	c.manager = manager
	c.startReadLoopLocked(manager)
	return manager, nil
}

func (c *TLSCaptureController) AttachDefaults() error {
	manager, err := c.EnsureStarted()
	if err != nil {
		return err
	}
	err = manager.AttachStaticLibs()
	c.startGoDiscovery(manager)
	if err != nil && c.store != nil {
		for _, library := range c.store.LibraryStatuses() {
			if library.Attached {
				c.setLastError(err)
				return nil
			}
		}
		c.setLastError(err)
		return err
	}
	c.setLastError(nil)
	return nil
}

func (c *TLSCaptureController) AttachLibrary(path, library string) error {
	manager, err := c.EnsureStarted()
	if err != nil {
		return err
	}
	if err := manager.AttachLibrary(path, library); err != nil {
		c.setLastError(err)
		return err
	}
	c.setLastError(nil)
	return nil
}

func (c *TLSCaptureController) Status() map[string]any {
	if c == nil {
		return map[string]any{"enabled": false, "available": false, "error": "TLS capture controller is unavailable"}
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return map[string]any{
		"enabled":            c.manager != nil,
		"available":          c.manager != nil,
		"readStarted":        c.readStarted,
		"goDiscoveryStarted": c.goDiscoveryStarted,
		"error":              c.lastError,
	}
}

func (c *TLSCaptureController) Close() error {
	if c == nil {
		return nil
	}
	c.mu.Lock()
	manager := c.manager
	c.manager = nil
	c.readStarted = false
	c.mu.Unlock()
	if manager != nil {
		return manager.Close()
	}
	return nil
}

func (c *TLSCaptureController) startReadLoopLocked(manager *TLSProbeManager) {
	if c.readStarted || manager == nil {
		return
	}
	c.readStarted = true
	go func() {
		if err := manager.ReadLoop(); err != nil {
			c.setLastError(err)
		}
	}()
}

func (c *TLSCaptureController) startGoDiscovery(manager *TLSProbeManager) {
	c.mu.Lock()
	if c.goDiscoveryStarted || manager == nil {
		c.mu.Unlock()
		return
	}
	c.goDiscoveryStarted = true
	c.mu.Unlock()
	manager.StartGoDiscoveryLoop(time.Minute)
}

func (c *TLSCaptureController) setLastError(err error) {
	c.mu.Lock()
	if err == nil {
		c.lastError = ""
	} else {
		c.lastError = err.Error()
	}
	c.mu.Unlock()
}

// ---- merged from capturehandlerstls.go ----

type tlsCaptureBroadcaster struct {
	mu      sync.Mutex
	clients map[*websocket.Conn]*sync.Mutex
}

func (b *tlsCaptureBroadcaster) Serve(c *gin.Context) {
	conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		return
	}

	writeMu := &sync.Mutex{}
	b.mu.Lock()
	b.clients[conn] = writeMu
	b.mu.Unlock()

	defer func() {
		b.mu.Lock()
		delete(b.clients, conn)
		b.mu.Unlock()
		_ = conn.Close()
	}()

	for {
		if _, _, err := conn.ReadMessage(); err != nil {
			return
		}
	}
}

func (b *tlsCaptureBroadcaster) Broadcast(event TLSPlaintextEvent) {
	type client struct {
		conn    *websocket.Conn
		writeMu *sync.Mutex
	}

	b.mu.Lock()
	clients := make([]client, 0, len(b.clients))
	for conn, writeMu := range b.clients {
		clients = append(clients, client{conn: conn, writeMu: writeMu})
	}
	b.mu.Unlock()

	for _, client := range clients {
		client.writeMu.Lock()
		err := client.conn.WriteJSON(event)
		client.writeMu.Unlock()
		if err != nil {
			_ = client.conn.Close()
			b.mu.Lock()
			delete(b.clients, client.conn)
			b.mu.Unlock()
		}
	}
}

type tlsCaptureRuntime interface {
	AttachDefaults() error
	AttachLibrary(path, library string) error
	EnsureStarted() (*TLSProbeManager, error)
	Status() map[string]any
}

func newTLSCaptureBroadcaster() *tlsCaptureBroadcaster {
	return &tlsCaptureBroadcaster{clients: make(map[*websocket.Conn]*sync.Mutex)}
}

func registerTLSCaptureRoutes(router gin.IRouter, runtime tlsCaptureRuntime, store *TLSCaptureStore, rules *TLSCaptureRuleStore) {
	router.GET("/tls-capture/recent", handleTLSCaptureRecent(store))
	router.GET("/tls-capture/libraries", handleTLSCaptureLibraries(store))
	router.GET("/tls-capture/status", handleTLSCaptureStatus(runtime, store))
	router.POST("/tls-capture/start", handleTLSCaptureStart(runtime))
	router.POST("/tls-capture/attach-defaults", handleTLSCaptureAttachDefaults(runtime))
	router.GET("/tls-capture/rules", handleTLSCaptureRulesGet(rules))
	router.PUT("/tls-capture/rules", handleTLSCaptureRulesPut(rules))
	router.POST("/tls-capture/library", handleTLSCaptureLibrary(runtime))
	router.POST("/tls-capture/go-binary", handleTLSCaptureGoBinary(runtime))
	router.POST("/tls-capture/executable", handleTLSCaptureExecutable(runtime))
}

func handleTLSCaptureRecent(store *TLSCaptureStore) gin.HandlerFunc {
	return func(c *gin.Context) {
		limit := parseEventLimitQuery(c.Query("limit"), 100)
		events := store.Recent(limit)
		if filter := c.Query("filter"); filter != "" {
			events = agentSightHTTPFilter.Filter(events, filter)
		}
		c.JSON(http.StatusOK, gin.H{"events": events})
	}
}

func filterTLSCaptureEvents(events []TLSPlaintextEvent, filter string) []TLSPlaintextEvent {
	terms := strings.Fields(filter)
	if len(terms) == 0 {
		return events
	}
	out := make([]TLSPlaintextEvent, 0, len(events))
	for _, event := range events {
		if tlsCaptureEventMatchesFilter(event, terms) {
			out = append(out, event)
		}
	}
	return out
}

func tlsCaptureEventMatchesFilter(event TLSPlaintextEvent, terms []string) bool {
	for _, term := range terms {
		key, value, ok := strings.Cut(term, ":")
		if !ok {
			value = term
			key = "text"
		}
		value = strings.ToLower(strings.TrimSpace(value))
		if value == "" {
			continue
		}
		var haystack string
		switch strings.ToLower(strings.TrimSpace(key)) {
		case "host":
			haystack = event.Host
		case "method":
			haystack = event.Method
		case "status":
			haystack = strconv.Itoa(event.StatusCode)
		case "type":
			haystack = event.Type
		case "comm", "process":
			haystack = event.Comm
		case "vendor":
			haystack = event.Vendor
		case "redaction":
			haystack = event.RedactionState
		default:
			haystack = strings.Join([]string{event.Type, event.Comm, event.Host, event.Method, event.URL, event.ContentType, event.Vendor, event.RedactionState}, " ")
		}
		if !strings.Contains(strings.ToLower(haystack), value) {
			return false
		}
	}
	return true
}

