// ---- merged from envelope_event.go ----

const eventEnvelopeSchemaVersion = "envelope.v1"

var eventEnvelopeJSONMarshaller = protojson.MarshalOptions{
	UseProtoNames:   true,
	EmitUnpopulated: false,
}

func normalizeCapturedEventRecord(record CapturedEventRecord) CapturedEventRecord {
	if record.Event == nil && record.Envelope != nil && record.Envelope.GetLegacyEvent() != nil {
		record.Event = cloneProtoEvent(record.Envelope.GetLegacyEvent())
	}
	if record.Envelope == nil {
		record.Envelope = buildEventEnvelope(record)
	} else {
		record.Envelope = normalizeEventEnvelope(record.Envelope, record)
	}
	return record
}

func cloneProtoEvent(event *pb.Event) *pb.Event {
	if event == nil {
		return nil
	}
	cloned, ok := proto.Clone(event).(*pb.Event)
	if ok {
		return cloned
	}
	return event
}

func normalizeEventEnvelope(envelope *pb.EventEnvelope, record CapturedEventRecord) *pb.EventEnvelope {
	if envelope == nil {
		return buildEventEnvelope(record)
	}
	cloned, ok := proto.Clone(envelope).(*pb.EventEnvelope)
	if !ok {
		cloned = envelope
	}
	if cloned.GetLegacyEvent() == nil && record.Event != nil {
		cloned.LegacyEvent = cloneProtoEvent(record.Event)
	}
	if strings.TrimSpace(cloned.GetSchemaVersion()) == "" {
		cloned.SchemaVersion = eventEnvelopeSchemaVersion
	}
	if cloned.GetTimestampNs() == 0 {
		timestamp := record.ReceivedAt.UTC()
		if timestamp.IsZero() {
			timestamp = time.Now().UTC()
		}
		cloned.TimestampNs = uint64(timestamp.UnixNano())
	}
	if strings.TrimSpace(cloned.GetSource()) == "" {
		cloned.Source = determineEventEnvelopeSource(record.Event)
	}
	if strings.TrimSpace(cloned.GetEventId()) == "" {
		cloned.EventId = buildEventEnvelopeID(record, firstNonNilEvent(record.Event, cloned.GetLegacyEvent()))
	}
	return cloned
}

func firstNonNilEvent(candidates ...*pb.Event) *pb.Event {
	for _, candidate := range candidates {
		if candidate != nil {
			return candidate
		}
	}
	return nil
}

func buildEventEnvelope(record CapturedEventRecord) *pb.EventEnvelope {
	event := record.Event
	if event == nil {
		return nil
	}
	event = cloneProtoEvent(event)
	timestamp := record.ReceivedAt.UTC()
	if timestamp.IsZero() {
		timestamp = time.Now().UTC()
	}
	envelope := &pb.EventEnvelope{
		SchemaVersion:  eventEnvelopeSchemaVersion,
		TimestampNs:    uint64(timestamp.UnixNano()),
		Source:         determineEventEnvelopeSource(event),
		AgentRunId:     event.GetAgentRunId(),
		TaskId:         event.GetTaskId(),
		ConversationId: event.GetConversationId(),
		TurnId:         event.GetTurnId(),
		ToolCallId:     event.GetToolCallId(),
		ToolName:       event.GetToolName(),
		TraceId:        event.GetTraceId(),
		SpanId:         event.GetSpanId(),
		Pid:            event.GetPid(),
		Tgid:           tgidOrPid(event),
		Ppid:           event.GetPpid(),
		Uid:            event.GetUid(),
		Gid:            event.GetGid(),
		Comm:           event.GetComm(),
		ArgvDigest:     event.GetArgvDigest(),
		Cwd:            event.GetCwd(),
		CgroupId:       event.GetCgroupId(),
		ContainerId:    event.GetContainerId(),
		PolicyDecision: event.GetDecision(),
		RiskScore:      event.GetRiskScore(),
		EventType:      event.GetEventType(),
		LegacyEvent:    event,
	}
	envelope.EventId = buildEventEnvelopeID(record, event)

	switch {
	case event.GetType() == "wrapper_intercept":
		envelope.Payload = &pb.EventEnvelope_WrapperEvent{WrapperEvent: buildWrapperEnvelopePayload(event)}
	case event.GetType() == "native_hook":
		envelope.Payload = &pb.EventEnvelope_HookEvent{HookEvent: buildHookEnvelopePayload(event)}
	case strings.HasPrefix(event.GetType(), "mcp"):
		envelope.Payload = &pb.EventEnvelope_McpEvent{McpEvent: buildMCPEnvelopePayload(event)}
	case buildProcessEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_ProcessEvent{ProcessEvent: buildProcessEnvelopePayload(event)}
	case buildTLSEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_TlsEvent{TlsEvent: buildTLSEnvelopePayload(event)}
	case buildOTelSpanEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_OtelSpanEvent{OtelSpanEvent: buildOTelSpanEnvelopePayload(event)}
	case buildStdioEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_StdioEvent{StdioEvent: buildStdioEnvelopePayload(event)}
	case buildSystemMetricEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_SystemMetricEvent{SystemMetricEvent: buildSystemMetricEnvelopePayload(event)}
	case buildNetworkEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_NetworkEvent{NetworkEvent: buildNetworkEnvelopePayload(event)}
	case event.GetType() == "execve":
		envelope.Payload = &pb.EventEnvelope_ExecEvent{ExecEvent: buildExecEnvelopePayload(event)}
	case buildFileEnvelopePayload(event) != nil:
		envelope.Payload = &pb.EventEnvelope_FileEvent{FileEvent: buildFileEnvelopePayload(event)}
	case event.GetType() == "semantic_alert" || strings.TrimSpace(event.GetDecision()) != "":
		envelope.Payload = &pb.EventEnvelope_PolicyEvent{PolicyEvent: buildPolicyEnvelopePayload(event)}
	}

	return envelope
}

func determineEventEnvelopeSource(event *pb.Event) string {
	if event == nil {
		return "unknown"
	}
	switch event.GetType() {
	case "wrapper_intercept":
		return "wrapper"
	case "native_hook":
		return "native_hook"
	case "semantic_alert":
		return "semantic_alert"
	default:
		if strings.HasPrefix(event.GetType(), "mcp") {
			return "mcp"
		}
		return "ebpf_ringbuf"
	}
}

func buildEventEnvelopeID(record CapturedEventRecord, event *pb.Event) string {
	if event == nil {
		return ""
	}
	timestamp := record.ReceivedAt.UTC()
	if timestamp.IsZero() {
		timestamp = time.Unix(0, 0).UTC()
	}
	parts := []string{
		strconvFormatInt(timestamp.UnixNano()),
		determineEventEnvelopeSource(event),
		event.GetType(),
		strconvFormatUint32(event.GetPid()),
		strconvFormatUint32(event.GetPpid()),
		event.GetComm(),
		event.GetPath(),
		event.GetNetEndpoint(),
		event.GetTraceId(),
		event.GetToolCallId(),
		event.GetDecision(),
		event.GetExtraInfo(),
	}
	sum := sha256.Sum256([]byte(strings.Join(parts, "\x00")))
	return "evt_" + hex.EncodeToString(sum[:12])
}

func buildExecEnvelopePayload(event *pb.Event) *pb.ExecEvent {
	return &pb.ExecEvent{
		Path:       event.GetPath(),
		Retval:     event.GetRetval(),
		DurationNs: event.GetDurationNs(),
		ExtraInfo:  event.GetExtraInfo(),
		ArgvDigest: event.GetArgvDigest(),
		Cwd:        event.GetCwd(),
	}
}

func buildFileEnvelopePayload(event *pb.Event) *pb.FileEvent {
	if event == nil {
		return nil
	}
	switch event.GetType() {
	case "openat", "open", "read", "write", "chmod", "chown", "rename", "link", "symlink", "mknod", "mkdir", "unlink", "unlinkat":
		return &pb.FileEvent{
			Operation: event.GetType(),
			Path:      event.GetPath(),
			ExtraPath: event.GetExtraPath(),
			Mode:      event.GetMode(),
			Bytes:     event.GetBytes(),
			UidArg:    event.GetUidArg(),
			GidArg:    event.GetGidArg(),
			Retval:    event.GetRetval(),
			ExtraInfo: event.GetExtraInfo(),
		}
	default:
		return nil
	}
}

func buildNetworkEnvelopePayload(event *pb.Event) *pb.NetworkEvent {
	if event == nil {
		return nil
	}
	switch event.GetType() {
	case "network_connect", "network_bind", "network_sendto", "network_recvfrom", "socket", "accept", "accept4", "tcp_connect", "tcp_close", "tcp_state_change", "dns_query":
		return &pb.NetworkEvent{
			Endpoint:       event.GetNetEndpoint(),
			Direction:      event.GetNetDirection(),
			Bytes:          event.GetNetBytes(),
			Family:         event.GetNetFamily(),
			Domain:         event.GetDomain(),
			SockType:       event.GetSockType(),
			Protocol:       event.GetProtocol(),
			Retval:         event.GetRetval(),
			ExtraInfo:      event.GetExtraInfo(),
			FlowId:         event.GetFlowId(),
			SrcIp:          event.GetSrcIp(),
			SrcPort:        event.GetSrcPort(),
			DstIp:          event.GetDstIp(),
			DstPort:        event.GetDstPort(),
			Transport:      event.GetTransport(),
			AppProtocol:    event.GetAppProtocol(),
			ServiceName:    event.GetServiceName(),
			DnsName:        event.GetDnsName(),
			Sni:            event.GetSni(),
			HttpHost:       event.GetHttpHost(),
			TlsAlpn:        event.GetTlsAlpn(),
			QuicState:      event.GetQuicState(),
			InterfaceName:  event.GetInterfaceName(),
			BytesIn:        event.GetBytesIn(),
			BytesOut:       event.GetBytesOut(),
			PacketsIn:      event.GetPacketsIn(),
			PacketsOut:     event.GetPacketsOut(),
			FirstSeenMs:    event.GetFirstSeenMs(),
			LastSeenMs:     event.GetLastSeenMs(),
			StaleLevel:     event.GetStaleLevel(),
			Historic:       event.GetHistoric(),
			GeoCountry:     event.GetGeoCountry(),
			GeoCountryCode: event.GetGeoCountryCode(),
			GeoAsn:         event.GetGeoAsn(),
			IpScope:        event.GetIpScope(),
		}
	default:
		return nil
	}
}

func buildOTelSpanEnvelopePayload(event *pb.Event) *pb.OtelSpanEvent {
	if event == nil || event.GetType() != "otel_span" {
		return nil
	}
	vendor := firstNonEmpty(event.GetServiceName(), parseStringField(event.GetExtraInfo(), "provider"))
	status := "ok"
	if event.GetDecision() == "ALERT" {
		status = "error"
	}
	return &pb.OtelSpanEvent{
		Name:     firstNonEmpty(event.GetToolName(), vendor, "genai.request"),
		Kind:     "client",
		Status:   status,
		Provider: vendor,
		Model:    parseStringField(event.GetExtraInfo(), "model"),
		Error:    parseStringField(event.GetExtraInfo(), "error"),
	}
}

func buildTLSEnvelopePayload(event *pb.Event) *pb.TLSEvent {
	if event == nil || event.GetType() != "tls_plaintext" {
		return nil
	}
	status := parseUintField(event.GetExtraInfo(), "status")
	return &pb.TLSEvent{
		Direction:      event.GetNetDirection(),
		Library:        parseStringField(event.GetExtraInfo(), "lib"),
		Host:           firstNonEmpty(event.GetHttpHost(), event.GetNetEndpoint()),
		Method:         event.GetPath(),
		Url:            event.GetExtraPath(),
		Status:         status,
		BodySize:       uint64(parseUintField(event.GetExtraInfo(), "body_size")),
		RedactionState: "sanitized",
		RawAvailable:   false,
		MessageRole:    parseStringField(event.GetExtraInfo(), "role"),
		PromptDigest:   parseStringField(event.GetExtraInfo(), "prompt_digest"),
		PromptLen:      uint64(parseUintField(event.GetExtraInfo(), "prompt_len")),
		Vendor:         firstNonEmpty(event.GetServiceName(), parseStringField(event.GetExtraInfo(), "vendor")),
	}
}

func buildStdioEnvelopePayload(event *pb.Event) *pb.StdioEvent {
	if event == nil || event.GetType() != "stdio" {
		return nil
	}
	stream := firstNonEmpty(parseStringField(event.GetExtraInfo(), "stream"), event.GetPath())
	return &pb.StdioEvent{
		Fd:             parseStringField(event.GetExtraInfo(), "fd"),
		Stream:         stream,
		Size:           event.GetBytes(),
		Truncated:      false,
		Binary:         false,
		RedactionState: "metadata_only",
	}
}

func buildSystemMetricEnvelopePayload(event *pb.Event) *pb.SystemMetricEvent {
	if event == nil || event.GetType() != "system_metric" {
		return nil
	}
	return &pb.SystemMetricEvent{
		CpuPercent:   parseFloatField(event.GetExtraInfo(), "cpu_percent"),
		MemoryBytes:  event.GetBytes(),
		ProcessState: parseStringField(event.GetExtraInfo(), "state"),
		Alert:        parseStringField(event.GetExtraInfo(), "alert"),
	}
}

func buildProcessEnvelopePayload(event *pb.Event) *pb.ProcessEvent {
	if event == nil {
		return nil
	}
	payload := &pb.ProcessEvent{
		ParentPid: event.GetPpid(),
		ExtraInfo: event.GetExtraInfo(),
	}
	switch event.GetType() {
	case "process_fork":
		payload.Phase = "fork"
		payload.ChildPid = parseUintField(event.GetExtraInfo(), "child_pid")
	case "clone":
		payload.Phase = "clone"
		payload.ChildPid = parseUintField(event.GetExtraInfo(), "child_pid")
	case "process_exec":
		payload.Phase = "exec"
		payload.OldPid = parseUintField(event.GetExtraInfo(), "old_pid")
	case "process_exit", "exit":
		payload.Phase = "exit"
		payload.ExitStatus = int32(parseUintField(event.GetExtraInfo(), "status"))
	case "wait4":
		payload.Phase = "wait4"
		payload.TargetPid = parseUintField(event.GetExtraInfo(), "target_pid")
	default:
		return nil
	}
	return payload
}

func buildPolicyEnvelopePayload(event *pb.Event) *pb.PolicyEvent {
	if event == nil {
		return nil
	}
	return &pb.PolicyEvent{
		Decision:        event.GetDecision(),
		RiskScore:       event.GetRiskScore(),
		Reason:          event.GetExtraInfo(),
		RelatedPath:     firstNonEmpty(event.GetPath(), event.GetExtraPath()),
		RelatedEndpoint: event.GetNetEndpoint(),
	}
}

func buildWrapperEnvelopePayload(event *pb.Event) *pb.WrapperEvent {
	if event == nil {
		return nil
	}
	commandLine := strings.TrimSpace(event.GetPath())
	parts := splitEnvelopeCommandLine(commandLine)
	args := []string{}
	if len(parts) > 1 {
		args = parts[1:]
	}
	return &pb.WrapperEvent{
		CommandLine: commandLine,
		Args:        args,
		Behavior:    event.GetBehavior(),
		ExtraInfo:   event.GetExtraInfo(),
		ToolName:    event.GetToolName(),
	}
}

func buildHookEnvelopePayload(event *pb.Event) *pb.HookEvent {
	if event == nil {
		return nil
	}
	hookName := event.GetComm()
	toolName := event.GetToolName()
	if before, after, ok := strings.Cut(event.GetComm(), ":"); ok {
		hookName = before
		if strings.TrimSpace(toolName) == "" {
			toolName = after
		}
	}
	return &pb.HookEvent{
		HookName:   strings.TrimSpace(hookName),
		ToolName:   strings.TrimSpace(toolName),
		TargetPath: firstNonEmpty(event.GetPath(), event.GetExtraPath()),
		ExtraInfo:  event.GetExtraInfo(),
	}
}

func buildMCPEnvelopePayload(event *pb.Event) *pb.McpEvent {
	if event == nil {
		return nil
	}
	return &pb.McpEvent{
		ToolName:  event.GetToolName(),
		Endpoint:  firstNonEmpty(event.GetNetEndpoint(), event.GetPath()),
		ExtraInfo: event.GetExtraInfo(),
	}
}

func splitEnvelopeCommandLine(commandLine string) []string {
	if strings.TrimSpace(commandLine) == "" {
		return nil
	}
	return strings.Fields(commandLine)
}

func buildCapturedEventJSONRecords(records []CapturedEventRecord) []map[string]any {
	items := make([]map[string]any, 0, len(records))
	for _, record := range records {
		record = normalizeCapturedEventRecord(record)
		items = append(items, map[string]any{
			"Event":     record.Event,
			"Timestamp": record.ReceivedAt.UnixMilli(),
			"Envelope":  eventEnvelopeToJSONValue(record.Envelope),
		})
	}
	return items
}

func eventEnvelopeToJSONValue(envelope *pb.EventEnvelope) map[string]any {
	if envelope == nil {
		return nil
	}
	payload, err := eventEnvelopeJSONMarshaller.Marshal(envelope)
	if err != nil {
		return map[string]any{"error": err.Error()}
	}
	decoded := make(map[string]any)
	if err := json.Unmarshal(payload, &decoded); err != nil {
		return map[string]any{"error": err.Error()}
	}
	return decoded
}

func strconvFormatUint32(value uint32) string {
	return fmt.Sprintf("%d", value)
}

func strconvFormatInt(value int64) string {
	return fmt.Sprintf("%d", value)
}

func tgidOrPid(event *pb.Event) uint32 {
	if tgid := event.GetTgid(); tgid != 0 {
		return tgid
	}
	return event.GetPid()
}

// ---- merged from event_flows.go ----

func recordUDPFlowFromEvent(event bpfEvent, out *pb.Event) {
	if out == nil {
		return
	}
	remoteIP := networkIP(event.NetFamily, event.NetAddr)
	if remoteIP == nil {
		return
	}
	remote := remoteIP.String()
	if remote == "" || remote == "<nil>" {
		return
	}
	srcIP, dstIP := "local", remote
	srcPort, dstPort := uint32(0), event.NetPort
	if out.GetNetDirection() == "incoming" {
		srcIP, dstIP = remote, "local"
	}
	recordNetworkFlowContextFromEvent(srcIP, dstIP, srcPort, dstPort, out, "")
	populateEventFlowFields(out, srcIP, dstIP, srcPort, dstPort, "UDP")
	if extraPath := sanitizeUTF8(event.Extra4[:]); len(extraPath) > 4 {
		entry := detectAndRecordProtocol(remote, dstPort, []byte(extraPath))
		networkFlowAggregator.ApplyProtocolMetadata(srcIP, dstIP, srcPort, dstPort, "UDP", entry)
		applyProtocolMetadataToEvent(out, entry)
	}
}

func populateEventFlowFields(out *pb.Event, srcIP, dstIP string, srcPort, dstPort uint32, transport string) {
	if out == nil {
		return
	}
	key := makeFlowKey(srcIP, dstIP, srcPort, dstPort, transport)
	out.FlowId = key.ID()
	out.SrcIp = srcIP
	out.SrcPort = srcPort
	out.DstIp = dstIP
	out.DstPort = dstPort
	out.Transport = transport
	out.ServiceName = lookupServiceByPort(dstPort)
	out.IpScope = string(classifyIPScope(netParseIPForFlow(dstIP)))
	if domain, ok := dnsCorrelation.LookupIP(dstIP); ok {
		out.DnsName = domain
		if out.Domain == "" {
			out.Domain = domain
		}
	}
	out.AppProtocol = detectAppProtocol(dstPort, out.Domain)
	if out.NetDirection == "incoming" {
		out.BytesIn = uint64(out.NetBytes)
		out.PacketsIn = 1
	} else if out.NetDirection == "outgoing" {
		out.BytesOut = uint64(out.NetBytes)
		out.PacketsOut = 1
	}
}

func applyProtocolMetadataToEvent(out *pb.Event, entry *protoDetectionEntry) {
	if out == nil || entry == nil {
		return
	}
	out.AppProtocol = string(entry.AppProtocol)
	if entry.SNI != "" {
		out.Sni = entry.SNI
		if out.Domain == "" {
			out.Domain = entry.SNI
		}
	}
	if entry.ALPN != "" {
		out.TlsAlpn = entry.ALPN
	}
	if entry.HTTPHost != "" {
		out.HttpHost = entry.HTTPHost
		if out.Domain == "" || out.Domain == out.Sni {
			out.Domain = entry.HTTPHost
		}
		if entry.AppProtocol == AppProtoDNS || entry.AppProtocol == AppProtomDNS {
			out.DnsName = entry.HTTPHost
		}
	}
}

func netParseIPForFlow(ip string) net.IP {
	if ip == "local" {
		return net.ParseIP("127.0.0.1")
	}
	return net.ParseIP(ip)
}

func formatIPv4Addr(addr uint32) string {
	return fmt.Sprintf("%d.%d.%d.%d",
		addr&0xFF, (addr>>8)&0xFF, (addr>>16)&0xFF, (addr>>24)&0xFF)
}

var tcpStateNames = map[uint8]string{
	1:  "ESTABLISHED",
	2:  "SYN_SENT",
	3:  "SYN_RECV",
	4:  "FIN_WAIT1",
	5:  "FIN_WAIT2",
	6:  "TIME_WAIT",
	7:  "CLOSE",
	8:  "CLOSE_WAIT",
	9:  "LAST_ACK",
	10: "LISTEN",
	11: "CLOSING",
}

func tcpStateName(state uint8) string {
	if name, ok := tcpStateNames[state]; ok {
		return name
	}
	return fmt.Sprintf("STATE_%d", state)
}

// ---- merged from events_hooks.go ----

func handleNativeHookEvent(c *gin.Context) {
	var payload map[string]interface{}
	if err := c.ShouldBindJSON(&payload); err != nil {
		c.JSON(400, gin.H{"error": "invalid json"})
		return
	}

	toolName, _ := payload["tool_name"].(string)
	hookEvent, _ := payload["hook_event_name"].(string)
	toolInput, _ := payload["tool_input"].(map[string]interface{})

	if toolName == "" {
		toolName, _ = payload["tool"].(string)
	}
	if toolName == "" {
		toolName, _ = payload["toolName"].(string)
	}
	if toolInput == nil {
		toolInput, _ = payload["toolInput"].(map[string]interface{})
	}
	if toolInput == nil {
		toolInput, _ = payload["toolArgs"].(map[string]interface{})
	}
	if toolCall, _ := payload["toolCall"].(map[string]interface{}); toolCall != nil {
		if toolName == "" {
			toolName, _ = toolCall["name"].(string)
		}
		if toolInput == nil {
			toolInput, _ = toolCall["args"].(map[string]interface{})
		}
	}
	if hookEvent == "" {
		hookEvent, _ = payload["event"].(string)
	}
	if hookEvent == "" {
		hookEvent, _ = payload["hookEventName"].(string)
	}
	if hookEvent == "" {
		hookEvent = strings.TrimSpace(c.GetHeader("X-Agent-Hook-Event"))
	}

	path := ""
	if toolInput != nil {
		path = extractNativeHookPath(toolInput)
	}
	extraInfo := buildNativeHookExtraInfo(payload, hookEvent, toolName)

	pid, ctx := buildProcessContextFromHookPayload(payload, toolName, path)
	if pid != 0 {
		trackedProcessContexts.Set(pid, ctx)
	}

	tag := "Native Hook"
	sourceCLI := strings.ToLower(strings.TrimSpace(c.GetHeader("X-Agent-CLI")))
	ua := strings.ToLower(c.GetHeader("User-Agent"))
	if sourceCLI == "claude" || strings.Contains(ua, "claude") {
		tag = "Claude Code"
	} else if sourceCLI == "gemini" || strings.Contains(ua, "gemini") {
		tag = "Gemini CLI"
	} else if sourceCLI == "codex" || strings.Contains(ua, "codex") {
		tag = "Codex"
	} else if sourceCLI == "copilot" || strings.Contains(ua, "copilot") || strings.Contains(ua, "gh-copilot") {
		tag = "GitHub Copilot"
	} else if sourceCLI == "kiro" || strings.Contains(ua, "kiro") {
		tag = "Kiro CLI"
	} else if sourceCLI == "augment" || strings.Contains(ua, "augment") || strings.Contains(ua, "auggie") {
		tag = "Augment"
	} else if sourceCLI == "antigravity" || sourceCLI == "agy" || strings.Contains(ua, "antigravity") || strings.Contains(ua, "agy") {
		tag = "Antigravity CLI"
	} else {
		if hookEvent == "BeforeTool" {
			tag = "Gemini CLI"
		} else if hookEvent == "preToolUse" {
			tag = "GitHub Copilot"
		} else if hookEvent == "agentSpawn" || hookEvent == "userPromptSubmit" || hookEvent == "stop" {
			tag = "Kiro CLI"
		}
	}

	broadcast <- &pb.Event{
		Pid:            pid,
		Type:           "native_hook",
		EventType:      pb.EventType_NATIVE_HOOK,
		Tag:            tag,
		Comm:           fmt.Sprintf("%s:%s", hookEvent, toolName),
		Path:           path,
		ExtraInfo:      extraInfo,
		SchemaVersion:  eventSchemaVersion,
		RootAgentPid:   ctx.RootAgentPid,
		AgentRunId:     ctx.AgentRunID,
		TaskId:         ctx.TaskID,
		ConversationId: ctx.ConversationID,
		TurnId:         ctx.TurnID,
		ToolCallId:     ctx.ToolCallID,
		ToolName:       ctx.ToolName,
		TraceId:        ctx.TraceID,
		SpanId:         ctx.SpanID,
		Decision:       ctx.Decision,
		RiskScore:      ctx.RiskScore,
		ContainerId:    ctx.ContainerID,
		ArgvDigest:     ctx.ArgvDigest,
		Cwd:            ctx.Cwd,
	}
	c.JSON(200, gin.H{"status": "ok"})
}

func extractNativeHookPath(toolInput map[string]interface{}) string {
	for _, key := range []string{
		"command", "Command", "CommandLine", "commandLine",
		"file_path", "filePath", "AbsolutePath", "absolutePath",
		"TargetFile", "targetFile", "DirectoryPath", "directoryPath",
		"SearchPath", "searchPath", "Cwd", "cwd",
	} {
		if value, ok := toolInput[key]; ok {
			if text := interfaceString(value); text != "" {
				return text
			}
		}
	}
	if args, ok := toolInput["arguments"].([]interface{}); ok && len(args) > 0 {
		return fmt.Sprintf("%v", args)
	}
	return ""
}

func buildNativeHookExtraInfo(payload map[string]interface{}, hookEvent, toolName string) string {
	parts := []string{}
	if trimmed := strings.TrimSpace(hookEvent); trimmed != "" {
		parts = append(parts, "hook_event="+sanitizeExtraInfoValue(trimmed))
	}
	if trimmed := strings.TrimSpace(toolName); trimmed != "" {
		parts = append(parts, "tool_name="+sanitizeExtraInfoValue(trimmed))
	}
	if prompt := extractHookPromptText(payload, hookEvent); prompt != "" {
		parts = append(parts,
			"prompt_digest="+digestHookText(prompt),
			fmt.Sprintf("prompt_len=%d", len([]rune(prompt))),
		)
	}
	if response := extractHookResponseText(payload, hookEvent); response != "" {
		parts = append(parts,
			"response_digest="+digestHookText(response),
			fmt.Sprintf("response_len=%d", len([]rune(response))),
		)
	}
	if sessionID := payloadString(payload, "session_id", "sessionId"); sessionID != "" {
		parts = append(parts, "session_id="+sanitizeExtraInfoValue(sessionID))
	}
	return strings.Join(parts, " ")
}

func extractHookPromptText(payload map[string]interface{}, hookEvent string) string {
	if payload == nil {
		return ""
	}
	if prompt := payloadNestedString(payload, "prompt", "initial_prompt", "initialPrompt", "user_prompt", "userPrompt", "input"); prompt != "" {
		return prompt
	}
	lowerEvent := strings.ToLower(strings.TrimSpace(hookEvent))
	if strings.Contains(lowerEvent, "prompt") {
		return payloadNestedString(payload, "message", "text", "content")
	}
	return ""
}

func extractHookResponseText(payload map[string]interface{}, hookEvent string) string {
	if payload == nil {
		return ""
	}
	if response := payloadNestedString(payload, "response", "prompt_response", "promptResponse", "final_response", "finalResponse", "output"); response != "" {
		return response
	}
	lowerEvent := strings.ToLower(strings.TrimSpace(hookEvent))
	if strings.Contains(lowerEvent, "afteragent") || strings.Contains(lowerEvent, "stop") || strings.Contains(lowerEvent, "response") {
		return payloadNestedString(payload, "message", "text", "content")
	}
	return ""
}

func payloadNestedString(payload map[string]interface{}, keys ...string) string {
	for _, key := range keys {
		if value, ok := payload[key]; ok {
			if text := interfaceString(value); text != "" {
				return text
			}
		}
	}
	for _, nestedKey := range []string{"tool_input", "toolInput", "tool_response", "toolResponse", "tool_output", "toolOutput", "tool_result", "toolResult"} {
		nested, _ := payload[nestedKey].(map[string]interface{})
		if nested == nil {
			continue
		}
		if text := payloadNestedString(nested, keys...); text != "" {
			return text
		}
	}
	return ""
}

func interfaceString(value interface{}) string {
	switch typed := value.(type) {
	case string:
		return strings.TrimSpace(typed)
	case fmt.Stringer:
		return strings.TrimSpace(typed.String())
	default:
		return ""
	}
}

func digestHookText(text string) string {
	sum := sha256.Sum256([]byte(text))
	return "sha256:" + hex.EncodeToString(sum[:8])
}

func sanitizeExtraInfoValue(value string) string {
	value = strings.TrimSpace(value)
	value = strings.ReplaceAll(value, "\\", "\\\\")
	value = strings.ReplaceAll(value, " ", "_")
	value = strings.ReplaceAll(value, "\n", "_")
	value = strings.ReplaceAll(value, "\r", "_")
	value = strings.ReplaceAll(value, "\t", "_")
	return value
}

