// ── Minimal PCAP writer (libpcap format) ──────────────────────────────

const (
	pcapMagicNumber      = 0xa1b2c3d4
	pcapVersionMajor     = 2
	pcapVersionMinor     = 4
	pcapThisZone         = 0
	pcapSigFigs          = 0
	pcapSnapLen          = 65535
	pcapLinkTypeEthernet = 1
)

type pcapGlobalHeader struct {
	MagicNumber  uint32
	VersionMajor uint16
	VersionMinor uint16
	ThisZone     int32
	SigFigs      uint32
	SnapLen      uint32
	LinkType     uint32
}

type pcapPacketHeader struct {
	TSSeconds   uint32
	TSUseconds  uint32
	IncludedLen uint32
	OrigLen     uint32
}

func writePCAPHeader(f *os.File) error {
	hdr := pcapGlobalHeader{
		MagicNumber:  pcapMagicNumber,
		VersionMajor: pcapVersionMajor,
		VersionMinor: pcapVersionMinor,
		SnapLen:      pcapSnapLen,
		LinkType:     pcapLinkTypeEthernet,
	}
	return binary.Write(f, binary.LittleEndian, hdr)
}

func writePCAPPacket(f *os.File, timestamp time.Time, data []byte) error {
	ts := timestamp.UTC()
	pktHdr := pcapPacketHeader{
		TSSeconds:   uint32(ts.Unix()),
		TSUseconds:  uint32(ts.Nanosecond() / 1000),
		IncludedLen: uint32(len(data)),
		OrigLen:     uint32(len(data)),
	}
	if err := binary.Write(f, binary.LittleEndian, pktHdr); err != nil {
		return err
	}
	_, err := f.Write(data)
	return err
}

// Build a synthetic Ethernet frame for a network flow.
// This is a minimal frame for Wireshark display — not a real captured packet.
func buildSyntheticEthernetFrame(srcIP, dstIP string, srcPort, dstPort uint32, protocol string, bytes uint64) []byte {
	frame := make([]byte, 14+20+20) // Eth(14) + IP(20) + TCP(20) = 54 bytes

	// Ethernet header
	frame[12] = 0x08 // EtherType: IPv4
	frame[13] = 0x00

	// IPv4 header
	frame[14] = 0x45                                                // Version=4, IHL=5
	frame[15] = 0x00                                                // DSCP/ECN
	binary.BigEndian.PutUint16(frame[16:18], uint16(len(frame)-14)) // Total length
	frame[18] = 0x00                                                // Identification
	frame[19] = 0x01
	frame[20] = 0x00 // Flags + Fragment
	frame[21] = 0x00
	frame[22] = 0x40 // TTL=64
	frame[23] = 0x06 // Protocol=TCP
	// Checksum at 24-25 (leave 0)
	frame[29] = 0x06 // Protocol=TCP (byte 9 of IP header)

	// Source IP (bytes 26-29)
	parseIPToBytes(srcIP, frame[26:30])
	// Dest IP (bytes 30-33)
	parseIPToBytes(dstIP, frame[30:34])

	// TCP header (starts at offset 34)
	binary.BigEndian.PutUint16(frame[34:36], uint16(srcPort))
	binary.BigEndian.PutUint16(frame[36:38], uint16(dstPort))
	// Sequence number
	frame[38] = 0x00
	frame[39] = 0x00
	frame[40] = 0x00
	frame[41] = 0x01
	// Ack number
	frame[46] = 0x50 // Data offset=5 (20 bytes), flags
	frame[47] = 0x02 // SYN flag
	// Window size
	frame[48] = 0xFF
	frame[49] = 0xFF

	return frame
}

func parseIPToBytes(ipStr string, dst []byte) {
	// Simple dotted-decimal parser
	var a, b, c, d int
	fmt.Sscanf(ipStr, "%d.%d.%d.%d", &a, &b, &c, &d)
	dst[0] = byte(a)
	dst[1] = byte(b)
	dst[2] = byte(c)
	dst[3] = byte(d)
}

// ── PCAP export handler ──────────────────────────────────────────────

func handlePCAPExport(c *gin.Context) {
	flows := networkFlowAggregator.Snapshot()
	tcpConns := tcpTracker.Snapshot()

	exportDir := runtimeSettingsDir()
	exportPath := filepath.Join(exportDir, fmt.Sprintf("network-export-%s.pcap", time.Now().UTC().Format("20060102-150405")))

	f, err := os.Create(exportPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	defer f.Close()

	if err := writePCAPHeader(f); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	packetCount := 0

	// Export aggregated flows
	for _, flow := range flows {
		srcIP := flow.SrcIP
		if srcIP == "" || srcIP == "0.0.0.0" {
			srcIP = "10.0.0.1"
		}
		dstIP := flow.DstIP
		if dstIP == "" || dstIP == "0.0.0.0" {
			continue
		}

		frame := buildSyntheticEthernetFrame(srcIP, dstIP, flow.SrcPort, flow.DstPort, flow.Protocol, flow.BytesOut)
		if err := writePCAPPacket(f, time.UnixMilli(flow.FirstSeen), frame); err != nil {
			continue
		}
		packetCount++
	}

	// Export TCP connections
	for _, conn := range tcpConns {
		srcIP := conn.SrcIP
		if srcIP == "" {
			srcIP = "10.0.0.1"
		}
		dstIP := conn.DstIP
		if dstIP == "" {
			continue
		}

		frame := buildSyntheticEthernetFrame(srcIP, dstIP, conn.SrcPort, conn.DstPort, "TCP", 0)
		if err := writePCAPPacket(f, conn.LastUpdate, frame); err != nil {
			continue
		}
		packetCount++
	}

	// Write JSONL sidecar file (rustnet-compatible enrichment data)
	jsonlPath := exportPath + ".jsonl"
	jsonlFile, _ := os.Create(jsonlPath)
	if jsonlFile != nil {
		for _, flow := range flows {
			fmt.Fprintf(jsonlFile, `{"srcIp":"%s","dstIp":"%s","dstPort":%d,"dstDomain":"%s","ipScope":"%s","comm":"%s","bytesOut":%d,"riskScore":%.2f}`+"\n",
				flow.SrcIP, flow.DstIP, flow.DstPort, flow.DstDomain, flow.IPScope,
				func() string {
					if len(flow.ProcessComms) > 0 {
						return flow.ProcessComms[0]
					}
					return ""
				}(),
				flow.BytesOut, flow.RiskScore)
		}
		jsonlFile.Close()
	}

	c.JSON(http.StatusOK, gin.H{
		"status":       "exported",
		"path":         exportPath,
		"jsonlPath":    jsonlPath,
		"packetCount":  packetCount,
		"flowCount":    len(flows),
		"tcpConnCount": len(tcpConns),
	})
}

// ---- merged from exporthelpersotel.go ----

func buildOTelTracerProvider(endpoint, serviceName string, headers map[string]string, owner *otelExporterState) (*sdktrace.TracerProvider, oteltrace.Tracer, error) {
	exporter, err := buildOTLPHTTPExporter(endpoint, headers, owner)
	if err != nil {
		return nil, nil, err
	}
	res, err := resource.New(
		context.Background(),
		resource.WithAttributes(
			semconv.ServiceNameKey.String(serviceName),
			attribute.String("agent.component", "agent-ebpf-filter"),
		),
	)
	if err != nil {
		return nil, nil, err
	}
	provider := sdktrace.NewTracerProvider(
		sdktrace.WithResource(res),
		sdktrace.WithBatcher(exporter,
			sdktrace.WithBatchTimeout(2*time.Second),
			sdktrace.WithMaxExportBatchSize(256),
		),
	)
	return provider, provider.Tracer("agent-ebpf-filter/otel"), nil
}

func buildOTLPHTTPExporter(endpoint string, headers map[string]string, owner *otelExporterState) (sdktrace.SpanExporter, error) {
	opts, err := buildOTLPHTTPOptions(endpoint, headers)
	if err != nil {
		return nil, err
	}
	exporter, err := otlptracehttp.New(context.Background(), opts...)
	if err != nil {
		return nil, err
	}
	return &monitoringSpanExporter{inner: exporter, owner: owner}, nil
}

func buildOTLPHTTPOptions(endpoint string, headers map[string]string) ([]otlptracehttp.Option, error) {
	trimmedEndpoint := strings.TrimSpace(endpoint)
	if trimmedEndpoint == "" {
		return nil, fmt.Errorf("empty OTLP endpoint")
	}
	opts := []otlptracehttp.Option{
		otlptracehttp.WithHeaders(cloneStringMap(headers)),
		otlptracehttp.WithTimeout(5 * time.Second),
	}
	if !strings.Contains(trimmedEndpoint, "://") {
		opts = append(opts, otlptracehttp.WithEndpoint(trimmedEndpoint))
		return opts, nil
	}
	parsed, err := url.Parse(trimmedEndpoint)
	if err != nil {
		return nil, err
	}
	if parsed.Host == "" {
		return nil, fmt.Errorf("invalid OTLP endpoint %q", endpoint)
	}
	path := strings.TrimSpace(parsed.EscapedPath())
	if path == "" || path == "/" {
		path = "/v1/traces"
	}
	opts = append(opts, otlptracehttp.WithEndpoint(parsed.Host), otlptracehttp.WithURLPath(path))
	switch parsed.Scheme {
	case "http":
		opts = append(opts, otlptracehttp.WithInsecure())
	case "https":
	default:
		return nil, fmt.Errorf("unsupported OTLP scheme %q", parsed.Scheme)
	}
	return opts, nil
}

func buildOTelAttributes(envelope *pb.EventEnvelope) []attribute.KeyValue {
	if envelope == nil {
		return nil
	}
	attrs := []attribute.KeyValue{
		attribute.String("agent.schema_version", envelope.GetSchemaVersion()),
		attribute.String("agent.event_id", envelope.GetEventId()),
		attribute.String("agent.source", envelope.GetSource()),
		attribute.String("agent.event_type", envelope.GetEventType().String()),
	}
	appendStringAttr := func(key, value string) {
		if trimmed := strings.TrimSpace(value); trimmed != "" {
			attrs = append(attrs, attribute.String(key, trimmed))
		}
	}
	appendIntAttr := func(key string, value uint64) {
		if value != 0 {
			attrs = append(attrs, attribute.Int64(key, int64(value)))
		}
	}
	appendStringAttr("agent.run_id", envelope.GetAgentRunId())
	appendStringAttr("agent.task_id", envelope.GetTaskId())
	appendStringAttr("agent.conversation_id", envelope.GetConversationId())
	appendStringAttr("agent.turn_id", envelope.GetTurnId())
	appendStringAttr("agent.tool_call_id", envelope.GetToolCallId())
	appendStringAttr("agent.tool_name", envelope.GetToolName())
	appendStringAttr("agent.trace_id", envelope.GetTraceId())
	appendStringAttr("agent.span_id", envelope.GetSpanId())
	appendStringAttr("agent.cwd", envelope.GetCwd())
	appendStringAttr("agent.container_id", envelope.GetContainerId())
	appendStringAttr("agent.argv_digest", envelope.GetArgvDigest())
	appendStringAttr("agent.policy_decision", envelope.GetPolicyDecision())
	appendIntAttr("process.pid", uint64(envelope.GetPid()))
	appendIntAttr("process.parent_pid", uint64(envelope.GetPpid()))
	appendIntAttr("process.tgid", uint64(envelope.GetTgid()))
	appendIntAttr("process.uid", uint64(envelope.GetUid()))
	appendIntAttr("process.gid", uint64(envelope.GetGid()))
	appendIntAttr("process.cgroup_id", envelope.GetCgroupId())
	appendStringAttr("process.command", envelope.GetComm())
	if envelope.GetRiskScore() > 0 {
		attrs = append(attrs, attribute.Float64("agent.risk_score", envelope.GetRiskScore()))
	}
	if legacy := envelope.GetLegacyEvent(); legacy != nil {
		if legacy.GetRetval() != 0 {
			attrs = append(attrs, attribute.Int64("process.retval", legacy.GetRetval()))
		}
		if legacy.GetDurationNs() > 0 {
			attrs = append(attrs, attribute.Int64("process.duration_ns", int64(legacy.GetDurationNs())))
		}
	}
	switch payload := envelope.GetPayload().(type) {
	case *pb.EventEnvelope_ExecEvent:
		appendStringAttr("process.executable.path", payload.ExecEvent.GetPath())
	case *pb.EventEnvelope_FileEvent:
		appendStringAttr("file.operation", payload.FileEvent.GetOperation())
		appendStringAttr("file.path", payload.FileEvent.GetPath())
		appendStringAttr("file.extra_path", payload.FileEvent.GetExtraPath())
		if payload.FileEvent.GetBytes() > 0 {
			attrs = append(attrs, attribute.Int64("file.bytes", int64(payload.FileEvent.GetBytes())))
		}
	case *pb.EventEnvelope_NetworkEvent:
		appendStringAttr("network.endpoint", payload.NetworkEvent.GetEndpoint())
		appendStringAttr("network.direction", payload.NetworkEvent.GetDirection())
		appendStringAttr("network.domain", payload.NetworkEvent.GetDomain())
		appendStringAttr("network.family", payload.NetworkEvent.GetFamily())
		appendStringAttr("network.sock_type", payload.NetworkEvent.GetSockType())
		if payload.NetworkEvent.GetBytes() > 0 {
			attrs = append(attrs, attribute.Int64("network.bytes", int64(payload.NetworkEvent.GetBytes())))
		}
	case *pb.EventEnvelope_ProcessEvent:
		appendStringAttr("process.phase", payload.ProcessEvent.GetPhase())
		appendIntAttr("process.child_pid", uint64(payload.ProcessEvent.GetChildPid()))
		appendIntAttr("process.target_pid", uint64(payload.ProcessEvent.GetTargetPid()))
		if payload.ProcessEvent.GetExitStatus() != 0 {
			attrs = append(attrs, attribute.Int("process.exit_status", int(payload.ProcessEvent.GetExitStatus())))
		}
	case *pb.EventEnvelope_PolicyEvent:
		appendStringAttr("policy.reason", payload.PolicyEvent.GetReason())
		appendStringAttr("policy.related_path", payload.PolicyEvent.GetRelatedPath())
		appendStringAttr("policy.related_endpoint", payload.PolicyEvent.GetRelatedEndpoint())
	case *pb.EventEnvelope_WrapperEvent:
		appendStringAttr("wrapper.command_line", payload.WrapperEvent.GetCommandLine())
	case *pb.EventEnvelope_HookEvent:
		appendStringAttr("hook.name", payload.HookEvent.GetHookName())
		appendStringAttr("hook.target_path", payload.HookEvent.GetTargetPath())
	case *pb.EventEnvelope_McpEvent:
		appendStringAttr("mcp.tool_name", payload.McpEvent.GetToolName())
		appendStringAttr("mcp.server_name", payload.McpEvent.GetServerName())
		appendStringAttr("mcp.endpoint", payload.McpEvent.GetEndpoint())
		appendStringAttr("mcp.request_id", payload.McpEvent.GetRequestId())
	}
	return attrs
}

func buildHierarchyAttributes(envelope *pb.EventEnvelope, level string) []attribute.KeyValue {
	attrs := []attribute.KeyValue{
		attribute.String("agent.hierarchy_level", level),
	}
	switch level {
	case "run":
		if value := firstNonEmpty(envelope.GetAgentRunId(), otelRunKey(envelope)); value != "" {
			attrs = append(attrs, attribute.String("agent.run_id", value))
		}
	case "task":
		if value := firstNonEmpty(envelope.GetTaskId(), otelTaskKey(envelope, otelRunKey(envelope))); value != "" {
			attrs = append(attrs, attribute.String("agent.task_id", value))
		}
	case "tool":
		if value := firstNonEmpty(envelope.GetToolCallId(), otelToolKey(envelope, otelTaskKey(envelope, otelRunKey(envelope)), otelRunKey(envelope))); value != "" {
			attrs = append(attrs, attribute.String("agent.tool_call_id", value))
		}
		if toolName := strings.TrimSpace(envelope.GetToolName()); toolName != "" {
			attrs = append(attrs, attribute.String("agent.tool_name", toolName))
		}
	}
	if traceID := strings.TrimSpace(envelope.GetTraceId()); traceID != "" {
		attrs = append(attrs, attribute.String("agent.trace_id", traceID))
	}
	return attrs
}

func otelEventName(envelope *pb.EventEnvelope) string {
	if envelope == nil {
		return "event.unknown"
	}
	switch envelope.GetPayload().(type) {
	case *pb.EventEnvelope_ExecEvent:
		return "process.exec"
	case *pb.EventEnvelope_FileEvent:
		file := envelope.GetFileEvent()
		operation := strings.TrimSpace(file.GetOperation())
		if operation == "" {
			operation = "unknown"
		}
		return "file." + operation
	case *pb.EventEnvelope_NetworkEvent:
		network := envelope.GetNetworkEvent()
		direction := strings.TrimSpace(network.GetDirection())
		switch {
		case strings.EqualFold(direction, "connect"), strings.Contains(strings.ToLower(network.GetEndpoint()), ":"):
			return "network.connect"
		case strings.EqualFold(direction, "send"):
			return "network.send"
		case strings.EqualFold(direction, "recv"):
			return "network.recv"
		default:
			return "network.flow"
		}
	case *pb.EventEnvelope_ProcessEvent:
		phase := strings.TrimSpace(envelope.GetProcessEvent().GetPhase())
		if phase == "" {
			phase = "unknown"
		}
		return "process." + phase
	case *pb.EventEnvelope_PolicyEvent:
		return "policy.decision"
	case *pb.EventEnvelope_WrapperEvent:
		return "tool.call"
	case *pb.EventEnvelope_HookEvent:
		return "hook.callback"
	case *pb.EventEnvelope_McpEvent:
		return "mcp.call"
	default:
		return "event." + strings.ToLower(strings.TrimSpace(envelope.GetSource()))
	}
}

func otelToolSpanName(envelope *pb.EventEnvelope) string {
	if envelope == nil {
		return "tool.call"
	}
	if _, ok := envelope.GetPayload().(*pb.EventEnvelope_McpEvent); ok {
		return "mcp.call"
	}
	toolName := strings.ToLower(strings.TrimSpace(envelope.GetToolName()))
	switch {
	case strings.Contains(toolName, "llm"), strings.Contains(toolName, "chat"), strings.Contains(toolName, "completion"):
		return "llm.call"
	case strings.Contains(toolName, "review"), strings.Contains(strings.ToLower(strings.TrimSpace(envelope.GetTaskId())), "review"):
		return "pr.review"
	default:
		return "tool.call"
	}
}

func shouldMarkSpanError(envelope *pb.EventEnvelope) bool {
	if envelope == nil {
		return false
	}
	if decision := strings.ToUpper(strings.TrimSpace(envelope.GetPolicyDecision())); decision == "BLOCK" || decision == "ALERT" {
		return true
	}
	if legacy := envelope.GetLegacyEvent(); legacy != nil && legacy.GetRetval() < 0 {
		return true
	}
	return false
}

func otelStatusMessage(envelope *pb.EventEnvelope) string {
	if envelope == nil {
		return ""
	}
	if decision := strings.TrimSpace(envelope.GetPolicyDecision()); decision != "" {
		return "policy decision: " + decision
	}
	if legacy := envelope.GetLegacyEvent(); legacy != nil && legacy.GetRetval() < 0 {
		return fmt.Sprintf("retval=%d", legacy.GetRetval())
	}
	return "runtime alert"
}

func shouldEndOTelHierarchy(envelope *pb.EventEnvelope) bool {
	if envelope == nil {
		return false
	}
	process := envelope.GetProcessEvent()
	if process == nil {
		return false
	}
	return strings.EqualFold(process.GetPhase(), "exit")
}

func otelRunKey(envelope *pb.EventEnvelope) string {
	if envelope == nil {
		return ""
	}
	parts := []string{}
	if runID := strings.TrimSpace(envelope.GetAgentRunId()); runID != "" {
		parts = append(parts, "run:"+runID)
	}
	if rootPID := envelope.GetPid(); envelope.GetLegacyEvent() != nil && envelope.GetLegacyEvent().GetRootAgentPid() != 0 {
		rootPID = envelope.GetLegacyEvent().GetRootAgentPid()
		if rootPID != 0 {
			parts = append(parts, fmt.Sprintf("root:%d", rootPID))
		}
	}
	if traceID := strings.TrimSpace(envelope.GetTraceId()); traceID != "" {
		parts = append(parts, "trace:"+traceID)
	}
	if len(parts) == 0 {
		if envelope.GetPid() == 0 {
			return ""
		}
		parts = append(parts, fmt.Sprintf("pid:%d", envelope.GetPid()))
	}
	return stableOTelKey(parts...)
}

func otelTaskKey(envelope *pb.EventEnvelope, runKey string) string {
	if envelope == nil {
		return ""
	}
	parts := []string{runKey}
	if taskID := strings.TrimSpace(envelope.GetTaskId()); taskID != "" {
		parts = append(parts, "task:"+taskID)
	} else if conversationID := strings.TrimSpace(envelope.GetConversationId()); conversationID != "" || strings.TrimSpace(envelope.GetTurnId()) != "" {
		parts = append(parts, "conversation:"+conversationID, "turn:"+strings.TrimSpace(envelope.GetTurnId()))
	} else {
		return ""
	}
	return stableOTelKey(parts...)
}

func otelToolKey(envelope *pb.EventEnvelope, taskKey, runKey string) string {
	if envelope == nil {
		return ""
	}
	parts := []string{runKey, taskKey}
	if toolCallID := strings.TrimSpace(envelope.GetToolCallId()); toolCallID != "" {
		parts = append(parts, "tool_call:"+toolCallID)
	} else if toolName := strings.TrimSpace(envelope.GetToolName()); toolName != "" {
		parts = append(parts, "tool_name:"+toolName)
		if envelope.GetPid() != 0 {
			parts = append(parts, fmt.Sprintf("pid:%d", envelope.GetPid()))
		}
	} else {
		return ""
	}
	return stableOTelKey(parts...)
}

func stableOTelKey(parts ...string) string {
	filtered := make([]string, 0, len(parts))
	for _, part := range parts {
		if trimmed := strings.TrimSpace(part); trimmed != "" {
			filtered = append(filtered, trimmed)
		}
	}
	if len(filtered) == 0 {
		return ""
	}
	sum := sha256.Sum256([]byte(strings.Join(filtered, "\x00")))
	return "otel_" + hex.EncodeToString(sum[:10])
}

func cloneStringMap(input map[string]string) map[string]string {
	if len(input) == 0 {
		return map[string]string{}
	}
	keys := make([]string, 0, len(input))
	for key := range input {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	out := make(map[string]string, len(keys))
	for _, key := range keys {
		if trimmedKey := strings.TrimSpace(key); trimmedKey != "" {
			out[trimmedKey] = strings.TrimSpace(input[key])
		}
	}
	return out
}

func handleOTelHealth(c *gin.Context) {
	c.JSON(http.StatusOK, otelExporterStore.Snapshot())
}

// ---- merged from exportspansotel.go ----

type otelSpanHierarchy struct {
	run  *activeOTelSpan
	task *activeOTelSpan
	tool *activeOTelSpan
}

func (s *otelExporterState) ensureSpanHierarchy(envelope *pb.EventEnvelope, ts time.Time) otelSpanHierarchy {
	var hierarchy otelSpanHierarchy
	if s == nil || envelope == nil {
		return hierarchy
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if !s.ready || s.tracer == nil {
		return hierarchy
	}

	runKey := otelRunKey(envelope)
	taskKey := otelTaskKey(envelope, runKey)
	toolKey := otelToolKey(envelope, taskKey, runKey)

	if runKey != "" {
		if span := s.runSpans[runKey]; span != nil {
			span.lastSeen = ts
			hierarchy.run = span
		} else {
			ctx, span := s.tracer.Start(
				context.Background(),
				"agent.run",
				oteltrace.WithTimestamp(ts),
				oteltrace.WithAttributes(buildHierarchyAttributes(envelope, "run")...),
			)
			active := &activeOTelSpan{ctx: ctx, span: span, key: runKey, runKey: runKey, lastSeen: ts}
			s.runSpans[runKey] = active
			hierarchy.run = active
		}
	}

	if taskKey != "" {
		if span := s.taskSpans[taskKey]; span != nil {
			span.lastSeen = ts
			hierarchy.task = span
		} else {
			parentCtx := context.Background()
			if hierarchy.run != nil {
				parentCtx = hierarchy.run.ctx
			}
			ctx, span := s.tracer.Start(
				parentCtx,
				"codex.task",
				oteltrace.WithTimestamp(ts),
				oteltrace.WithAttributes(buildHierarchyAttributes(envelope, "task")...),
			)
			active := &activeOTelSpan{ctx: ctx, span: span, key: taskKey, runKey: runKey, taskKey: taskKey, lastSeen: ts}
			s.taskSpans[taskKey] = active
			hierarchy.task = active
		}
	}

	if toolKey != "" {
		if span := s.toolSpans[toolKey]; span != nil {
			span.lastSeen = ts
			hierarchy.tool = span
		} else {
			parentCtx := context.Background()
			if hierarchy.task != nil {
				parentCtx = hierarchy.task.ctx
			} else if hierarchy.run != nil {
				parentCtx = hierarchy.run.ctx
			}
			ctx, span := s.tracer.Start(
				parentCtx,
				otelToolSpanName(envelope),
				oteltrace.WithTimestamp(ts),
				oteltrace.WithAttributes(buildHierarchyAttributes(envelope, "tool")...),
			)
			active := &activeOTelSpan{ctx: ctx, span: span, key: toolKey, runKey: runKey, taskKey: taskKey, lastSeen: ts}
			s.toolSpans[toolKey] = active
			hierarchy.tool = active
		}
	}

	if hierarchy.task == nil && hierarchy.tool != nil {
		hierarchy.task = s.taskSpans[hierarchy.tool.taskKey]
	}
	if hierarchy.run == nil {
		switch {
		case hierarchy.tool != nil:
			hierarchy.run = s.runSpans[hierarchy.tool.runKey]
		case hierarchy.task != nil:
			hierarchy.run = s.runSpans[hierarchy.task.runKey]
		}
	}
	return hierarchy
}

func (s *otelExporterState) shouldCreateChildSpan(envelope *pb.EventEnvelope) bool {
	if envelope == nil {
		return false
	}
	switch envelope.GetPayload().(type) {
	case *pb.EventEnvelope_ExecEvent, *pb.EventEnvelope_NetworkEvent, *pb.EventEnvelope_ProcessEvent, *pb.EventEnvelope_McpEvent, *pb.EventEnvelope_WrapperEvent, *pb.EventEnvelope_HookEvent:
		return true
	case *pb.EventEnvelope_FileEvent:
		return strings.HasPrefix(otelEventName(envelope), "file.")
	case *pb.EventEnvelope_PolicyEvent:
		return strings.TrimSpace(envelope.GetPolicyDecision()) != "" || envelope.GetRiskScore() > 0
	default:
		return false
	}
}

func (s *otelExporterState) createChildSpan(parentCtx context.Context, spanName string, envelope *pb.EventEnvelope, attrs []attribute.KeyValue, ts time.Time) {
	if s == nil || envelope == nil {
		return
	}
	s.mu.RLock()
	tracer := s.tracer
	ready := s.ready
	s.mu.RUnlock()
	if !ready || tracer == nil {
		return
	}
	endTs := ts.Add(time.Nanosecond)
	if legacy := envelope.GetLegacyEvent(); legacy != nil && legacy.GetDurationNs() > 0 {
		endTs = ts.Add(time.Duration(legacy.GetDurationNs()))
	}
	_, span := tracer.Start(parentCtx, spanName, oteltrace.WithTimestamp(ts), oteltrace.WithAttributes(attrs...))
	if shouldMarkSpanError(envelope) {
		span.SetStatus(codes.Error, otelStatusMessage(envelope))
	}
	span.End(oteltrace.WithTimestamp(endTs))
}

func (s *otelExporterState) endIdleSpans(now time.Time) {
	if s == nil {
		return
	}
	s.mu.Lock()
	toolSpans := collectIdleSpans(s.toolSpans, now, otelToolIdleTimeout)
	for _, span := range toolSpans {
		delete(s.toolSpans, span.key)
	}
	taskSpans := collectIdleTaskSpans(s.taskSpans, s.toolSpans, now, otelTaskIdleTimeout)
	for _, span := range taskSpans {
		delete(s.taskSpans, span.key)
	}
	runSpans := collectIdleRunSpans(s.runSpans, s.taskSpans, s.toolSpans, now, otelRunIdleTimeout)
	for _, span := range runSpans {
		delete(s.runSpans, span.key)
	}
	tp := s.tp
	s.mu.Unlock()

	endSpanSlice(toolSpans, now)
	endSpanSlice(taskSpans, now)
	endSpanSlice(runSpans, now)
	if tp != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		_ = tp.ForceFlush(ctx)
		cancel()
	}
}

func (s *otelExporterState) endRelatedSpans(envelope *pb.EventEnvelope, ts time.Time) {
	if s == nil || envelope == nil {
		return
	}
	runKey := otelRunKey(envelope)
	taskKey := otelTaskKey(envelope, runKey)
	toolKey := otelToolKey(envelope, taskKey, runKey)

	s.mu.Lock()
	var spans []*activeOTelSpan
	if toolKey != "" {
		if span := s.toolSpans[toolKey]; span != nil {
			spans = append(spans, span)
			delete(s.toolSpans, toolKey)
		}
	}
	if taskKey != "" && !hasActiveToolForTask(s.toolSpans, taskKey) {
		if span := s.taskSpans[taskKey]; span != nil {
			spans = append(spans, span)
			delete(s.taskSpans, taskKey)
		}
	}
	if runKey != "" && !hasActiveTaskForRun(s.taskSpans, runKey) && !hasActiveToolForRun(s.toolSpans, runKey) {
		if span := s.runSpans[runKey]; span != nil {
			spans = append(spans, span)
			delete(s.runSpans, runKey)
		}
	}
	tp := s.tp
	s.mu.Unlock()

	endSpanSlice(spans, ts)
	if tp != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		_ = tp.ForceFlush(ctx)
		cancel()
	}
}

// ---- merged from features.go ----

// Feature vector design (128 dimensions) inspired by:
// - Forrest et al. "A Sense of Self for Unix Processes" (stide n-gram model)
// - LIGHT-HIDS (2509.13464): DeepSVDD + Isolation Forest hybrid
// - eBPF ransomware detection (2409.06452): per-syscall frequency + entropy features

const FeatureDim = core.FeatureDim

// RecentWrapperEvent holds a summary of a recent wrapper_intercept event
type RecentWrapperEvent struct {
	Comm         string
	Category     string
	Action       string
	AnomalyScore float64
	Timestamp    time.Time
}

// RecentHistoryBuffer is a sliding window of recent wrapper intercept events
type RecentHistoryBuffer struct {
	mu      sync.RWMutex
	events  []RecentWrapperEvent
	maxSize int
}

func newRecentHistoryBuffer(size int) *RecentHistoryBuffer {
	if size <= 0 {
		size = 100
	}
	return &RecentHistoryBuffer{maxSize: size}
}

func (b *RecentHistoryBuffer) Add(e RecentWrapperEvent) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.events = append(b.events, e)
	if len(b.events) > b.maxSize {
		copy(b.events, b.events[len(b.events)-b.maxSize:])
		b.events = b.events[:b.maxSize]
	}
}

func (b *RecentHistoryBuffer) Snapshot() []RecentWrapperEvent {
	b.mu.RLock()
	defer b.mu.RUnlock()
	out := make([]RecentWrapperEvent, len(b.events))
	copy(out, b.events)
	return out
}

func (b *RecentHistoryBuffer) Len() int {
	b.mu.RLock()
	defer b.mu.RUnlock()
	return len(b.events)
}

// FeatureExtractor builds a 128-dim feature vector from wrapper request context
type FeatureExtractor struct {
	history *RecentHistoryBuffer
	// Running statistics for normalization
	mu          sync.RWMutex
	minVals     [FeatureDim]float64
	maxVals     [FeatureDim]float64
	sampleCount int
}

var globalFeatureExtractor = &FeatureExtractor{
	history: newRecentHistoryBuffer(100),
}

var globalEmbedder = behavior.NewInstructionEmbedder()

func (fe *FeatureExtractor) Extract(comm string, args []string, user string, pid uint32) [FeatureDim]float64 {
	var f [FeatureDim]float64

	// ── Group A: Command/Process Features [0-31] ──
	// BehaviorCategory one-hot (15 dims, 0-14)
	classification := behavior.ClassifyBehavior(comm, args)
	for _, cat := range classification.Categories {
		if int(cat) < 15 {
			f[int(cat)] = 1.0
		}
	}

	// Binary flags [15-25]
	f[15] = boolToFloat(isShell(comm))                                      // is_shell
	f[16] = boolToFloat(isPackageManager(comm))                             // is_package_manager
	f[17] = boolToFloat(isAgentCLI(comm))                                   // is_agent_cli
	f[18] = boolToFloat(user == "root")                                     // is_root_user
	f[19] = boolToFloat(hasNetworkArgs(args))                               // has_network_args
	f[20] = boolToFloat(hasFileArgs(args))                                  // has_file_args
	f[21] = boolToFloat(hasRedirect(args))                                  // has_redirection
	f[22] = boolToFloat(hasPipeChain(args))                                 // has_pipe
	f[23] = boolToFloat(len(args) > 10)                                     // many_args
	f[24] = boolToFloat(strings.Contains(strings.Join(args, " "), "/dev/")) // dev_access
	f[25] = boolToFloat(hasSudoInArgs(args))                                // sudo_in_args

	// Confidence encoding [26-27]
	switch classification.Confidence {
	case "high":
		f[26] = 1.0
	case "medium":
		f[27] = 1.0
	}

	// Command length stats [28-31]
	commLen := float64(len(comm)) / 16.0
	if commLen > 1.0 {
		commLen = 1.0
	}
	f[28] = commLen
	f[29] = float64(len(args)) / 20.0
	if f[29] > 1.0 {
		f[29] = 1.0
	}

	// ── Group B: Argument Statistical Features [32-63] ──
	if len(args) > 0 {
		var sumLen, sumSqLen float64
		for _, a := range args {
			l := float64(len(a))
			sumLen += l
			sumSqLen += l * l
		}
		meanLen := sumLen / float64(len(args))
		f[32] = meanLen / 256.0 // mean arg length (normalized)
		if f[32] > 1.0 {
			f[32] = 1.0
		}
		variance := sumSqLen/float64(len(args)) - meanLen*meanLen
		f[33] = math.Sqrt(math.Abs(variance)) / 256.0 // std dev
		if f[33] > 1.0 {
			f[33] = 1.0
		}
		f[34] = sumLen / 4096.0 // total arg bytes
		if f[34] > 1.0 {
			f[34] = 1.0
		}
		f[35] = shannonEntropy(strings.Join(args, "")) // path-like entropy
	}

	// Flag vs positional counts [36-37]
	flagCount := 0
	posCount := 0
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			flagCount++
		} else {
			posCount++
		}
	}
	f[36] = float64(flagCount) / 20.0
	if f[36] > 1.0 {
		f[36] = 1.0
	}
	f[37] = float64(posCount) / 20.0
	if f[37] > 1.0 {
		f[37] = 1.0
	}

	// Sensitive path flags [38-47]
	allArgs := strings.Join(args, " ")
	f[38] = boolToFloat(strings.Contains(allArgs, "/etc/"))
	f[39] = boolToFloat(strings.Contains(allArgs, "/proc/"))
	f[40] = boolToFloat(strings.Contains(allArgs, "/sys/"))
	f[41] = boolToFloat(strings.Contains(allArgs, "/var/log/"))
	f[42] = boolToFloat(strings.Contains(allArgs, "/root/"))
	f[43] = boolToFloat(strings.Contains(allArgs, "/home/"))
	f[44] = boolToFloat(strings.Contains(allArgs, "/tmp/"))
	f[45] = boolToFloat(strings.Contains(allArgs, "~/.ssh"))
	f[46] = boolToFloat(strings.Contains(allArgs, "~/.gnupg"))
	f[47] = boolToFloat(strings.Contains(allArgs, "/boot/"))

	// File extension histogram top 10 [48-57]
	extCounts := make(map[string]int)
	topExts := []string{".go", ".py", ".js", ".ts", ".json", ".yaml", ".toml", ".md", ".sh", ".txt"}
	for _, a := range args {
		for _, ext := range topExts {
			if strings.HasSuffix(a, ext) {
				extCounts[ext]++
			}
		}
	}
	for i, ext := range topExts {
		c := float64(extCounts[ext])
		if c > 3 {
			c = 3
		}
		f[48+i] = c / 3.0
	}

	// URL/IP patterns in args [58-59]
	f[58] = boolToFloat(hasURLPattern(allArgs))
	f[59] = boolToFloat(hasIPPattern(allArgs))

	// Redirection operators count [60-61]
	redirectCount := 0
	for _, a := range args {
		if a == ">" || a == ">>" || a == "<" || a == "2>" || a == "&>" {
			redirectCount++
		}
	}
	f[60] = float64(redirectCount) / 5.0
	if f[60] > 1.0 {
		f[60] = 1.0
	}

	pipeCount := 0
	for _, a := range args {
		if a == "|" {
			pipeCount++
		}
	}
	f[61] = float64(pipeCount) / 5.0
	if f[61] > 1.0 {
		f[61] = 1.0
	}

	// Argument uniqueness ratio [62-63]
	uniqueArgs := make(map[string]struct{})
	for _, a := range args {
		uniqueArgs[a] = struct{}{}
	}
	if len(args) > 0 {
		f[62] = float64(len(uniqueArgs)) / float64(len(args))
	}
	f[63] = boolToFloat(hasEnvironmentVar(args))

	// ── Group C: Embedding Projection [64-95] ──
	_, emb := globalEmbedder.ClassifyAndEmbed(comm, args)
	// Take first 32 dims of the 64-dim LSH embedding
	copy(f[64:96], emb.Vector[:32])

	// ── Group D: Recent History Aggregates [96-111] ──
	history := fe.history.Snapshot()
	if len(history) > 0 {
		// Frequency of this comm in window
		commMatch := 0
		blockCount, alertCount := 0, 0
		var sumAnomaly, sumSqAnomaly float64
		categorySet := make(map[string]struct{})
		for _, h := range history {
			if h.Comm == comm {
				commMatch++
			}
			switch h.Action {
			case "BLOCK":
				blockCount++
			case "ALERT":
				alertCount++
			}
			sumAnomaly += h.AnomalyScore
			sumSqAnomaly += h.AnomalyScore * h.AnomalyScore
			categorySet[h.Category] = struct{}{}
		}
		n := float64(len(history))
		f[96] = float64(commMatch) / n
		f[97] = float64(blockCount) / n
		f[98] = float64(alertCount) / n
		f[99] = sumAnomaly / n                // mean anomaly
		f[100] = sumSqAnomaly/n - f[99]*f[99] // variance
		if f[100] < 0 {
			f[100] = 0
		}
		f[101] = float64(len(categorySet)) / 15.0 // category diversity

		// Anomaly trend: recent half vs older half
		if len(history) >= 4 {
			mid := len(history) / 2
			var recentMean, olderMean float64
			for j, h := range history {
				if j >= mid {
					recentMean += h.AnomalyScore
				} else {
					olderMean += h.AnomalyScore
				}
			}
			recentMean /= float64(len(history) - mid)
			olderMean /= float64(mid)
			f[102] = (recentMean - olderMean + 1.0) / 2.0
		} else {
			f[102] = 0.5
		}

		// Time-weighted recent activity (last 5 events)
		if len(history) >= 3 {
			recentComm := 0
			tail := history
			if len(tail) > 5 {
				tail = tail[len(tail)-5:]
			}
			for _, h := range tail {
				if h.Comm == comm {
					recentComm++
				}
			}
			f[103] = float64(recentComm) / float64(len(tail))
		}

		// Command repetition burst
		if commMatch > 1 {
			f[104] = math.Min(float64(commMatch-1)/10.0, 1.0)
		}

		// Comm-specific alert rate
		commAlerts := 0
		for _, h := range history {
			if h.Comm == comm && h.Action == "ALERT" {
				commAlerts++
			}
		}
		if commMatch > 0 {
			f[105] = float64(commAlerts) / float64(commMatch)
		}
	}

	// ── Group E: Event Rate Features [112-119] ──
	now := time.Now()
	recentCutoff := now.Add(-1 * time.Second)
	recentCount := 0
	distinctPids := make(map[uint32]struct{})
	for _, h := range history {
		if h.Timestamp.After(recentCutoff) {
			recentCount++
		}
	}
	f[112] = float64(recentCount) / 50.0 // events per second (cap at 50)
	if f[112] > 1.0 {
		f[112] = 1.0
	}
	f[113] = float64(len(distinctPids)) / 20.0
	if f[113] > 1.0 {
		f[113] = 1.0
	}

	// Timestamp features [114-115]
	f[114] = float64(now.Hour()) / 24.0   // hour of day
	f[115] = float64(now.Weekday()) / 7.0 // day of week

	// ── Group F: Network Audit Features [120-127] ──
	cmdline := strings.Join(args, " ")
	netAudit := AuditNetworkBehavior(comm, cmdline)
	f[120] = netAudit.RiskScore / 100.0 // normalized risk score
	f[121] = boolToFloat(netAudit.Flags.SuspiciousPort)
	f[122] = boolToFloat(netAudit.Flags.ReverseShell)
	f[123] = boolToFloat(netAudit.Flags.DataExfil)
	f[124] = boolToFloat(netAudit.Flags.DNSTunnel)
	f[125] = boolToFloat(netAudit.Flags.ClearTextProto)
	f[126] = boolToFloat(netAudit.Flags.UnusualTarget)
	f[127] = boolToFloat(netAudit.Flags.PortScan)

	fe.updateStats(f)
	return f
}

// AddHistory adds a wrapper event to the history buffer
func (fe *FeatureExtractor) AddHistory(comm, category, action string, anomalyScore float64) {
	fe.history.Add(RecentWrapperEvent{
		Comm:         comm,
		Category:     category,
		Action:       action,
		AnomalyScore: anomalyScore,
		Timestamp:    time.Now(),
	})
}

func (fe *FeatureExtractor) updateStats(f [FeatureDim]float64) {
	fe.mu.Lock()
	defer fe.mu.Unlock()
	if fe.sampleCount == 0 {
		fe.minVals = f
		fe.maxVals = f
	} else {
		for i := range f {
			if f[i] < fe.minVals[i] {
				fe.minVals[i] = f[i]
			}
			if f[i] > fe.maxVals[i] {
				fe.maxVals[i] = f[i]
			}
		}
	}
	fe.sampleCount++
}

// GetHistoryBuffer returns the shared history buffer
func (fe *FeatureExtractor) GetHistoryBuffer() *RecentHistoryBuffer {
	return fe.history
}

