func toInternalDomainForwardProxySettings(settings DomainForwardProxySettings) domainforwardproxy.DomainForwardProxySettings {
	routes := make([]domainforwardproxy.DomainForwardRoute, 0, len(settings.Routes))
	for _, route := range settings.Routes {
		routes = append(routes, domainforwardproxy.DomainForwardRoute{
			Host:     route.Host,
			Upstream: route.Upstream,
			CertFile: route.CertFile,
			KeyFile:  route.KeyFile,
		})
	}
	return domainforwardproxy.DomainForwardProxySettings{
		Enabled:            settings.Enabled,
		HTTPPort:           settings.HTTPPort,
		HTTPSPort:          settings.HTTPSPort,
		DefaultScheme:      settings.DefaultScheme,
		AllowAnyHost:       settings.AllowAnyHost,
		DNSResolver:        settings.DNSResolver,
		DialTimeoutSeconds: settings.DialTimeoutSeconds,
		CertFile:           settings.CertFile,
		KeyFile:            settings.KeyFile,
		Routes:             routes,
	}
}

func fromInternalDomainForwardProxySettings(settings domainforwardproxy.DomainForwardProxySettings) DomainForwardProxySettings {
	routes := make([]DomainForwardRoute, 0, len(settings.Routes))
	for _, route := range settings.Routes {
		routes = append(routes, DomainForwardRoute{
			Host:     route.Host,
			Upstream: route.Upstream,
			CertFile: route.CertFile,
			KeyFile:  route.KeyFile,
		})
	}
	return DomainForwardProxySettings{
		Enabled:            settings.Enabled,
		HTTPPort:           settings.HTTPPort,
		HTTPSPort:          settings.HTTPSPort,
		DefaultScheme:      settings.DefaultScheme,
		AllowAnyHost:       settings.AllowAnyHost,
		DNSResolver:        settings.DNSResolver,
		DialTimeoutSeconds: settings.DialTimeoutSeconds,
		CertFile:           settings.CertFile,
		KeyFile:            settings.KeyFile,
		Routes:             routes,
	}
}

func fromInternalDomainForwardRoute(route domainforwardproxy.DomainForwardRoute) DomainForwardRoute {
	return DomainForwardRoute{
		Host:     route.Host,
		Upstream: route.Upstream,
		CertFile: route.CertFile,
		KeyFile:  route.KeyFile,
	}
}

func newDomainForwardTLSConfig(settings DomainForwardProxySettings) (*tls.Config, []string, error) {
	return domainforwardproxy.NewTLSConfig(toInternalDomainForwardProxySettings(settings))
}

func newDomainForwardTransport(settings DomainForwardProxySettings) http.RoundTripper {
	return domainforwardproxy.NewTransport(toInternalDomainForwardProxySettings(settings))
}

func normalizeDomainForwardProxySettings(settings *DomainForwardProxySettings) {
	if settings == nil {
		return
	}
	internal := toInternalDomainForwardProxySettings(*settings)
	domainforwardproxy.NormalizeSettings(&internal)
	*settings = fromInternalDomainForwardProxySettings(internal)
}

func normalizeDomainPattern(raw string) string {
	return domainforwardproxy.NormalizeDomainPattern(raw)
}

func normalizeForwardHost(raw string) string {
	return domainforwardproxy.NormalizeForwardHost(raw)
}

func domainForwardProxySettingsEqual(a, b DomainForwardProxySettings) bool {
	return domainforwardproxy.SettingsEqual(toInternalDomainForwardProxySettings(a), toInternalDomainForwardProxySettings(b))
}

type domainForwardProxyHandler struct {
	inner *domainforwardproxy.Handler
}

func newDomainForwardProxyHandler(settings DomainForwardProxySettings) *domainForwardProxyHandler {
	return &domainForwardProxyHandler{inner: domainforwardproxy.NewHandler(toInternalDomainForwardProxySettings(settings))}
}

func (h *domainForwardProxyHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h.inner.ServeHTTP(w, r)
}

func (h *domainForwardProxyHandler) targetForHost(host string) (*url.URL, DomainForwardRoute, error) {
	target, route, err := h.inner.TargetForHost(host)
	return target, fromInternalDomainForwardRoute(route), err
}

func parseForwardUpstream(raw string, defaultScheme string, requestHost string) (*url.URL, error) {
	return domainforwardproxy.ParseUpstream(raw, defaultScheme, requestHost)
}

func joinForwardProxyPath(target *url.URL, incoming *url.URL) (path, rawpath string) {
	return domainforwardproxy.JoinPath(target, incoming)
}

func requestForwardedProto(r *http.Request) string {
	if r.TLS != nil {
		return "https"
	}
	return "http"
}

// ---- merged from fragmentassemblertls.go ----

const tlsMaxPendingFragments = 4096

type tlsFragmentAssemblerKey struct {
	PID         uint32
	TGID        uint32
	TimestampNS uint64
	Direction   uint8
}

type pendingTLSFragment struct {
	firstSeen   time.Time
	fragCount   uint16
	totalLen    uint32
	originalLen uint32
	comm        string
	flags       uint8
	function    uint8
	fragMap     map[uint16]tlsFragment
}

type FragmentAssembler struct {
	mu      sync.Mutex
	pending map[tlsFragmentAssemblerKey]*pendingTLSFragment
	timeout time.Duration
	dropped int
}

func NewFragmentAssembler(timeout time.Duration) *FragmentAssembler {
	return &FragmentAssembler{
		pending: make(map[tlsFragmentAssemblerKey]*pendingTLSFragment),
		timeout: timeout,
	}
}

func fragmentAssemblerKey(f tlsFragment) tlsFragmentAssemblerKey {
	return tlsFragmentAssemblerKey{
		PID:         f.PID,
		TGID:        f.TGID,
		TimestampNS: f.TimestampNS,
		Direction:   f.Direction,
	}
}

func (a *FragmentAssembler) evictOldestPendingLocked() {
	var oldestKey tlsFragmentAssemblerKey
	var oldest *pendingTLSFragment
	for key, pending := range a.pending {
		if oldest == nil || pending.firstSeen.Before(oldest.firstSeen) {
			oldestKey = key
			oldest = pending
		}
	}
	if oldest != nil {
		delete(a.pending, oldestKey)
		a.dropped++
	}
}

func sanitizeTLSComm(comm [16]byte) string {
	return sanitizeUTF8(comm[:])
}

func (a *FragmentAssembler) Add(fragment tlsFragment) (*completedTLSFragment, bool) {
	if fragment.FragCount == 0 || fragment.FragIndex >= fragment.FragCount || fragment.TotalLen == 0 {
		a.mu.Lock()
		a.dropped++
		a.mu.Unlock()
		return nil, false
	}
	if fragment.FragCount > tlsMaxFragments {
		a.mu.Lock()
		a.dropped++
		a.mu.Unlock()
		return nil, false
	}
	if fragment.DataLen > tlsFragmentSize {
		a.mu.Lock()
		a.dropped++
		a.mu.Unlock()
		return nil, false
	}

	now := time.Unix(0, int64(fragment.TimestampNS))
	if now.IsZero() {
		now = time.Now()
	}
	key := fragmentAssemblerKey(fragment)

	a.mu.Lock()
	defer a.mu.Unlock()

	pending := a.pending[key]
	if pending == nil {
		if len(a.pending) >= tlsMaxPendingFragments {
			a.evictOldestPendingLocked()
		}
		pending = &pendingTLSFragment{
			firstSeen:   now,
			fragCount:   fragment.FragCount,
			totalLen:    fragment.TotalLen,
			originalLen: fragment.OriginalLen,
			comm:        sanitizeTLSComm(fragment.Comm),
			flags:       fragment.Flags,
			function:    fragment.Function,
			fragMap:     make(map[uint16]tlsFragment, fragment.FragCount),
		}
		a.pending[key] = pending
	} else if pending.fragCount != fragment.FragCount || pending.totalLen != fragment.TotalLen || pending.originalLen != fragment.OriginalLen || pending.flags != fragment.Flags || pending.function != fragment.Function {
		delete(a.pending, key)
		a.dropped++
		return nil, false
	}
	if _, exists := pending.fragMap[fragment.FragIndex]; exists {
		a.dropped++
		return nil, false
	}

	fragCopy := fragment
	pending.fragMap[fragment.FragIndex] = fragCopy
	if uint16(len(pending.fragMap)) != pending.fragCount {
		return nil, false
	}

	payload := make([]byte, 0, pending.totalLen)
	for i := uint16(0); i < pending.fragCount; i++ {
		frag, ok := pending.fragMap[i]
		if !ok {
			delete(a.pending, key)
			a.dropped++
			return nil, false
		}
		payload = append(payload, frag.Data[:frag.DataLen]...)
	}
	delete(a.pending, key)

	return &completedTLSFragment{
		TimestampNS: fragment.TimestampNS,
		PID:         fragment.PID,
		TGID:        fragment.TGID,
		DataLen:     fragment.DataLen,
		TotalLen:    pending.totalLen,
		OriginalLen: pending.originalLen,
		FragCount:   pending.fragCount,
		LibType:     fragment.LibType,
		Direction:   fragment.Direction,
		Flags:       pending.flags,
		Function:    pending.function,
		Comm:        pending.comm,
		Payload:     payload,
	}, true
}

func (a *FragmentAssembler) CleanupExpired(now time.Time) int {
	a.mu.Lock()
	defer a.mu.Unlock()

	removed := 0
	for key, pending := range a.pending {
		if now.Sub(pending.firstSeen) > a.timeout {
			delete(a.pending, key)
			removed++
		}
	}
	return removed
}

func (a *FragmentAssembler) Pending() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return len(a.pending)
}

func (a *FragmentAssembler) RemoveByTGID(tgid uint32) int {
	a.mu.Lock()
	defer a.mu.Unlock()
	removed := 0
	for key := range a.pending {
		if key.TGID == tgid {
			delete(a.pending, key)
			removed++
		}
	}
	return removed
}

func (a *FragmentAssembler) RemoveByPID(pid uint32) int {
	a.mu.Lock()
	defer a.mu.Unlock()
	removed := 0
	for key := range a.pending {
		if key.PID == pid {
			delete(a.pending, key)
			removed++
		}
	}
	return removed
}

func (a *FragmentAssembler) Dropped() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.dropped
}

