// ---- merged from handlersstatssystem.go ----

func serveSystemStatsWS(c *gin.Context) {
	conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	intervalStr := c.DefaultQuery("interval", "2000")
	iv, _ := time.ParseDuration(intervalStr + "ms")
	if iv < 500*time.Millisecond {
		iv = 500 * time.Millisecond
	}
	ticker := time.NewTicker(iv)
	defer ticker.Stop()

	coreTypes := getCoreTypes()
	lastFaults, err := readVMFaultCounters()
	if err != nil {
		lastFaults = vmFaultCounters{}
	}
	lastNetIO, _ := gnet.IOCounters(true)
	lastDiskIO, _ := disk.IOCounters()
	lastIOStatTime := time.Now()
	lastFaultTime := time.Now()
	type procCPUSample struct {
		createTime int64
		totalCPU   float64
		sampleTime time.Time
	}
	procCPUSamples := make(map[int32]procCPUSample)
	cpuScale := float64(runtime.NumCPU())
	if cpuScale <= 0 {
		cpuScale = 1
	}
	for range ticker.C {
		now := time.Now()
		gm, gs := getGPUMetrics()
		vm, _ := mem.VirtualMemory()
		sm, _ := mem.SwapMemory()
		cc, _ := cpu.Percent(0, false)
		cp, _ := cpu.Percent(0, true)
		netIO, _ := gnet.IOCounters(true)
		diskIO, _ := disk.IOCounters()
		pbIO := &pb.IOInfo{}
		dtIO := now.Sub(lastIOStatTime).Seconds()
		vmFaults, faultErr := readVMFaultCounters()
		faultInfo := &pb.FaultInfo{}
		currentPIDs := make(map[int32]struct{})
		emittedSystemMetric := false
		if faultErr == nil {
			pageFaults := vmFaults.PageFaults
			majorFaults := vmFaults.MajorFaults
			minorFaults := uint64(0)
			if pageFaults >= majorFaults {
				minorFaults = pageFaults - majorFaults
			}
			faultInfo.PageFaults = pageFaults
			faultInfo.MajorFaults = majorFaults
			faultInfo.MinorFaults = minorFaults
			dt := now.Sub(lastFaultTime).Seconds()
			if dt > 0 {
				pageDelta := deltaUint64(pageFaults, lastFaults.PageFaults)
				majorDelta := deltaUint64(majorFaults, lastFaults.MajorFaults)
				swapInDelta := deltaUint64(vmFaults.SwapIn, lastFaults.SwapIn)
				swapOutDelta := deltaUint64(vmFaults.SwapOut, lastFaults.SwapOut)
				faultInfo.PageFaultRate = float64(pageDelta) / dt
				faultInfo.MajorFaultRate = float64(majorDelta) / dt
				faultInfo.MinorFaultRate = faultInfo.PageFaultRate - faultInfo.MajorFaultRate
				if faultInfo.MinorFaultRate < 0 {
					faultInfo.MinorFaultRate = 0
				}
				faultInfo.SwapIn = vmFaults.SwapIn
				faultInfo.SwapOut = vmFaults.SwapOut
				faultInfo.SwapInRate = float64(swapInDelta) / dt
				faultInfo.SwapOutRate = float64(swapOutDelta) / dt
			}
			lastFaults = vmFaults
			lastFaultTime = now
		}

		if dtIO > 0 {
			for _, n := range netIO {
				var rb, sb uint64
				for _, prev := range lastNetIO {
					if prev.Name == n.Name {
						rb = deltaUint64(n.BytesRecv, prev.BytesRecv)
						sb = deltaUint64(n.BytesSent, prev.BytesSent)
						break
					}
				}
				pbIO.Networks = append(pbIO.Networks, &pb.NetworkInterface{
					Name:      n.Name,
					RecvBytes: uint64(float64(rb) / dtIO),
					SentBytes: uint64(float64(sb) / dtIO),
				})
				pbIO.TotalNetRecvBytes += uint64(float64(rb) / dtIO)
				pbIO.TotalNetSentBytes += uint64(float64(sb) / dtIO)
			}
			for name, d := range diskIO {
				var rb, wb uint64
				if prev, ok := lastDiskIO[name]; ok {
					rb = deltaUint64(d.ReadBytes, prev.ReadBytes)
					wb = deltaUint64(d.WriteBytes, prev.WriteBytes)
				}
				pbIO.Disks = append(pbIO.Disks, &pb.DiskDevice{
					Name:       name,
					ReadBytes:  uint64(float64(rb) / dtIO),
					WriteBytes: uint64(float64(wb) / dtIO),
				})
				pbIO.TotalReadBytes += uint64(float64(rb) / dtIO)
				pbIO.TotalWriteBytes += uint64(float64(wb) / dtIO)
			}
		}
		lastNetIO = netIO
		lastDiskIO = diskIO
		lastIOStatTime = now
		cpuInfo := &pb.CPUInfo{Total: cc[0], Cores: cp}
		for i, usage := range cp {
			ct := pb.CPUInfo_Core_PERFORMANCE
			if i < len(coreTypes) {
				ct = coreTypes[i]
			}
			cpuInfo.CoreDetails = append(cpuInfo.CoreDetails, &pb.CPUInfo_Core{Index: uint32(i), Usage: usage, Type: ct})
		}
		zused, ztotal := getZramStats()
		stats := &pb.SystemStats{Gpus: gs, Cpu: cpuInfo, Memory: &pb.MemoryInfo{
			Total:     vm.Total,
			Used:      vm.Used,
			Percent:   float32(vm.UsedPercent),
			Cached:    vm.Cached,
			Buffers:   vm.Buffers,
			Shared:    vm.Shared,
			ZramUsed:  zused,
			ZramTotal: ztotal,
			SwapTotal: sm.Total,
			SwapUsed:  sm.Used,
		}, Io: pbIO, Faults: faultInfo}
		psList, _ := ps.Processes()
		for _, p := range psList {
			n, _ := p.Name()
			pp, _ := p.Ppid()
			ct, _ := p.CreateTime()
			ccp := 0.0
			if times, err := p.Times(); err == nil {
				totalCPU := times.Total()
				if prev, ok := procCPUSamples[p.Pid]; ok && prev.createTime == ct {
					dt := now.Sub(prev.sampleTime).Seconds()
					if dt > 0 {
						ccp = ((totalCPU - prev.totalCPU) / dt) * 100 / cpuScale
						if ccp < 0 || math.IsNaN(ccp) || math.IsInf(ccp, 0) {
							ccp = 0
						}
					}
				}
				if ct > 0 {
					procCPUSamples[p.Pid] = procCPUSample{createTime: ct, totalCPU: totalCPU, sampleTime: now}
				}
			}
			mp, _ := p.MemoryPercent()
			u, _ := p.Username()
			cmdl, _ := p.Cmdline()
			gmem, gid, gutil := uint32(0), uint32(0), uint32(0)
			if info, ok := gm[p.Pid]; ok {
				gmem, gid, gutil = info.Mem, info.GPU, info.Util
			}
			minF, majF := uint64(0), uint64(0)
			if faults, err := p.PageFaults(); err == nil && faults != nil {
				minF = faults.MinorFaults
				majF = faults.MajorFaults
			}
			currentPIDs[p.Pid] = struct{}{}
			stats.Processes = append(stats.Processes, &pb.Process{Pid: p.Pid, Ppid: pp, Name: n, Cpu: ccp, Mem: mp, User: u, GpuMem: gmem, GpuId: gid, GpuUtil: gutil, Cmdline: cmdl, CreateTime: ct, MinorFaults: minF, MajorFaults: majF})
			if !emittedSystemMetric && (ccp >= 80 || mp >= 20) {
				emitSystemMetricEvent(p.Pid, pp, n, ccp, mp, uint64(float64(vm.Total)*float64(mp)/100), "threshold")
				emittedSystemMetric = true
			}
		}
		for pid := range procCPUSamples {
			if _, ok := currentPIDs[pid]; !ok {
				delete(procCPUSamples, pid)
			}
		}
		data, _ := proto.Marshal(stats)
		if err := conn.WriteMessage(websocket.BinaryMessage, data); err != nil {
			return
		}
	}
}

func emitSystemMetricEvent(pid, ppid int32, comm string, cpuPercent float64, memoryPercent float32, memoryBytes uint64, alert string) {
	if broadcast == nil {
		return
	}
	event := &pb.Event{
		Pid:           uint32(pid),
		Ppid:          uint32(maxInt(int(ppid), 0)),
		Type:          "system_metric",
		EventType:     pb.EventType_SYSTEM_METRIC,
		Tag:           "System Metric",
		Comm:          comm,
		ExtraInfo:     fmt.Sprintf("cpu_percent=%.2f memory_percent=%.2f memory_bytes=%d alert=%s", cpuPercent, memoryPercent, memoryBytes, alert),
		Bytes:         memoryBytes,
		RiskScore:     maxFloat64(cpuPercent/100, float64(memoryPercent)/100),
		Decision:      "ALERT",
		SchemaVersion: eventSchemaVersion,
	}
	sendTLSBridge(broadcast, event)
}

// ---- merged from health_bootstrap.go ----

type TracepointBootstrapStatus struct {
	KernelRelease      string    `json:"kernelRelease"`
	CompiledCount      int       `json:"compiledCount"`
	AttachedCount      int       `json:"attachedCount"`
	SkippedCount       int       `json:"skippedCount"`
	SkippedTracepoints []string  `json:"skippedTracepoints,omitempty"`
	Status             string    `json:"status"`
	Message            string    `json:"message"`
	ObservedAt         time.Time `json:"observedAt"`
}

type tracepointBootstrapState struct {
	mu     sync.RWMutex
	status TracepointBootstrapStatus
}

func newTracepointBootstrapState() *tracepointBootstrapState {
	return &tracepointBootstrapState{
		status: TracepointBootstrapStatus{Status: "unknown", Message: "Tracepoint bootstrap has not been observed yet."},
	}
}

var bootstrapTracepointStatusStore = newTracepointBootstrapState()

func currentKernelRelease() string {
	if data, err := os.ReadFile("/proc/sys/kernel/osrelease"); err == nil {
		if rel := strings.TrimSpace(string(data)); rel != "" {
			return rel
		}
	}
	return "unknown"
}

func buildTracepointBootstrapStatus(compiledCount int, skipped []string) TracepointBootstrapStatus {
	status := TracepointBootstrapStatus{
		KernelRelease: currentKernelRelease(),
		CompiledCount: compiledCount,
		AttachedCount: compiledCount - len(skipped),
		SkippedCount:  len(skipped),
		Status:        "ready",
		ObservedAt:    time.Now().UTC(),
	}

	if status.AttachedCount < 0 {
		status.AttachedCount = 0
	}

	if len(skipped) > 0 {
		status.SkippedTracepoints = append([]string(nil), skipped...)
		sort.Strings(status.SkippedTracepoints)
		if status.AttachedCount == 0 {
			status.Status = "error"
			status.Message = "The backend could not attach any compiled tracepoints on this kernel."
		} else {
			status.Status = "partial"
			status.Message = "The backend booted successfully, but some kernel tracepoints were not exposed and were skipped."
		}
	} else {
		status.Message = "All compiled tracepoints attached successfully."
	}

	if status.CompiledCount == 0 {
		status.Status = "error"
		status.Message = "No tracepoint programs were compiled into the backend."
	}

	return status
}

func recordTracepointBootstrapStatus(compiledCount int, skipped []string) {
	bootstrapTracepointStatusStore.mu.Lock()
	bootstrapTracepointStatusStore.status = buildTracepointBootstrapStatus(compiledCount, skipped)
	bootstrapTracepointStatusStore.mu.Unlock()
}

func (s *tracepointBootstrapState) Snapshot() TracepointBootstrapStatus {
	s.mu.RLock()
	defer s.mu.RUnlock()

	status := s.status
	if len(status.SkippedTracepoints) > 0 {
		status.SkippedTracepoints = append([]string(nil), status.SkippedTracepoints...)
	}
	return status
}

func handleBootstrapHealth(c *gin.Context) {
	c.JSON(200, bootstrapTracepointStatusStore.Snapshot())
}

// ---- merged from helpers_auth.go ----

func authMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		if !releaseAuthEnforced() || clusterRequestAuthAllowed(c) {
			c.Next()
			return
		}
		token := requestAuthToken(c)
		expectedKey := runtimeSettingsStore.ExpectedToken()
		if token == "" || expectedKey == "" || subtle.ConstantTimeCompare([]byte(token), []byte(expectedKey)) != 1 {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "Unauthorized"})
			return
		}
		c.Next()
	}
}

func releaseAuthEnforced() bool {
	return gin.Mode() == gin.ReleaseMode && os.Getenv("DISABLE_AUTH") != "true"
}

func hookIngressAuthMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		if !releaseAuthEnforced() || clusterRequestAuthAllowed(c) {
			c.Next()
			return
		}

		if token := requestAuthToken(c); token != "" {
			expectedKey := runtimeSettingsStore.ExpectedToken()
			if subtle.ConstantTimeCompare([]byte(token), []byte(expectedKey)) == 1 {
				c.Next()
				return
			}
		}

		hookID := strings.ToLower(strings.TrimSpace(c.GetHeader("X-Agent-CLI")))
		secret := strings.TrimSpace(c.GetHeader("X-Agent-Hook-Secret"))
		expectedSecret := runtimeSettingsStore.HookSecret(hookID)
		if hookID == "" || secret == "" || subtle.ConstantTimeCompare([]byte(secret), []byte(expectedSecret)) != 1 {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "Unauthorized"})
			return
		}

		c.Next()
	}
}

func runtimeToggleMiddleware(featureName string, enabled func(core.RuntimeSettings) bool) gin.HandlerFunc {
	return func(c *gin.Context) {
		if enabled(runtimeSettingsStore.Snapshot()) {
			c.Next()
			return
		}
		c.AbortWithStatusJSON(http.StatusForbidden, gin.H{
			"error":   featureName + " is disabled",
			"feature": featureName,
		})
	}
}

func shellSessionsEnabledMiddleware() gin.HandlerFunc {
	return runtimeToggleMiddleware("shell_sessions", func(settings core.RuntimeSettings) bool {
		return settings.ShellSessionsEnabled
	})
}

func systemRunEnabledMiddleware() gin.HandlerFunc {
	return runtimeToggleMiddleware("system_run", func(settings core.RuntimeSettings) bool {
		return settings.SystemRunEnabled
	})
}

func hookManagementEnabledMiddleware() gin.HandlerFunc {
	return runtimeToggleMiddleware("hook_management", func(settings core.RuntimeSettings) bool {
		return settings.HookManagementEnabled
	})
}

func policyManagementEnabledMiddleware() gin.HandlerFunc {
	return runtimeToggleMiddleware("policy_management", func(settings core.RuntimeSettings) bool {
		return settings.PolicyManagementEnabled
	})
}

func requestAuthToken(c *gin.Context) string {
	if token := strings.TrimSpace(c.Query("key")); token != "" {
		return token
	}
	if token := strings.TrimSpace(c.GetHeader("X-API-KEY")); token != "" {
		return token
	}
	if authHeader := strings.TrimSpace(c.GetHeader("Authorization")); authHeader != "" {
		lower := strings.ToLower(authHeader)
		if strings.HasPrefix(lower, "bearer ") {
			return strings.TrimSpace(authHeader[len("Bearer "):])
		}
	}
	return ""
}

func buildRuntimeConfigResponseFromSettings(settings core.RuntimeSettings) core.RuntimeConfigResponse {
	logPath := strings.TrimSpace(settings.LogFilePath)
	logAlive := false
	if settings.LogPersistenceEnabled && logPath != "" {
		if info, err := os.Stat(logPath); err == nil && !info.IsDir() {
			logAlive = true
		}
	}
	settings.MLConfig.LlmAPIKey = ""
	if settings.OtlpHeaders == nil {
		settings.OtlpHeaders = map[string]string{}
	} else {
		cloned := make(map[string]string, len(settings.OtlpHeaders))
		for key, value := range settings.OtlpHeaders {
			if trimmedKey := strings.TrimSpace(key); trimmedKey != "" {
				cloned[trimmedKey] = strings.TrimSpace(value)
			}
		}
		settings.OtlpHeaders = cloned
	}
	return core.RuntimeConfigResponse{
		Runtime:                settings,
		MCPEndpoint:            fmt.Sprintf("http://127.0.0.1:%d/mcp", resolveBackendPort()),
		AuthHeaderName:         "X-API-KEY",
		BearerAuthHeaderName:   "Authorization: Bearer",
		PersistedEventLogPath:  logPath,
		PersistedEventLogAlive: logAlive,
	}
}

func buildRuntimeConfigResponse() core.RuntimeConfigResponse {
	return buildRuntimeConfigResponseFromSettings(runtimeSettingsStore.Snapshot())
}

func getTagName(id uint32) string {
	tagsMu.RLock()
	defer tagsMu.RUnlock()
	if name, ok := tagMap[id]; ok {
		return name
	}
	return fmt.Sprintf("Tag-%d", id)
}

func getTagID(name string) uint32 {
	tagsMu.Lock()
	defer tagsMu.Unlock()
	if id, ok := tagNameToID[name]; ok {
		return id
	}
	id := nextTagID
	tagMap[id] = name
	tagNameToID[name] = id
	nextTagID++
	return id
}

func deltaUint64(current, previous uint64) uint64 {
	if current >= previous {
		return current - previous
	}
	return 0
}

// ── Proto response negotiation ─────────────────────────────────────────

func clientPrefersProto(c *gin.Context) bool {
	accept := c.GetHeader("Accept")
	return strings.Contains(accept, "application/x-protobuf") || strings.Contains(accept, "application/protobuf")
}

func writeProtoResponse(c *gin.Context, code int, msg proto.Message) {
	data, err := proto.Marshal(msg)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "proto marshal failed"})
		return
	}
	c.Data(code, "application/x-protobuf", data)
}

// writeProtoOrJSON sends a protobuf response if the client prefers it, otherwise JSON.
// jsonData should be a value compatible with gin's c.JSON().
func writeProtoOrJSON(c *gin.Context, code int, msg proto.Message, jsonData interface{}) {
	if clientPrefersProto(c) {
		writeProtoResponse(c, code, msg)
	} else {
		c.JSON(code, jsonData)
	}
}

