const hookMarker = "agent-ebpf-hook-active"
const kiroManagedAgent = "agent-ebpf-hook"
const (
	textPreviewLimitBytes   = 64 * 1024
	binaryPreviewLimitBytes = 4 * 1024
	imagePreviewLimitBytes  = 2 * 1024 * 1024
)

var (
	getRealHomeOnce sync.Once
	getRealHomeVal  string
)

// writeFileAsRealUser writes a file with the real user's ownership instead of root
func writeFileAsRealUser(path string, data []byte, perm os.FileMode) error {
	if err := os.WriteFile(path, data, perm); err != nil {
		return err
	}
	if os.Getuid() == 0 {
		if uid, gid, ok := originalInvokerIDs(); ok {
			_ = os.Chown(path, int(uid), int(gid))
		}
	}
	return nil
}

// mkdirAllAsRealUser creates directories with the real user's ownership
func mkdirAllAsRealUser(path string, perm os.FileMode) error {
	if err := os.MkdirAll(path, perm); err != nil {
		return err
	}
	if os.Getuid() == 0 {
		if uid, gid, ok := originalInvokerIDs(); ok {
			_ = os.Chown(path, int(uid), int(gid))
		}
	}
	return nil
}

func getRealHomeDir() string {
	getRealHomeOnce.Do(func() {
		// 1. Check for our own environment variable (passed across sudo/pkexec)
		if h := os.Getenv("AGENT_REAL_HOME"); h != "" {
			getRealHomeVal = h
			return
		}
		// 2. If we are root, try to find the real user who started us via standard envs
		if os.Getuid() == 0 {
			// Try sudo user
			if sudoUser := os.Getenv("SUDO_USER"); sudoUser != "" {
				if u, err := user.Lookup(sudoUser); err == nil {
					getRealHomeVal = u.HomeDir
					return
				}
			}
			// Try pkexec user (PolicyKit)
			if pkexecUid := os.Getenv("PKEXEC_UID"); pkexecUid != "" {
				if u, err := user.LookupId(pkexecUid); err == nil {
					getRealHomeVal = u.HomeDir
					return
				}
			}
			// Try preserved HOME if it's not /root
			if home := os.Getenv("HOME"); home != "" && home != "/root" {
				getRealHomeVal = home
				return
			}
			// Try to find the first non-root user in /home
			if entries, err := os.ReadDir("/home"); err == nil {
				for _, entry := range entries {
					if entry.IsDir() && entry.Name() != "lost+found" {
						getRealHomeVal = filepath.Join("/home", entry.Name())
						return
					}
				}
			}
		}
		// Default to standard lookup
		h, _ := os.UserHomeDir()
		if h == "" || h == "/root" {
			// Final fallback: check for any /home/xxx
			if entries, err := os.ReadDir("/home"); err == nil && len(entries) > 0 {
				for _, entry := range entries {
					if entry.IsDir() && entry.Name() != "lost+found" {
						getRealHomeVal = filepath.Join("/home", entry.Name())
						return
					}
				}
			}
		}
		getRealHomeVal = h
	})
	return getRealHomeVal
}

func getShellConfigPath() string {
	home := getRealHomeDir()
	shell := os.Getenv("SHELL")
	if strings.Contains(shell, "zsh") {
		return filepath.Join(home, ".zshrc")
	}
	return filepath.Join(home, ".bashrc")
}

func isTextLikeMime(mimeType string) bool {
	if mimeType == "" {
		return false
	}
	mt := strings.ToLower(mimeType)
	return strings.HasPrefix(mt, "text/") ||
		strings.Contains(mt, "json") ||
		strings.Contains(mt, "xml") ||
		strings.Contains(mt, "javascript") ||
		strings.Contains(mt, "typescript") ||
		strings.Contains(mt, "markdown") ||
		strings.Contains(mt, "yaml") ||
		strings.Contains(mt, "toml") ||
		strings.Contains(mt, "x-sh") ||
		strings.Contains(mt, "x-c") ||
		strings.Contains(mt, "x-cpp") ||
		strings.Contains(mt, "x-python") ||
		strings.Contains(mt, "x-go") ||
		strings.Contains(mt, "x-rust") ||
		strings.Contains(mt, "x-java")
}

func detectTextEncoding(data []byte) string {
	if len(data) >= 2 {
		if data[0] == 0xff && data[1] == 0xfe {
			return "utf-16le"
		}
		if data[0] == 0xfe && data[1] == 0xff {
			return "utf-16be"
		}
	}
	if len(data) >= 16 {
		evenNUL := 0
		oddNUL := 0
		for i, b := range data {
			if b != 0 {
				continue
			}
			if i%2 == 0 {
				evenNUL++
			} else {
				oddNUL++
			}
		}
		pairs := len(data) / 2
		if pairs > 0 && oddNUL*2 > pairs {
			return "utf-16le"
		}
		if pairs > 0 && evenNUL*2 > pairs {
			return "utf-16be"
		}
	}
	return "utf-8"
}

func decodeTextPreview(data []byte, encoding string) string {
	if encoding != "utf-16le" && encoding != "utf-16be" {
		return string(data)
	}
	start := 0
	if len(data) >= 2 && ((data[0] == 0xff && data[1] == 0xfe) || (data[0] == 0xfe && data[1] == 0xff)) {
		start = 2
	}
	if (len(data)-start)%2 != 0 {
		data = data[:len(data)-1]
	}
	units := make([]uint16, 0, (len(data)-start)/2)
	for i := start; i+1 < len(data); i += 2 {
		if encoding == "utf-16le" {
			units = append(units, uint16(data[i])|uint16(data[i+1])<<8)
		} else {
			units = append(units, uint16(data[i])<<8|uint16(data[i+1]))
		}
	}
	return string(utf16.Decode(units))
}

func detectLanguage(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	if len(ext) > 0 && ext[0] == '.' {
		ext = ext[1:]
	}
	switch ext {
	case "cpp", "cc", "cxx", "hpp":
		return "cpp"
	case "c", "h":
		return "c"
	case "py":
		return "python"
	case "js", "mjs":
		return "javascript"
	case "ts", "mts":
		return "typescript"
	case "go":
		return "go"
	case "rs":
		return "rust"
	case "md":
		return "markdown"
	case "sh", "bash":
		return "bash"
	case "yml", "yaml":
		return "yaml"
	case "json":
		return "json"
	case "html":
		return "html"
	case "css":
		return "css"
	case "sql":
		return "sql"
	case "java":
		return "java"
	default:
		return ext
	}
}

func buildFilePreview(path string) (*FilePreviewResponse, error) {
	cleanPath := filepath.Clean(strings.TrimSpace(path))
	absPath, err := filepath.Abs(cleanPath)
	if err != nil {
		return nil, err
	}

	info, err := os.Stat(absPath)
	if err != nil {
		return nil, err
	}

	res := &FilePreviewResponse{
		Path:      absPath,
		Name:      info.Name(),
		ParentDir: filepath.Dir(absPath),
		IsDir:     info.IsDir(),
		Size:      info.Size(),
		Mode:      info.Mode().String(),
		ModTime:   info.ModTime(),
	}
	if absPath == "/" {
		res.ParentDir = "/"
	}

	if info.IsDir() {
		res.PreviewType = "directory"
		return res, nil
	}

	file, err := os.Open(absPath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	head := make([]byte, 512)
	n, readErr := file.Read(head)
	if readErr != nil && readErr != io.EOF {
		return nil, readErr
	}
	head = head[:n]

	mimeType := mime.TypeByExtension(strings.ToLower(filepath.Ext(absPath)))
	if mimeType == "" && len(head) > 0 {
		mimeType = http.DetectContentType(head)
	}
	// Explicit correction for webm which is often misidentified as audio/webm
	if strings.ToLower(filepath.Ext(absPath)) == ".webm" && strings.HasPrefix(mimeType, "audio/") {
		mimeType = "video/webm"
	}
	if mimeType == "" {
		mimeType = "application/octet-stream"
	}
	res.MimeType = mimeType
	res.Hexable = true

	if len(head) >= 4 && head[0] == 0x7f && head[1] == 'E' && head[2] == 'L' && head[3] == 'F' {
		res.PreviewType = "elf"
		res.MimeType = "application/x-elf"
		return res, nil
	}

	if _, err := file.Seek(0, io.SeekStart); err != nil {
		return nil, err
	}

	if mimeType == "application/pdf" || strings.ToLower(filepath.Ext(absPath)) == ".pdf" {
		res.PreviewType = "pdf"
		res.MimeType = "application/pdf"
		return res, nil
	}

	if strings.HasPrefix(mimeType, "image/") {
		res.PreviewType = "image"
		if info.Size() > imagePreviewLimitBytes {
			res.Content = fmt.Sprintf("Image is too large to preview inline (limit: %d MiB).", imagePreviewLimitBytes/(1024*1024))
			res.Truncated = true
			return res, nil
		}

		data, err := io.ReadAll(io.LimitReader(file, imagePreviewLimitBytes+1))
		if err != nil {
			return nil, err
		}
		if len(data) > imagePreviewLimitBytes {
			data = data[:imagePreviewLimitBytes]
			res.Truncated = true
		}
		res.DataURL = fmt.Sprintf("data:%s;base64,%s", mimeType, base64.StdEncoding.EncodeToString(data))
		return res, nil
	}

	if strings.HasPrefix(mimeType, "video/") || strings.HasPrefix(mimeType, "audio/") {
		res.PreviewType = "video" // We'll use 'video' as a generic media type for now
		return res, nil
	}

	previewLimit := int64(binaryPreviewLimitBytes)
	if isTextLikeMime(mimeType) {
		previewLimit = textPreviewLimitBytes
	}

	data, err := io.ReadAll(io.LimitReader(file, previewLimit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > previewLimit {
		data = data[:previewLimit]
		res.Truncated = true
	}
	if info.Size() > int64(len(data)) {
		res.Truncated = true
	}

	encoding := detectTextEncoding(data)
	if isTextLikeMime(mimeType) || utf8.Valid(data) || encoding != "utf-8" {
		res.PreviewType = "text"
		res.Language = detectLanguage(absPath)
		res.Encoding = encoding
		res.Content = decodeTextPreview(data, encoding)
		res.Streamable = res.Truncated
		return res, nil
	}

	res.PreviewType = "binary"
	res.Content = hex.Dump(data)
	return res, nil
}

func getZramStats() (used, total uint64) {
	zramDevices, _ := filepath.Glob("/sys/block/zram*")
	for _, dev := range zramDevices {
		// disksize is the total uncompressed swap capacity of this zram device
		if data, err := os.ReadFile(filepath.Join(dev, "disksize")); err == nil {
			val := strings.TrimSpace(string(data))
			if sz, err := strconv.ParseUint(val, 10, 64); err == nil {
				total += sz
			}
		}
		// mm_stat provides detailed memory usage: orig_data_size compr_data_size mem_used_total ...
		if data, err := os.ReadFile(filepath.Join(dev, "mm_stat")); err == nil {
			var memUsed uint64
			fields := strings.Fields(string(data))
			if len(fields) >= 3 {
				memUsed, _ = strconv.ParseUint(fields[2], 10, 64)
				// used is the actual physical memory consumed by zram (mem_used_total)
				used += memUsed
			}
		} else {
			// fallback to compr_data_size (compressed size) if mm_stat is not available
			if data, err := os.ReadFile(filepath.Join(dev, "compr_data_size")); err == nil {
				var c uint64
				fmt.Sscanf(string(data), "%d", &c)
				used += c
			}
		}
	}
	return
}

func refreshHooksPaths() {
	home := getRealHomeDir()
	log.Printf("[DEBUG] Resolving agent config paths for home: %s", home)
	for i := range availableHooks {
		if availableHooks[i].HookType == HookTypeNative {
			switch availableHooks[i].ID {
			case "claude":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".claude", "settings.json")
			case "gemini":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".gemini", "settings.json")
			case "codex":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".codex", "hooks.json")
				availableHooks[i].NativeFeatureConfigPath = filepath.Join(home, ".codex", "config.toml")
			case "kiro":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".kiro", "agents", "agent-ebpf-hook.json")
			case "copilot":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".copilot", "config.json")
			case "augment":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".augment", "settings.json")
			case "antigravity":
				availableHooks[i].NativeConfigPath = filepath.Join(home, ".gemini", "antigravity-cli", "plugins", hookMarker, "hooks.json")
			}
		}
	}
}

// ---- merged from helpers_resolve.go ----

func resolveBackendPort() int {
	if raw := strings.TrimSpace(os.Getenv("AGENT_BACKEND_PORT")); raw != "" {
		if port, err := strconv.Atoi(raw); err == nil && port > 0 {
			return port
		}
	}

	candidates := []string{".port"}
	if _, sourceFile, _, ok := runtime.Caller(0); ok {
		candidates = append(candidates, filepath.Join(filepath.Dir(sourceFile), ".port"))
	}

	for _, candidate := range candidates {
		b, err := os.ReadFile(candidate)
		if err != nil {
			continue
		}
		if port, err := strconv.Atoi(strings.TrimSpace(string(b))); err == nil && port > 0 {
			return port
		}
	}

	return 8080
}

func resolveHookCallbackURL() string {
	if raw := strings.TrimSpace(os.Getenv("AGENT_HOOK_ENDPOINT")); raw != "" {
		return raw
	}
	return fmt.Sprintf("http://127.0.0.1:%d/hooks/event", resolveBackendPort())
}

func resolveWrapperPath() string {
	if override := os.Getenv("AGENT_WRAPPER_PATH"); override != "" {
		if info, err := os.Stat(override); err == nil && !info.IsDir() {
			return override
		}
	}

	if _, sourceFile, _, ok := runtime.Caller(0); ok {
		sourceDir := filepath.Dir(sourceFile)
		candidates := []string{
			filepath.Join(sourceDir, "..", "agent-wrapper"),
			filepath.Join(sourceDir, "agent-wrapper"),
			filepath.Join(sourceDir, "..", "..", "agent-wrapper"),
		}
		for _, cnd := range candidates {
			if info, err := os.Stat(cnd); err == nil && !info.IsDir() {
				return cnd
			}
		}
	}

	if cwd, err := os.Getwd(); err == nil {
		for _, rel := range []string{
			"agent-wrapper",
			"../agent-wrapper",
			"../../agent-wrapper",
			"../../../agent-wrapper",
		} {
			cnd := filepath.Clean(filepath.Join(cwd, rel))
			if info, err := os.Stat(cnd); err == nil && !info.IsDir() {
				return cnd
			}
		}
	}

	if execPath, err := os.Executable(); err == nil {
		execDir := filepath.Dir(execPath)
		for _, rel := range []string{
			"agent-wrapper",
			"../agent-wrapper",
			"../../agent-wrapper",
		} {
			cnd := filepath.Clean(filepath.Join(execDir, rel))
			if info, err := os.Stat(cnd); err == nil && !info.IsDir() {
				return cnd
			}
		}
	}

	return ""
}

func resolveShellCandidate(candidate string) string {
	candidate = strings.TrimSpace(candidate)
	if candidate == "" {
		return ""
	}

	if strings.ContainsRune(candidate, os.PathSeparator) {
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() && info.Mode()&0111 != 0 {
			return candidate
		}
		return ""
	}

	if resolved, err := exec.LookPath(candidate); err == nil {
		return resolved
	}

	for _, prefix := range []string{"/bin/", "/usr/bin/", "/usr/local/bin/"} {
		path := prefix + candidate
		if info, err := os.Stat(path); err == nil && !info.IsDir() && info.Mode()&0111 != 0 {
			return path
		}
	}

	return ""
}

func resolveShellPath(requested string) string {
	requested = strings.TrimSpace(requested)

	switch strings.ToLower(requested) {
	case "", "auto":
		for _, candidate := range []string{"fish", "zsh", "bash", "ash", "sh"} {
			if resolved := resolveShellCandidate(candidate); resolved != "" {
				return resolved
			}
		}
		return ""
	case "system", "env":
		if resolved := resolveShellCandidate(os.Getenv("SHELL")); resolved != "" {
			return resolved
		}
		for _, candidate := range []string{"fish", "zsh", "bash", "ash", "sh"} {
			if resolved := resolveShellCandidate(candidate); resolved != "" {
				return resolved
			}
		}
		return ""
	default:
		return resolveShellCandidate(requested)
	}
}

func resolveShellWorkDir() string {
	if override := os.Getenv("AGENT_SHELL_DIR"); override != "" {
		if info, err := os.Stat(override); err == nil && info.IsDir() {
			return override
		}
	}

	if _, sourceFile, _, ok := runtime.Caller(0); ok {
		repoRoot := filepath.Dir(filepath.Dir(sourceFile))
		if info, err := os.Stat(repoRoot); err == nil && info.IsDir() {
			return repoRoot
		}
	}

	if cwd, err := os.Getwd(); err == nil {
		return cwd
	}

	if home, err := os.UserHomeDir(); err == nil {
		return home
	}

	return "/"
}

func setEnvValue(env []string, key, value string) []string {
	prefix := key + "="
	replaced := false
	for i, entry := range env {
		if strings.HasPrefix(entry, prefix) {
			env[i] = prefix + value
			replaced = true
			break
		}
	}
	if !replaced {
		env = append(env, prefix+value)
	}
	return env
}

func writePortFile(actualPort int) {
	data := []byte(fmt.Sprintf("%d", actualPort))
	_ = os.WriteFile(".port", data, 0644)

	if _, sourceFile, _, ok := runtime.Caller(0); ok {
		backendDir := filepath.Dir(sourceFile)
		_ = os.WriteFile(filepath.Join(backendDir, ".port"), data, 0644)
	}
}

// ---- merged from hooks.go ----

func ensureHookRelayScript(h HookDef) (string, error) {
	scriptDir := filepath.Join(filepath.Dir(h.NativeConfigPath), "hooks")
	if err := mkdirAllAsRealUser(scriptDir, 0755); err != nil {
		return "", err
	}

	scriptPath := hookRelayScriptPath(h)
	scriptContent := buildHookRelayScript(h)

	if err := writeFileAsRealUser(scriptPath, []byte(scriptContent), 0755); err != nil {
		return "", err
	}
	return scriptPath, nil
}

func buildHookRelayScript(h HookDef) string {
	if h.ID == "antigravity" {
		return buildAntigravityHookRelayScript(h)
	}
	return buildGenericHookRelayScript(h)
}

func buildGenericHookRelayScript(h HookDef) string {
	hookSecret := runtimeSettingsStore.HookSecret(h.ID)
	return fmt.Sprintf(`#!/usr/bin/env bash
hook_event="${1:-${AGENT_EBPF_HOOK_EVENT:-}}"
tmp_file="$(mktemp "${TMPDIR:-/tmp}/agent-ebpf-hook.XXXXXX")" || exit 0
trap 'rm -f "$tmp_file"' EXIT
cat >"$tmp_file"
event_header=()
if [ -n "$hook_event" ]; then
  event_header=(-H "X-Agent-Hook-Event: $hook_event")
fi
curl -fsS -X POST '%s' \
  -H 'Content-Type: application/json' \
  -H 'X-Agent-CLI: %s' \
  -H 'X-Agent-Hook-Secret: %s' \
  "${event_header[@]}" \
  --data-binary "@$tmp_file" \
  >/dev/null 2>&1 || true
`, resolveHookCallbackURL(), h.ID, hookSecret)
}

// installNativeHook injects a hook into the agent CLI's settings (JSON or TOML)
// that POSTs every tool call to our backend for inspection.
func installNativeHook(h HookDef) error {
	if h.ID == "kiro" {
		return installKiroNativeHook(h)
	}
	if h.ID == "antigravity" {
		return installAntigravityNativeHook(h)
	}

	cleanupLegacyCodexHookConfig(h)

	if h.NativeFeatureConfigPath != "" {
		if err := ensureCodexHooksFeatureEnabled(h.NativeFeatureConfigPath); err != nil {
			return err
		}
	}

	cfgPath := h.NativeConfigPath
	if err := mkdirAllAsRealUser(filepath.Dir(cfgPath), 0755); err != nil {
		return err
	}

	// Read existing config (may not exist yet).
	var cfg map[string]interface{}
	if b, err := os.ReadFile(cfgPath); err == nil {
		if h.ConfigFormat == ConfigFormatTOML {
			_ = toml.Unmarshal(b, &cfg)
		} else {
			_ = json.Unmarshal(b, &cfg)
		}
	}
	if cfg == nil {
		cfg = make(map[string]interface{})
	}

	// Build the hook entry.
	if _, err := ensureHookRelayScript(h); err != nil {
		return err
	}
	hookCmd := hookCommand(h, h.NativeHookEvent)

	hookEntry := map[string]interface{}{
		"type":          "command",
		"command":       hookCmd,
		"statusMessage": "agent-ebpf-hook-active: inspecting...",
	}
	switch h.ID {
	case "codex":
		// Codex doesn't support async hooks
	case "augment":
		// Augment uses `timeout` (ms) rather than async
		hookEntry["timeout"] = 5000
	default:
		hookEntry["async"] = true
	}
	matcher := map[string]interface{}{"hooks": []interface{}{hookEntry}}
	if h.NativeMatcher != "" {
		matcher["matcher"] = h.NativeMatcher
	} else {
		matcher["matcher"] = ""
	}

	// Merge into existing hooks[eventName] array.
	hooks, _ := cfg["hooks"].(map[string]interface{})
	if hooks == nil {
		hooks = make(map[string]interface{})
	}
	eventHooks, _ := hooks[h.NativeHookEvent].([]interface{})

	// Remove any existing agent-ebpf-hook entry to avoid duplicates.
	filtered := []interface{}{}
	for _, m := range eventHooks {
		if mm, ok := m.(map[string]interface{}); ok {
			hs, _ := mm["hooks"].([]interface{})
			isOurs := false
			for _, h := range hs {
				if hm, ok := h.(map[string]interface{}); ok {
					if cmd, _ := hm["command"].(string); strings.Contains(cmd, hookMarker) {
						isOurs = true
					}
				}
			}
			if !isOurs {
				filtered = append(filtered, m)
			}
		}
	}
	hooks[h.NativeHookEvent] = append(filtered, matcher)
	cfg["hooks"] = hooks

	var (
		b   []byte
		err error
	)
	if h.ConfigFormat == ConfigFormatTOML {
		b, err = toml.Marshal(cfg)
	} else {
		b, err = json.MarshalIndent(cfg, "", "  ")
	}

	if err != nil {
		return err
	}
	return writeFileAsRealUser(cfgPath, b, 0644)
}

// uninstallNativeHook removes the agent-ebpf hook from settings.
func uninstallNativeHook(h HookDef) error {
	if h.ID == "kiro" {
		return uninstallKiroNativeHook(h)
	}
	if h.ID == "antigravity" {
		return uninstallAntigravityNativeHook(h)
	}

	b, err := os.ReadFile(h.NativeConfigPath)
	if err != nil {
		_ = os.Remove(hookRelayScriptPath(h))
		cleanupLegacyCodexHookConfig(h)
		return nil // nothing to do
	}
	var cfg map[string]interface{}
	if h.ConfigFormat == ConfigFormatTOML {
		if err := toml.Unmarshal(b, &cfg); err != nil {
			return err
		}
	} else {
		if err := json.Unmarshal(b, &cfg); err != nil {
			return err
		}
	}

	hooks, _ := cfg["hooks"].(map[string]interface{})
	if hooks == nil {
		_ = os.Remove(hookRelayScriptPath(h))
		cleanupLegacyCodexHookConfig(h)
		return nil
	}
	eventHooks, _ := hooks[h.NativeHookEvent].([]interface{})
	filtered := []interface{}{}
	for _, m := range eventHooks {
		if mm, ok := m.(map[string]interface{}); ok {
			hs, _ := mm["hooks"].([]interface{})
			isOurs := false
			for _, h := range hs {
				if hm, ok := h.(map[string]interface{}); ok {
					if cmd, _ := hm["command"].(string); strings.Contains(cmd, hookMarker) {
						isOurs = true
					}
				}
			}
			if !isOurs {
				filtered = append(filtered, m)
			}
		}
	}
	if len(filtered) == 0 {
		delete(hooks, h.NativeHookEvent)
	} else {
		hooks[h.NativeHookEvent] = filtered
	}
	if len(hooks) == 0 {
		delete(cfg, "hooks")
	}

	var out []byte
	if h.ConfigFormat == ConfigFormatTOML {
		out, err = toml.Marshal(cfg)
	} else {
		out, err = json.MarshalIndent(cfg, "", "  ")
	}

	if err != nil {
		return err
	}
	if err := writeFileAsRealUser(h.NativeConfigPath, out, 0644); err != nil {
		return err
	}
	_ = os.Remove(hookRelayScriptPath(h))

	cleanupLegacyCodexHookConfig(h)
	return nil
}

// ---- merged from httpparsertls.go ----

const tlsMaxBodySize = 16 * 1024

const tlsRedactedValue = "***REDACTED***"

var tlsSensitiveQueryKeys = map[string]struct{}{
	"access_token":  {},
	"api_key":       {},
	"apikey":        {},
	"auth":          {},
	"authorization": {},
	"bearer":        {},
	"client_secret": {},
	"key":           {},
	"password":      {},
	"secret":        {},
	"session":       {},
	"token":         {},
}

var tlsBearerTokenPattern = regexp.MustCompile(`(?i)\b(bearer\s+)[A-Za-z0-9._~+/=-]+`)
var tlsInlineSecretPattern = regexp.MustCompile(`(?i)(api[_-]?key|access[_-]?token|auth[_-]?token|client[_-]?secret|password|secret|token)=([^\s&]+)`)

func parseTLSPlaintext(fragment completedTLSFragment) TLSPlaintextEvent {
	capturedLen := len(fragment.Payload)
	originalLen := int(fragment.OriginalLen)
	if originalLen == 0 {
		originalLen = int(fragment.TotalLen)
	}
	event := TLSPlaintextEvent{
		Type:         "raw",
		Timestamp:    time.Unix(0, int64(fragment.TimestampNS)).UTC(),
		PID:          fragment.PID,
		TGID:         fragment.TGID,
		Comm:         fragment.Comm,
		Direction:    tlsDirectionLabel(fragment.Direction),
		Lib:          tlsLibLabel(fragment.LibType),
		Function:     tlsFunctionLabel(fragment.Function),
		CapturedLen:  capturedLen,
		OriginalLen:  originalLen,
		Truncated:    fragment.Flags&tlsFlagTruncated != 0 || originalLen > capturedLen,
		RawAvailable: false,
	}

	if req, ok := parseTLSPlaintextHTTPRequest(fragment.Payload); ok {
		collectorMetricsStore.RecordAgentSightCounter("tls.http_request.parsed")
		return buildTLSPlaintextHTTPRequestEvent(event, req)
	}
	if resp, ok := parseTLSPlaintextHTTPResponse(fragment.Payload); ok {
		collectorMetricsStore.RecordAgentSightCounter("tls.http_response.parsed")
		return buildTLSPlaintextHTTPResponseEvent(event, resp)
	}

	event.RawHexDump = hexDump(fragment.Payload)
	collectorMetricsStore.RecordAgentSightCounter("tls.raw")
	return event
}

type tlsHTTPRequest struct {
	req      *http.Request
	body     []byte
	bodySize int
	host     string
	content  string
}

type tlsHTTPResponse struct {
	resp     *http.Response
	body     []byte
	bodySize int
	content  string
}

func parseTLSPlaintextHTTPRequest(payload []byte) (*tlsHTTPRequest, bool) {
	if !looksLikeTLSHTTPRequest(payload) {
		return nil, false
	}

	req, err := http.ReadRequest(bufio.NewReader(bytes.NewReader(payload)))
	if err != nil {
		return nil, false
	}
	body, bodySize, err := readBoundedTLSBody(req.Body)
	if err != nil {
		_ = req.Body.Close()
		return nil, false
	}
	_ = req.Body.Close()
	contentType := req.Header.Get("Content-Type")
	if contentType == "" {
		contentType = req.Header.Get("content-type")
	}
	return &tlsHTTPRequest{
		req:      req,
		body:     body,
		bodySize: bodySize,
		host:     req.Host,
		content:  contentType,
	}, true
}

func looksLikeTLSHTTPRequest(payload []byte) bool {
	lineEnd := bytes.IndexAny(payload, "\r\n")
	if lineEnd <= 0 {
		return false
	}
	firstLine := string(payload[:lineEnd])
	parts := strings.Split(firstLine, " ")
	if len(parts) != 3 {
		return false
	}
	if !validTLSHTTPRequestMethod(parts[0]) {
		return false
	}
	if parts[1] == "" {
		return false
	}
	if !strings.HasPrefix(parts[2], "HTTP/1.") {
		return false
	}
	return true
}

func validTLSHTTPRequestMethod(method string) bool {
	switch method {
	case http.MethodGet, http.MethodPost, http.MethodPut, http.MethodPatch, http.MethodDelete, http.MethodHead, http.MethodOptions, http.MethodTrace, http.MethodConnect:
		return true
	default:
		return false
	}
}

func parseTLSPlaintextHTTPResponse(payload []byte) (*tlsHTTPResponse, bool) {
	if !bytes.HasPrefix(payload, []byte("HTTP/")) {
		return nil, false
	}
	resp, err := http.ReadResponse(bufio.NewReader(bytes.NewReader(payload)), &http.Request{Method: http.MethodGet})
	if err != nil {
		return nil, false
	}
	body, bodySize, err := readBoundedTLSBody(resp.Body)
	if err != nil {
		_ = resp.Body.Close()
		return nil, false
	}
	_ = resp.Body.Close()
	contentType := resp.Header.Get("Content-Type")
	if contentType == "" {
		contentType = resp.Header.Get("content-type")
	}
	return &tlsHTTPResponse{
		resp:     resp,
		body:     body,
		bodySize: bodySize,
		content:  contentType,
	}, true
}

func buildTLSPlaintextHTTPRequestEvent(base TLSPlaintextEvent, parsed *tlsHTTPRequest) TLSPlaintextEvent {
	base.Type = "http_request"
	base.Method = parsed.req.Method
	base.URL = sanitizeTLSURL(parsed.req.URL.String())
	base.Host = parsed.host
	base.Headers = sanitizeTLSHeaders(parsed.req.Header)
	base.ContentType = parsed.content
	base.BodySize = parsed.bodySize
	base.Body, base.Truncated = formatTLSPlaintextBody(parsed.body, base.ContentType)
	base.Body = sanitizeTLSBody(base.Body, base.ContentType)
	base.RedactionState = "sanitized"
	annotateTLSSSEEvent(&base)
	base.RawAvailable = true
	return base
}

func buildTLSPlaintextHTTPResponseEvent(base TLSPlaintextEvent, parsed *tlsHTTPResponse) TLSPlaintextEvent {
	base.Type = "http_response"
	base.StatusCode = parsed.resp.StatusCode
	base.Headers = sanitizeTLSHeaders(parsed.resp.Header)
	base.ContentType = parsed.content
	base.BodySize = parsed.bodySize
	base.Body, base.Truncated = formatTLSPlaintextBody(parsed.body, base.ContentType)
	base.Body = sanitizeTLSBody(base.Body, base.ContentType)
	base.RedactionState = "sanitized"
	annotateTLSSSEEvent(&base)
	base.RawAvailable = true
	return base
}

func sanitizeTLSHeaders(headers http.Header) map[string]string {
	if len(headers) == 0 {
		return nil
	}
	redacted := map[string]string{
		"authorization":       tlsRedactedValue,
		"proxy-authorization": tlsRedactedValue,
		"x-api-key":           tlsRedactedValue,
		"cookie":              tlsRedactedValue,
		"set-cookie":          tlsRedactedValue,
	}
	out := make(map[string]string, len(headers))
	for key, values := range headers {
		lower := strings.ToLower(key)
		if replacement, ok := redacted[lower]; ok {
			out[lower] = replacement
			continue
		}
		out[lower] = strings.Join(values, ", ")
	}
	return out
}

func sanitizeTLSURL(rawURL string) string {
	if strings.TrimSpace(rawURL) == "" {
		return rawURL
	}
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return sanitizeTLSInlineSecrets(rawURL)
	}
	query := parsed.Query()
	changed := false
	for key := range query {
		if isTLSSensitiveKey(key) {
			query.Set(key, tlsRedactedValue)
			changed = true
		}
	}
	if !changed {
		return sanitizeTLSInlineSecrets(rawURL)
	}
	collectorMetricsStore.RecordAgentSightCounter("tls.redaction.url")
	parsed.RawQuery = query.Encode()
	return parsed.String()
}

func sanitizeTLSBody(body, contentType string) string {
	if strings.TrimSpace(body) == "" {
		return body
	}
	if looksLikeTLSJSON(contentType, []byte(body)) {
		var payload any
		if err := json.Unmarshal([]byte(body), &payload); err == nil {
			if sanitizeTLSJSONValue(&payload) {
				collectorMetricsStore.RecordAgentSightCounter("tls.redaction.body")
				if redacted, err := json.MarshalIndent(payload, "", "  "); err == nil {
					return string(redacted)
				}
			}
		}
	}
	if strings.Contains(strings.ToLower(contentType), "x-www-form-urlencoded") {
		if values, err := url.ParseQuery(body); err == nil {
			changed := false
			for key := range values {
				if isTLSSensitiveKey(key) {
					values.Set(key, tlsRedactedValue)
					changed = true
				}
			}
			if changed {
				collectorMetricsStore.RecordAgentSightCounter("tls.redaction.body")
				return values.Encode()
			}
		}
	}
	return sanitizeTLSInlineSecrets(body)
}

func sanitizeTLSJSONValue(value *any) bool {
	switch typed := (*value).(type) {
	case map[string]any:
		changed := false
		for key, child := range typed {
			if isTLSSensitiveKey(key) {
				typed[key] = tlsRedactedValue
				changed = true
				continue
			}
			childValue := child
			if sanitizeTLSJSONValue(&childValue) {
				typed[key] = childValue
				changed = true
			}
		}
		return changed
	case []any:
		changed := false
		for i, child := range typed {
			childValue := child
			if sanitizeTLSJSONValue(&childValue) {
				typed[i] = childValue
				changed = true
			}
		}
		return changed
	case string:
		redacted := sanitizeTLSInlineSecrets(typed)
		if redacted != typed {
			*value = redacted
			return true
		}
	}
	return false
}

func isTLSSensitiveKey(key string) bool {
	normalized := strings.ToLower(strings.TrimSpace(key))
	normalized = strings.ReplaceAll(normalized, "-", "_")
	if _, ok := tlsSensitiveQueryKeys[normalized]; ok {
		return true
	}
	return strings.Contains(normalized, "token") || strings.Contains(normalized, "secret") || strings.Contains(normalized, "password") || strings.Contains(normalized, "api_key")
}

func sanitizeTLSInlineSecrets(value string) string {
	encodedRedactedValue := url.QueryEscape(tlsRedactedValue)
	placeholder := "__TLS_REDACTED_VALUE__"
	protected := strings.ReplaceAll(value, encodedRedactedValue, placeholder)
	redacted := tlsBearerTokenPattern.ReplaceAllString(protected, `${1}`+tlsRedactedValue)
	redacted = tlsInlineSecretPattern.ReplaceAllString(redacted, `${1}=`+tlsRedactedValue)
	redacted = strings.ReplaceAll(redacted, placeholder, encodedRedactedValue)
	if redacted != value {
		collectorMetricsStore.RecordAgentSightCounter("tls.redaction.inline")
	}
	return redacted
}

func annotateTLSSSEEvent(event *TLSPlaintextEvent) {
	if event == nil || !strings.Contains(strings.ToLower(event.ContentType), "text/event-stream") {
		return
	}
	event.Type = "sse_message"
	collectorMetricsStore.RecordAgentSightCounter("tls.sse.parsed")
	var dataParts []string
	for _, line := range strings.Split(event.Body, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "event:") && event.SSEEvent == "" {
			event.SSEEvent = strings.TrimSpace(strings.TrimPrefix(trimmed, "event:"))
		}
		if strings.HasPrefix(trimmed, "data:") {
			data := strings.TrimSpace(strings.TrimPrefix(trimmed, "data:"))
			if data != "" {
				dataParts = append(dataParts, data)
			}
		}
	}
	if len(dataParts) > 0 {
		event.SSEDataCount = len(dataParts)
		sum := sha256.Sum256([]byte(strings.Join(dataParts, "\n")))
		event.SSEDataDigest = "sha256:" + hex.EncodeToString(sum[:8])
	}
}

func formatTLSPlaintextBody(body []byte, contentType string) (string, bool) {
	if len(body) == 0 {
		return "", false
	}

	formatted := body
	if looksLikeTLSJSON(contentType, body) {
		if pretty, err := prettyPrintJSON(body); err == nil {
			formatted = pretty
		}
	}

	truncated := len(body) > tlsMaxBodySize || len(formatted) > tlsMaxBodySize
	if len(formatted) > tlsMaxBodySize {
		formatted = formatted[:tlsMaxBodySize]
	}
	return string(formatted), truncated
}

func readBoundedTLSBody(r io.Reader) ([]byte, int, error) {
	limited := io.LimitReader(r, tlsMaxBodySize+1)
	body, err := io.ReadAll(limited)
	if err != nil && !errors.Is(err, io.ErrUnexpectedEOF) {
		return nil, 0, err
	}
	return body, len(body), nil
}

func looksLikeTLSJSON(contentType string, body []byte) bool {
	lower := strings.ToLower(contentType)
	if strings.Contains(lower, "json") || strings.Contains(lower, "+json") {
		return json.Valid(bytes.TrimSpace(body))
	}
	trimmed := bytes.TrimSpace(body)
	return len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') && json.Valid(trimmed)
}

func prettyPrintJSON(body []byte) ([]byte, error) {
	var buf bytes.Buffer
	if err := json.Indent(&buf, body, "", "  "); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func hexDump(payload []byte) string {
	if len(payload) == 0 {
		return ""
	}
	var b strings.Builder
	for i, v := range payload {
		if i > 0 {
			b.WriteByte(' ')
		}
		_, _ = fmt.Fprintf(&b, "%02x", v)
	}
	return b.String()
}

func tlsDirectionLabel(direction uint8) string {
	switch direction {
	case tlsDirectionRecv:
		return "recv"
	case tlsDirectionSend:
		return "send"
	default:
		return fmt.Sprintf("direction_%d", direction)
	}
}

func tlsLibLabel(lib uint8) string {
	switch lib {
	case tlsLibOpenSSL:
		return "openssl"
	case tlsLibGo:
		return "go"
	case tlsLibGnuTLS:
		return "gnutls"
	case tlsLibNSS:
		return "nss"
	default:
		return fmt.Sprintf("lib_%d", lib)
	}
}

func tlsFunctionLabel(function uint8) string {
	switch function {
	case tlsFuncSSLWrite:
		return "SSL_write"
	case tlsFuncSSLRead:
		return "SSL_read"
	case tlsFuncSSLWriteEx:
		return "SSL_write_ex"
	case tlsFuncSSLReadEx:
		return "SSL_read_ex"
	case tlsFuncGnuTLSRecordSend:
		return "gnutls_record_send"
	case tlsFuncGnuTLSRecordRecv:
		return "gnutls_record_recv"
	case tlsFuncPRWrite:
		return "PR_Write"
	case tlsFuncPRRead:
		return "PR_Read"
	case tlsFuncGoConnWrite:
		return "crypto/tls.(*Conn).Write"
	case tlsFuncGoConnRead:
		return "crypto/tls.(*Conn).Read"
	default:
		return ""
	}
}

// ---- merged from httpstreamassemblertls.go ----

const tlsHTTPStreamMaxBuffer = 512 * 1024
const tlsHTTPStreamRequestQueueLimit = 64

type tlsHTTPStreamKey struct {
	PID     uint32
	TGID    uint32
	LibType uint8
}

type tlsHTTPBufferKey struct {
	PID       uint32
	TGID      uint32
	LibType   uint8
	Direction uint8
}

type pendingTLSHTTPStream struct {
	firstSeen time.Time
	lastSeen  time.Time
	meta      completedTLSFragment
	buffer    []byte
	flags     uint8
}

type tlsHTTPRequestContext struct {
	Method string
	URL    string
	Host   string
}

type TLSHTTPStreamAssembler struct {
	mu       sync.Mutex
	pending  map[tlsHTTPBufferKey]*pendingTLSHTTPStream
	requests map[tlsHTTPStreamKey][]tlsHTTPRequestContext
	timeout  time.Duration
	dropped  int
}

func NewTLSHTTPStreamAssembler(timeout time.Duration) *TLSHTTPStreamAssembler {
	if timeout <= 0 {
		timeout = 10 * time.Second
	}
	return &TLSHTTPStreamAssembler{
		pending:  make(map[tlsHTTPBufferKey]*pendingTLSHTTPStream),
		requests: make(map[tlsHTTPStreamKey][]tlsHTTPRequestContext),
		timeout:  timeout,
	}
}

func (a *TLSHTTPStreamAssembler) Add(fragment completedTLSFragment) []TLSPlaintextEvent {
	if a == nil || len(fragment.Payload) == 0 {
		return nil
	}
	now := time.Unix(0, int64(fragment.TimestampNS))
	if now.IsZero() {
		now = time.Now()
	}

	a.mu.Lock()
	defer a.mu.Unlock()

	a.cleanupExpiredLocked(now)

	key := tlsHTTPBufferKey{PID: fragment.PID, TGID: fragment.TGID, LibType: fragment.LibType, Direction: fragment.Direction}
	pending := a.pending[key]
	if pending == nil {
		payload := trimTLSHTTPMessageSeparators(fragment.Payload)
		if !looksLikeTLSHTTPMessageStart(payload, fragment.Direction) {
			return nil
		}
		meta := fragment
		meta.Payload = nil
		pending = &pendingTLSHTTPStream{
			firstSeen: now,
			lastSeen:  now,
			meta:      meta,
			buffer:    append([]byte(nil), payload...),
			flags:     fragment.Flags,
		}
		a.pending[key] = pending
	} else {
		pending.lastSeen = now
		pending.flags |= fragment.Flags
		pending.buffer = append(pending.buffer, fragment.Payload...)
		if len(pending.buffer) > tlsHTTPStreamMaxBuffer {
			delete(a.pending, key)
			a.dropped++
			return nil
		}
	}

	var events []TLSPlaintextEvent
	for {
		pending.buffer = trimTLSHTTPMessageSeparators(pending.buffer)
		if len(pending.buffer) == 0 {
			delete(a.pending, key)
			return events
		}
		messageLen, complete, invalid := tlsCompleteHTTPMessageLength(pending.buffer, fragment.Direction)
		if invalid {
			delete(a.pending, key)
			a.dropped++
			return events
		}
		if !complete {
			return events
		}

		messagePayload := append([]byte(nil), pending.buffer[:messageLen]...)
		messageFragment := pending.meta
		messageFragment.TimestampNS = fragment.TimestampNS
		messageFragment.Payload = messagePayload
		messageFragment.TotalLen = uint32(len(messagePayload))
		messageFragment.OriginalLen = uint32(len(messagePayload))
		messageFragment.DataLen = uint32(len(messagePayload))
		messageFragment.FragCount = 1
		messageFragment.Flags = pending.flags
		event := parseTLSPlaintext(messageFragment)
		if isTLSHTTPDisplayEvent(event) {
			a.trackHTTPEventLocked(key, &event)
			events = append(events, event)
		}

		pending.buffer = pending.buffer[messageLen:]
		pending.flags = 0
	}
}

func (a *TLSHTTPStreamAssembler) Pending() int {
	if a == nil {
		return 0
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	return len(a.pending)
}

func (a *TLSHTTPStreamAssembler) Dropped() int {
	if a == nil {
		return 0
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.dropped
}

func (a *TLSHTTPStreamAssembler) cleanupExpiredLocked(now time.Time) {
	for key, pending := range a.pending {
		if now.Sub(pending.lastSeen) > a.timeout || now.Sub(pending.firstSeen) > 2*a.timeout {
			delete(a.pending, key)
			a.dropped++
		}
	}
}

func (a *TLSHTTPStreamAssembler) trackHTTPEventLocked(key tlsHTTPBufferKey, event *TLSPlaintextEvent) {
	streamKey := tlsHTTPStreamKey{PID: key.PID, TGID: key.TGID, LibType: key.LibType}
	if event.Type == "http_request" {
		queue := append(a.requests[streamKey], tlsHTTPRequestContext{Method: event.Method, URL: event.URL, Host: event.Host})
		if len(queue) > tlsHTTPStreamRequestQueueLimit {
			queue = queue[len(queue)-tlsHTTPStreamRequestQueueLimit:]
		}
		a.requests[streamKey] = queue
		return
	}
	if event.Type != "http_response" && event.Type != "sse_message" {
		return
	}
	queue := a.requests[streamKey]
	if len(queue) == 0 {
		return
	}
	request := queue[0]
	if len(queue) == 1 {
		delete(a.requests, streamKey)
	} else {
		a.requests[streamKey] = queue[1:]
	}
	if event.Method == "" {
		event.Method = request.Method
	}
	if event.URL == "" {
		event.URL = request.URL
	}
	if event.Host == "" {
		event.Host = request.Host
	}
}

func isTLSHTTPDisplayEvent(event TLSPlaintextEvent) bool {
	return event.Type == "http_request" || event.Type == "http_response" || event.Type == "sse_message"
}

func trimTLSHTTPMessageSeparators(payload []byte) []byte {
	return bytes.TrimLeft(payload, "\r\n")
}

func looksLikeTLSHTTPMessageStart(payload []byte, direction uint8) bool {
	if len(payload) == 0 {
		return false
	}
	if direction == tlsDirectionRecv {
		return bytes.HasPrefix(payload, []byte("HTTP/"))
	}
	return looksLikeTLSHTTPRequest(payload)
}

func tlsCompleteHTTPMessageLength(payload []byte, direction uint8) (int, bool, bool) {
	if !looksLikeTLSHTTPMessageStart(payload, direction) {
		return 0, false, true
	}
	headerEnd, separatorLen := tlsHTTPHeaderEnd(payload)
	if headerEnd < 0 {
		return 0, false, false
	}
	headersStart := tlsHTTPFirstLineEnd(payload)
	if headersStart < 0 || headersStart > headerEnd {
		return 0, false, true
	}
	headers := parseTLSHTTPHeaderMap(string(payload[headersStart:headerEnd]))
	bodyStart := headerEnd + separatorLen

	if tlsHTTPHasChunkedTransfer(headers) {
		bodyLen, ok := tlsChunkedBodyLength(payload[bodyStart:])
		if !ok {
			return 0, false, false
		}
		return bodyStart + bodyLen, true, false
	}

	if contentLength, ok, valid := tlsHTTPContentLength(headers); ok || !valid {
		if !valid || contentLength < 0 {
			return 0, false, true
		}
		if len(payload)-bodyStart < contentLength {
			return 0, false, false
		}
		return bodyStart + contentLength, true, false
	}

	if direction == tlsDirectionRecv && tlsHTTPResponseHasNoBody(payload) {
		return bodyStart, true, false
	}
	if direction == tlsDirectionSend {
		return bodyStart, true, false
	}
	return 0, false, false
}

func tlsHTTPHeaderEnd(payload []byte) (int, int) {
	if idx := bytes.Index(payload, []byte("\r\n\r\n")); idx >= 0 {
		return idx, 4
	}
	if idx := bytes.Index(payload, []byte("\n\n")); idx >= 0 {
		return idx, 2
	}
	return -1, 0
}

func tlsHTTPFirstLineEnd(payload []byte) int {
	if idx := bytes.Index(payload, []byte("\r\n")); idx >= 0 {
		return idx + 2
	}
	if idx := bytes.IndexByte(payload, '\n'); idx >= 0 {
		return idx + 1
	}
	return -1
}

func parseTLSHTTPHeaderMap(raw string) map[string][]string {
	headers := make(map[string][]string)
	for _, line := range strings.Split(strings.ReplaceAll(raw, "\r\n", "\n"), "\n") {
		line = strings.TrimRight(line, "\r")
		if strings.TrimSpace(line) == "" || strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
			continue
		}
		key, value, ok := strings.Cut(line, ":")
		if !ok {
			continue
		}
		key = strings.ToLower(strings.TrimSpace(key))
		value = strings.TrimSpace(value)
		headers[key] = append(headers[key], value)
	}
	return headers
}

func tlsHTTPHasChunkedTransfer(headers map[string][]string) bool {
	for _, value := range headers["transfer-encoding"] {
		for _, part := range strings.Split(value, ",") {
			if strings.EqualFold(strings.TrimSpace(part), "chunked") {
				return true
			}
		}
	}
	return false
}

func tlsHTTPContentLength(headers map[string][]string) (int, bool, bool) {
	values := headers["content-length"]
	if len(values) == 0 {
		return 0, false, true
	}
	value := strings.TrimSpace(values[len(values)-1])
	parsed, err := strconv.Atoi(value)
	if err != nil {
		return 0, true, false
	}
	return parsed, true, true
}

func tlsHTTPResponseHasNoBody(payload []byte) bool {
	lineEnd := bytes.IndexAny(payload, "\r\n")
	if lineEnd <= 0 {
		return false
	}
	parts := strings.Fields(string(payload[:lineEnd]))
	if len(parts) < 2 {
		return false
	}
	status, err := strconv.Atoi(parts[1])
	if err != nil {
		return false
	}
	return (status >= 100 && status < 200) || status == 204 || status == 304
}

func tlsChunkedBodyLength(body []byte) (int, bool) {
	offset := 0
	for {
		lineEnd, lineBreakLen := tlsChunkLineEnd(body[offset:])
		if lineEnd < 0 {
			return 0, false
		}
		sizeLine := string(body[offset : offset+lineEnd])
		if semi := strings.IndexByte(sizeLine, ';'); semi >= 0 {
			sizeLine = sizeLine[:semi]
		}
		size, err := strconv.ParseInt(strings.TrimSpace(sizeLine), 16, 64)
		if err != nil || size < 0 {
			return 0, false
		}
		offset += lineEnd + lineBreakLen
		if size == 0 {
			trailerLen, ok := tlsChunkTrailerLength(body[offset:])
			if !ok {
				return 0, false
			}
			return offset + trailerLen, true
		}
		need := int(size) + 2
		if len(body)-offset < need {
			return 0, false
		}
		if !bytes.Equal(body[offset+int(size):offset+need], []byte("\r\n")) {
			return 0, false
		}
		offset += need
	}
}

func tlsChunkLineEnd(body []byte) (int, int) {
	if idx := bytes.Index(body, []byte("\r\n")); idx >= 0 {
		return idx, 2
	}
	if idx := bytes.IndexByte(body, '\n'); idx >= 0 {
		return idx, 1
	}
	return -1, 0
}

func tlsChunkTrailerLength(body []byte) (int, bool) {
	if len(body) >= 2 && bytes.Equal(body[:2], []byte("\r\n")) {
		return 2, true
	}
	if len(body) >= 1 && body[0] == '\n' {
		return 1, true
	}
	if idx := bytes.Index(body, []byte("\r\n\r\n")); idx >= 0 {
		return idx + 4, true
	}
	if idx := bytes.Index(body, []byte("\n\n")); idx >= 0 {
		return idx + 2, true
	}
	return 0, false
}

// ---- merged from integration_ml.go ----

// DefaultMLConfig re-exports the core default configuration.
// The canonical MLConfig type lives in the core package.
var DefaultMLConfig = core.DefaultMLConfig

// Global ML state
var (
	mlEngine         Model
	mlConfig         MLConfig
	mlEnabled        bool
	mlModelLoaded    bool
	currentModelType ModelType
)

func currentMLConfig() MLConfig {
	return runtimeSettingsStore.Snapshot().MLConfig
}

// InitMLEngine initializes the ML engine. Only active on master nodes.
func InitMLEngine(cfg MLConfig) {
	mlConfig = cfg
	if !cfg.Enabled {
		log.Printf("[ML] Behavior classifier disabled by configuration")
		return
	}

	if !clusterManagerStore.IsMaster() {
		log.Printf("[ML] Slave node detected — ML inference disabled (runs only on master)")
		return
	}

	// Initialize training store
	InitTrainingStore(100000)

	if cfg.ModelType == "" {
		cfg.ModelType = ModelRandomForest
	}
	if _, ok := modelRegistry[cfg.ModelType]; !ok {
		log.Printf("[ML] Unknown model type %q; falling back to %s", cfg.ModelType, ModelRandomForest)
		cfg.ModelType = ModelRandomForest
	}
	mlConfig = cfg
	currentModelType = cfg.ModelType

	// Try loading existing model
	modelPath := cfg.ModelPath
	if modelPath == "" {
		modelPath = defaultMLModelPath()
	}

	if m := tryLoadModel(modelPath, cfg.ModelType); m != nil {
		mlEngine = m
		mlModelLoaded = true
		log.Printf("[ML] Loaded pre-trained %s model from %s", modelName(cfg.ModelType), modelPath)
	} else {
		log.Printf("[ML] No pre-trained %s model found at %s — will train once sufficient data is collected", modelName(cfg.ModelType), modelPath)
	}

	log.Printf("[ML] Behavior classifier initialized on master node (type=%s, features=%d dims)", cfg.ModelType, FeatureDim)
	mlEnabled = true
}

func tryLoadModel(path string, t ModelType) Model {
	requested := t
	base := baseModelType(t)
	var loaded Model
	switch base {
	case ModelRandomForest:
		if m, err := DeserializeForest(path); err == nil {
			loaded = m
		}
	case ModelExtraTrees:
		if m, err := DeserializeForest(path); err == nil {
			loaded = &ExtraTreesModel{Forest: m, MaxDepth: m.MaxDepth, NumTrees: len(m.Trees)}
		}
	case ModelKNN:
		if m, err := DeserializeKNN(path); err == nil {
			loaded = m
		}
	case ModelLogisticRegression:
		if m, err := DeserializeLogistic(path); err == nil {
			loaded = m
		}
	case ModelNaiveBayes:
		if m, err := DeserializeNaiveBayes(path); err == nil {
			loaded = m
		}
	case ModelNearestCentroid:
		if m, err := DeserializeNearestCentroid(path); err == nil {
			loaded = m
		}
	case ModelAdaBoost:
		if m, err := DeserializeAdaBoost(path); err == nil {
			loaded = m
		}
	case ModelSVM:
		if m, err := DeserializeSVM(path); err == nil {
			loaded = m
		}
	case ModelRidge:
		if m, err := DeserializeRidge(path); err == nil {
			loaded = m
		}
	case ModelPerceptron:
		if m, err := DeserializePerceptron(path); err == nil {
			loaded = m
		}
	case ModelPassiveAggressive:
		if m, err := DeserializePA(path); err == nil {
			loaded = m
		}
	case ModelEnsemble:
		if m, err := DeserializeEnsemble(path); err == nil {
			loaded = m
		}
	}
	return wrapModelType(loaded, requested)
}

// StartMLEngine starts background tasks for the ML engine
func StartMLEngine() {
	if !mlEnabled {
		return
	}

	// Auto-training scheduler
	if mlConfig.AutoTrain {
		go mlAutoTrainLoop()
	}

	// Periodic data flush
	go mlFlushLoop()
}

// resolveAction fuses rule-based classification, anomaly scoring, and ML prediction
// into a final WrapperResponse action. Inspired by the LIGHT-HIDS two-layer architecture.
//
// Layer 1: Fast heuristic triage using existing regex classifier + anomaly score
// Layer 2: ML random forest for uncertain cases
func resolveAction(
	req *pb.WrapperRequest,
	ruleAction string,
	rulePriority int,
	classification *pb.BehaviorClassification,
	anomalyScore float64,
	mlPrediction Prediction,
	cfg MLConfig,
) (pb.WrapperResponse_Action, string) {

	// ── Explicit high-priority rules always win ──
	if ruleAction != "" && rulePriority >= cfg.RuleOverridePriority {
		switch ruleAction {
		case "BLOCK":
			return pb.WrapperResponse_BLOCK, "High-priority explicit rule: BLOCK"
		case "ALERT":
			return pb.WrapperResponse_ALERT, "High-priority explicit rule: ALERT"
		case "REWRITE":
			return pb.WrapperResponse_REWRITE, "High-priority explicit rule: REWRITE"
		}
	}

	// ── Layer 1: Heuristic triage ──
	if classification != nil && classification.Confidence == "high" {
		primaryCat := classification.PrimaryCategory
		if primaryCat == "SENSITIVE" || primaryCat == "FILE_DELETE" {
			if anomalyScore > cfg.HighAnomalyThreshold {
				return pb.WrapperResponse_ALERT,
					"High-confidence sensitive/file-delete category with anomalous pattern"
			}
		}
	}

	// ── Layer 1.5: Network audit escalation ──
	cmdline := strings.Join(req.Args, " ")
	netAudit := AuditNetworkBehavior(req.Comm, cmdline)
	if netAudit.RiskLevel == "CRITICAL" {
		return pb.WrapperResponse_ALERT,
			"CRITICAL network audit: " + netAudit.Findings[0].Description
	}
	if netAudit.RiskLevel == "HIGH" && anomalyScore > 0.5 {
		return pb.WrapperResponse_ALERT,
			"HIGH network risk with anomalous pattern"
	}

	// ── Layer 2: ML model ──
	if mlEnabled && mlModelLoaded && mlPrediction.Confidence >= cfg.MlMinConfidence {
		switch mlPrediction.Action {
		case 1: // BLOCK
			if mlPrediction.Confidence >= cfg.BlockConfidenceThreshold {
				return pb.WrapperResponse_BLOCK, "ML classification: BLOCK (high confidence)"
			}
			// Uncertain block → alert instead
			return pb.WrapperResponse_ALERT, "ML classification: suspicious (elevated to ALERT)"
		case 3: // ALERT
			return pb.WrapperResponse_ALERT, "ML classification: ALERT"
		case 2: // REWRITE
			if ruleAction == "REWRITE" {
				return pb.WrapperResponse_REWRITE, "ML classification: REWRITE (rule exists)"
			}
			return pb.WrapperResponse_ALERT, "ML classification: REWRITE (no rewrite rule available, alerting)"
		case 0: // ALLOW
			if anomalyScore < cfg.LowAnomalyThreshold {
				return pb.WrapperResponse_ALLOW, "ML classification: benign behavior"
			}
			return pb.WrapperResponse_ALERT, "ML classification: uncertain benign (anomaly elevated)"
		}
	}

	// ── Layer 2 anomaly-only (model not confident, but anomalous) ──
	if mlEnabled && anomalyScore > cfg.HighAnomalyThreshold {
		// High anomaly with low model confidence — still worth alerting
		return pb.WrapperResponse_ALERT, "Anomalous behavior detected (insufficient labeled data for ML classification)"
	}

	// ── Fallback: existing rule-based behavior ──
	switch ruleAction {
	case "BLOCK":
		return pb.WrapperResponse_BLOCK, "Rule-based policy: BLOCK"
	case "ALERT":
		return pb.WrapperResponse_ALERT, "Rule-based policy: ALERT"
	case "REWRITE":
		return pb.WrapperResponse_REWRITE, "Rule-based policy: REWRITE"
	default:
		return pb.WrapperResponse_ALLOW, ""
	}
}

// mlAutoTrainLoop periodically checks if enough labeled data exists and triggers training
func mlAutoTrainLoop() {
	interval := 1 * time.Hour
	if d, err := time.ParseDuration(mlConfig.TrainInterval); err == nil && d > 0 {
		interval = d
	}

	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		if !mlEnabled {
			return
		}
		_, labeled := globalTrainingStore.Status()
		if labeled >= mlConfig.MinSamplesForTraining {
			log.Printf("[ML] Auto-training triggered: %d labeled samples available", labeled)
			model, result := globalTrainer.TrainWithConfig(globalTrainingStore, mlConfig)
			if result.Error != "" {
				log.Printf("[ML] Auto-training failed: %s", result.Error)
				continue
			}
			mlEngine = model
			mlModelLoaded = true
			log.Printf("[ML] Auto-training complete: accuracy=%.2f%%, type=%s", result.Accuracy*100, model.Type())

			// Persist model
			modelPath := mlConfig.ModelPath
			if modelPath == "" {
				modelPath = defaultMLModelPath()
			}
			if err := model.Serialize(modelPath); err != nil {
				log.Printf("[ML] Failed to save model: %v", err)
			}
		}
	}
}

// mlFlushLoop periodically flushes training data to disk
func mlFlushLoop() {
	ticker := time.NewTicker(60 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		if !mlEnabled {
			return
		}
		if globalTrainingStore != nil {
			if err := globalTrainingStore.Flush(); err != nil {
				log.Printf("[ML] Failed to flush training data: %v", err)
			}
		}
	}
}

func defaultMLModelPath() string {
	return runtimeSettingsDir() + "/ml_model.bin"
}

// mlStatus builds the ML status protobuf for the API
func mlStatus() *pb.MLStatus {
	cfg := currentMLConfig()
	status := &pb.MLStatus{
		ModelLoaded:        mlModelLoaded,
		TrainingInProgress: globalTrainer.isRunning,
		TrainingProgress:   globalTrainer.progress,
	}

	if mlEngine != nil {
		switch model := unwrapModelType(mlEngine).(type) {
		case *DecisionForest:
			status.NumTrees = int32(len(model.Trees))
		case *ExtraTreesModel:
			if model.Forest != nil {
				status.NumTrees = int32(len(model.Forest.Trees))
			} else {
				status.NumTrees = int32(model.NumTrees)
			}
		case *AdaBoostModel:
			status.NumTrees = int32(len(model.Stumps))
		case *EnsembleModel:
			status.NumTrees = int32(len(model.Models))
		}
	}

	if globalTrainingStore != nil {
		total, labeled := globalTrainingStore.Status()
		status.NumSamples = int32(total)
		status.NumLabeledSamples = int32(labeled)
	}

	if !globalTrainer.lastTrain.IsZero() {
		status.LastTrained = globalTrainer.lastTrain.Format(time.RFC3339)
		status.TestAccuracy = globalTrainer.accuracy
	}

	if cfg.ModelPath != "" {
		status.ModelPath = cfg.ModelPath
	} else {
		status.ModelPath = defaultMLModelPath()
	}

	return status
}

// ---- merged from jobs_background.go ----

func startKernelEventReader(rd *ringbuf.Reader) {
	go func() {
		var event bpfEvent
		selfPid := uint32(os.Getpid())
		for {
			record, err := rd.Read()
			if err != nil {
				return
			}
			if err := binary.Read(bytes.NewBuffer(record.RawSample), binary.LittleEndian, &event); err != nil {
				log.Printf("[WARN] failed to decode eBPF event: %v (sample len=%d)", err, len(record.RawSample))
				continue
			}
			if event.PID == selfPid {
				continue
			}
			comm := sanitizeUTF8(event.Comm[:])
			if isCommDisabled(comm) {
				continue
			}
			if isEventTypeDisabled(event.Type) {
				continue
			}
			broadcast <- buildKernelEvent(event)
		}
	}()
}

func startRuntimeBackgroundJobs() {
	startEventBroadcaster()
	go startUDSServer(broadcast)
	startCgroupAttributionGC()
	startDNSCacheGC()
	startTCPStateTrackerGC()
	startFlowAggregatorGC()
	startExfilDetectionLoop()
	go func() {
		time.Sleep(100 * time.Millisecond)
		initGeoIPDatabase()
	}()
	go func() {
		ticker := time.NewTicker(3 * time.Minute)
		for range ticker.C {
			globalBandwidthTracker.EvictOlderThan(15 * time.Minute)
		}
	}()
	go func() {
		if err := ensureCgroupSandboxLoaded(); err != nil {
			log.Printf("[CGROUP-SANDBOX] not available: %v", err)
		}
	}()
	go func() {
		if err := ensureLsmEnforcerLoaded(); err != nil {
			log.Printf("[LSM-ENFORCER] not available: %v", err)
		}
	}()
}

func startArchiveEvictionLoop(ctx context.Context) {
	go func() {
		ticker := time.NewTicker(5 * time.Minute)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				settings := runtimeSettingsStore.Snapshot()
				if d, err := time.ParseDuration(settings.MaxEventAge); err == nil && d > 0 {
					capturedEventArchive.EvictOlderThan(time.Now().UTC().Add(-d))
				}
			}
		}
	}()
}

func startDeferredMLRuntime() {
	go func() {
		time.Sleep(1 * time.Second)
		settings := runtimeSettingsStore.Snapshot()
		InitMLEngine(settings.MLConfig)
		StartMLEngine()
	}()
}

func startDeferredPluginRuntime() {
	go func() {
		time.Sleep(2 * time.Second)
		ReapplyEBPFPluginsOnBoot()
	}()
}

