// ── BPF LSM enforcement map and link management ────────────────────────

const lsmEnforcerPinRoot = ebpfPinRoot + "/lsm_enforcer"
const lsmEnforcerMapsDir = lsmEnforcerPinRoot + "/maps"
const lsmEnforcerLinksDir = lsmEnforcerPinRoot + "/links"
const lsmEnforcerMapPinMode os.FileMode = 0600
const expectedLsmEnforcerLinks = 14

type lsmEnforcerRuntime struct {
	ExecPathBlocklist *ebpf.Map
	ExecNameBlocklist *ebpf.Map
	FileNameBlocklist *ebpf.Map
	Stats             *ebpf.Map
	Links             []link.Link
	LinkPins          []string
	LastError         string
}

type lsmPathKey struct {
	Path [256]byte
}

type lsmNameKey struct {
	Name [64]byte
}

type lsmEnforcerStats struct {
	ExecChecked uint64 `json:"execChecked"`
	ExecBlocked uint64 `json:"execBlocked"`
	FileChecked uint64 `json:"fileChecked"`
	FileBlocked uint64 `json:"fileBlocked"`
}

var lsmEnforcer lsmEnforcerRuntime
var lsmEnforcerMu sync.RWMutex
var errLsmEnforcerPinnedLinksMissing = errors.New("BPF LSM pinned links missing")

type lsmEnforcerSnapshot struct {
	ExecPathBlocklist *ebpf.Map
	ExecNameBlocklist *ebpf.Map
	FileNameBlocklist *ebpf.Map
	Stats             *ebpf.Map
	LinkCount         int
	LinkPins          []string
	LastError         string
}

func currentLsmEnforcerSnapshot() lsmEnforcerSnapshot {
	lsmEnforcerMu.RLock()
	defer lsmEnforcerMu.RUnlock()
	return lsmEnforcerSnapshot{
		ExecPathBlocklist: lsmEnforcer.ExecPathBlocklist,
		ExecNameBlocklist: lsmEnforcer.ExecNameBlocklist,
		FileNameBlocklist: lsmEnforcer.FileNameBlocklist,
		Stats:             lsmEnforcer.Stats,
		LinkCount:         len(lsmEnforcer.Links),
		LinkPins:          append([]string(nil), lsmEnforcer.LinkPins...),
		LastError:         lsmEnforcer.LastError,
	}
}

func (s lsmEnforcerSnapshot) available() bool {
	return s.ExecPathBlocklist != nil && s.ExecNameBlocklist != nil && s.FileNameBlocklist != nil && s.Stats != nil
}

func (s lsmEnforcerSnapshot) attached() bool {
	return s.LinkCount >= expectedLsmEnforcerLinks
}

func lsmEnforcerAvailable() bool {
	lsmEnforcerMu.RLock()
	defer lsmEnforcerMu.RUnlock()
	return lsmEnforcerAvailableLocked()
}

func lsmEnforcerAvailableLocked() bool {
	return lsmEnforcer.ExecPathBlocklist != nil &&
		lsmEnforcer.ExecNameBlocklist != nil &&
		lsmEnforcer.FileNameBlocklist != nil &&
		lsmEnforcer.Stats != nil
}

func lsmEnforcerAttached() bool {
	lsmEnforcerMu.RLock()
	defer lsmEnforcerMu.RUnlock()
	return lsmEnforcerAttachedLocked()
}

func lsmEnforcerAttachedLocked() bool {
	return len(lsmEnforcer.Links) >= expectedLsmEnforcerLinks
}

func closeLsmEnforcerLinks() {
	for _, existing := range lsmEnforcer.Links {
		_ = existing.Close()
	}
	lsmEnforcer.Links = nil
	lsmEnforcer.LinkPins = nil
}

func replaceLsmEnforcerLinks(links []link.Link) {
	closeLsmEnforcerLinks()
	lsmEnforcer.Links = links
}

// ---- merged from manager_camera.go ----

type CameraStream struct {
	devName string
	cam     *device.Device

	// Zero-copy broadcasting mechanism
	latestFrame []byte
	frameCond   *sync.Cond
	frameMu     sync.Mutex // Changed from RWMutex to Mutex to fix sync.Cond panic

	subscriberCount int32
	stopTimer       *time.Timer
	cancelFunc      context.CancelFunc
	running         bool
	streamMu        sync.Mutex
}

var (
	activeStreams = make(map[string]*CameraStream)
	streamsMu     sync.Mutex
)

// Consumer representation
type CameraSubscriber struct {
	stream *CameraStream
	closed int32
}

func getCameraStream(devName string) *CameraStream {
	streamsMu.Lock()
	defer streamsMu.Unlock()

	s, ok := activeStreams[devName]
	if !ok {
		s = &CameraStream{
			devName: devName,
		}
		s.frameCond = sync.NewCond(&s.frameMu)
		activeStreams[devName] = s
	}
	return s
}

func (s *CameraStream) Subscribe() *CameraSubscriber {
	s.streamMu.Lock()
	defer s.streamMu.Unlock()

	atomic.AddInt32(&s.subscriberCount, 1)

	// Cancel any pending shutdown
	if s.stopTimer != nil {
		s.stopTimer.Stop()
		s.stopTimer = nil
	}

	if !s.running {
		var cam *device.Device
		var err error

		for i := 0; i < 3; i++ {
			cam, err = device.Open(s.devName, device.WithIOType(v4l2.IOTypeMMAP))
			if err == nil {
				break
			}
			log.Printf("[WARN] camera open retry %d for %s: %v", i+1, s.devName, err)
			time.Sleep(500 * time.Millisecond)
		}

		if err != nil {
			log.Printf("[ERROR] failed to open camera %s: %v", s.devName, err)
			atomic.AddInt32(&s.subscriberCount, -1)
			return nil
		}

		if err := cam.SetPixFormat(v4l2.PixFormat{PixelFormat: v4l2.PixelFmtMJPEG, Width: 640, Height: 480}); err != nil {
			log.Printf("[WARN] MJPEG not supported on %s: %v", s.devName, err)
			cam.Close()
			atomic.AddInt32(&s.subscriberCount, -1)
			return nil
		}

		ctx, cancel := context.WithCancel(context.Background())
		if err := cam.Start(ctx); err != nil {
			log.Printf("[ERROR] failed to start camera stream %s: %v", s.devName, err)
			cancel()
			cam.Close()
			atomic.AddInt32(&s.subscriberCount, -1)
			return nil
		}

		s.cam = cam
		s.cancelFunc = cancel
		s.running = true

		// Independent producer thread
		go func(stream *CameraStream) {
			output := stream.cam.GetOutput()
			for frame := range output {
				stream.frameMu.Lock()
				stream.latestFrame = frame
				stream.frameMu.Unlock()
				stream.frameCond.Broadcast()
			}

			// Hardware cleanup
			stream.streamMu.Lock()
			if stream.cam != nil {
				_ = stream.cam.Stop()
				_ = stream.cam.Close()
				stream.cam = nil
			}
			stream.running = false
			stream.streamMu.Unlock()

			streamsMu.Lock()
			delete(activeStreams, stream.devName)
			streamsMu.Unlock()

			stream.frameCond.Broadcast()
		}(s)
	}

	return &CameraSubscriber{stream: s}
}

func (sub *CameraSubscriber) NextFrame(ctx context.Context) ([]byte, error) {
	if atomic.LoadInt32(&sub.closed) == 1 {
		return nil, context.Canceled
	}

	s := sub.stream
	s.frameMu.Lock() // Must use Lock() for sync.Cond.Wait()
	s.frameCond.Wait()

	if !s.running || atomic.LoadInt32(&sub.closed) == 1 {
		s.frameMu.Unlock()
		return nil, context.Canceled
	}

	select {
	case <-ctx.Done():
		s.frameMu.Unlock()
		return nil, ctx.Err()
	default:
	}

	frame := s.latestFrame
	s.frameMu.Unlock()
	return frame, nil
}

func (sub *CameraSubscriber) Unsubscribe() {
	if !atomic.CompareAndSwapInt32(&sub.closed, 0, 1) {
		return
	}

	s := sub.stream
	s.frameCond.Broadcast()

	s.streamMu.Lock()
	defer s.streamMu.Unlock()

	count := atomic.AddInt32(&s.subscriberCount, -1)
	if count <= 0 && s.running {
		if s.stopTimer != nil {
			s.stopTimer.Stop()
		}
		s.stopTimer = time.AfterFunc(5*time.Second, func() {
			s.streamMu.Lock()
			defer s.streamMu.Unlock()
			if atomic.LoadInt32(&s.subscriberCount) <= 0 && s.running {
				if s.cancelFunc != nil {
					s.cancelFunc()
					s.cancelFunc = nil
				}
			}
		})
	}
}

// ---- merged from metrics.go ----

func getGPUMetrics() (map[int32]gpuInfo, []*pb.GPUStatus) {
	procMap := make(map[int32]gpuInfo)
	var globalStats []*pb.GPUStatus

	// 1. NVIDIA (Native)
	if nvmlInitialized {
		count, _ := nvml.DeviceGetCount()
		for i := 0; i < count; i++ {
			device, _ := nvml.DeviceGetHandleByIndex(i)
			name, _ := device.GetName()
			util, _ := device.GetUtilizationRates()
			mInfo, _ := device.GetMemoryInfo()
			temp, _ := device.GetTemperature(nvml.TEMPERATURE_GPU)

			gs := &pb.GPUStatus{
				Index: uint32(i), Name: name, UtilGpu: util.Gpu, UtilMem: util.Memory,
				MemTotal: uint32(mInfo.Total / 1024 / 1024), MemUsed: uint32(mInfo.Used / 1024 / 1024), Temp: temp,
			}

			// Detailed NVIDIA engine stats
			if encUtil, _, ret := device.GetEncoderUtilization(); ret == nvml.SUCCESS {
				gs.EncUtil = encUtil
			}
			if decUtil, _, ret := device.GetDecoderUtilization(); ret == nvml.SUCCESS {
				gs.DecUtil = decUtil
			}
			if smClock, ret := device.GetClockInfo(nvml.CLOCK_SM); ret == nvml.SUCCESS {
				gs.SmClockMhz = smClock
			}
			if memClock, ret := device.GetClockInfo(nvml.CLOCK_MEM); ret == nvml.SUCCESS {
				gs.MemClockMhz = memClock
			}
			if gfxClock, ret := device.GetClockInfo(nvml.CLOCK_GRAPHICS); ret == nvml.SUCCESS {
				gs.GfxClockMhz = gfxClock
			}
			if powerMw, ret := device.GetPowerUsage(); ret == nvml.SUCCESS {
				gs.PowerW = powerMw / 1000
			}
			if limitMw, ret := device.GetPowerManagementLimit(); ret == nvml.SUCCESS {
				gs.PowerLimitW = limitMw / 1000
			}
			if fan, ret := device.GetFanSpeed(); ret == nvml.SUCCESS {
				gs.FanSpeed = fan
			}
			if gen, ret := device.GetCurrPcieLinkGeneration(); ret == nvml.SUCCESS {
				gs.PcieGen = int32(gen)
			}
			if width, ret := device.GetCurrPcieLinkWidth(); ret == nvml.SUCCESS {
				gs.PcieWidth = int32(width)
			}

			globalStats = append(globalStats, gs)

			procs, ret := device.GetComputeRunningProcesses()
			if ret == nvml.SUCCESS {
				for _, p := range procs {
					procMap[int32(p.Pid)] = gpuInfo{Mem: uint32(p.UsedGpuMemory / 1024 / 1024), GPU: uint32(i), Util: 0}
				}
			}
		}
	}

	// 2. Generic DRM (Intel/AMD via fdinfo)
	scanFdinfo(procMap, &globalStats)

	return procMap, globalStats
}

func readVMFaultCounters() (vmFaultCounters, error) {
	data, err := os.ReadFile("/proc/vmstat")
	if err != nil {
		return vmFaultCounters{}, err
	}

	counters := vmFaultCounters{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) != 2 {
			continue
		}

		val, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil {
			continue
		}

		switch fields[0] {
		case "pgfault":
			counters.PageFaults = val
		case "pgmajfault":
			counters.MajorFaults = val
		case "pswpin":
			counters.SwapIn = val
		case "pswpout":
			counters.SwapOut = val
		}
	}

	if err := scanner.Err(); err != nil {
		return vmFaultCounters{}, err
	}

	return counters, nil
}

func scanFdinfo(procMap map[int32]gpuInfo, globalStats *[]*pb.GPUStatus) {
	now := time.Now()
	fdinfoHistoryMu.Lock()
	dt := now.Sub(fdinfoTime).Nanoseconds()
	fdinfoTime = now
	fdinfoHistoryMu.Unlock()

	// Track seen client IDs to avoid overcounting VRAM (some drivers provide drm-client-id)
	type clientKey struct {
		pid int
		id  string
	}
	seenClients := make(map[clientKey]bool)

	procDirs, _ := os.ReadDir("/proc")
	for _, pd := range procDirs {
		pid, err := strconv.Atoi(pd.Name())
		if err != nil {
			continue
		}

		fdDir := fmt.Sprintf("/proc/%d/fdinfo", pid)
		fds, err := os.ReadDir(fdDir)
		if err != nil {
			continue
		}

		for _, fd := range fds {
			fpath := filepath.Join(fdDir, fd.Name())
			file, err := os.Open(fpath)
			if err != nil {
				continue
			}

			scanner := bufio.NewScanner(file)
			var driver, clientId string
			var memKb, enginesNs uint64

			for scanner.Scan() {
				line := scanner.Text()
				if strings.HasPrefix(line, "drm-driver:") {
					driver = strings.TrimSpace(line[11:])
				} else if strings.HasPrefix(line, "drm-client-id:") {
					clientId = strings.TrimSpace(line[14:])
				} else if strings.HasPrefix(line, "drm-total-") || strings.HasPrefix(line, "drm-memory-") {
					parts := strings.Fields(line)
					if len(parts) >= 2 {
						v, _ := strconv.ParseUint(parts[1], 10, 64)
						memKb += v
					}
				} else if strings.HasPrefix(line, "drm-engine-") {
					parts := strings.Fields(line)
					if len(parts) >= 2 {
						v, _ := strconv.ParseUint(parts[1], 10, 64)
						enginesNs += v
					}
				}
			}
			file.Close()

			if driver == "" || (driver == "nvidia" && nvmlInitialized) {
				continue
			}

			// Normalize driver name for UI
			if driver == "i915" || driver == "xe" {
				driver = "Intel Graphics"
			}
			if driver == "amdgpu" {
				driver = "AMD Radeon"
			}

			// Utilization calculation
			histKey := fmt.Sprintf("%d:%s", pid, fd.Name())
			util := uint32(0)
			fdinfoHistoryMu.RLock()
			prev, ok := fdinfoHistory[histKey]
			fdinfoHistoryMu.RUnlock()
			if ok && dt > 0 {
				diff := enginesNs - prev
				util = uint32((diff * 100) / uint64(dt))
			}
			fdinfoHistoryMu.Lock()
			fdinfoHistory[histKey] = enginesNs
			fdinfoHistoryMu.Unlock()

			// Aggregate per process
			p := int32(pid)
			ckey := clientKey{pid, clientId}

			cur := procMap[p]
			if !seenClients[ckey] {
				cur.Mem += uint32(memKb / 1024)
				seenClients[ckey] = true
			}
			if util > cur.Util {
				cur.Util = util
			}
			procMap[p] = cur

			// Global aggregation
			found := false
			for _, gs := range *globalStats {
				if gs.Name == driver {
					gs.UtilGpu += util // Summing across all processes' engine usage is correct for global util.
					if gs.UtilGpu > 100 {
						gs.UtilGpu = 100
					}
					gs.MemUsed = cur.Mem // This is tricky. Let's just track drivers.
					found = true
					break
				}
			}
			if !found {
				*globalStats = append(*globalStats, &pb.GPUStatus{
					Index: uint32(len(*globalStats)), Name: driver, UtilGpu: util, MemUsed: uint32(memKb / 1024),
				})
			}
		}
	}
}

func getCoreTypes() []pb.CPUInfo_Core_Type {
	cores, _ := cpu.Counts(true)
	types := make([]pb.CPUInfo_Core_Type, cores)
	maxFreqs := make([]int64, cores)
	overallMax := int64(0)
	for i := 0; i < cores; i++ {
		data, err := os.ReadFile(fmt.Sprintf("/sys/devices/system/cpu/cpu%d/topology/core_type", i))
		if err == nil {
			val := strings.TrimSpace(string(data))
			if val == "intel_atom" {
				types[i] = pb.CPUInfo_Core_EFFICIENCY
				continue
			}
			if val == "intel_core" {
				types[i] = pb.CPUInfo_Core_PERFORMANCE
				continue
			}
		}
		freqData, err := os.ReadFile(fmt.Sprintf("/sys/devices/system/cpu/cpu%d/cpufreq/cpuinfo_max_freq", i))
		if err == nil {
			fmt.Sscanf(string(freqData), "%d", &maxFreqs[i])
			if maxFreqs[i] > overallMax {
				overallMax = maxFreqs[i]
			}
		}
	}
	if overallMax > 0 {
		for i := 0; i < cores; i++ {
			if types[i] != 0 {
				continue
			}
			if maxFreqs[i] < (overallMax * 8 / 10) {
				types[i] = pb.CPUInfo_Core_EFFICIENCY
			} else {
				types[i] = pb.CPUInfo_Core_PERFORMANCE
			}
		}
	}
	return types
}

