// ── Model Type Registration ────────────────────────────────────────

func init() {
	RegisterModel(ModelEnsemble, func() Model { return NewEnsembleModel(nil, "soft", nil) })
}

// EnsembleModel combines multiple base models via weighted voting.
// Supports "hard" (majority) and "soft" (probability-weighted) voting.
type EnsembleModel struct {
	Models  []Model   `json:"-"`
	Weights []float64 `json:"weights"`
	Voting  string    `json:"voting"` // hard, soft
}

type ensembleManifest struct {
	Version    int       `json:"version"`
	Voting     string    `json:"voting"`
	Weights    []float64 `json:"weights"`
	ModelTypes []string  `json:"modelTypes"`
	ModelFiles []string  `json:"modelFiles"`
}

func NewEnsembleModel(models []Model, voting string, weights []float64) *EnsembleModel {
	if voting == "" {
		voting = "soft"
	}
	if len(weights) != len(models) {
		weights = make([]float64, len(models))
		for i := range weights {
			weights[i] = 1.0
		}
	}
	totalW := 0.0
	for _, w := range weights {
		totalW += w
	}
	for i := range weights {
		weights[i] /= totalW
	}
	return &EnsembleModel{Models: models, Voting: voting, Weights: weights}
}

func (m *EnsembleModel) Type() ModelType { return ModelEnsemble }

func (m *EnsembleModel) Predict(features [FeatureDim]float64) Prediction {
	if len(m.Models) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	if m.Voting == "hard" {
		return m.hardVote(features)
	}
	return m.softVote(features)
}

func (m *EnsembleModel) hardVote(features [FeatureDim]float64) Prediction {
	votes := make([]float64, 4)
	totalW := 0.0
	for i, model := range m.Models {
		pred := model.Predict(features)
		if pred.Action >= 0 && pred.Action < 4 {
			votes[pred.Action] += m.Weights[i]
			totalW += m.Weights[i]
		}
	}
	if totalW == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}
	bestClass := int32(0)
	bestVotes := votes[0]
	for c := 1; c < 4; c++ {
		if votes[c] > bestVotes {
			bestVotes = votes[c]
			bestClass = int32(c)
		}
	}
	confidence := bestVotes / totalW
	return Prediction{Action: bestClass, Confidence: confidence, AnomalyScore: 1 - confidence}
}

func (m *EnsembleModel) softVote(features [FeatureDim]float64) Prediction {
	classProbs := make([]float64, 4)
	totalW := 0.0
	for i, model := range m.Models {
		pred := model.Predict(features)
		w := m.Weights[i]
		for c := 0; c < 4; c++ {
			if pred.Action == int32(c) {
				classProbs[c] += pred.Confidence * w
			} else {
				classProbs[c] += (1 - pred.Confidence) / 3 * w
			}
		}
		totalW += w
	}
	if totalW == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}
	for c := range classProbs {
		classProbs[c] /= totalW
	}
	bestClass := int32(0)
	bestProb := classProbs[0]
	for c := 1; c < 4; c++ {
		if classProbs[c] > bestProb {
			bestProb = classProbs[c]
			bestClass = int32(c)
		}
	}
	return Prediction{Action: bestClass, Confidence: bestProb, AnomalyScore: 1 - bestProb}
}

func (m *EnsembleModel) Serialize(path string) error {
	dir := filepath.Dir(path)
	os.MkdirAll(dir, 0755)
	basePath := strings.TrimSuffix(path, filepath.Ext(path))
	modelTypes := make([]string, 0, len(m.Models))
	modelFiles := make([]string, 0, len(m.Models))
	for i, model := range m.Models {
		subPath := fmt.Sprintf("%s_ensemble_%d_%s.bin", basePath, i, model.Type())
		if err := model.Serialize(subPath); err != nil {
			return fmt.Errorf("ensemble serialize model[%d] %s: %w", i, model.Type(), err)
		}
		modelTypes = append(modelTypes, string(model.Type()))
		modelFiles = append(modelFiles, filepath.Base(subPath))
	}
	manifest := ensembleManifest{
		Version:    1,
		Voting:     m.Voting,
		Weights:    append([]float64(nil), m.Weights...),
		ModelTypes: modelTypes,
		ModelFiles: modelFiles,
	}
	data, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func DeserializeEnsemble(path string) (*EnsembleModel, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var manifest ensembleManifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		return nil, err
	}
	baseDir := filepath.Dir(path)
	models := make([]Model, 0, len(manifest.ModelFiles))
	for i, file := range manifest.ModelFiles {
		if i >= len(manifest.ModelTypes) {
			return nil, fmt.Errorf("ensemble manifest missing model type for %s", file)
		}
		mt := ModelType(manifest.ModelTypes[i])
		subPath := filepath.Join(baseDir, file)
		model, err := deserializeModelByType(mt, subPath)
		if err != nil {
			return nil, fmt.Errorf("ensemble load model[%d] %s: %w", i, mt, err)
		}
		models = append(models, model)
	}
	return NewEnsembleModel(models, manifest.Voting, manifest.Weights), nil
}

func deserializeModelByType(mt ModelType, path string) (Model, error) {
	base := baseModelType(mt)
	var (
		model Model
		err   error
	)
	switch base {
	case ModelRandomForest:
		model, err = DeserializeForest(path)
	case ModelExtraTrees:
		var forest *DecisionForest
		forest, err = DeserializeForest(path)
		if err == nil {
			model = &ExtraTreesModel{Forest: forest, MaxDepth: forest.MaxDepth, NumTrees: len(forest.Trees)}
		}
	case ModelKNN:
		model, err = DeserializeKNN(path)
	case ModelLogisticRegression:
		model, err = DeserializeLogistic(path)
	case ModelNaiveBayes:
		model, err = DeserializeNaiveBayes(path)
	case ModelNearestCentroid:
		model, err = DeserializeNearestCentroid(path)
	case ModelAdaBoost:
		model, err = DeserializeAdaBoost(path)
	case ModelSVM:
		model, err = DeserializeSVM(path)
	case ModelRidge:
		model, err = DeserializeRidge(path)
	case ModelPerceptron:
		model, err = DeserializePerceptron(path)
	case ModelPassiveAggressive:
		model, err = DeserializePA(path)
	default:
		return nil, fmt.Errorf("unsupported ensemble member type: %s", mt)
	}
	if err != nil {
		return nil, err
	}
	return wrapModelType(model, mt), nil
}

// ── Prediction Cache ────────────────────────────────────────────────

type predictionCacheEntry struct {
	Prediction Prediction
	CommandKey string
	AccessTime time.Time
}

// PredictionCache is a bounded LRU cache for ML predictions.
type PredictionCache struct {
	mu       sync.RWMutex
	entries  map[string]*predictionCacheEntry
	order    []string
	capacity int
	hits     uint64
	misses   uint64
}

var globalPredictionCache = newPredictionCache(1000)

func newPredictionCache(capacity int) *PredictionCache {
	if capacity < 10 {
		capacity = 10
	}
	return &PredictionCache{
		entries:  make(map[string]*predictionCacheEntry, capacity),
		capacity: capacity,
	}
}

func (c *PredictionCache) Get(key string) (Prediction, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	entry, ok := c.entries[key]
	if !ok {
		c.misses++
		return Prediction{}, false
	}
	c.hits++
	entry.AccessTime = time.Now()
	return entry.Prediction, true
}

func (c *PredictionCache) Set(key string, pred Prediction) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if entry, ok := c.entries[key]; ok {
		entry.Prediction = pred
		entry.AccessTime = time.Now()
		return
	}
	if len(c.entries) >= c.capacity {
		c.evictLRU()
	}
	c.entries[key] = &predictionCacheEntry{
		Prediction: pred,
		CommandKey: key,
		AccessTime: time.Now(),
	}
}

func (c *PredictionCache) evictLRU() {
	var oldestKey string
	oldestTime := time.Now()
	for k, entry := range c.entries {
		if entry.AccessTime.Before(oldestTime) {
			oldestTime = entry.AccessTime
			oldestKey = k
		}
	}
	if oldestKey != "" {
		delete(c.entries, oldestKey)
	}
}

func (c *PredictionCache) HitRate() float64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	total := c.hits + c.misses
	if total == 0 {
		return 0
	}
	return float64(c.hits) / float64(total)
}

func (c *PredictionCache) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.entries = make(map[string]*predictionCacheEntry, c.capacity)
	c.order = nil
	c.hits = 0
	c.misses = 0
}

func makePredictionCacheKey(comm string, args []string) string {
	return comm + "\x00" + strings.Join(args, "\x00")
}

// ── Two-Tier Inference ──────────────────────────────────────────────

// fastPredict uses a lightweight model (single decision tree or fast linear model)
// for initial assessment. Returns true if fast path is conclusive.
func fastPredict(features [FeatureDim]float64) (Prediction, bool) {
	if !mlModelLoaded || mlEngine == nil {
		return Prediction{}, false
	}

	pred := mlEngine.Predict(features)
	// Fast path: high confidence AND not BLOCK/ALERT (safe to fast-track ALLOW)
	if pred.Confidence >= 0.90 && pred.Action == 0 {
		return pred, true
	}
	return Prediction{}, false
}

// ── Optimized Decision Forest Predict ───────────────────────────────

// PredictFast is an optimized Predict that terminates early when
// a high-confidence prediction is found.
func (f *DecisionForest) PredictFast(features [FeatureDim]float64, earlyStopConfidence float64) Prediction {
	if !f.IsTrained || len(f.Trees) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0}
	}

	classVotes := make([]float64, f.NumClasses)
	treesEvaluated := 0

	for i := range f.Trees {
		leaf := f.Trees[i].Predict(features)
		cls := int(math.Round(float64(leaf)))
		if cls < 0 || cls >= f.NumClasses {
			continue
		}
		classVotes[cls]++
		treesEvaluated++

		// Early termination: if any class has overwhelming majority
		if treesEvaluated >= 5 && earlyStopConfidence > 0 {
			_ = int32(0)
			bestCount := classVotes[0]
			for c := 1; c < f.NumClasses; c++ {
				if classVotes[c] > bestCount {
					bestCount = classVotes[c]
					_ = int32(c)
				}
			}
			conf := bestCount / float64(treesEvaluated)
			// If highly confident and we've evaluated enough trees
			if conf >= earlyStopConfidence && treesEvaluated >= len(f.Trees)/3 {
				for j := i + 1; j < len(f.Trees); j++ {
					l := f.Trees[j].Predict(features)
					c := int(math.Round(float64(l)))
					if c >= 0 && c < f.NumClasses {
						classVotes[c]++
						treesEvaluated++
					}
					// Re-check every 5 trees
					if (j-i)%5 == 0 {
						_ = int32(0)
						bcv := classVotes[0]
						for c2 := 1; c2 < f.NumClasses; c2++ {
							if classVotes[c2] > bcv {
								bcv = classVotes[c2]
								_ = int32(c2)
							}
						}
						if bcv/float64(treesEvaluated) < earlyStopConfidence {
							break
						}
					}
				}
				break
			}
		}
	}

	if treesEvaluated == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	bestClass := int32(0)
	bestVotes := classVotes[0]
	for i := 1; i < f.NumClasses; i++ {
		if classVotes[i] > bestVotes {
			bestVotes = classVotes[i]
			bestClass = int32(i)
		}
	}

	confidence := bestVotes / float64(treesEvaluated)
	return Prediction{
		Action:       bestClass,
		Confidence:   confidence,
		AnomalyScore: 1 - confidence,
	}
}

// ── Inference with Cache and Two-Tier ───────────────────────────────

// predictWithOptimizations wraps the ML prediction with caching and fast path.
func predictWithOptimizations(features [FeatureDim]float64, cacheKey string) Prediction {
	// 1. Check cache first
	if cacheKey != "" {
		if cached, ok := globalPredictionCache.Get(cacheKey); ok {
			return cached
		}
	}

	// 2. Two-tier inference
	if fastPred, ok := fastPredict(features); ok {
		if cacheKey != "" {
			globalPredictionCache.Set(cacheKey, fastPred)
		}
		return fastPred
	}

	// 3. Full model inference
	pred := mlEngine.Predict(features)

	// 4. Cache result
	if cacheKey != "" {
		globalPredictionCache.Set(cacheKey, pred)
	}

	return pred
}

// ---- merged from model_knn.go ----

func init() {
	RegisterModel(ModelKNN, func() Model { return NewKNNModel(5, "euclidean", "uniform") })
}

// KNNModel is a k-nearest neighbors classifier.
// Pure Go — stores training data in memory for lazy inference.
type KNNModel struct {
	K           int                   `json:"k"`
	Distance    string                `json:"distance"`              // euclidean, manhattan
	Weight      string                `json:"weight"`                // uniform, distance
	MaxDistance float64               `json:"maxDistance,omitempty"` // skip samples beyond this dist (0=unlimited)
	Samples     [][FeatureDim]float64 `json:"-"`
	Labels      []int32               `json:"-"`
	NumClasses  int                   `json:"numClasses"`
}

func NewKNNModel(k int, distance, weight string) *KNNModel {
	if k < 1 {
		k = 1
	}
	return &KNNModel{K: k, Distance: distance, Weight: weight, NumClasses: 4}
}

func (m *KNNModel) Type() ModelType { return ModelKNN }

// ── Heap-based KNN Search ──────────────────────────────────────────

type knnHeapItem struct {
	idx      int
	distance float64
}

// max-heap of knnHeapItem (sorted by distance descending)
type knnMaxHeap []knnHeapItem

func (h knnMaxHeap) Len() int           { return len(h) }
func (h knnMaxHeap) Less(i, j int) bool { return h[i].distance > h[j].distance }
func (h knnMaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *knnMaxHeap) Push(x any)        { *h = append(*h, x.(knnHeapItem)) }
func (h *knnMaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// knnSearch finds the K nearest neighbors using a max-heap (O(N log K)).
// When MaxDistance > 0, skips samples beyond the threshold.
func (m *KNNModel) knnSearch(features [FeatureDim]float64) []knnHeapItem {
	k := m.K
	if k <= 0 {
		k = 1
	}
	if k > len(m.Samples) {
		k = len(m.Samples)
	}

	h := &knnMaxHeap{}
	heap.Init(h)

	for i, sample := range m.Samples {
		d := m.computeDistance(features, sample)
		if m.MaxDistance > 0 && d > m.MaxDistance {
			continue
		}
		if h.Len() < k {
			heap.Push(h, knnHeapItem{idx: i, distance: d})
		} else if d < (*h)[0].distance {
			(*h)[0] = knnHeapItem{idx: i, distance: d}
			heap.Fix(h, 0)
		}
	}

	// Convert to sorted slice (ascending)
	result := make([]knnHeapItem, h.Len())
	for i := len(result) - 1; i >= 0; i-- {
		result[i] = heap.Pop(h).(knnHeapItem)
	}
	return result
}

func (m *KNNModel) Predict(features [FeatureDim]float64) Prediction {
	if len(m.Samples) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	var neighbors []knnHeapItem

	if cuda.IsAvailable() && len(m.Samples) >= 1000 {
		// GPU-accelerated batch distance computation
		q := make([]float32, FeatureDim)
		r := make([]float32, len(m.Samples)*FeatureDim)
		for d := 0; d < FeatureDim; d++ {
			q[d] = float32(features[d])
		}
		for i, s := range m.Samples {
			for d := 0; d < FeatureDim; d++ {
				r[i*FeatureDim+d] = float32(s[d])
			}
		}
		dists := cuda.KNNDistances(q, r, 1, len(m.Samples), FeatureDim, m.Distance)
		allDists := make([]knnHeapItem, len(m.Samples))
		for i := range allDists {
			allDists[i] = knnHeapItem{idx: i, distance: float64(dists[i])}
		}
		// Use same heap-based selection for GPU path
		k := m.K
		if k <= 0 {
			k = 1
		}
		if k > len(allDists) {
			k = len(allDists)
		}
		h := &knnMaxHeap{}
		heap.Init(h)
		for _, n := range allDists {
			if m.MaxDistance > 0 && n.distance > m.MaxDistance {
				continue
			}
			if h.Len() < k {
				heap.Push(h, n)
			} else if n.distance < (*h)[0].distance {
				(*h)[0] = n
				heap.Fix(h, 0)
			}
		}
		neighbors = make([]knnHeapItem, h.Len())
		for i := len(neighbors) - 1; i >= 0; i-- {
			neighbors[i] = heap.Pop(h).(knnHeapItem)
		}
	} else {
		// CPU path: heap-based O(N log K)
		neighbors = m.knnSearch(features)
	}

	if len(neighbors) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	k := len(neighbors)
	classVotes := make([]float64, m.NumClasses)
	totalWeight := 0.0
	for i := 0; i < k; i++ {
		n := neighbors[i]
		w := 1.0
		if m.Weight == "distance" && n.distance > 1e-10 {
			w = 1.0 / n.distance
		}
		classVotes[m.Labels[n.idx]] += w
		totalWeight += w
	}

	bestClass := int32(0)
	bestVotes := classVotes[0]
	for i := 1; i < m.NumClasses; i++ {
		if classVotes[i] > bestVotes {
			bestVotes = classVotes[i]
			bestClass = int32(i)
		}
	}

	confidence := 0.0
	if totalWeight > 0 {
		confidence = bestVotes / totalWeight
	}

	avgDist := 0.0
	for i := 0; i < k; i++ {
		avgDist += neighbors[i].distance
	}
	avgDist /= float64(k)
	anomalyScore := math.Tanh(avgDist)

	return Prediction{Action: bestClass, Confidence: confidence, AnomalyScore: anomalyScore}
}

func (m *KNNModel) computeDistance(a, b [FeatureDim]float64) float64 {
	if m.Distance == "cosine" {
		dot := 0.0
		normA := 0.0
		normB := 0.0
		for i := 0; i < FeatureDim; i++ {
			dot += a[i] * b[i]
			normA += a[i] * a[i]
			normB += b[i] * b[i]
		}
		if normA <= 0 || normB <= 0 {
			return 1.0
		}
		return 1.0 - dot/(math.Sqrt(normA)*math.Sqrt(normB))
	}
	var sum float64
	for i := 0; i < FeatureDim; i++ {
		diff := a[i] - b[i]
		if m.Distance == "manhattan" {
			sum += math.Abs(diff)
		} else {
			sum += diff * diff
		}
	}
	if m.Distance == "manhattan" {
		return sum
	}
	return math.Sqrt(sum)
}

func (m *KNNModel) Serialize(path string) error {
	size := 4*7 + len(m.Samples)*(FeatureDim*8+4)
	data := make([]byte, 0, size)

	putU32 := func(v uint32) {
		b := make([]byte, 4)
		binary.LittleEndian.PutUint32(b, v)
		data = append(data, b...)
	}

	data = append(data, []byte("KNNN")...)
	putU32(2)                       // version (2 = added MaxDistance)
	putU32(uint32(m.K))             // k
	putU32(uint32(len(m.Distance))) // dist len
	data = append(data, []byte(m.Distance)...)
	putU32(uint32(len(m.Weight))) // weight len
	data = append(data, []byte(m.Weight)...)
	putU32(uint32(len(m.Samples))) // sample count
	putU32(uint32(m.NumClasses))
	// MaxDistance (new in v2)
	b := make([]byte, 8)
	binary.LittleEndian.PutUint64(b, math.Float64bits(m.MaxDistance))
	data = append(data, b...)

	// Each sample: features (FeatureDim * 8 bytes) + label (4 bytes)
	for i, feat := range m.Samples {
		for _, v := range feat {
			b := make([]byte, 8)
			binary.LittleEndian.PutUint64(b, math.Float64bits(v))
			data = append(data, b...)
		}
		label := make([]byte, 4)
		binary.LittleEndian.PutUint32(label, uint32(m.Labels[i]))
		data = append(data, label...)
	}

	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func DeserializeKNN(path string) (*KNNModel, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(raw) < 24 || string(raw[0:4]) != "KNNN" {
		return nil, fmt.Errorf("invalid KNN model file")
	}
	pos := 4

	readU32 := func() uint32 {
		v := binary.LittleEndian.Uint32(raw[pos:])
		pos += 4
		return v
	}

	ver := readU32()
	k := int(readU32())
	distLen := int(readU32())
	distance := string(raw[pos : pos+distLen])
	pos += distLen
	weightLen := int(readU32())
	weight := string(raw[pos : pos+weightLen])
	pos += weightLen
	numSamples := int(readU32())
	numClasses := int(readU32())

	m := &KNNModel{K: k, Distance: distance, Weight: weight, NumClasses: numClasses}

	// Read MaxDistance if v2+
	if ver >= 2 {
		m.MaxDistance = math.Float64frombits(binary.LittleEndian.Uint64(raw[pos:]))
		pos += 8
	}

	m.Samples = make([][FeatureDim]float64, numSamples)
	m.Labels = make([]int32, numSamples)

	for i := 0; i < numSamples; i++ {
		for j := 0; j < FeatureDim; j++ {
			m.Samples[i][j] = math.Float64frombits(binary.LittleEndian.Uint64(raw[pos:]))
			pos += 8
		}
		m.Labels[i] = int32(binary.LittleEndian.Uint32(raw[pos:]))
		pos += 4
	}

	return m, nil
}

// ---- merged from model_logistic.go ----

func init() {
	RegisterModel(ModelLogisticRegression, func() Model { return NewLogisticModel(0.01, "l2", 1000) })
}

// LogisticModel is a one-vs-rest multinomial logistic regression classifier.
// Pure Go SGD implementation — no external ML dependencies.
type LogisticModel struct {
	Weights        [][FeatureDim + 1]float64 `json:"-"` // +1 for bias, one per class
	NumClasses     int                       `json:"numClasses"`
	LearningRate   float64                   `json:"learningRate"`
	Regularization string                    `json:"regularization"` // l1, l2, none
	MaxIterations  int                       `json:"maxIterations"`
	ClassWeights   []float64                 `json:"classWeights,omitempty"` // per-class loss weight for imbalance
}

func NewLogisticModel(learningRate float64, reg string, maxIter int) *LogisticModel {
	if learningRate <= 0 {
		learningRate = 0.01
	}
	if maxIter <= 0 {
		maxIter = 1000
	}
	return &LogisticModel{
		NumClasses:     4,
		LearningRate:   learningRate,
		Regularization: reg,
		MaxIterations:  maxIter,
	}
}

func (m *LogisticModel) Type() ModelType { return ModelLogisticRegression }

func sigmoid(x float64) float64 {
	if x > 20 {
		return 1.0
	}
	if x < -20 {
		return 0.0
	}
	return 1.0 / (1.0 + math.Exp(-x))
}

func (m *LogisticModel) dot(features [FeatureDim]float64, classIdx int) float64 {
	sum := m.Weights[classIdx][FeatureDim] // bias
	for i := 0; i < FeatureDim; i++ {
		sum += m.Weights[classIdx][i] * features[i]
	}
	return sum
}

func (m *LogisticModel) softmax(features [FeatureDim]float64) []float64 {
	probs := make([]float64, m.NumClasses)
	maxLogit := math.Inf(-1)
	logits := make([]float64, m.NumClasses)
	for c := 0; c < m.NumClasses; c++ {
		logits[c] = m.dot(features, c)
		if logits[c] > maxLogit {
			maxLogit = logits[c]
		}
	}
	sum := 0.0
	for c := 0; c < m.NumClasses; c++ {
		probs[c] = math.Exp(logits[c] - maxLogit)
		sum += probs[c]
	}
	for c := 0; c < m.NumClasses; c++ {
		probs[c] /= sum
	}
	return probs
}

func (m *LogisticModel) Predict(features [FeatureDim]float64) Prediction {
	if len(m.Weights) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	probs := m.softmax(features)

	bestClass := int32(0)
	bestProb := probs[0]
	for c := 1; c < m.NumClasses; c++ {
		if probs[c] > bestProb {
			bestProb = probs[c]
			bestClass = int32(c)
		}
	}

	// Anomaly: 1 - max_prob (uncertain prediction = anomalous)
	anomalyScore := 1.0 - bestProb

	return Prediction{Action: bestClass, Confidence: bestProb, AnomalyScore: anomalyScore}
}

// Train runs SGD on the provided samples and labels.
func (m *LogisticModel) Train(samples [][FeatureDim]float64, labels []int32) {
	nSamples := len(samples)
	if nSamples == 0 {
		return
	}

	// Initialize weights with small random values
	m.Weights = make([][FeatureDim + 1]float64, m.NumClasses)
	rng := rand.New(rand.NewSource(42))
	for c := 0; c < m.NumClasses; c++ {
		for i := 0; i <= FeatureDim; i++ {
			m.Weights[c][i] = (rng.Float64() - 0.5) * 0.01
		}
	}

	// ── CUDA-accelerated training path ──
	if cuda.IsAvailable() && nSamples >= 100 {
		m.trainWithCUDA(samples, labels, nSamples)
		return
	}

	// SGD loop (CPU fallback)
	for iter := 0; iter < m.MaxIterations; iter++ {
		// Learning rate decay
		lr := m.LearningRate * (1.0 - float64(iter)/float64(m.MaxIterations)*0.95)

		// Shuffle
		order := rng.Perm(nSamples)
		totalLoss := 0.0

		for _, idx := range order {
			features := samples[idx]
			trueLabel := int(labels[idx])
			if trueLabel < 0 || trueLabel >= m.NumClasses {
				continue
			}

			probs := m.softmax(features)

			// Class weight: upweight minority classes
			cw := 1.0
			if len(m.ClassWeights) == m.NumClasses {
				cw = m.ClassWeights[trueLabel]
			}

			// Cross-entropy loss gradient (scaled by class weight)
			for c := 0; c < m.NumClasses; c++ {
				target := 0.0
				if c == trueLabel {
					target = 1.0
				}
				error := (probs[c] - target) * cw

				// Update weights with regularization
				for i := 0; i < FeatureDim; i++ {
					grad := error * features[i]
					// L2 regularization
					if m.Regularization == "l2" {
						grad += 0.001 * m.Weights[c][i]
					} else if m.Regularization == "l1" {
						if m.Weights[c][i] > 0 {
							grad += 0.001
						} else if m.Weights[c][i] < 0 {
							grad -= 0.001
						}
					}
					m.Weights[c][i] -= lr * grad
				}
				// Bias update
				m.Weights[c][FeatureDim] -= lr * error
			}

			if probs[trueLabel] > 0 {
				totalLoss += -math.Log(probs[trueLabel]) * cw
			}
		}

		// Early stopping if loss is very small
		avgLoss := totalLoss / float64(nSamples)
		if avgLoss < 0.01 && iter > 100 {
			break
		}
	}
}

// computeClassWeights computes inverse-frequency class weights to handle imbalance.
// Minority classes get weight > 1, majority get weight <= 1.
func computeClassWeights(labels []int32, numClasses int) []float64 {
	counts := make([]int, numClasses)
	for _, l := range labels {
		if l >= 0 && int(l) < numClasses {
			counts[l]++
		}
	}
	total := 0
	for _, c := range counts {
		total += c
	}
	if total == 0 {
		return nil
	}

	weights := make([]float64, numClasses)
	maxW := 0.0
	for c := 0; c < numClasses; c++ {
		if counts[c] > 0 {
			weights[c] = float64(total) / (float64(numClasses) * float64(counts[c]))
			if weights[c] > maxW {
				maxW = weights[c]
			}
		} else {
			weights[c] = 1.0
		}
	}

	// Cap max weight at 5.0 to prevent extreme values
	if maxW > 5.0 {
		for c := range weights {
			weights[c] = weights[c] / maxW * 5.0
		}
	}
	return weights
}

// Serialize writes the logistic model to a binary file
func (m *LogisticModel) Serialize(path string) error {
	size := 4*5 + m.NumClasses*(FeatureDim+1)*8
	data := make([]byte, 0, size)

	putU32 := func(v uint32) {
		b := make([]byte, 4)
		binary.LittleEndian.PutUint32(b, v)
		data = append(data, b...)
	}
	putU32F := func(v float64) {
		b := make([]byte, 8)
		binary.LittleEndian.PutUint64(b, math.Float64bits(v))
		data = append(data, b...)
	}

	data = append(data[:0], []byte("LOGR")...)
	putU32(1) // version
	putU32(uint32(m.NumClasses))
	putU32F(m.LearningRate)
	putU32(uint32(len(m.Regularization)))
	data = append(data, []byte(m.Regularization)...)

	for c := 0; c < m.NumClasses; c++ {
		for i := 0; i <= FeatureDim; i++ {
			putU32F(m.Weights[c][i])
		}
	}

	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

// DeserializeLogistic loads a logistic model from disk
func DeserializeLogistic(path string) (*LogisticModel, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(raw) < 16 || string(raw[0:4]) != "LOGR" {
		return nil, fmt.Errorf("invalid logistic model file")
	}
	pos := 4

	readU32 := func() uint32 {
		v := binary.LittleEndian.Uint32(raw[pos:])
		pos += 4
		return v
	}
	readF64 := func() float64 {
		v := math.Float64frombits(binary.LittleEndian.Uint64(raw[pos:]))
		pos += 8
		return v
	}

	_ = readU32() // version (readU32 advances pos by 4)
	numClasses := int(readU32())
	learningRate := readF64()
	regLen := int(readU32())
	regularization := string(raw[pos : pos+regLen])
	pos += regLen

	m := &LogisticModel{
		NumClasses:     numClasses,
		LearningRate:   learningRate,
		Regularization: regularization,
		Weights:        make([][FeatureDim + 1]float64, numClasses),
	}

	for c := 0; c < numClasses; c++ {
		for i := 0; i <= FeatureDim; i++ {
			m.Weights[c][i] = readF64()
		}
	}

	return m, nil
}

// trainWithCUDA uses GPU-accelerated mini-batch SGD via CUDA.
func (m *LogisticModel) trainWithCUDA(samples [][FeatureDim]float64, labels []int32, nSamples int) {
	// Convert data to float32 for CUDA
	X := make([]float32, nSamples*FeatureDim)
	L := make([]int32, nSamples)
	for i := 0; i < nSamples; i++ {
		for d := 0; d < FeatureDim; d++ {
			X[i*FeatureDim+d] = float32(samples[i][d])
		}
		L[i] = labels[i]
	}

	W := make([]float32, m.NumClasses*(FeatureDim+1))
	// Initialize weights with small random values
	for i := range W {
		W[i] = (float32(i%100)/100.0 - 0.5) * 0.01
	}

	for iter := 0; iter < m.MaxIterations; iter++ {
		lr := float32(m.LearningRate * (1.0 - float64(iter)/float64(m.MaxIterations)*0.95))

		// Forward: compute softmax probabilities on GPU
		P := cuda.LogisticForward(X, W, nSamples, FeatureDim, m.NumClasses)

		// Gradient: compute on GPU
		G := make([]float32, m.NumClasses*(FeatureDim+1))
		cuda.LogisticGradient(X, P, L, G, nSamples, FeatureDim, m.NumClasses)

		// Update weights with learning rate
		for i := range W {
			W[i] -= lr * (G[i] + 0.0005*W[i]) // L2 regularization
		}

		// Early stopping: check average loss
		if iter%50 == 0 && iter > 0 {
			avgLoss := float32(0)
			for s := 0; s < nSamples; s++ {
				prob := P[s*m.NumClasses+int(L[s])]
				if prob > 1e-10 {
					avgLoss += float32(-math.Log(float64(prob)))
				}
			}
			avgLoss /= float32(nSamples)
			if avgLoss < 0.05 && iter > 200 {
				break
			}
		}
	}

	// Copy trained weights back
	for c := 0; c < m.NumClasses; c++ {
		for d := 0; d <= FeatureDim; d++ {
			m.Weights[c][d] = float64(W[c*(FeatureDim+1)+d])
		}
	}
}

