// ---- merged from modelnearestcentroid.go ----

func init() {
	RegisterModel(ModelNearestCentroid, func() Model { return NewNearestCentroid("euclidean", false) })
}

// NearestCentroidModel is a simple linear-time tabular baseline.
// It stores one centroid per class and predicts by nearest centroid
// under a selectable metric. A uniform-prior mode helps on imbalanced sets.
type NearestCentroidModel struct {
	Centroids    [][FeatureDim]float64 `json:"-"`
	Priors       []float64             `json:"priors,omitempty"`
	Classes      int                   `json:"classes"`
	Metric       string                `json:"metric"`
	UniformPrior bool                  `json:"uniformPrior"`
}

func NewNearestCentroid(metric string, uniformPrior bool) *NearestCentroidModel {
	if metric == "" {
		metric = "euclidean"
	}
	return &NearestCentroidModel{
		Classes:      4,
		Metric:       strings.ToLower(metric),
		UniformPrior: uniformPrior,
	}
}

func (m *NearestCentroidModel) Type() ModelType { return ModelNearestCentroid }

func (m *NearestCentroidModel) Predict(features [FeatureDim]float64) Prediction {
	if len(m.Centroids) == 0 {
		return Prediction{Action: 0, Confidence: 0, AnomalyScore: 0.5}
	}

	scores := make([]float64, m.Classes)
	bestClass := int32(0)
	bestScore := math.Inf(-1)
	for c := 0; c < m.Classes; c++ {
		if len(m.Priors) == m.Classes && m.Priors[c] <= 0 {
			scores[c] = math.Inf(-1)
			continue
		}
		score := -m.distance(features, m.Centroids[c])
		if !m.UniformPrior && len(m.Priors) == m.Classes && m.Priors[c] > 0 {
			score += math.Log(m.Priors[c])
		}
		scores[c] = score
		if score > bestScore {
			bestScore = score
			bestClass = int32(c)
		}
	}

	maxScore := scores[0]
	for _, s := range scores[1:] {
		if s > maxScore {
			maxScore = s
		}
	}
	sumExp := 0.0
	bestExp := 0.0
	for c, score := range scores {
		e := math.Exp(score - maxScore)
		sumExp += e
		if int32(c) == bestClass {
			bestExp = e
		}
	}
	confidence := 0.0
	if sumExp > 0 {
		confidence = bestExp / sumExp
	}
	return Prediction{Action: bestClass, Confidence: confidence, AnomalyScore: 1 - confidence}
}

func (m *NearestCentroidModel) distance(a, b [FeatureDim]float64) float64 {
	switch m.Metric {
	case "cosine":
		dot := 0.0
		normA := 0.0
		normB := 0.0
		for i := 0; i < FeatureDim; i++ {
			dot += a[i] * b[i]
			normA += a[i] * a[i]
			normB += b[i] * b[i]
		}
		if normA <= 0 || normB <= 0 {
			return 1.0
		}
		return 1.0 - dot/(math.Sqrt(normA)*math.Sqrt(normB))
	case "manhattan":
		sum := 0.0
		for i := 0; i < FeatureDim; i++ {
			sum += math.Abs(a[i] - b[i])
		}
		return sum
	default:
		sum := 0.0
		for i := 0; i < FeatureDim; i++ {
			diff := a[i] - b[i]
			sum += diff * diff
		}
		return math.Sqrt(sum)
	}
}

func (m *NearestCentroidModel) Serialize(path string) error {
	data := make([]byte, 0, 8+len(m.Centroids)*(FeatureDim+1)*8)
	putU32 := func(v uint32) {
		b := make([]byte, 4)
		binary.LittleEndian.PutUint32(b, v)
		data = append(data, b...)
	}
	putF64 := func(v float64) {
		b := make([]byte, 8)
		binary.LittleEndian.PutUint64(b, math.Float64bits(v))
		data = append(data, b...)
	}
	data = append(data, []byte("NCEN")...)
	putU32(1)
	putU32(uint32(m.Classes))
	putU32(uint32(len(m.Metric)))
	data = append(data, []byte(m.Metric)...)
	if m.UniformPrior {
		putU32(1)
	} else {
		putU32(0)
	}
	putU32(uint32(len(m.Priors)))
	for _, p := range m.Priors {
		putF64(p)
	}
	putU32(uint32(len(m.Centroids)))
	for _, centroid := range m.Centroids {
		for _, v := range centroid {
			putF64(v)
		}
	}

	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func DeserializeNearestCentroid(path string) (*NearestCentroidModel, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(raw) < 16 || string(raw[:4]) != "NCEN" {
		return nil, fmt.Errorf("invalid nearest centroid model file")
	}
	pos := 4
	readU32 := func() uint32 {
		v := binary.LittleEndian.Uint32(raw[pos:])
		pos += 4
		return v
	}
	readF64 := func() float64 {
		v := math.Float64frombits(binary.LittleEndian.Uint64(raw[pos:]))
		pos += 8
		return v
	}
	_ = readU32() // version
	classes := int(readU32())
	metricLen := int(readU32())
	if pos+metricLen > len(raw) {
		return nil, fmt.Errorf("invalid nearest centroid model file")
	}
	metric := strings.ToLower(string(raw[pos : pos+metricLen]))
	pos += metricLen
	uniformPrior := readU32() != 0
	priorsLen := int(readU32())
	if priorsLen < 0 || priorsLen > 256 {
		return nil, fmt.Errorf("invalid nearest centroid model file")
	}
	priors := make([]float64, priorsLen)
	for i := range priors {
		priors[i] = readF64()
	}
	centroidCount := int(readU32())
	centroids := make([][FeatureDim]float64, centroidCount)
	for c := 0; c < centroidCount; c++ {
		for d := 0; d < FeatureDim; d++ {
			centroids[c][d] = readF64()
		}
	}
	return &NearestCentroidModel{
		Centroids:    centroids,
		Priors:       priors,
		Classes:      classes,
		Metric:       metric,
		UniformPrior: uniformPrior,
	}, nil
}

// ---- merged from plugins.go ----

// PluginKind enumerates the plugin types supported by the registry.
type PluginKind string

const (
	PluginKindEBPF    PluginKind = "ebpf"    // user-authored eBPF program (built via online builder)
	PluginKindWebhook PluginKind = "webhook" // forwards selected events to an HTTP endpoint
	PluginKindCommand PluginKind = "command" // wrapper rewrite rule expressed as a plugin
)

// PluginAttachKind describes how an eBPF plugin attaches to the kernel.
type PluginAttachKind string

const (
	PluginAttachTracepoint PluginAttachKind = "tracepoint"
	PluginAttachKprobe     PluginAttachKind = "kprobe"
	PluginAttachKretprobe  PluginAttachKind = "kretprobe"
	PluginAttachLSM        PluginAttachKind = "lsm"
	PluginAttachNone       PluginAttachKind = "none"
)

// PluginManifest is the on-disk descriptor for a registered plugin.
type PluginManifest struct {
	ID          string     `json:"id"`
	Name        string     `json:"name"`
	Description string     `json:"description,omitempty"`
	Author      string     `json:"author,omitempty"`
	Version     string     `json:"version,omitempty"`
	Kind        PluginKind `json:"kind"`
	Enabled     bool       `json:"enabled"`
	CreatedAt   time.Time  `json:"createdAt"`
	UpdatedAt   time.Time  `json:"updatedAt"`

	// eBPF specific
	SourceSHA256 string           `json:"sourceSha256,omitempty"`
	ObjectSHA256 string           `json:"objectSha256,omitempty"`
	AttachKind   PluginAttachKind `json:"attachKind,omitempty"`
	AttachTarget string           `json:"attachTarget,omitempty"` // e.g. "syscalls/sys_enter_openat", "do_unlinkat", or "lsm/file_open"
	ProgramName  string           `json:"programName,omitempty"`  // BPF program (section) name to attach

	// Webhook specific
	WebhookURL    string   `json:"webhookUrl,omitempty"`
	WebhookEvents []string `json:"webhookEvents,omitempty"`

	// Command specific
	CommandComm    string   `json:"commandComm,omitempty"`
	CommandArgs    []string `json:"commandArgs,omitempty"`
	CommandRule    string   `json:"commandRule,omitempty"` // ALLOW / BLOCK / ALERT / REWRITE
	CommandRewrite []string `json:"commandRewrite,omitempty"`

	// Runtime state (not persisted, but populated when listing)
	Loaded    bool   `json:"loaded,omitempty"`
	LoadError string `json:"loadError,omitempty"`
}

var pluginIDRegex = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{1,62}$`)

type pluginStore struct {
	mu      sync.RWMutex
	entries map[string]*PluginManifest
	loaded  bool
}

var pluginRegistry = &pluginStore{entries: make(map[string]*PluginManifest)}

func pluginsRootDir() string {
	return filepath.Join(runtimeSettingsDir(), "plugins")
}

func pluginDir(id string) string {
	return filepath.Join(pluginsRootDir(), id)
}

func pluginManifestPath(id string) string {
	return filepath.Join(pluginDir(id), "manifest.json")
}

func pluginSourcePath(id string) string {
	return filepath.Join(pluginDir(id), "source.c")
}

func pluginObjectPath(id string) string {
	return filepath.Join(pluginDir(id), "program.o")
}

func validatePluginID(id string) error {
	if !pluginIDRegex.MatchString(id) {
		return errors.New("plugin id must match [a-z0-9][a-z0-9-]{1,62}")
	}
	return nil
}

func sha256Hex(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func (s *pluginStore) ensureLoaded() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.loaded {
		return nil
	}
	if err := mkdirAllAsRealUser(pluginsRootDir(), 0755); err != nil {
		return err
	}
	entries, err := os.ReadDir(pluginsRootDir())
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		id := entry.Name()
		path := pluginManifestPath(id)
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var manifest PluginManifest
		if err := json.Unmarshal(data, &manifest); err != nil {
			continue
		}
		if manifest.ID == "" {
			manifest.ID = id
		}
		s.entries[manifest.ID] = &manifest
	}
	s.loaded = true
	return nil
}

func (s *pluginStore) List() []PluginManifest {
	_ = s.ensureLoaded()
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]PluginManifest, 0, len(s.entries))
	for _, m := range s.entries {
		copy := *m
		copy.Loaded, copy.LoadError = ebpfPluginRuntimeState(copy.ID)
		out = append(out, copy)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func (s *pluginStore) Get(id string) (PluginManifest, bool) {
	_ = s.ensureLoaded()
	s.mu.RLock()
	defer s.mu.RUnlock()
	m, ok := s.entries[id]
	if !ok {
		return PluginManifest{}, false
	}
	copy := *m
	copy.Loaded, copy.LoadError = ebpfPluginRuntimeState(copy.ID)
	return copy, true
}

func (s *pluginStore) saveLocked(m *PluginManifest) error {
	if err := mkdirAllAsRealUser(pluginDir(m.ID), 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAsRealUser(pluginManifestPath(m.ID), data, 0644)
}

func (s *pluginStore) Upsert(m *PluginManifest) error {
	if err := validatePluginID(m.ID); err != nil {
		return err
	}
	if err := s.ensureLoaded(); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if existing, ok := s.entries[m.ID]; ok {
		m.CreatedAt = existing.CreatedAt
	} else {
		m.CreatedAt = time.Now().UTC()
	}
	m.UpdatedAt = time.Now().UTC()
	if err := s.saveLocked(m); err != nil {
		return err
	}
	s.entries[m.ID] = m
	return nil
}

func (s *pluginStore) Delete(id string) error {
	_ = s.ensureLoaded()
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.entries[id]; !ok {
		return fmt.Errorf("plugin %q not found", id)
	}
	delete(s.entries, id)
	return os.RemoveAll(pluginDir(id))
}

func (s *pluginStore) SetEnabled(id string, enabled bool) (PluginManifest, error) {
	_ = s.ensureLoaded()
	s.mu.Lock()
	defer s.mu.Unlock()
	m, ok := s.entries[id]
	if !ok {
		return PluginManifest{}, fmt.Errorf("plugin %q not found", id)
	}
	m.Enabled = enabled
	m.UpdatedAt = time.Now().UTC()
	if err := s.saveLocked(m); err != nil {
		return PluginManifest{}, err
	}
	return *m, nil
}

// PluginSource returns the on-disk C source for an eBPF plugin (empty if absent).
func PluginSource(id string) (string, error) {
	if err := validatePluginID(id); err != nil {
		return "", err
	}
	data, err := os.ReadFile(pluginSourcePath(id))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func writePluginSource(id, source string) error {
	if err := mkdirAllAsRealUser(pluginDir(id), 0755); err != nil {
		return err
	}
	return writeFileAsRealUser(pluginSourcePath(id), []byte(source), 0644)
}

// PluginExportSummary is used when exporting/importing plugin manifests.
func pluginExportPayload() map[string]any {
	plugins := pluginRegistry.List()
	stripped := make([]PluginManifest, 0, len(plugins))
	for _, p := range plugins {
		p.Loaded = false
		p.LoadError = ""
		stripped = append(stripped, p)
	}
	return map[string]any{
		"plugins":    stripped,
		"exportedAt": time.Now().UTC(),
	}
}

func sanitizePluginName(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return "untitled-plugin"
	}
	return name
}

// ---- merged from privileges.go ----

func originalInvokerIDs() (uid, gid uint32, ok bool) {
	if uidStr := os.Getenv("SUDO_UID"); uidStr != "" {
		gidStr := os.Getenv("SUDO_GID")
		if gidStr == "" {
			return 0, 0, false
		}
		parsedUID, err1 := strconv.ParseUint(uidStr, 10, 32)
		parsedGID, err2 := strconv.ParseUint(gidStr, 10, 32)
		if err1 != nil || err2 != nil {
			return 0, 0, false
		}
		return uint32(parsedUID), uint32(parsedGID), true
	}

	if uidStr := os.Getenv("PKEXEC_UID"); uidStr != "" {
		u, err := user.LookupId(uidStr)
		if err != nil {
			return 0, 0, false
		}
		parsedUID, err1 := strconv.ParseUint(uidStr, 10, 32)
		parsedGID, err2 := strconv.ParseUint(u.Gid, 10, 32)
		if err1 != nil || err2 != nil {
			return 0, 0, false
		}
		return uint32(parsedUID), uint32(parsedGID), true
	}

	return 0, 0, false
}

func allowedControlPlaneUIDs() map[uint32]struct{} {
	allowed := map[uint32]struct{}{
		uint32(os.Getuid()): {},
	}
	if uid, _, ok := originalInvokerIDs(); ok {
		allowed[uid] = struct{}{}
	}
	return allowed
}

func applyCredentialToCommand(cmd *exec.Cmd, uid, gid uint32, uidStr string) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.Credential = &syscall.Credential{Uid: uid, Gid: gid}

	if u, err := user.LookupId(uidStr); err == nil {
		if cmd.Env == nil {
			cmd.Env = os.Environ()
		}
		cmd.Env = setEnvValue(cmd.Env, "USER", u.Username)
		cmd.Env = setEnvValue(cmd.Env, "LOGNAME", u.Username)
		cmd.Env = setEnvValue(cmd.Env, "HOME", u.HomeDir)
	}
}

func configureCommandForRealUser(cmd *exec.Cmd) {
	if os.Getuid() != 0 {
		return
	}

	if uid, gid, ok := originalInvokerIDs(); ok {
		applyCredentialToCommand(cmd, uid, gid, strconv.FormatUint(uint64(uid), 10))
	}
}

// dropPrivileges modifies cmd.SysProcAttr to run the command as the original
// invoking user (SUDO_UID/SUDO_GID) instead of root, mitigating security risks
// when executing shells or arbitrary commands from the backend.
// It also updates the HOME and USER environment variables.
func dropPrivileges(cmd *exec.Cmd) {
	configureCommandForRealUser(cmd)
}

// ---- merged from probediscoverytls.go ----

func parseProcPID(path string) (int, bool) {
	cleaned := filepath.Clean(path)
	parts := strings.Split(cleaned, string(os.PathSeparator))
	for i := 0; i < len(parts)-1; i++ {
		if parts[i] != "proc" {
			continue
		}
		pid, err := strconv.Atoi(parts[i+1])
		if err != nil || pid <= 0 {
			return 0, false
		}
		return pid, true
	}
	return 0, false
}

func (m *TLSProbeManager) shouldAttachGoBinary(binPath string, pid int) bool {
	if m == nil {
		return false
	}
	key := goAttachKey(binPath, pid)
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.attachedGo == nil {
		m.attachedGo = make(map[string]bool)
	}
	if m.attachedGo[key] {
		return false
	}
	m.attachedGo[key] = true
	return true
}

func (m *TLSProbeManager) forgetGoBinaryAttach(binPath string, pid int) {
	if m == nil {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.attachedGo, goAttachKey(binPath, pid))
}

func goAttachKey(binPath string, pid int) string {
	return fmt.Sprintf("%d\x00%s", pid, binPath)
}

func (m *TLSProbeManager) DiscoverGoProcesses() {
	if m == nil {
		return
	}
	entries, err := filepath.Glob("/proc/[0-9]*/exe")
	if err != nil {
		return
	}
	for _, exeLink := range entries {
		pid, ok := parseProcPID(exeLink)
		if !ok {
			continue
		}
		binPath, err := os.Readlink(exeLink)
		if err != nil || binPath == "" {
			continue
		}
		if !m.shouldAttachGoBinary(binPath, pid) {
			continue
		}
		if err := m.AttachGoUprobes(binPath, pid); err != nil {
			m.forgetGoBinaryAttach(binPath, pid)
			if m.store != nil {
				m.store.SetLibraryStatus(TLSLibraryStatus{Name: "Go", Path: binPath, Attached: false, Available: true, Error: err.Error()})
			}
		}
	}
}

func (m *TLSProbeManager) StartGoDiscoveryLoop(interval time.Duration) {
	if m == nil {
		return
	}
	if interval <= 0 {
		interval = time.Minute
	}
	go func() {
		m.DiscoverGoProcesses()
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for range ticker.C {
			m.mu.Lock()
			closed := m.closed
			m.mu.Unlock()
			if closed {
				return
			}
			m.DiscoverGoProcesses()
		}
	}()
}

func findFirstExistingPath(paths ...string) (string, bool) {
	for _, path := range paths {
		if path == "" {
			continue
		}
		if _, err := os.Stat(path); err == nil {
			return path, true
		}
	}
	return "", false
}

func parseGoTLSSymbols(binPath string) ([]string, error) {
	exe, err := elf.Open(binPath)
	if err != nil {
		return nil, err
	}
	defer exe.Close()

	symbols, err := exe.Symbols()
	if err != nil {
		symbols, err = exe.DynamicSymbols()
		if err != nil {
			return nil, err
		}
	}

	out := make([]string, 0, 2)
	seen := make(map[string]struct{}, 2)
	for _, sym := range symbols {
		if name, ok := goTLSSymbolName(sym.Name); ok {
			if _, exists := seen[name]; exists {
				continue
			}
			seen[name] = struct{}{}
			out = append(out, name)
		}
	}
	if len(out) == 0 {
		return nil, fmt.Errorf("no Go TLS symbols found in %s", binPath)
	}
	return out, nil
}

func goTLSSymbolName(name string) (string, bool) {
	switch name {
	case "crypto/tls.(*Conn).Write", "crypto/tls.(*Conn).Read":
		return name, true
	default:
		return "", false
	}
}

func tlsProgramForSymbol(symbol string) (string, bool) {
	switch symbol {
	case "SSL_write":
		return "uprobe_ssl_write", true
	case "SSL_write_ex":
		return "uprobe_ssl_write_ex", true
	case "gnutls_record_send":
		return "uprobe_gnutls_record_send", true
	case "PR_Write":
		return "uprobe_pr_write", true
	case "crypto/tls.(*Conn).Write":
		return "uprobe_crypto_tls_conn_write", true
	case "crypto/tls.(*Conn).Read":
		return "uprobe_crypto_tls_conn_read", true
	case "gnutls_record_recv":
		return "uprobe_gnutls_record_recv", true
	case "PR_Read":
		return "uprobe_pr_read", true
	case "SSL_read":
		return "uprobe_ssl_read", true
	case "SSL_read_ex":
		return "uprobe_ssl_read_ex", true
	default:
		return "", false
	}
}

func tlsReturnProgramForSymbol(symbol string) (string, bool) {
	switch symbol {
	case "SSL_read":
		return "uretprobe_ssl_read", true
	case "SSL_read_ex":
		return "uretprobe_ssl_read_ex", true
	case "SSL_write_ex":
		return "uretprobe_ssl_write_ex", true
	case "gnutls_record_recv":
		return "uretprobe_gnutls_record_recv", true
	case "PR_Read":
		return "uretprobe_pr_read", true
	case "crypto/tls.(*Conn).Read":
		return "uretprobe_crypto_tls_conn_read", true
	default:
		return "", false
	}
}

func tlsProgramForSymbolName(symbol string) string {
	if name, ok := tlsProgramForSymbol(symbol); ok {
		return name
	}
	return ""
}

func tlsReturnProgramForSymbolName(symbol string) string {
	if name, ok := tlsReturnProgramForSymbol(symbol); ok {
		return name
	}
	return ""
}

