func clusterTargetFromContext(c *gin.Context) string {
	if target := strings.TrimSpace(c.GetHeader(clusterTargetHeader)); target != "" {
		return target
	}
	if target := strings.TrimSpace(c.Query("cluster")); target != "" {
		return target
	}
	return clusterTargetLocal
}

func shouldProxyPath(path string) bool {
	switch {
	case path == "/ws", path == "/ws/system", path == "/ws/shell", path == "/ws/shell-sessions", path == "/ws/ml-status", path == "/ws/envelopes", path == "/ws/events/graph":
		return true
	case path == "/events/recent", path == "/events/graph", path == "/events/recording", path == "/events/recording/start", path == "/events/recording/stop", path == "/events/recording/replay", path == "/events/recording/browser/save", path == "/metrics":
		return true
	case strings.HasPrefix(path, "/agentsight/"):
		return true
	case strings.HasPrefix(path, "/api/events") || strings.HasPrefix(path, "/api/runners") || strings.HasPrefix(path, "/api/stream"):
		return true
	case strings.HasPrefix(path, "/config/"):
		return true
	case strings.HasPrefix(path, "/system/"):
		return true
	case strings.HasPrefix(path, "/api/v1/"):
		return true
	case strings.HasPrefix(path, "/shell-sessions"):
		return true
	case path == "/register", path == "/unregister", path == "/hooks/event", path == "/mcp":
		return true
	default:
		return false
	}
}

func isProtectedClusterProxyPath(path string) bool {
	switch {
	case path == "/ws", path == "/ws/system", path == "/ws/shell", path == "/ws/shell-sessions", path == "/ws/ml-status", path == "/ws/envelopes", path == "/ws/events/graph":
		return true
	case path == "/events/recent", path == "/events/graph", path == "/events/recording", path == "/events/recording/start", path == "/events/recording/stop", path == "/events/recording/replay", path == "/events/recording/browser/save", path == "/metrics":
		return true
	case strings.HasPrefix(path, "/agentsight/"):
		return true
	case strings.HasPrefix(path, "/api/events") || strings.HasPrefix(path, "/api/runners") || strings.HasPrefix(path, "/api/stream"):
		return true
	case strings.HasPrefix(path, "/config/"):
		return true
	case strings.HasPrefix(path, "/system/"):
		return true
	case strings.HasPrefix(path, "/api/v1/"):
		return true
	case strings.HasPrefix(path, "/shell-sessions"):
		return true
	case path == "/register", path == "/unregister", path == "/hooks/event":
		return true
	case path == "/mcp":
		return true
	default:
		return false
	}
}

func clusterProxyRequestAllowed(c *gin.Context) bool {
	if gin.Mode() != gin.ReleaseMode || os.Getenv("DISABLE_AUTH") == "true" {
		return true
	}
	if clusterRequestAuthAllowed(c) {
		return true
	}
	if !isProtectedClusterProxyPath(c.Request.URL.Path) {
		return true
	}
	token := requestAuthToken(c)
	if token == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(token), []byte(runtimeSettingsStore.ExpectedToken())) == 1
}

func (m *clusterManager) targetNode(target string) (ClusterNode, bool) {
	if target == "" || target == clusterTargetLocal {
		return ClusterNode{}, false
	}

	m.mu.RLock()
	defer m.mu.RUnlock()

	if target == m.config.NodeID {
		return ClusterNode{}, false
	}
	if node, ok := m.nodes[target]; ok && node != nil {
		return *node, true
	}
	return ClusterNode{}, false
}

func (m *clusterManager) reverseProxyForNode(node ClusterNode) (*httputil.ReverseProxy, error) {
	baseURL := strings.TrimSpace(node.URL)
	if baseURL == "" {
		return nil, fmt.Errorf("cluster node %q has no URL", node.ID)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	if proxy, ok := m.proxyCache[baseURL]; ok {
		return proxy, nil
	}

	targetURL, err := url.Parse(baseURL)
	if err != nil {
		return nil, err
	}
	proxy := httputil.NewSingleHostReverseProxy(targetURL)
	originalDirector := proxy.Director
	proxy.Director = func(req *http.Request) {
		originalDirector(req)
		req.Host = targetURL.Host
		req.Header.Del("X-API-KEY")
		req.Header.Del("Authorization")
		req.Header.Set(clusterProxyHeader, "1")
		m.mu.RLock()
		account := m.config.Account
		password := m.config.Password
		m.mu.RUnlock()
		if account != "" {
			req.Header.Set(clusterAccountHeader, account)
		}
		if password != "" {
			req.Header.Set(clusterPasswordHeader, password)
		}
	}
	proxy.ErrorHandler = func(w http.ResponseWriter, r *http.Request, err error) {
		log.Printf("[WARN] cluster proxy to %s failed: %v", baseURL, err)
		http.Error(w, fmt.Sprintf("cluster proxy to %s failed: %v", baseURL, err), http.StatusBadGateway)
	}

	m.proxyCache[baseURL] = proxy
	return proxy, nil
}

func (m *clusterManager) proxyRequest(c *gin.Context, target string) bool {
	if !m.IsMaster() {
		return false
	}
	if !shouldProxyPath(c.Request.URL.Path) {
		return false
	}
	if !clusterProxyRequestAllowed(c) {
		c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "Unauthorized"})
		return true
	}

	node, ok := m.targetNode(target)
	if !ok {
		if target == "" || target == clusterTargetLocal {
			return false
		}
		c.AbortWithStatusJSON(http.StatusNotFound, gin.H{"error": "cluster target not found"})
		return true
	}
	if strings.TrimSpace(node.URL) == "" {
		c.AbortWithStatusJSON(http.StatusBadGateway, gin.H{"error": "cluster target has no URL"})
		return true
	}

	proxy, err := m.reverseProxyForNode(node)
	if err != nil {
		c.AbortWithStatusJSON(http.StatusBadGateway, gin.H{"error": err.Error()})
		return true
	}

	proxy.ServeHTTP(c.Writer, c.Request)
	c.Abort()
	return true
}

func clusterGatewayMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		if clusterManagerStore.proxyRequest(c, clusterTargetFromContext(c)) {
			return
		}
		c.Next()
	}
}

func clusterStateHandler(c *gin.Context) {
	c.JSON(http.StatusOK, clusterManagerStore.StateSnapshot())
}

func clusterNodesHandler(c *gin.Context) {
	c.JSON(http.StatusOK, ClusterNodesResponse{Nodes: clusterManagerStore.SnapshotNodes()})
}

func clusterHeartbeatHandler(c *gin.Context) {
	if !clusterControlAuthAllowed(c) {
		c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "Unauthorized"})
		return
	}
	if clusterManagerStore.IsSlave() {
		c.AbortWithStatusJSON(http.StatusConflict, gin.H{"error": "slave nodes do not accept cluster heartbeats"})
		return
	}

	var req ClusterHeartbeatRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "invalid cluster heartbeat payload"})
		return
	}

	if req.NodeID == "" {
		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "missing nodeId"})
		return
	}

	node := clusterManagerStore.upsertHeartbeat(req)
	c.JSON(http.StatusOK, ClusterHeartbeatResponse{
		OK:         true,
		ReceivedAt: time.Now().UTC(),
		Registered: node,
	})
}

func startClusterHeartbeatLoop() {
	cfg := clusterManagerStore.ConfigSnapshot()
	if cfg.Role != ClusterRoleSlave || strings.TrimSpace(cfg.MasterURL) == "" {
		return
	}

	go func() {
		client := &http.Client{Timeout: 5 * time.Second}
		ticker := time.NewTicker(clusterHeartbeatEvery)
		defer ticker.Stop()

		send := func() {
			state := clusterManagerStore.StateSnapshot()
			body := ClusterHeartbeatRequest{
				NodeID:   state.NodeID,
				NodeName: state.NodeName,
				NodeURL:  state.NodeURL,
				Role:     state.Role,
				Version:  clusterVersion,
			}
			payload, err := json.Marshal(body)
			if err != nil {
				log.Printf("[WARN] failed to marshal cluster heartbeat: %v", err)
				return
			}

			req, err := http.NewRequest(http.MethodPost, cfg.MasterURL+"/cluster/heartbeat", strings.NewReader(string(payload)))
			if err != nil {
				log.Printf("[WARN] failed to build cluster heartbeat request: %v", err)
				return
			}
			req.Header.Set("Content-Type", "application/json")
			req.Header.Set(clusterAccountHeader, cfg.Account)
			req.Header.Set(clusterPasswordHeader, cfg.Password)

			resp, err := client.Do(req)
			if err != nil {
				log.Printf("[WARN] cluster heartbeat failed: %v", err)
				return
			}
			_ = resp.Body.Close()
			if resp.StatusCode >= 300 {
				log.Printf("[WARN] cluster heartbeat returned %s", resp.Status)
			}
		}

		send()
		for range ticker.C {
			send()
		}
	}()
}

// ---- merged from recording_event.go ----

type eventRecordingRequest struct {
	Path     string `json:"path"`
	Truncate bool   `json:"truncate"`
	Limit    int    `json:"limit"`
}

type eventReplayRequest struct {
	Path  string `json:"path"`
	Limit int    `json:"limit"`
}

type browserRecordingSaveRequest struct {
	Path   string          `json:"path"`
	Export json.RawMessage `json:"export"`
}

type eventRecordingStatus struct {
	Active      bool   `json:"active"`
	Path        string `json:"path,omitempty"`
	DefaultPath string `json:"defaultPath"`
	StartedAt   string `json:"startedAt,omitempty"`
	Count       int64  `json:"count"`
}

type eventRecordingState struct {
	mu        sync.Mutex
	path      string
	file      *os.File
	writer    *bufio.Writer
	startedAt time.Time
	count     int64
}

var eventRecordingStore = &eventRecordingState{}

func defaultEventRecordingPath() string {
	return filepath.Join(runtimeSettingsDir(), "recordings", "events-"+time.Now().UTC().Format("20060102-150405")+".jsonl")
}

func defaultBrowserRecordingPath() string {
	return filepath.Join(runtimeSettingsDir(), "recordings", "browser-memory-"+time.Now().UTC().Format("20060102-150405")+".json")
}

func expandEventRecordingPath(raw string) string {
	path := strings.TrimSpace(raw)
	if path == "" {
		return defaultEventRecordingPath()
	}
	if path == "~" {
		return getRealHomeDir()
	}
	if strings.HasPrefix(path, "~/") {
		return filepath.Join(getRealHomeDir(), strings.TrimPrefix(path, "~/"))
	}
	return path
}

func (s *eventRecordingState) Status() eventRecordingStatus {
	s.mu.Lock()
	defer s.mu.Unlock()
	status := eventRecordingStatus{
		Active:      s.writer != nil,
		Path:        s.path,
		DefaultPath: defaultEventRecordingPath(),
		Count:       s.count,
	}
	if !s.startedAt.IsZero() {
		status.StartedAt = s.startedAt.UTC().Format(time.RFC3339Nano)
	}
	return status
}

func (s *eventRecordingState) Start(path string, truncate bool) (eventRecordingStatus, error) {
	path = expandEventRecordingPath(path)
	if strings.TrimSpace(path) == "" {
		return eventRecordingStatus{}, errors.New("recording path is empty")
	}
	if err := mkdirAllAsRealUser(filepath.Dir(path), 0o755); err != nil {
		return eventRecordingStatus{}, err
	}
	flags := os.O_CREATE | os.O_WRONLY | os.O_APPEND
	if truncate {
		flags = os.O_CREATE | os.O_WRONLY | os.O_TRUNC
	}
	file, err := os.OpenFile(path, flags, 0o600)
	if err != nil {
		return eventRecordingStatus{}, err
	}
	// Fix ownership if running as root
	if os.Getuid() == 0 {
		if uid, gid, ok := originalInvokerIDs(); ok {
			_ = os.Chown(path, int(uid), int(gid))
		}
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	s.closeLocked()
	s.path = path
	s.file = file
	s.writer = bufio.NewWriter(file)
	s.startedAt = time.Now().UTC()
	s.count = 0
	return s.statusLocked(), nil
}

func (s *eventRecordingState) Stop() (eventRecordingStatus, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	status := s.statusLocked()
	err := s.closeLocked()
	status.Active = false
	return status, err
}

func (s *eventRecordingState) Record(record CapturedEventRecord) {
	if record.Event == nil {
		return
	}
	record = normalizeCapturedEventRecord(record)
	payload, err := json.Marshal(record)
	if err != nil {
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.writer == nil {
		return
	}
	if _, err := s.writer.Write(payload); err != nil {
		return
	}
	if err := s.writer.WriteByte('\n'); err != nil {
		return
	}
	if err := s.writer.Flush(); err != nil {
		return
	}
	s.count++
}

func (s *eventRecordingState) statusLocked() eventRecordingStatus {
	status := eventRecordingStatus{
		Active:      s.writer != nil,
		Path:        s.path,
		DefaultPath: defaultEventRecordingPath(),
		Count:       s.count,
	}
	if !s.startedAt.IsZero() {
		status.StartedAt = s.startedAt.UTC().Format(time.RFC3339Nano)
	}
	return status
}

func (s *eventRecordingState) closeLocked() error {
	var err error
	if s.writer != nil {
		if flushErr := s.writer.Flush(); flushErr != nil {
			err = flushErr
		}
	}
	if s.file != nil {
		if closeErr := s.file.Close(); closeErr != nil && err == nil {
			err = closeErr
		}
	}
	s.file = nil
	s.writer = nil
	return err
}

func readCapturedEventsFile(path string, limit int) ([]CapturedEventRecord, error) {
	path = expandEventRecordingPath(path)
	if strings.TrimSpace(path) == "" {
		return nil, errors.New("replay path is empty")
	}
	if limit <= 0 || limit > 10000 {
		limit = 10000
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	records := make([]CapturedEventRecord, 0, min(limit, 1024))
	for scanner.Scan() {
		var record CapturedEventRecord
		if err := json.Unmarshal(scanner.Bytes(), &record); err != nil || record.Event == nil {
			continue
		}
		record = normalizeCapturedEventRecord(record)
		records = append(records, record)
		if len(records) > limit {
			copy(records, records[len(records)-limit:])
			records = records[:limit]
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return records, nil
}

func saveBrowserRecordingExport(path string, payload json.RawMessage) (string, int, error) {
	path = expandEventRecordingPath(path)
	if strings.TrimSpace(path) == "" {
		path = defaultBrowserRecordingPath()
	}
	if len(payload) == 0 || string(payload) == "null" {
		return "", 0, errors.New("browser recording export is empty")
	}
	var normalized any
	if err := json.Unmarshal(payload, &normalized); err != nil {
		return "", 0, err
	}
	pretty, err := json.MarshalIndent(normalized, "", "  ")
	if err != nil {
		return "", 0, err
	}
	if err := mkdirAllAsRealUser(filepath.Dir(path), 0o755); err != nil {
		return "", 0, err
	}
	if err := writeFileAsRealUser(path, append(pretty, '\n'), 0o600); err != nil {
		return "", 0, err
	}
	count := 0
	if object, ok := normalized.(map[string]any); ok {
		if snapshots, ok := object["snapshots"].([]any); ok {
			count = len(snapshots)
		}
	}
	return path, count, nil
}

func handleEventRecordingStatus(c *gin.Context) {
	c.JSON(200, eventRecordingStore.Status())
}

func handleStartEventRecording(c *gin.Context) {
	var req eventRecordingRequest
	_ = c.ShouldBindJSON(&req)
	status, err := eventRecordingStore.Start(req.Path, req.Truncate)
	if err != nil {
		c.JSON(400, gin.H{"error": err.Error()})
		return
	}
	c.JSON(200, status)
}

func handleStopEventRecording(c *gin.Context) {
	status, err := eventRecordingStore.Stop()
	if err != nil {
		c.JSON(500, gin.H{"error": err.Error(), "status": status})
		return
	}
	c.JSON(200, status)
}

func handleReplayEventRecording(c *gin.Context) {
	var req eventReplayRequest
	_ = c.ShouldBindJSON(&req)
	if req.Path == "" {
		req.Path = c.Query("path")
	}
	if req.Limit <= 0 {
		if parsed, ok := parsePositiveIntQuery(c.Query("limit"), 10000); ok {
			req.Limit = parsed
		}
	}
	records, err := readCapturedEventsFile(req.Path, req.Limit)
	if err != nil {
		c.JSON(400, gin.H{"error": err.Error()})
		return
	}
	graph := buildExecutionGraph(records, executionGraphFiltersFromRequest(c))
	graph.Source = "replay_file"
	c.JSON(200, gin.H{"path": expandEventRecordingPath(req.Path), "events": len(records), "graph": graph})
}

func handleSaveBrowserRecording(c *gin.Context) {
	var req browserRecordingSaveRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(400, gin.H{"error": "invalid request"})
		return
	}
	path, snapshots, err := saveBrowserRecordingExport(req.Path, req.Export)
	if err != nil {
		c.JSON(400, gin.H{"error": err.Error()})
		return
	}
	c.JSON(200, gin.H{"path": path, "snapshots": snapshots})
}

func parsePositiveIntQuery(raw string, fallback int) (int, bool) {
	value := strings.TrimSpace(raw)
	if value == "" {
		return fallback, false
	}
	var parsed int
	if err := json.Unmarshal([]byte(value), &parsed); err != nil || parsed <= 0 {
		return fallback, false
	}
	return parsed, true
}

// ---- merged from remote_datasets.go ----

const remoteDatasetFetchLimitBytes = 20 << 20
const remoteDatasetUploadLimitBytes = 100 << 20

type remoteDatasetRequest struct {
	URL            string `json:"url"`
	Content        string `json:"content"`
	ContentBase64  string `json:"contentBase64"`
	SourceName     string `json:"sourceName"`
	Format         string `json:"format"`
	Limit          int    `json:"limit"`
	LabelMode      string `json:"labelMode"`
	ImportAll      bool   `json:"importAll"`
	CleanSensitive bool   `json:"cleanSensitive"`
}

type remoteDatasetRow struct {
	Row          int      `json:"row"`
	Source       string   `json:"source,omitempty"`
	CommandLine  string   `json:"commandLine"`
	Comm         string   `json:"comm"`
	Args         []string `json:"args"`
	Label        string   `json:"label"`
	LabelSource  string   `json:"labelSource"`
	Category     string   `json:"category"`
	AnomalyScore float64  `json:"anomalyScore"`
	HasAnomaly   bool     `json:"-"`
	Timestamp    string   `json:"timestamp"`
	UserLabel    string   `json:"userLabel"`
	Duplicate    bool     `json:"duplicate"`
}

type remoteDatasetResponse struct {
	Source         string             `json:"source"`
	Format         string             `json:"format"`
	ContentType    string             `json:"contentType"`
	Total          int                `json:"total"`
	Limit          int                `json:"limit"`
	Truncated      bool               `json:"truncated"`
	Imported       int                `json:"imported,omitempty"`
	Skipped        int                `json:"skipped,omitempty"`
	TotalSamples   int                `json:"totalSamples,omitempty"`
	LabeledSamples int                `json:"labeledSamples,omitempty"`
	Rows           []remoteDatasetRow `json:"rows,omitempty"`
}

type remoteDatasetRecord struct {
	Row         int
	Source      string
	CommandLine string
	Comm        string
	Args        []string
	Label       string
	LabelSource string
	Category    string
	Anomaly     float64
	HasAnomaly  bool
	Timestamp   time.Time
	UserLabel   string
}

type remoteDatasetPayload struct {
	Source      string
	ContentType string
	Data        []byte
}

func handleMLDatasetPullPost(c *gin.Context) {
	req, ok := bindRemoteDatasetRequest(c)
	if !ok {
		return
	}

	resp, err := pullRemoteDataset(req)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, resp)
}

func handleMLDatasetImportPost(c *gin.Context) {
	req, ok := bindRemoteDatasetRequest(c)
	if !ok {
		return
	}
	if globalTrainingStore == nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "ML training store not initialized"})
		return
	}

	resp, err := pullRemoteDataset(req)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	imported := 0
	skipped := 0
	seen := make(map[string]struct{})
	for _, row := range resp.Rows {
		if row.Comm == "" {
			skipped++
			continue
		}
		key := commandKey(row.Comm, row.Args)
		if _, exists := seen[key]; exists {
			skipped++
			continue
		}
		seen[key] = struct{}{}
		if globalTrainingStore.HasExactCommand(row.Comm, row.Args) {
			skipped++
			continue
		}

		sample := buildRemoteDatasetSample(row, req.LabelMode, req.CleanSensitive)
		globalTrainingStore.Add(sample)
		recordCommandSampleSideEffects(sample)
		imported++
	}

	if err := globalTrainingStore.Flush(); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "imported remote dataset but failed to persist: " + err.Error()})
		return
	}

	total, labeled := globalTrainingStore.Status()
	resp.Imported = imported
	resp.Skipped = skipped
	resp.TotalSamples = total
	resp.LabeledSamples = labeled
	c.JSON(http.StatusOK, resp)
}

func handleMLDatasetExportGet(c *gin.Context) {
	if globalTrainingStore == nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "ML training store not initialized"})
		return
	}

	items := globalTrainingStore.AllSamplesWithIndex()
	rows := make([]remoteDatasetRow, 0, len(items))
	for _, item := range items {
		rows = append(rows, trainingSampleToRemoteDatasetRow(item.Index, item.Sample))
	}
	total, labeled := globalTrainingStore.Status()
	resp := remoteDatasetResponse{
		Source:         "local-training-store",
		Format:         "json",
		ContentType:    "application/json",
		Total:          total,
		Limit:          total,
		Truncated:      false,
		TotalSamples:   total,
		LabeledSamples: labeled,
		Rows:           rows,
	}
	c.Header("Content-Disposition", `attachment; filename="agent-ebpf-filter-training-dataset.json"`)
	c.JSON(http.StatusOK, resp)
}

func handleMLDatasetClearDelete(c *gin.Context) {
	if globalTrainingStore == nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "ML training store not initialized"})
		return
	}

	cleared := globalTrainingStore.Clear()
	if err := globalTrainingStore.Flush(); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cleared training store but failed to persist: " + err.Error()})
		return
	}

	total, labeled := globalTrainingStore.Status()
	c.JSON(http.StatusOK, gin.H{
		"status":         "ok",
		"cleared":        cleared,
		"totalSamples":   total,
		"labeledSamples": labeled,
	})
}

func bindRemoteDatasetRequest(c *gin.Context) (remoteDatasetRequest, bool) {
	var req remoteDatasetRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
		return req, false
	}

	req.URL = strings.TrimSpace(req.URL)
	req.SourceName = strings.TrimSpace(req.SourceName)
	req.ContentBase64 = strings.TrimSpace(req.ContentBase64)
	hasContent := strings.TrimSpace(req.Content) != "" || req.ContentBase64 != ""
	if req.URL == "" && !hasContent {
		c.JSON(http.StatusBadRequest, gin.H{"error": "url or content is required"})
		return req, false
	}
	if req.URL != "" {
		if _, err := validateRemoteDatasetURL(req.URL); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return req, false
		}
	}

	sourceRef := req.SourceName
	if sourceRef == "" {
		sourceRef = req.URL
	}
	if hasContent {
		req.Format = strings.ToLower(strings.TrimSpace(req.Format))
		if req.Format != "" && req.Format != "auto" {
			req.Format = normalizeRemoteDatasetFormat(req.Format, "")
		} else {
			req.Format = "auto"
		}
	} else {
		req.Format = normalizeRemoteDatasetFormat(req.Format, sourceRef)
	}
	req.Limit = parseDatasetLimit(req.Limit)
	req.LabelMode = normalizeRemoteDatasetLabelMode(req.LabelMode)
	return req, true
}

func pullRemoteDataset(req remoteDatasetRequest) (*remoteDatasetResponse, error) {
	downloaded, contentType, source, err := loadRemoteDatasetPayload(req)
	if err != nil {
		return nil, err
	}
	if looksLikeHTMLDataset(downloaded, contentType) {
		if source == "" {
			source = req.URL
		}
		return nil, fmt.Errorf("dataset source %q looks like an HTML landing page; please use a raw file URL or import a local file instead", source)
	}

	payloads, err := expandRemoteDatasetPayloads(downloaded, contentType, source, 0)
	if err != nil {
		return nil, err
	}

	records := make([]remoteDatasetRecord, 0)
	format := ""
	for _, payload := range payloads {
		payloadRecords, payloadFormat, parseErr := parseRemoteDatasetRecords(payload.Data, req.Format, payload.Source)
		if parseErr != nil {
			if len(payloads) == 1 {
				return nil, parseErr
			}
			continue
		}
		if len(payloadRecords) == 0 {
			continue
		}
		records = append(records, payloadRecords...)
		format = mergeDatasetFormat(format, payloadFormat)
	}
	if len(records) == 0 {
		return nil, errors.New("no dataset records found in payload")
	}
	if format == "" {
		format = normalizeRemoteDatasetFormat(req.Format, source)
	}

	rows := make([]remoteDatasetRow, 0, len(records))
	for _, record := range records {
		row := buildRemoteDatasetRow(record, req.LabelMode, req.CleanSensitive)
		if globalTrainingStore != nil {
			row.Duplicate = globalTrainingStore.HasExactCommand(row.Comm, row.Args)
		}
		rows = append(rows, row)
	}

	truncated := false
	if !req.ImportAll && req.Limit > 0 && len(rows) > req.Limit {
		rows = rows[:req.Limit]
		truncated = true
	}
	limit := req.Limit
	if req.ImportAll {
		limit = len(rows)
	}
	if contentType == "" {
		contentType = contentTypeForDatasetFormat(format)
	}
	if source == "" {
		source = req.URL
	}

	return &remoteDatasetResponse{
		Source:      source,
		Format:      format,
		ContentType: contentType,
		Total:       len(records),
		Limit:       limit,
		Truncated:   truncated,
		Rows:        rows,
	}, nil
}

func loadRemoteDatasetPayload(req remoteDatasetRequest) ([]byte, string, string, error) {
	if strings.TrimSpace(req.ContentBase64) != "" {
		raw, err := base64.StdEncoding.DecodeString(req.ContentBase64)
		if err != nil {
			return nil, "", "", fmt.Errorf("invalid base64 dataset content: %w", err)
		}
		if len(raw) > remoteDatasetUploadLimitBytes {
			return nil, "", "", fmt.Errorf("remote dataset content is larger than %d bytes", remoteDatasetUploadLimitBytes)
		}
		source := strings.TrimSpace(req.SourceName)
		if source == "" {
			source = "inline"
		}
		return raw, "", source, nil
	}
	if strings.TrimSpace(req.Content) != "" {
		raw := []byte(req.Content)
		if len(raw) > remoteDatasetUploadLimitBytes {
			return nil, "", "", fmt.Errorf("remote dataset content is larger than %d bytes", remoteDatasetUploadLimitBytes)
		}
		source := strings.TrimSpace(req.SourceName)
		if source == "" {
			source = "inline"
		}
		return raw, "", source, nil
	}
	downloaded, contentType, err := downloadRemoteDataset(req.URL)
	if err != nil {
		return nil, "", "", err
	}
	source := req.URL
	if req.SourceName != "" {
		source = req.SourceName
	}
	return downloaded, contentType, source, nil
}

// ---- merged from remotedatasetsarchive.go ----

func expandRemoteDatasetPayloads(data []byte, contentType, source string, depth int) ([]remoteDatasetPayload, error) {
	if depth > 4 {
		return []remoteDatasetPayload{{Source: source, ContentType: contentType, Data: data}}, nil
	}
	if isZipPayload(data, contentType, source) {
		return expandZipRemoteDatasetPayload(data, source, depth)
	}
	if isTarPayload(data, contentType, source) {
		return expandTarRemoteDatasetPayload(data, source, depth)
	}
	if isGzipPayload(data, contentType, source) {
		decompressed, err := gunzipRemoteDatasetPayload(data)
		if err != nil {
			return nil, err
		}
		return expandRemoteDatasetPayloads(decompressed, "", stripCompressionSuffix(source), depth+1)
	}
	if isBzip2Payload(data, contentType, source) {
		decompressed, err := bunzip2RemoteDatasetPayload(data)
		if err != nil {
			return nil, err
		}
		return expandRemoteDatasetPayloads(decompressed, "", stripCompressionSuffix(source), depth+1)
	}
	if isXzPayload(data, contentType, source) {
		decompressed, err := unxzRemoteDatasetPayload(data)
		if err != nil {
			return nil, err
		}
		return expandRemoteDatasetPayloads(decompressed, "", stripCompressionSuffix(source), depth+1)
	}
	return []remoteDatasetPayload{{Source: source, ContentType: contentType, Data: data}}, nil
}

func expandZipRemoteDatasetPayload(data []byte, source string, depth int) ([]remoteDatasetPayload, error) {
	reader, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return nil, err
	}

	payloads := make([]remoteDatasetPayload, 0, len(reader.File))
	for _, file := range reader.File {
		if file.FileInfo().IsDir() {
			continue
		}
		if shouldSkipArchiveMember(file.Name) {
			continue
		}
		rc, err := file.Open()
		if err != nil {
			continue
		}
		fileData, readErr := io.ReadAll(io.LimitReader(rc, remoteDatasetFetchLimitBytes+1))
		_ = rc.Close()
		if readErr != nil {
			continue
		}
		if len(fileData) > remoteDatasetFetchLimitBytes {
			return nil, fmt.Errorf("extracted file %q is larger than %d bytes", file.Name, remoteDatasetFetchLimitBytes)
		}
		nextSource := joinDatasetSource(source, file.Name)
		nested, err := expandRemoteDatasetPayloads(fileData, "", nextSource, depth+1)
		if err != nil {
			continue
		}
		payloads = append(payloads, nested...)
	}
	if len(payloads) == 0 {
		return nil, fmt.Errorf("zip archive %q did not contain any extractable dataset files", source)
	}
	return payloads, nil
}

func expandTarRemoteDatasetPayload(data []byte, source string, depth int) ([]remoteDatasetPayload, error) {
	reader := tar.NewReader(bytes.NewReader(data))
	payloads := make([]remoteDatasetPayload, 0)
	for {
		hdr, err := reader.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			continue
		}
		if hdr == nil || hdr.FileInfo().IsDir() {
			continue
		}
		if shouldSkipArchiveMember(hdr.Name) {
			continue
		}
		if hdr.Size > remoteDatasetFetchLimitBytes {
			return nil, fmt.Errorf("extracted file %q is larger than %d bytes", hdr.Name, remoteDatasetFetchLimitBytes)
		}
		fileData, err := io.ReadAll(io.LimitReader(reader, remoteDatasetFetchLimitBytes+1))
		if err != nil {
			continue
		}
		nextSource := joinDatasetSource(source, hdr.Name)
		nested, err := expandRemoteDatasetPayloads(fileData, "", nextSource, depth+1)
		if err != nil {
			continue
		}
		payloads = append(payloads, nested...)
	}
	if len(payloads) == 0 {
		return nil, fmt.Errorf("tar archive %q did not contain any extractable dataset files", source)
	}
	return payloads, nil
}

func gunzipRemoteDatasetPayload(data []byte) ([]byte, error) {
	reader, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer reader.Close()
	return io.ReadAll(io.LimitReader(reader, remoteDatasetFetchLimitBytes+1))
}

func bunzip2RemoteDatasetPayload(data []byte) ([]byte, error) {
	return io.ReadAll(io.LimitReader(bzip2.NewReader(bytes.NewReader(data)), remoteDatasetFetchLimitBytes+1))
}

func unxzRemoteDatasetPayload(data []byte) ([]byte, error) {
	reader, err := xz.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	return io.ReadAll(io.LimitReader(reader, remoteDatasetFetchLimitBytes+1))
}

func isZipPayload(data []byte, contentType, source string) bool {
	if len(data) >= 4 && bytes.Equal(data[:4], []byte("PK\x03\x04")) {
		return true
	}
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "zip") {
		return true
	}
	lower := strings.ToLower(source)
	return strings.HasSuffix(lower, ".zip") || strings.HasSuffix(lower, ".jar") || strings.HasSuffix(lower, ".war")
}

func isTarPayload(data []byte, contentType, source string) bool {
	if len(data) >= 262 && bytes.Equal(data[257:262], []byte("ustar")) {
		return true
	}
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "tar") {
		return true
	}
	lower := strings.ToLower(source)
	return strings.HasSuffix(lower, ".tar")
}

func isGzipPayload(data []byte, contentType, source string) bool {
	if len(data) >= 2 && data[0] == 0x1f && data[1] == 0x8b {
		return true
	}
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "gzip") || strings.Contains(ct, "x-gzip") {
		return true
	}
	lower := strings.ToLower(source)
	return strings.HasSuffix(lower, ".gz") || strings.HasSuffix(lower, ".tgz") || strings.HasSuffix(lower, ".tar.gz")
}

func isBzip2Payload(data []byte, contentType, source string) bool {
	if len(data) >= 3 && bytes.Equal(data[:3], []byte("BZh")) {
		return true
	}
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "bzip2") || strings.Contains(ct, "x-bzip2") {
		return true
	}
	lower := strings.ToLower(source)
	return strings.HasSuffix(lower, ".bz2") || strings.HasSuffix(lower, ".tbz2") || strings.HasSuffix(lower, ".tbz")
}

func isXzPayload(data []byte, contentType, source string) bool {
	if len(data) >= 6 && bytes.Equal(data[:6], []byte{0xfd, '7', 'z', 'X', 'Z', 0x00}) {
		return true
	}
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "x-xz") || strings.Contains(ct, "xz") {
		return true
	}
	lower := strings.ToLower(source)
	return strings.HasSuffix(lower, ".xz") || strings.HasSuffix(lower, ".txz")
}

func stripCompressionSuffix(source string) string {
	lower := strings.ToLower(strings.TrimSpace(source))
	switch {
	case strings.HasSuffix(lower, ".tar.gz"):
		return source[:len(source)-3]
	case strings.HasSuffix(lower, ".tar.bz2"):
		return source[:len(source)-4]
	case strings.HasSuffix(lower, ".tgz"), strings.HasSuffix(lower, ".tbz2"), strings.HasSuffix(lower, ".tbz"), strings.HasSuffix(lower, ".txz"):
		if idx := strings.LastIndex(source, "."); idx > 0 {
			return source[:idx] + ".tar"
		}
	case strings.HasSuffix(lower, ".gz"):
		return source[:len(source)-3]
	case strings.HasSuffix(lower, ".bz2"):
		return source[:len(source)-4]
	case strings.HasSuffix(lower, ".xz"):
		return source[:len(source)-3]
	}
	return source
}

func joinDatasetSource(parent, child string) string {
	parent = strings.TrimSpace(parent)
	child = strings.TrimSpace(child)
	switch {
	case parent == "":
		return child
	case child == "":
		return parent
	default:
		return parent + "!" + child
	}
}

func shouldSkipArchiveMember(name string) bool {
	base := strings.ToLower(strings.TrimSpace(filepath.Base(name)))
	if base == "" {
		return true
	}
	switch {
	case strings.HasPrefix(base, "readme"),
		strings.HasPrefix(base, "license"),
		strings.HasPrefix(base, "notice"),
		strings.HasPrefix(base, "changelog"),
		strings.HasPrefix(base, "copying"):
		return true
	case strings.HasSuffix(base, ".md"),
		strings.HasSuffix(base, ".rst"),
		strings.HasSuffix(base, ".html"),
		strings.HasSuffix(base, ".htm"),
		strings.HasSuffix(base, ".pdf"),
		strings.HasSuffix(base, ".png"),
		strings.HasSuffix(base, ".jpg"),
		strings.HasSuffix(base, ".jpeg"),
		strings.HasSuffix(base, ".gif"),
		strings.HasSuffix(base, ".svg"),
		strings.HasSuffix(base, ".exe"),
		strings.HasSuffix(base, ".dll"),
		strings.HasSuffix(base, ".so"),
		strings.HasSuffix(base, ".o"),
		strings.HasSuffix(base, ".a"),
		strings.HasSuffix(base, ".pyc"),
		strings.HasSuffix(base, ".class"),
		strings.HasSuffix(base, ".zip"),
		strings.HasSuffix(base, ".gz"),
		strings.HasSuffix(base, ".tar"),
		strings.HasSuffix(base, ".bz2"),
		strings.HasSuffix(base, ".xz"):
		return true
	}
	return false
}

func mergeDatasetFormat(current, next string) string {
	current = strings.ToLower(strings.TrimSpace(current))
	next = strings.ToLower(strings.TrimSpace(next))
	if next == "" {
		return current
	}
	if current == "" {
		return next
	}
	if current == next {
		return current
	}
	return "archive"
}

func looksLikeHTMLDataset(raw []byte, contentType string) bool {
	ct := strings.ToLower(strings.TrimSpace(contentType))
	if strings.Contains(ct, "text/html") || strings.Contains(ct, "application/xhtml") {
		return true
	}

	if isBinary(raw) {
		return false
	}

	// Only check the first few hundred bytes for common HTML tags
	checkLen := len(raw)
	if checkLen > 1024 {
		checkLen = 1024
	}
	trimmed := strings.ToLower(strings.TrimSpace(string(raw[:checkLen])))
	return strings.HasPrefix(trimmed, "<!doctype html") ||
		strings.HasPrefix(trimmed, "<html") ||
		strings.HasPrefix(trimmed, "<body")
}

// ---- merged from remotedatasetshelpers.go ----

func downloadRemoteDataset(rawURL string) ([]byte, string, error) {
	parsed, err := validateRemoteDatasetURL(rawURL)
	if err != nil {
		return nil, "", err
	}

	client := &http.Client{Timeout: 20 * time.Second}
	req, err := http.NewRequest(http.MethodGet, parsed.String(), nil)
	if err != nil {
		return nil, "", err
	}
	req.Header.Set("User-Agent", "agent-ebpf-filter/1.0")

	resp, err := client.Do(req)
	if err != nil {
		return nil, "", err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, "", fmt.Errorf("remote dataset fetch failed: %s", resp.Status)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, remoteDatasetFetchLimitBytes+1))
	if err != nil {
		return nil, "", err
	}
	if len(body) > remoteDatasetFetchLimitBytes {
		return nil, "", fmt.Errorf("remote dataset is larger than %d bytes", remoteDatasetFetchLimitBytes)
	}

	contentType := resp.Header.Get("Content-Type")
	if mediaType, _, err := mime.ParseMediaType(contentType); err == nil {
		contentType = mediaType
	}
	return body, contentType, nil
}

func validateRemoteDatasetURL(rawURL string) (*url.URL, error) {
	parsed, err := url.Parse(strings.TrimSpace(rawURL))
	if err != nil {
		return nil, err
	}
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return nil, fmt.Errorf("unsupported dataset URL scheme: %s", parsed.Scheme)
	}
	if parsed.Host == "" {
		return nil, errors.New("dataset URL must include a host")
	}
	return parsed, nil
}

func normalizeRemoteDatasetFormat(format, sourceURL string) string {
	format = strings.ToLower(strings.TrimSpace(format))
	if format != "" && format != "auto" {
		return format
	}

	ext := strings.ToLower(filepath.Ext(sourceURL))
	switch ext {
	case ".json":
		return "json"
	case ".jsonl", ".ndjson":
		return "jsonl"
	case ".csv":
		return "csv"
	case ".tsv":
		return "tsv"
	case ".txt", ".log":
		return "text"
	default:
		return "auto"
	}
}

func normalizeRemoteDatasetLabelMode(mode string) string {
	switch strings.ToLower(strings.TrimSpace(mode)) {
	case "", "preserve", "keep", "source":
		return "preserve"
	case "unlabeled", "manual", "none":
		return "unlabeled"
	case "heuristic", "auto", "automatic":
		return "heuristic"
	case "block", "dangerous", "highrisk", "high-risk":
		return "block"
	default:
		return "preserve"
	}
}

func contentTypeForDatasetFormat(format string) string {
	switch strings.ToLower(strings.TrimSpace(format)) {
	case "json":
		return "application/json"
	case "jsonl", "ndjson":
		return "application/x-ndjson"
	case "csv":
		return "text/csv; charset=utf-8"
	case "tsv":
		return "text/tab-separated-values; charset=utf-8"
	case "text", "txt":
		return "text/plain; charset=utf-8"
	default:
		return "text/plain; charset=utf-8"
	}
}

func parseDatasetLimit(limit int) int {
	if limit <= 0 {
		return 200
	}
	if limit > 5000 {
		return 5000
	}
	return limit
}

func trainingSampleToRemoteDatasetRow(index int, sample TrainingSample) remoteDatasetRow {
	label := sampleLabelName(sample.Label)
	if label == "" {
		label = "-"
	}
	timestamp := sample.Timestamp.UTC()
	if timestamp.IsZero() {
		timestamp = time.Now().UTC()
	}
	return remoteDatasetRow{
		Row:          index,
		CommandLine:  trainingSampleCommandLine(sample),
		Comm:         sample.Comm,
		Args:         append([]string(nil), sample.Args...),
		Label:        label,
		LabelSource:  sample.UserLabel,
		Category:     sample.Category,
		AnomalyScore: sample.AnomalyScore,
		HasAnomaly:   true,
		Timestamp:    timestamp.Format(time.RFC3339),
		UserLabel:    sample.UserLabel,
	}
}

