// ---- merged from server_mcp.go ----

type MCPTailEventsInput struct {
	Limit int `json:"limit,omitempty" jsonschema:"maximum number of events to return"`
}

type MCPConfigSnapshotOutput struct {
	Runtime                RuntimeSettings        `json:"runtime"`
	MCPEndpoint            string                 `json:"mcpEndpoint"`
	AuthHeaderName         string                 `json:"authHeaderName"`
	Tags                   []string               `json:"tags"`
	TrackedCommands        map[string]string      `json:"trackedCommands"`
	TrackedPaths           map[string]string      `json:"trackedPaths"`
	WrapperRules           map[string]WrapperRule `json:"wrapperRules"`
	PersistedEventLogPath  string                 `json:"persistedEventLogPath"`
	PersistedEventLogAlive bool                   `json:"persistedEventLogAlive"`
}

type MCPEventRecord struct {
	ReceivedAt time.Time      `json:"receivedAt"`
	Event      *pb.Event      `json:"event"`
	Envelope   map[string]any `json:"envelope,omitempty"`
}

type MCPTailEventsOutput struct {
	Source string           `json:"source"`
	Limit  int              `json:"limit"`
	Events []MCPEventRecord `json:"events"`
}

var (
	mcpServerOnce sync.Once
	mcpServer     *mcp.Server
)

func buildTrackedCommandsSnapshot() map[string]string {
	out := make(map[string]string)
	if trackerMaps.TrackedComms == nil {
		return out
	}
	iter := trackerMaps.TrackedComms.Iterate()
	var k [16]byte
	var tid uint32
	for iter.Next(&k, &tid) {
		out[string(bytes.TrimRight(k[:], "\x00"))] = getTagName(tid)
	}
	return out
}

func buildTrackedPathsSnapshot() map[string]string {
	out := make(map[string]string)
	if trackerMaps.TrackedPaths == nil {
		return out
	}
	iter := trackerMaps.TrackedPaths.Iterate()
	var k [256]byte
	var tid uint32
	for iter.Next(&k, &tid) {
		out[string(bytes.TrimRight(k[:], "\x00"))] = getTagName(tid)
	}
	return out
}

func buildTagsSnapshot() []string {
	tagsMu.RLock()
	defer tagsMu.RUnlock()

	type tagEntry struct {
		id   uint32
		name string
	}
	entries := make([]tagEntry, 0, len(tagMap))
	for id, name := range tagMap {
		entries = append(entries, tagEntry{id: id, name: name})
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].id == entries[j].id {
			return entries[i].name < entries[j].name
		}
		return entries[i].id < entries[j].id
	})
	out := make([]string, 0, len(entries))
	for _, entry := range entries {
		out = append(out, entry.name)
	}
	return out
}

func buildWrapperRulesSnapshot() map[string]WrapperRule {
	rulesMu.RLock()
	defer rulesMu.RUnlock()

	out := make(map[string]WrapperRule, len(wrapperRules))
	for comm, rule := range wrapperRules {
		out[comm] = rule
	}
	return out
}

func buildMCPServer() *mcp.Server {
	mcpServerOnce.Do(func() {
		server := mcp.NewServer(&mcp.Implementation{
			Name:    "agent-ebpf-filter",
			Version: "1.0.0",
		}, nil)

		mcp.AddTool(server, &mcp.Tool{
			Name:        "tail_events",
			Title:       "Tail Captured Events",
			Description: "Return the latest captured eBPF / wrapper / hook events, preferring the persistent JSONL log when it is enabled.",
		}, func(ctx context.Context, req *mcp.CallToolRequest, args MCPTailEventsInput) (*mcp.CallToolResult, MCPTailEventsOutput, error) {
			limit := args.Limit
			if limit <= 0 {
				limit = 50
			}
			if limit > 500 {
				limit = 500
			}
			records, source, err := runtimeSettingsStore.RecentEvents(limit)
			if err != nil {
				return nil, MCPTailEventsOutput{}, err
			}
			events := make([]MCPEventRecord, 0, len(records))
			for _, record := range records {
				record = normalizeCapturedEventRecord(record)
				if record.Event == nil {
					continue
				}
				events = append(events, MCPEventRecord{
					ReceivedAt: record.ReceivedAt,
					Event:      record.Event,
					Envelope:   eventEnvelopeToJSONValue(record.Envelope),
				})
			}
			return nil, MCPTailEventsOutput{
				Source: source,
				Limit:  limit,
				Events: events,
			}, nil
		})

		mcp.AddTool(server, &mcp.Tool{
			Name:        "config_snapshot",
			Title:       "Capture Configuration Snapshot",
			Description: "Return the current registry, runtime logging settings, and MCP endpoint information.",
		}, func(ctx context.Context, req *mcp.CallToolRequest, _ struct{}) (*mcp.CallToolResult, MCPConfigSnapshotOutput, error) {
			settings := runtimeSettingsStore.Snapshot()
			logPath := settings.LogFilePath
			logAlive := false
			if settings.LogPersistenceEnabled && logPath != "" {
				if info, err := os.Stat(logPath); err == nil && !info.IsDir() {
					logAlive = true
				}
			}
			return nil, MCPConfigSnapshotOutput{
				Runtime:                settings,
				MCPEndpoint:            fmt.Sprintf("http://127.0.0.1:%d/mcp", resolveBackendPort()),
				AuthHeaderName:         "X-API-KEY",
				Tags:                   buildTagsSnapshot(),
				TrackedCommands:        buildTrackedCommandsSnapshot(),
				TrackedPaths:           buildTrackedPathsSnapshot(),
				WrapperRules:           buildWrapperRulesSnapshot(),
				PersistedEventLogPath:  logPath,
				PersistedEventLogAlive: logAlive,
			}, nil
		})

		mcpServer = server
	})

	return mcpServer
}

func buildMCPHandler() http.Handler {
	return mcp.NewSSEHandler(func(*http.Request) *mcp.Server {
		return buildMCPServer()
	}, nil)
}

// ---- merged from server_uds.go ----

func startUDSServer(broadcast chan *pb.Event) {
	_ = os.Remove(udsPath)
	l, err := net.Listen("unix", udsPath)
	if err != nil {
		return
	}
	_ = os.Chmod(udsPath, 0600)
	if uid, gid, ok := originalInvokerIDs(); ok {
		_ = os.Chown(udsPath, int(uid), int(gid))
	}
	defer l.Close()
	for {
		conn, err := l.Accept()
		if err != nil {
			continue
		}
		go func(c net.Conn) {
			defer c.Close()
			if err := verifyUDSPeerCredentials(c); err != nil {
				return
			}
			buf := make([]byte, 4096)
			for {
				n, err := c.Read(buf)
				if err != nil {
					return
				}
				req := &pb.WrapperRequest{}
				if err := proto.Unmarshal(buf[:n], req); err != nil {
					continue
				}

				rulesMu.RLock()
				rule, hasRule := wrapperRules[req.Comm]
				rulesMu.RUnlock()

				ruleAction := ""
				rulePriority := 0
				if hasRule {
					ruleAction = rule.Action
					rulePriority = rule.Priority
				}

				// ── Layer 1: Rule-based classification + embedding + anomaly scoring ──
				classification, embedding := globalEmbedder.ClassifyAndEmbed(req.Comm, req.Args)
				globalEmbedder.RegisterVocab(fmt.Sprintf("process %s performed wrapper_intercept on %s %s tagged Wrapper",
					req.Comm, req.Comm, strings.Join(req.Args, " ")))

				// Only cluster if we have enough history (avoid cold-start noise)
				globalEmbedder.AddToCluster(embedding)
				anomalyScore := globalEmbedder.ComputeAnomalyScore(embedding)

				// ── Network audit ──
				cmdline := strings.Join(req.Args, " ")
				netAudit := AuditNetworkBehavior(req.Comm, cmdline)

				// ── Layer 2: ML random forest prediction ──
				features := globalFeatureExtractor.Extract(req.Comm, req.Args, req.User, req.Pid)
				var mlPrediction Prediction
				if mlEnabled && mlModelLoaded {
					mlPrediction = mlEngine.Predict(features)
				}

				// ── Decision fusion ──
				resolvedAction, reason := resolveAction(
					req, ruleAction, rulePriority,
					classification, anomalyScore, mlPrediction, mlConfig,
				)

				// ── Apply REWRITE logic ──
				resp := &pb.WrapperResponse{
					Action:         resolvedAction,
					Classification: classification,
					AnomalyScore:   anomalyScore,
				}

				if mlEnabled && mlModelLoaded {
					resp.MlScore = mlPrediction.Confidence
					resp.MlAction = actionLabel[mlPrediction.Action]
					resp.MlReasoning = mlReasoning(mlPrediction, anomalyScore, classification)
				}

				resp.Message = reason

				if resolvedAction == pb.WrapperResponse_REWRITE && hasRule {
					resp.Action = pb.WrapperResponse_REWRITE
					if rule.Regex != "" {
						fullArgs := strings.Join(req.Args, " ")
						re, err := regexp.Compile(rule.Regex)
						if err == nil {
							newFull := re.ReplaceAllString(fullArgs, rule.Replacement)
							resp.RewrittenArgs = strings.Fields(newFull)
						} else {
							resp.RewrittenArgs = rule.RewrittenCmd
						}
					} else {
						resp.RewrittenArgs = rule.RewrittenCmd
					}
				}

				// ── Record to training store and history buffer ──
				if mlEnabled && globalTrainingStore != nil {
					sample := TrainingSample{
						Features:     features,
						Label:        -1, // unlabeled initially
						CommandLine:  joinCommandLine(req.Comm, req.Args),
						Comm:         req.Comm,
						Args:         req.Args,
						Category:     classification.PrimaryCategory,
						AnomalyScore: anomalyScore,
						Timestamp:    time.Now(),
					}
					globalTrainingStore.Add(sample)
				}

				globalFeatureExtractor.AddHistory(
					req.Comm,
					classification.PrimaryCategory,
					actionLabel[mlPrediction.Action],
					anomalyScore,
				)

				decision := actionLabel[int32(resolvedAction)]
				riskScore := maxFloat64(anomalyScore, mlPrediction.Confidence)
				ctx := buildProcessContextFromWrapperRequest(req, decision, riskScore)
				trackedProcessContexts.Set(req.Pid, ctx)

				// Register wrapper PID in eBPF agent_pids
				if trackerMaps.AgentPids != nil {
					_ = trackerMaps.AgentPids.Put(req.Pid, getTagID("Wrapper"))
				}
				if trackerMaps.TrackedComms != nil {
					var k [16]byte
					copy(k[:], req.Comm)
					_ = trackerMaps.TrackedComms.Put(k, getTagID("Wrapper"))
				}

				select {
				case broadcast <- &pb.Event{
					Pid:            req.Pid,
					Comm:           req.Comm,
					Type:           "wrapper_intercept",
					EventType:      pb.EventType_WRAPPER_INTERCEPT,
					Tag:            "Wrapper",
					Path:           strings.Join(append([]string{req.Comm}, req.Args...), " "),
					Behavior:       classification,
					ExtraInfo:      fmt.Sprintf("net_audit:%s risk:%.0f", netAudit.RiskLevel, netAudit.RiskScore),
					SchemaVersion:  eventSchemaVersion,
					RootAgentPid:   ctx.RootAgentPid,
					AgentRunId:     ctx.AgentRunID,
					TaskId:         ctx.TaskID,
					ConversationId: ctx.ConversationID,
					TurnId:         ctx.TurnID,
					ToolCallId:     ctx.ToolCallID,
					ToolName:       ctx.ToolName,
					TraceId:        ctx.TraceID,
					SpanId:         ctx.SpanID,
					Decision:       ctx.Decision,
					RiskScore:      ctx.RiskScore,
					ContainerId:    ctx.ContainerID,
					ArgvDigest:     ctx.ArgvDigest,
					Cwd:            ctx.Cwd,
				}:
				default:
				}
				out, _ := proto.Marshal(resp)
				_, _ = c.Write(out)
			}
		}(conn)
	}
}

func verifyUDSPeerCredentials(conn net.Conn) error {
	unixConn, ok := conn.(*net.UnixConn)
	if !ok {
		return errors.New("unexpected UDS connection type")
	}

	rawConn, err := unixConn.SyscallConn()
	if err != nil {
		return err
	}

	var cred *unix.Ucred
	var credErr error
	if err := rawConn.Control(func(fd uintptr) {
		cred, credErr = unix.GetsockoptUcred(int(fd), unix.SOL_SOCKET, unix.SO_PEERCRED)
	}); err != nil {
		return err
	}
	if credErr != nil {
		return credErr
	}
	if cred == nil {
		return errors.New("missing peer credentials")
	}

	if _, ok := allowedControlPlaneUIDs()[cred.Uid]; !ok {
		return fmt.Errorf("unauthorized UDS peer uid %d", cred.Uid)
	}
	return nil
}

// ---- merged from sessioncoreshell.go ----

type shellSession struct {
	mu sync.Mutex

	id        string
	label     string
	kind      string
	shellReq  string
	shellPath string
	command   string
	args      []string
	workDir   string
	createdAt time.Time
	updatedAt time.Time
	status    string
	lastError string
	pid       int

	cmd      *exec.Cmd
	ptmx     *os.File
	conn     *websocket.Conn
	attached bool
	closed   bool

	backlog      []byte
	backlogLimit int
	writeMu      sync.Mutex

	onChange func()
}

var shellSessions = newShellSessionManager()

func (m *shellSessionManager) Create(req ShellSessionCreateRequest) (*ShellSessionInfo, error) {
	shellReq := stringsTrimToDefault(req.Shell, "auto")
	label := strings.TrimSpace(req.Label)
	commandReq := strings.TrimSpace(req.Command)
	launchArgs := append([]string(nil), req.Args...)
	kind := normalizeShellSessionKind(req.Kind)
	if kind == shellSessionKindShell {
		shellReqLower := strings.ToLower(shellReq)
		commandReqLower := strings.ToLower(commandReq)
		switch {
		case shellReqLower == shellSessionKindTmux || commandReqLower == shellSessionKindTmux:
			kind = shellSessionKindTmux
		case shellReqLower == shellSessionKindWrapper || commandReqLower == "agent-wrapper":
			kind = shellSessionKindWrapper
		case strings.Contains(shellReqLower, "python") || strings.Contains(shellReqLower, "node") ||
			strings.Contains(commandReqLower, "python") || strings.Contains(commandReqLower, "node"):
			kind = shellSessionKindScript
		}
	}
	launchReq := shellReq
	if commandReq != "" {
		launchReq = commandReq
	}
	if label == "" {
		label = launchReq
	}

	var launchPath string
	if kind == shellSessionKindWrapper || shellReq == shellSessionKindWrapper || commandReq == "agent-wrapper" || launchReq == "agent-wrapper" {
		launchPath = resolveWrapperPath()
	} else {
		launchPath = resolveShellPath(launchReq)
	}
	if launchPath == "" {
		return nil, fmt.Errorf("launcher not found")
	}

	workDir := resolveShellWorkDir()
	if req.WorkDir != "" {
		if info, err := os.Stat(req.WorkDir); err == nil && info.IsDir() {
			workDir = req.WorkDir
		} else {
			return nil, fmt.Errorf("invalid working directory: %s", req.WorkDir)
		}
	}

	cols := req.Cols
	if cols <= 0 {
		cols = 100
	}
	rows := req.Rows
	if rows <= 0 {
		rows = 32
	}

	cmd := exec.Command(launchPath, launchArgs...)
	cmd.Dir = workDir
	cmd.Env = setEnvValue(os.Environ(), "TERM", "xterm-256color")

	// Disable fish shell's query-terminal feature to prevent 10s wait warnings
	ff := os.Getenv("fish_features")
	if ff == "" {
		ff = "no-query-term"
	} else if !strings.Contains(ff, "no-query-term") {
		ff = ff + ",no-query-term"
	}
	cmd.Env = setEnvValue(cmd.Env, "fish_features", ff)
	for key, value := range req.Env {
		if strings.TrimSpace(key) == "" {
			continue
		}
		cmd.Env = setEnvValue(cmd.Env, key, value)
	}

	dropPrivileges(cmd)

	ptmx, err := pty.StartWithSize(cmd, &pty.Winsize{
		Cols: uint16(cols),
		Rows: uint16(rows),
	})
	if err != nil {
		return nil, err
	}

	now := time.Now()
	session := &shellSession{
		id:           fmt.Sprintf("%d", m.nextID.Add(1)),
		label:        label,
		kind:         kind,
		shellReq:     shellReq,
		shellPath:    launchPath,
		command:      commandReq,
		args:         append([]string(nil), launchArgs...),
		workDir:      workDir,
		createdAt:    now,
		updatedAt:    now,
		status:       shellSessionStatusRunning,
		pid:          cmd.Process.Pid,
		cmd:          cmd,
		ptmx:         ptmx,
		backlogLimit: shellSessionBacklogLimit,
		onChange:     func() { m.notify() },
	}

	m.mu.Lock()
	m.sessions[session.id] = session
	m.mu.Unlock()

	m.notify()

	go session.readLoop()

	info := session.snapshot()
	return &info, nil
}

func (m *shellSessionManager) List() []ShellSessionInfo {
	m.mu.RLock()
	defer m.mu.RUnlock()

	items := make([]ShellSessionInfo, 0, len(m.sessions))
	for _, session := range m.sessions {
		items = append(items, session.snapshot())
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].CreatedAt.Equal(items[j].CreatedAt) {
			return items[i].ID > items[j].ID
		}
		return items[i].CreatedAt.After(items[j].CreatedAt)
	})
	return items
}

func (m *shellSessionManager) Get(id string) (*shellSession, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	session, ok := m.sessions[id]
	return session, ok
}

func (m *shellSessionManager) Delete(id string) error {
	m.mu.Lock()
	session, ok := m.sessions[id]
	if ok {
		delete(m.sessions, id)
	}
	m.mu.Unlock()
	m.notify()
	if !ok {
		return fmt.Errorf("shell session not found")
	}
	_ = session.Close()
	return nil
}

func (m *shellSessionManager) SendInput(id string, payload []byte) error {
	session, ok := m.Get(id)
	if !ok {
		return fmt.Errorf("shell session not found")
	}
	return session.WriteInput(payload)
}

func (m *shellSessionManager) ClearClosed() {
	m.mu.Lock()
	defer m.mu.Unlock()
	for id, session := range m.sessions {
		session.mu.Lock()
		status := session.status
		closed := session.closed
		session.mu.Unlock()
		if closed || status == shellSessionStatusExited || status == shellSessionStatusClosed {
			delete(m.sessions, id)
		}
	}
}

func (s *shellSession) readLoop() {
	buf := make([]byte, 4096)
	for {
		n, err := s.ptmx.Read(buf)
		if n > 0 {
			s.forwardOutput(bytes.Clone(buf[:n]))
		}
		if err != nil {
			s.finishRead(err)
			return
		}
	}
}

func (s *shellSession) emitStdioEvent(stream string, payload []byte) {
	if s == nil || len(payload) == 0 || broadcast == nil {
		return
	}
	fd := "stdout"
	if stream == "stdin" {
		fd = "stdin"
	}
	event := &pb.Event{
		Pid:           uint32(maxInt(s.pid, 0)),
		Type:          "stdio",
		EventType:     pb.EventType_STDIO,
		Tag:           "Shell Session",
		Comm:          firstNonEmpty(s.label, s.kind, "shell"),
		Path:          stream,
		Bytes:         uint64(len(payload)),
		ExtraInfo:     fmt.Sprintf("session_id=%s stream=%s fd=%s size=%d", s.id, stream, fd, len(payload)),
		SchemaVersion: eventSchemaVersion,
		Cwd:           s.workDir,
	}
	sendTLSBridge(broadcast, event)
}

func (s *shellSession) forwardOutput(payload []byte) {
	if len(payload) == 0 {
		return
	}

	s.emitStdioEvent("stdout", payload)

	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return
	}
	s.appendBacklogLocked(payload)
	conn := s.conn
	s.updatedAt = time.Now()
	s.mu.Unlock()

	if conn == nil {
		return
	}

	s.writeMu.Lock()
	err := conn.WriteMessage(websocket.BinaryMessage, payload)
	s.writeMu.Unlock()
	if err != nil {
		s.Detach(conn)
	}
}

func (s *shellSession) finishRead(readErr error) {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return
	}
	if readErr != nil && !errors.Is(readErr, io.EOF) {
		s.status = shellSessionStatusError
		s.lastError = readErr.Error()
	} else {
		s.status = shellSessionStatusExited
	}
	s.updatedAt = time.Now()
	conn := s.conn
	s.conn = nil
	s.attached = false
	s.mu.Unlock()

	if conn != nil {
		_ = conn.Close()
	}
	if s.onChange != nil {
		s.onChange()
	}
}

func (s *shellSession) Attach(conn *websocket.Conn) ([]byte, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil, fmt.Errorf("shell session has been closed")
	}
	if s.status != shellSessionStatusRunning {
		return nil, fmt.Errorf("shell session is not running")
	}
	if s.conn != nil {
		return nil, fmt.Errorf("shell session is already attached")
	}
	s.conn = conn
	s.attached = true
	s.updatedAt = time.Now()
	return bytes.Clone(s.backlog), nil
}

func (s *shellSession) Detach(conn *websocket.Conn) {
	s.mu.Lock()
	if s.conn == conn {
		s.conn = nil
		s.attached = false
		s.updatedAt = time.Now()
	}
	s.mu.Unlock()
	_ = conn.Close()
}

func (s *shellSession) WriteInput(payload []byte) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return fmt.Errorf("shell session has been closed")
	}
	if s.ptmx == nil {
		return fmt.Errorf("shell session PTY is unavailable")
	}
	_, err := s.ptmx.Write(payload)
	if err == nil {
		s.emitStdioEvent("stdin", payload)
	}
	return err
}

func (s *shellSession) Resize(cols, rows int) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return fmt.Errorf("shell session has been closed")
	}
	if s.ptmx == nil {
		return fmt.Errorf("shell session PTY is unavailable")
	}
	return pty.Setsize(s.ptmx, &pty.Winsize{
		Cols: uint16(cols),
		Rows: uint16(rows),
	})
}

func (s *shellSession) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	s.status = shellSessionStatusClosed
	s.updatedAt = time.Now()
	conn := s.conn
	s.conn = nil
	s.attached = false
	ptmx := s.ptmx
	s.ptmx = nil
	cmd := s.cmd
	s.mu.Unlock()

	if conn != nil {
		_ = conn.Close()
	}
	if ptmx != nil {
		_ = ptmx.Close()
	}
	if cmd != nil && cmd.Process != nil {
		_ = cmd.Process.Kill()
	}
	if cmd != nil {
		_ = cmd.Wait()
	}
	return nil
}

func (s *shellSession) snapshot() ShellSessionInfo {
	s.mu.Lock()
	defer s.mu.Unlock()
	info := ShellSessionInfo{
		ID:        s.id,
		Label:     s.label,
		Kind:      s.kind,
		Shell:     s.shellReq,
		ShellPath: s.shellPath,
		Command:   s.command,
		Args:      append([]string(nil), s.args...),
		WorkDir:   s.workDir,
		PID:       s.pid,
		Status:    s.status,
		Attached:  s.attached,
		CreatedAt: s.createdAt,
		UpdatedAt: s.updatedAt,
		LastError: s.lastError,
	}
	return info
}

func (s *shellSession) appendBacklogLocked(payload []byte) {
	if len(payload) == 0 {
		return
	}
	if s.backlogLimit <= 0 {
		s.backlog = append(s.backlog, payload...)
		return
	}
	if len(payload) >= s.backlogLimit {
		s.backlog = append(s.backlog[:0], payload[len(payload)-s.backlogLimit:]...)
		return
	}
	overflow := len(s.backlog) + len(payload) - s.backlogLimit
	if overflow > 0 {
		if overflow >= len(s.backlog) {
			s.backlog = append(s.backlog[:0], payload...)
			return
		}
		s.backlog = append(bytes.Clone(s.backlog[overflow:]), payload...)
		return
	}
	s.backlog = append(s.backlog, payload...)
}

// ---- merged from sessionhandlersshell.go ----

func (m *shellSessionManager) AttachWS(c *gin.Context) {
	sessionID := stringsTrimToDefault(c.Query("session_id"), "")
	if sessionID == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "session_id is required"})
		return
	}

	session, ok := m.Get(sessionID)
	if !ok {
		c.JSON(http.StatusNotFound, gin.H{"error": "shell session not found"})
		return
	}

	conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		return
	}

	backlog, err := session.Attach(conn)
	if err != nil {
		_ = conn.WriteMessage(websocket.TextMessage, []byte(err.Error()))
		_ = conn.Close()
		return
	}
	defer session.Detach(conn)

	if len(backlog) > 0 {
		session.writeMu.Lock()
		if err := conn.WriteMessage(websocket.BinaryMessage, backlog); err != nil {
			session.writeMu.Unlock()
			return
		}
		session.writeMu.Unlock()
	}

	for {
		messageType, data, err := conn.ReadMessage()
		if err != nil {
			return
		}

		switch messageType {
		case websocket.BinaryMessage:
			if len(data) == 0 {
				continue
			}
			if err := session.WriteInput(data); err != nil {
				return
			}
		case websocket.TextMessage:
			var ctrl shellControlMessage
			if err := json.Unmarshal(data, &ctrl); err == nil && ctrl.Type == "resize" {
				if ctrl.Cols > 0 && ctrl.Rows > 0 {
					_ = session.Resize(ctrl.Cols, ctrl.Rows)
				}
				continue
			}
			if err := session.WriteInput(data); err != nil {
				return
			}
		}
	}
}

func serveShellSessionsWS(c *gin.Context) {
	conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	notifyCh := shellSessions.subscribe()
	defer shellSessions.unsubscribe(notifyCh)

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	sendList := func() {
		list := shellSessions.List()
		data, err := json.Marshal(list)
		if err != nil {
			return
		}
		if err := conn.WriteMessage(websocket.TextMessage, data); err != nil {
			return
		}
	}

	sendList()

	for {
		select {
		case <-notifyCh:
			sendList()
		case <-done:
			return
		}
	}
}

func handleCreateShellSession(c *gin.Context) {
	var req ShellSessionCreateRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	session, err := shellSessions.Create(req)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, session)
}

func handleListShellSessions(c *gin.Context) {
	c.JSON(http.StatusOK, shellSessions.List())
}

func handleDeleteShellSession(c *gin.Context) {
	if err := shellSessions.Delete(c.Param("id")); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, gin.H{"status": "ok"})
}

func handleSendShellSessionInput(c *gin.Context) {
	sessionID := strings.TrimSpace(c.Param("id"))
	if sessionID == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "session id is required"})
		return
	}

	var req ShellSessionInputRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	data := []byte(req.Data)
	if len(data) == 0 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "data is required"})
		return
	}

	if err := shellSessions.SendInput(sessionID, data); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, gin.H{"status": "ok"})
}

func handleShellSessionsCleanup(c *gin.Context) {
	shellSessions.ClearClosed()
	c.JSON(http.StatusOK, gin.H{"status": "ok"})
}

func stringsTrimToDefault(value, fallback string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return fallback
	}
	return value
}

func normalizeShellSessionKind(value string) string {
	switch strings.TrimSpace(strings.ToLower(value)) {
	case shellSessionKindTmux:
		return shellSessionKindTmux
	case shellSessionKindScript:
		return shellSessionKindScript
	case shellSessionKindWrapper:
		return shellSessionKindWrapper
	case "", shellSessionKindShell:
		return shellSessionKindShell
	default:
		return shellSessionKindShell
	}
}

