func serveLegacyShellWS(c *gin.Context) {
	shellPath := resolveShellPath(c.DefaultQuery("shell", "auto"))
	if shellPath == "" {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "shell not found"})
		return
	}

	cols, rows := 80, 24
	if v, err := strconv.Atoi(c.DefaultQuery("cols", "80")); err == nil && v > 0 {
		cols = v
	}
	if v, err := strconv.Atoi(c.DefaultQuery("rows", "24")); err == nil && v > 0 {
		rows = v
	}

	cmd := exec.Command(shellPath)
	cmd.Dir = resolveShellWorkDir()
	cmd.Env = setEnvValue(os.Environ(), "TERM", "xterm-256color")

	// Disable fish shell's query-terminal feature to prevent 10s wait warnings
	ff := os.Getenv("fish_features")
	if ff == "" {
		ff = "no-query-term"
	} else if !strings.Contains(ff, "no-query-term") {
		ff = ff + ",no-query-term"
	}
	cmd.Env = setEnvValue(cmd.Env, "fish_features", ff)

	dropPrivileges(cmd)

	ptmx, err := pty.StartWithSize(cmd, &pty.Winsize{
		Cols: uint16(cols),
		Rows: uint16(rows),
	})
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		_ = ptmx.Close()
		if cmd.Process != nil {
			_ = cmd.Process.Kill()
		}
		_ = cmd.Wait()
		return
	}
	defer func() {
		_ = ptmx.Close()
		if cmd.Process != nil {
			_ = cmd.Process.Kill()
		}
		_ = cmd.Wait()
	}()

	go func() {
		defer conn.Close()
		buf := make([]byte, 4096)
		for {
			n, readErr := ptmx.Read(buf)
			if n > 0 {
				payload := append([]byte(nil), buf[:n]...)
				if writeErr := conn.WriteMessage(websocket.BinaryMessage, payload); writeErr != nil {
					return
				}
			}
			if readErr != nil {
				return
			}
		}
	}()

	for {
		messageType, data, err := conn.ReadMessage()
		if err != nil {
			return
		}

		switch messageType {
		case websocket.BinaryMessage:
			if len(data) == 0 {
				continue
			}
			if _, err := ptmx.Write(data); err != nil {
				return
			}
		case websocket.TextMessage:
			var ctrl shellControlMessage
			if err := json.Unmarshal(data, &ctrl); err == nil && ctrl.Type == "resize" {
				if ctrl.Cols > 0 && ctrl.Rows > 0 {
					_ = pty.Setsize(ptmx, &pty.Winsize{
						Cols: uint16(ctrl.Cols),
						Rows: uint16(ctrl.Rows),
					})
				}
				continue
			}
			if _, err := ptmx.Write(data); err != nil {
				return
			}
		}
	}
}

// ---- merged from spanhelpersotel.go ----

func collectIdleSpans(spans map[string]*activeOTelSpan, now time.Time, idleFor time.Duration) []*activeOTelSpan {
	if len(spans) == 0 {
		return nil
	}
	out := make([]*activeOTelSpan, 0)
	for _, span := range spans {
		if span == nil || now.Sub(span.lastSeen) < idleFor {
			continue
		}
		out = append(out, span)
	}
	return out
}

func collectIdleTaskSpans(tasks, tools map[string]*activeOTelSpan, now time.Time, idleFor time.Duration) []*activeOTelSpan {
	if len(tasks) == 0 {
		return nil
	}
	out := make([]*activeOTelSpan, 0)
	for _, span := range tasks {
		if span == nil || now.Sub(span.lastSeen) < idleFor || hasActiveToolForTask(tools, span.key) {
			continue
		}
		out = append(out, span)
	}
	return out
}

func collectIdleRunSpans(runs, tasks, tools map[string]*activeOTelSpan, now time.Time, idleFor time.Duration) []*activeOTelSpan {
	if len(runs) == 0 {
		return nil
	}
	out := make([]*activeOTelSpan, 0)
	for _, span := range runs {
		if span == nil || now.Sub(span.lastSeen) < idleFor || hasActiveTaskForRun(tasks, span.key) || hasActiveToolForRun(tools, span.key) {
			continue
		}
		out = append(out, span)
	}
	return out
}

func hasActiveToolForTask(tools map[string]*activeOTelSpan, taskKey string) bool {
	for _, span := range tools {
		if span != nil && span.taskKey == taskKey {
			return true
		}
	}
	return false
}

func hasActiveTaskForRun(tasks map[string]*activeOTelSpan, runKey string) bool {
	for _, span := range tasks {
		if span != nil && span.runKey == runKey {
			return true
		}
	}
	return false
}

func hasActiveToolForRun(tools map[string]*activeOTelSpan, runKey string) bool {
	for _, span := range tools {
		if span != nil && span.runKey == runKey {
			return true
		}
	}
	return false
}

func endSpanMap(spans map[string]*activeOTelSpan, ts time.Time) {
	if len(spans) == 0 {
		return
	}
	list := make([]*activeOTelSpan, 0, len(spans))
	for _, span := range spans {
		if span != nil {
			list = append(list, span)
		}
	}
	endSpanSlice(list, ts)
}

func endSpanSlice(spans []*activeOTelSpan, ts time.Time) {
	for _, span := range spans {
		if span == nil || span.span == nil {
			continue
		}
		span.span.End(oteltrace.WithTimestamp(ts))
	}
}

// ---- merged from startup_server.go ----

func chooseBackendPort() int {
	startPort, maxTries := 8080, 10
	if rawPort := strings.TrimSpace(os.Getenv("AGENT_BACKEND_PORT")); rawPort != "" {
		if configuredPort, err := strconv.Atoi(rawPort); err == nil && configuredPort > 0 {
			startPort = configuredPort
			maxTries = 1
		} else {
			log.Printf("[WARN] ignoring invalid AGENT_BACKEND_PORT=%q", rawPort)
		}
	}
	actualPort := startPort
	for i := 0; i < maxTries; i++ {
		l, err := net.Listen("tcp", fmt.Sprintf(":%d", startPort+i))
		if err == nil {
			actualPort = startPort + i
			l.Close()
			break
		}
	}
	return actualPort
}

func configureRuntimePort(port int) {
	clusterManagerStore.ConfigurePort(port)
	writePortFile(port)
	startClusterHeartbeatLoop()
}

