	TCPStateSynRecv     = netcore.TCPStateSynRecv
	TCPStateFinWait1    = netcore.TCPStateFinWait1
	TCPStateFinWait2    = netcore.TCPStateFinWait2
	TCPStateTimeWait    = netcore.TCPStateTimeWait
