func (t *ModelTrainer) trainPA(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < 10 {
		return nil, TrainResult{Error: "need >=10 labeled samples"}
	}

	C := 1.0
	if cfg.NumTrees > 0 {
		C = float64(cfg.NumTrees) / 10.0
	}
	maxIter := cfg.MinSamplesLeaf
	if maxIter < 100 {
		maxIter = 1000
	}

	m := NewPAModel(C, maxIter)
	m.Weights = make([][FeatureDim + 1]float64, m.Classes)
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	for c := range m.Weights {
		for d := range m.Weights[c] {
			m.Weights[c][d] = (rng.Float64() - 0.5) * 0.01
		}
	}

	var classWeights []float64
	if cfg.BalanceClasses {
		_, labels := extractFeaturesLabels(labeled)
		classWeights = computeClassWeights(labels, m.Classes)
	}
	trainSGD(m.Weights, m.Classes, labeled, 1.0, maxIter, C, "pa", classWeights, t)
	t.logf("Passive-Aggressive 训练完成: C=%.2f, iter=%d", C, maxIter)

	samples := toTrainSamples(labeled)
	acc := evalLinearModel(m.Weights, m.Classes, samples)
	t.finishMetrics(acc, acc, acc, len(labeled), len(samples), 0)
	t.setLastSplit(labeled, labeled)
	return m, TrainResult{Accuracy: acc, TrainAccuracy: acc, ValidationAccuracy: acc, NumSamples: len(labeled), TrainSamples: len(samples)}
}

// ── SGD Training Helper ─────────────────────────────────────────────

func trainSGD(W [][FeatureDim + 1]float64, nClasses int, labeled []TrainingSample, lr float64, maxIter int, C float64, loss string, classWeights []float64, t *ModelTrainer) {
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	for iter := 0; iter < maxIter; iter++ {
		if t.IsCancelled() {
			return
		}
		eta := lr * (1.0 - float64(iter)/float64(maxIter)*0.95)
		order := rng.Perm(len(labeled))
		for _, idx := range order {
			s := labeled[idx]
			if s.Label < 0 || int(s.Label) >= nClasses {
				continue
			}

			scores := make([]float64, nClasses)
			for c := 0; c < nClasses; c++ {
				scores[c] = W[c][FeatureDim]
				for d := 0; d < FeatureDim; d++ {
					scores[c] += W[c][d] * s.Features[d]
				}
			}

			trueC := int(s.Label)
			bestWrongC := -1
			bestWrongScore := math.Inf(-1)
			for c := 0; c < nClasses; c++ {
				if c == trueC {
					continue
				}
				if scores[c] > bestWrongScore {
					bestWrongScore = scores[c]
					bestWrongC = c
				}
			}
			if bestWrongC < 0 {
				continue
			}
			margin := scores[trueC] - scores[bestWrongC]
			sampleWeight := 1.0
			if len(classWeights) == nClasses {
				sampleWeight = classWeights[trueC]
				if sampleWeight <= 0 {
					sampleWeight = 1.0
				}
			}

			switch loss {
			case "hinge": // SVM
				if margin < 1.0 {
					step := eta * sampleWeight
					for d := 0; d <= FeatureDim; d++ {
						v := 0.0
						if d == FeatureDim {
							v = 1.0
						} else {
							v = s.Features[d]
						}
						W[trueC][d] += step * v
						W[bestWrongC][d] -= step * v
					}
				}
			case "perceptron":
				if margin <= 0 {
					step := eta * sampleWeight
					for d := 0; d <= FeatureDim; d++ {
						v := 0.0
						if d == FeatureDim {
							v = 1.0
						} else {
							v = s.Features[d]
						}
						W[trueC][d] += step * v
						W[bestWrongC][d] -= step * v
					}
				}
			case "pa":
				if margin < 1.0 {
					normSq := 0.0
					for d := 0; d < FeatureDim; d++ {
						normSq += s.Features[d] * s.Features[d]
					}
					normSq += 1.0 // bias
					tau := (1.0 - margin) / (normSq + 1.0/(2*C))
					tau *= sampleWeight
					for d := 0; d <= FeatureDim; d++ {
						v := 0.0
						if d == FeatureDim {
							v = 1.0
						} else {
							v = s.Features[d]
						}
						W[trueC][d] += tau * v
						W[bestWrongC][d] -= tau * v
					}
				}
			}
		}
	}
}

func ridgeFit(W [][FeatureDim + 1]float64, nClasses int, labeled []TrainingSample, alpha float64) {
	_ = len(labeled)
	// One-vs-rest: for each class, solve (X^T X + αI) w = X^T y using SGD approximation
	// Simplified: iterative ridge via SGD
	for c := 0; c < nClasses; c++ {
		for iter := 0; iter < 500; iter++ {
			lr := 0.01 * (1.0 - float64(iter)/500.0*0.9)
			for _, s := range labeled {
				target := 0.0
				if int(s.Label) == c {
					target = 1.0
				}
				dot := W[c][FeatureDim]
				for d := 0; d < FeatureDim; d++ {
					dot += W[c][d] * s.Features[d]
				}
				err := dot - target
				for d := 0; d < FeatureDim; d++ {
					W[c][d] -= lr * (err*s.Features[d] + 2*alpha*W[c][d])
				}
				W[c][FeatureDim] -= lr * err
			}
		}
	}
}

// ---- merged from trainer_more.go ----

// ── Naive Bayes ────────────────────────────────────────────────────

func (t *ModelTrainer) trainNaiveBayes(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < 10 {
		return nil, TrainResult{Error: "need >=10 labeled samples"}
	}

	m := NewNaiveBayes()
	m.Means = make([][FeatureDim]float64, m.Classes)
	m.Vars = make([][FeatureDim]float64, m.Classes)
	m.Priors = make([]float64, m.Classes)
	counts := make([]int, m.Classes)

	for _, s := range labeled {
		if s.Label < 0 || int(s.Label) >= m.Classes {
			continue
		}
		c := s.Label
		counts[c]++
		for d := 0; d < FeatureDim; d++ {
			m.Means[c][d] += s.Features[d]
		}
	}
	n := float64(len(labeled))
	nonEmptyClasses := 0
	for _, count := range counts {
		if count > 0 {
			nonEmptyClasses++
		}
	}
	for c := 0; c < m.Classes; c++ {
		if counts[c] > 0 {
			if cfg.BalanceClasses && nonEmptyClasses > 0 {
				m.Priors[c] = 1.0 / float64(nonEmptyClasses)
			} else {
				m.Priors[c] = float64(counts[c]) / n
			}
			for d := 0; d < FeatureDim; d++ {
				m.Means[c][d] /= float64(counts[c])
			}
		}
	}
	// Compute variances
	for _, s := range labeled {
		if s.Label < 0 || int(s.Label) >= m.Classes {
			continue
		}
		c := s.Label
		for d := 0; d < FeatureDim; d++ {
			diff := s.Features[d] - m.Means[c][d]
			m.Vars[c][d] += diff * diff
		}
	}
	for c := 0; c < m.Classes; c++ {
		if counts[c] > 1 {
			for d := 0; d < FeatureDim; d++ {
				m.Vars[c][d] /= float64(counts[c] - 1)
			}
		}
	}

	t.logf("Naive Bayes 训练完成: classes=%d", m.Classes)
	acc := evalModelLabeled(m, labeled)
	t.finishMetrics(acc, acc, acc, len(labeled), len(labeled), 0)
	t.setLastSplit(labeled, labeled)
	return m, TrainResult{Accuracy: acc, TrainAccuracy: acc, ValidationAccuracy: acc, NumSamples: len(labeled), TrainSamples: len(labeled)}
}

// ── Nearest Centroid ───────────────────────────────────────────────

func (t *ModelTrainer) trainNearestCentroid(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < 10 {
		return nil, TrainResult{Error: "need >=10 labeled samples"}
	}

	trainSet, valSet, _, _, err := prepareAutoTuneSplit(labeled, cfg.ValidationSplitRatio)
	if err != nil {
		return nil, TrainResult{Error: err.Error()}
	}

	metric := "euclidean"
	switch cfg.MaxDepth {
	case 4:
		metric = "cosine"
	case 12:
		metric = "manhattan"
	}

	m := NewNearestCentroid(metric, cfg.BalanceClasses)
	m.Classes = 4
	m.Centroids = make([][FeatureDim]float64, m.Classes)
	m.Priors = make([]float64, m.Classes)
	counts := make([]int, m.Classes)
	for _, s := range trainSet {
		if s.label < 0 || int(s.label) >= m.Classes {
			continue
		}
		c := int(s.label)
		counts[c]++
		for d := 0; d < FeatureDim; d++ {
			m.Centroids[c][d] += s.features[d]
		}
	}
	nonEmptyClasses := 0
	for _, count := range counts {
		if count > 0 {
			nonEmptyClasses++
		}
	}
	for c := 0; c < m.Classes; c++ {
		if counts[c] > 0 {
			for d := 0; d < FeatureDim; d++ {
				m.Centroids[c][d] /= float64(counts[c])
			}
		}
		if cfg.BalanceClasses && nonEmptyClasses > 0 {
			if counts[c] > 0 {
				m.Priors[c] = 1.0 / float64(nonEmptyClasses)
			}
		} else if len(trainSet) > 0 {
			m.Priors[c] = float64(counts[c]) / float64(len(trainSet))
		}
	}

	trainAcc := evalModelSamples(m, trainSet)
	valAcc := evalModelSamples(m, valSet)
	t.logf("Nearest Centroid 训练完成: metric=%s, balanced=%t", metric, cfg.BalanceClasses)
	t.finishMetrics(valAcc, trainAcc, valAcc, len(labeled), len(trainSet), len(valSet))
	t.setLastSplit(toTrainingSamples(trainSet), toTrainingSamples(valSet))
	return m, TrainResult{Accuracy: valAcc, TrainAccuracy: trainAcc, ValidationAccuracy: valAcc, NumSamples: len(labeled), TrainSamples: len(trainSet), ValidationSamples: len(valSet)}
}

// ── Extra Trees ────────────────────────────────────────────────────

func (t *ModelTrainer) trainExtraTrees(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < cfg.MinSamplesLeaf*10 {
		return nil, TrainResult{Error: "insufficient labeled samples"}
	}

	samples := make([]trainSample, len(labeled))
	for i, s := range labeled {
		samples[i] = trainSample{features: s.Features, label: s.Label}
	}
	trainSet, valSet, _, _, _ := prepareAutoTuneSplit(labeled, cfg.ValidationSplitRatio)

	nt := cfg.NumTrees
	if nt < 1 {
		nt = 31
	}
	md := cfg.MaxDepth
	if md < 1 {
		md = 8
	}
	ml := cfg.MinSamplesLeaf
	if ml < 1 {
		ml = 5
	}

	forest := buildExtraTrees(samples, nt, md, ml, time.Now().UnixNano())
	m := &ExtraTreesModel{Forest: forest, NumTrees: nt, MaxDepth: md}

	t.logf("Extra Trees 训练完成: trees=%d, depth=%d", nt, md)
	trainAcc := evalModelSamples(m, trainSet)
	valAcc := evalModelSamples(m, valSet)
	t.finishMetrics(valAcc, trainAcc, valAcc, len(labeled), len(trainSet), len(valSet))
	t.setLastSplit(toTrainingSamples(trainSet), toTrainingSamples(valSet))
	return m, TrainResult{Accuracy: valAcc, TrainAccuracy: trainAcc, ValidationAccuracy: valAcc, NumSamples: len(labeled), TrainSamples: len(trainSet), ValidationSamples: len(valSet)}
}

// ── AdaBoost ───────────────────────────────────────────────────────

func (t *ModelTrainer) trainAdaBoost(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < 10 {
		return nil, TrainResult{Error: "need >=10 labeled samples"}
	}

	nEst := cfg.NumTrees
	if nEst < 10 {
		nEst = 50
	}
	m := NewAdaBoost(nEst)

	samples := make([]trainSample, len(labeled))
	for i, s := range labeled {
		samples[i] = trainSample{features: s.Features, label: s.Label}
	}

	n := len(samples)
	weights := make([]float64, n)
	for i := range weights {
		weights[i] = 1.0 / float64(n)
	}
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))

	for e := 0; e < nEst; e++ {
		t.progress = float64(e) / float64(nEst)
		if t.IsCancelled() {
			return nil, TrainResult{Error: "cancelled"}
		}

		// Weighted sampling
		cum := make([]float64, n)
		cum[0] = weights[0]
		for i := 1; i < n; i++ {
			cum[i] = cum[i-1] + weights[i]
		}
		totalW := cum[n-1]

		// Find best stump: sample a few random features and thresholds
		bestStump := adaboostStump{Feature: -1}
		bestErr := 1e9
		for tries := 0; tries < 50; tries++ {
			fi := rng.Intn(FeatureDim)
			si := rng.Intn(n)
			thresh := samples[si].features[fi]

			var leftErr, rightErr, leftW, rightW float64
			for i, s := range samples {
				if s.features[fi] < thresh {
					if s.label != 1 {
						leftErr += weights[i]
					}
					leftW += weights[i]
				} else {
					if s.label != 0 {
						rightErr += weights[i]
					}
					rightW += weights[i]
				}
			}
			err := (leftErr + rightErr) / totalW
			if err < bestErr {
				bestErr = err
				bestStump = adaboostStump{
					Feature: fi, Threshold: thresh,
					LeftVote: float64(1), RightVote: float64(0),
				}
				if leftErr/leftW > rightErr/rightW {
					bestStump.LeftVote = 0
					bestStump.RightVote = 1
				}
			}
		}
		if bestStump.Feature < 0 {
			continue
		}

		// Compute alpha
		err := math.Max(bestErr, 1e-10)
		alpha := 0.5 * math.Log((1-err)/err)
		if alpha <= 0 {
			continue
		}

		// Update weights
		for i, s := range samples {
			pred := 0
			if s.features[bestStump.Feature] < bestStump.Threshold {
				pred = int(bestStump.LeftVote)
			} else {
				pred = int(bestStump.RightVote)
			}
			if pred != int(s.label) {
				weights[i] *= math.Exp(alpha)
			}
		}

		m.Stumps = append(m.Stumps, bestStump)
		m.Alphas = append(m.Alphas, alpha)
	}

	t.logf("AdaBoost 训练完成: estimators=%d", len(m.Stumps))
	acc := evalModelSamples(m, samples)
	t.finishMetrics(acc, acc, acc, len(labeled), len(samples), 0)
	t.setLastSplit(labeled, labeled)
	return m, TrainResult{Accuracy: acc, TrainAccuracy: acc, ValidationAccuracy: acc, NumSamples: len(labeled), TrainSamples: len(samples)}
}

// ── Ensemble ───────────────────────────────────────────────────────

func (t *ModelTrainer) trainEnsemble(store *TrainingDataStore, cfg MLConfig) (Model, TrainResult) {
	t.acquire()
	defer t.release()
	t.ResetCancel()
	t.isRunning = true
	t.progress = 0
	defer func() { t.isRunning = false; t.progress = 1.0 }()

	labeled := store.LabeledSamples()
	if len(labeled) < 10 {
		return nil, TrainResult{Error: "need >=10 labeled samples"}
	}

	model := buildEnsembleFromStore(store)
	if model == nil {
		return nil, TrainResult{Error: "failed to build ensemble"}
	}

	samples := toTrainSamples(labeled)
	acc := evalModelSamples(model, samples)
	t.logf("Ensemble 训练完成: voting=%s, models=%d", model.Voting, len(model.Models))
	t.finishMetrics(acc, acc, acc, len(labeled), len(samples), 0)
	t.setLastSplit(labeled, labeled)
	return model, TrainResult{Accuracy: acc, TrainAccuracy: acc, ValidationAccuracy: acc, NumSamples: len(labeled), TrainSamples: len(samples)}
}

// ---- merged from trainer_tree.go ----

// buildTree recursively builds a decision tree using Gini impurity
func buildTree(samples []trainSample, depth, maxDepth, minSamplesLeaf, featureSampleCount int, rng *rand.Rand) []DecisionNode {
	if depth >= maxDepth || len(samples) < minSamplesLeaf*2 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	allSame := true
	firstLabel := samples[0].label
	for _, s := range samples[1:] {
		if s.label != firstLabel {
			allSame = false
			break
		}
	}
	if allSame {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: float32(firstLabel)}}
	}

	best := findBestSplit(samples, featureSampleCount, rng)
	if best.giniGain <= 0 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	var leftSamples, rightSamples []trainSample
	for _, s := range samples {
		if s.features[best.featureIdx] < best.threshold {
			leftSamples = append(leftSamples, s)
		} else {
			rightSamples = append(rightSamples, s)
		}
	}

	if len(leftSamples) == 0 || len(rightSamples) == 0 {
		return []DecisionNode{{LeftChild: -1, RightChild: -1, LeafValue: majorityClass(samples)}}
	}

	leftNodes := buildTree(leftSamples, depth+1, maxDepth, minSamplesLeaf, featureSampleCount, rng)
	rightNodes := buildTree(rightSamples, depth+1, maxDepth, minSamplesLeaf, featureSampleCount, rng)

	leftOffset := 1
	rightOffset := 1 + len(leftNodes)

	for i := range leftNodes {
		n := &leftNodes[i]
		if !n.IsLeaf() {
			n.LeftChild += int16(leftOffset)
			n.RightChild += int16(leftOffset)
		}
	}
	for i := range rightNodes {
		n := &rightNodes[i]
		if !n.IsLeaf() {
			n.LeftChild += int16(rightOffset)
			n.RightChild += int16(rightOffset)
		}
	}

	root := DecisionNode{
		FeatureIndex: uint8(best.featureIdx),
		Threshold:    float32(best.threshold),
		LeftChild:    int16(leftOffset),
		RightChild:   int16(rightOffset),
		LeafValue:    0,
	}

	nodes := []DecisionNode{root}
	nodes = append(nodes, leftNodes...)
	nodes = append(nodes, rightNodes...)

	return nodes
}

// findBestSplit finds the best feature and threshold using Gini impurity
func findBestSplit(samples []trainSample, featureSampleCount int, rng *rand.Rand) splitPoint {
	best := splitPoint{giniGain: -1}
	parentGini := giniImpurity(samples)

	features := make([]int, FeatureDim)
	for i := range features {
		features[i] = i
	}
	rng.Shuffle(len(features), func(i, j int) { features[i], features[j] = features[j], features[i] })
	selectedFeatures := features[:featureSampleCount]

	for _, fi := range selectedFeatures {
		sort.Slice(samples, func(i, j int) bool {
			return samples[i].features[fi] < samples[j].features[fi]
		})

		for i := 1; i < len(samples); i++ {
			if samples[i].features[fi] == samples[i-1].features[fi] {
				continue
			}
			threshold := (samples[i].features[fi] + samples[i-1].features[fi]) / 2.0

			leftSamples := samples[:i]
			rightSamples := samples[i:]

			if len(leftSamples) < 1 || len(rightSamples) < 1 {
				continue
			}

			leftWeight := float64(len(leftSamples)) / float64(len(samples))
			gain := parentGini - leftWeight*giniImpurity(leftSamples) -
				(1-leftWeight)*giniImpurity(rightSamples)

			if gain > best.giniGain {
				best = splitPoint{
					featureIdx: fi,
					threshold:  threshold,
					giniGain:   gain,
				}
			}
		}
	}
	return best
}

// giniImpurity computes Gini impurity for a set of samples
func giniImpurity(samples []trainSample) float64 {
	if len(samples) == 0 {
		return 0
	}
	counts := make(map[int32]float64)
	for _, s := range samples {
		counts[s.label]++
	}
	var impurity float64
	n := float64(len(samples))
	for _, c := range counts {
		p := c / n
		impurity += p * (1 - p)
	}
	return impurity
}

// majorityClass returns the most common class label as float32
func majorityClass(samples []trainSample) float32 {
	if len(samples) == 0 {
		return 0
	}
	counts := make(map[int32]int)
	for _, s := range samples {
		counts[s.label]++
	}
	best := int32(0)
	bestCount := 0
	for label, count := range counts {
		if count > bestCount {
			bestCount = count
			best = label
		}
	}
	return float32(best)
}

// classStratifiedBootstrap creates a bootstrap sample where each class
// is proportionally represented. Minority classes are upsampled to ensure
// they appear in every tree's training set.
func classStratifiedBootstrap(src, dst []trainSample, rng *rand.Rand) {
	groups := make(map[int32][]trainSample)
	for _, s := range src {
		groups[s.label] = append(groups[s.label], s)
	}

	nClasses := len(groups)
	if nClasses == 0 {
		return
	}
	perClass := len(dst) / nClasses
	if perClass < 1 {
		perClass = 1
	}

	i := 0
	for i < len(dst) {
		for _, group := range groups {
			if i >= len(dst) {
				break
			}
			dst[i] = group[rng.Intn(len(group))]
			i++
		}
	}
}

func evaluateForest(forest *DecisionForest, testSet []trainSample) float64 {
	if len(testSet) == 0 {
		return 1.0
	}
	correct := 0
	for _, s := range testSet {
		pred := forest.Predict(s.features)
		if pred.Action == s.label {
			correct++
		}
	}
	return float64(correct) / float64(len(testSet))
}

// ---- merged from trainer_types.go ----

// TrainingLogEntry is a single timestamped log line during training
type TrainingLogEntry struct {
	Timestamp time.Time
	Message   string
}

// TrainingHistoryEntry records metrics from a single training run
type TrainingHistoryEntry struct {
	Timestamp            time.Time `json:"timestamp"`
	Accuracy             float64   `json:"accuracy"`
	TrainAccuracy        float64   `json:"trainAccuracy,omitempty"`
	ValidationAccuracy   float64   `json:"validationAccuracy,omitempty"`
	NumTrees             int       `json:"numTrees"`
	NumSamples           int       `json:"numSamples"`
	TrainSamples         int       `json:"trainSamples,omitempty"`
	ValidationSamples    int       `json:"validationSamples,omitempty"`
	ValidationSplitRatio float64   `json:"validationSplitRatio,omitempty"`
	LLMScoredSamples     int       `json:"llmScoredSamples,omitempty"`
	LLMAverageRiskScore  float64   `json:"llmAverageRiskScore,omitempty"`
	LLMAgreement         float64   `json:"llmAgreement,omitempty"`
	Duration             float64   `json:"duration"` // seconds
}

// ModelTrainer builds and evaluates random forest models
type ModelTrainer struct {
	mu                 chan struct{} // single-training mutex via channel
	cancelCh           chan struct{} // closed to request cancellation
	isRunning          bool
	progress           float64
	lastError          string
	lastTrain          time.Time
	accuracy           float64
	trainAccuracy      float64
	validationAccuracy float64
	validationRatio    float64
	// Training log ring buffer
	logMu      sync.RWMutex
	logs       []TrainingLogEntry
	logMaxSize int
	logNext    int
	logTotal   int
	// Training history
	historyMu             sync.RWMutex
	history               []TrainingHistoryEntry
	splitMu               sync.RWMutex
	lastTrainSamples      []TrainingSample
	lastValidationSamples []TrainingSample
	lastLLMReview         *LLMReviewSummary
}

// TrainResult holds the outcome of a training run
type TrainResult struct {
	Accuracy            float64
	TrainAccuracy       float64
	ValidationAccuracy  float64
	NumTrees            int
	NumSamples          int
	TrainSamples        int
	ValidationSamples   int
	LLMScoredSamples    int
	LLMAverageRiskScore float64
	LLMAgreement        float64
	Error               string
}

// splitPoint represents a candidate feature split during training
type splitPoint struct {
	featureIdx int
	threshold  float64
	giniGain   float64
}

// trainSample labels are [0,3] for ALLOW/BLOCK/REWRITE/ALERT
type trainSample struct {
	features [FeatureDim]float64
	label    int32
}

var globalTrainer = &ModelTrainer{
	mu:         make(chan struct{}, 1),
	cancelCh:   make(chan struct{}),
	logMaxSize: 200,
}

// CancelTraining signals any running training to stop.
func (t *ModelTrainer) CancelTraining() {
	if t.isRunning {
		t.logf("训练中止请求已接收")
		close(t.cancelCh)
	}
}

// IsCancelled returns true if cancellation has been requested.
func (t *ModelTrainer) IsCancelled() bool {
	select {
	case <-t.cancelCh:
		return true
	default:
		return false
	}
}

// ResetCancel prepares a new cancel channel for the next training run.
func (t *ModelTrainer) ResetCancel() {
	t.cancelCh = make(chan struct{})
}

func (t *ModelTrainer) logf(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	log.Printf("[ML-Train] %s", msg)

	t.logMu.Lock()
	entry := TrainingLogEntry{Timestamp: time.Now(), Message: msg}
	if len(t.logs) < t.logMaxSize {
		t.logs = append(t.logs, entry)
	} else {
		t.logs[t.logNext] = entry
	}
	t.logNext = (t.logNext + 1) % t.logMaxSize
	t.logTotal++
	t.logMu.Unlock()
}

// GetLogs returns recent training log entries (newest last)
func (t *ModelTrainer) GetLogs(limit int) []TrainingLogEntry {
	t.logMu.RLock()
	defer t.logMu.RUnlock()

	n := len(t.logs)
	if limit <= 0 || limit > n {
		limit = n
	}
	if n == 0 {
		return nil
	}
	out := make([]TrainingLogEntry, limit)
	copy(out, t.logs[max(0, n-limit):])
	return out
}

// GetHistory returns training history entries
func (t *ModelTrainer) GetHistory() []TrainingHistoryEntry {
	t.historyMu.RLock()
	defer t.historyMu.RUnlock()
	out := make([]TrainingHistoryEntry, len(t.history))
	copy(out, t.history)
	return out
}

// addHistory records a training run to history
func (t *ModelTrainer) addHistory(entry TrainingHistoryEntry) {
	t.historyMu.Lock()
	defer t.historyMu.Unlock()
	t.history = append(t.history, entry)
	if len(t.history) > 100 {
		t.history = t.history[len(t.history)-100:]
	}
}

func (t *ModelTrainer) setLastSplit(trainSamples, validationSamples []TrainingSample) {
	t.splitMu.Lock()
	defer t.splitMu.Unlock()

	t.lastTrainSamples = append(t.lastTrainSamples[:0], trainSamples...)
	t.lastValidationSamples = append(t.lastValidationSamples[:0], validationSamples...)
}

func (t *ModelTrainer) setLastLLMReview(review *LLMReviewSummary) {
	t.splitMu.Lock()
	defer t.splitMu.Unlock()

	if review == nil {
		t.lastLLMReview = nil
		return
	}
	copyReview := *review
	t.lastLLMReview = &copyReview
}

func (t *ModelTrainer) LastValidationSamples() []TrainingSample {
	t.splitMu.RLock()
	defer t.splitMu.RUnlock()

	out := make([]TrainingSample, len(t.lastValidationSamples))
	copy(out, t.lastValidationSamples)
	return out
}

func (t *ModelTrainer) LastTrainSamples() []TrainingSample {
	t.splitMu.RLock()
	defer t.splitMu.RUnlock()

	out := make([]TrainingSample, len(t.lastTrainSamples))
	copy(out, t.lastTrainSamples)
	return out
}

func (t *ModelTrainer) LastLLMReview() *LLMReviewSummary {
	t.splitMu.RLock()
	defer t.splitMu.RUnlock()

	if t.lastLLMReview == nil {
		return nil
	}
	copyReview := *t.lastLLMReview
	return &copyReview
}

func (t *ModelTrainer) SplitMetrics() (trainAccuracy, validationAccuracy, validationRatio float64, trainSamples, validationSamples int) {
	t.splitMu.RLock()
	defer t.splitMu.RUnlock()

	return t.trainAccuracy, t.validationAccuracy, t.validationRatio, len(t.lastTrainSamples), len(t.lastValidationSamples)
}

// GetStatus returns training status for the API
func (t *ModelTrainer) GetStatus() map[string]interface{} {
	return map[string]interface{}{
		"isRunning": t.isRunning,
		"progress":  t.progress,
		"lastError": t.lastError,
		"lastTrain": t.lastTrain.Format(time.RFC3339),
		"accuracy":  t.accuracy,
	}
}

// mlReasoning builds a human-readable explanation of the ML prediction
func mlReasoning(pred Prediction, anomalyScore float64, classification *pb.BehaviorClassification) string {
	parts := make([]string, 0, 3)

	if pred.Confidence >= 0.85 {
		parts = append(parts, "high-confidence ML prediction")
	} else if pred.Confidence >= 0.60 {
		parts = append(parts, "moderate-confidence ML prediction")
	} else {
		parts = append(parts, "low-confidence ML prediction")
	}

	parts = append(parts, "action="+actionLabel[pred.Action])

	if anomalyScore > 0.7 {
		parts = append(parts, "highly anomalous")
	} else if anomalyScore > 0.3 {
		parts = append(parts, "moderately anomalous")
	} else {
		parts = append(parts, "behavior within normal range")
	}

	if classification != nil && classification.PrimaryCategory != "" {
		parts = append(parts, "category="+classification.PrimaryCategory)
	}

	return strings.Join(parts, "; ")
}

