// ---- merged from types_cluster.go ----

const (
	clusterTargetLocal    = "local"
	clusterTargetHeader   = "X-Cluster-Target"
	clusterProxyHeader    = "X-Cluster-Proxy"
	clusterAccountHeader  = "X-Cluster-Account"
	clusterPasswordHeader = "X-Cluster-Password"
	clusterHeartbeatEvery = 5 * time.Second
	clusterOfflineAfter   = 15 * time.Second
	clusterVersion        = "1.0.0"
)

type ClusterRole string

const (
	ClusterRoleMaster ClusterRole = "master"
	ClusterRoleSlave  ClusterRole = "slave"
)

type ClusterConfig struct {
	Role      ClusterRole
	MasterURL string
	NodeURL   string
	NodeID    string
	NodeName  string
	Account   string
	Password  string
	Hostname  string
}

type ClusterNode struct {
	ID       string      `json:"id"`
	Name     string      `json:"name"`
	URL      string      `json:"url"`
	Role     ClusterRole `json:"role"`
	Status   string      `json:"status"`
	LastSeen time.Time   `json:"lastSeen"`
	IsLocal  bool        `json:"isLocal"`
	Version  string      `json:"version,omitempty"`
}

type ClusterStateResponse struct {
	Role               ClusterRole `json:"role"`
	MasterURL          string      `json:"masterUrl,omitempty"`
	NodeURL            string      `json:"nodeUrl"`
	NodeID             string      `json:"nodeId"`
	NodeName           string      `json:"nodeName"`
	AccountConfigured  bool        `json:"accountConfigured"`
	PasswordConfigured bool        `json:"passwordConfigured"`
	LocalNode          ClusterNode `json:"localNode"`
}

type ClusterNodesResponse struct {
	Nodes []ClusterNode `json:"nodes"`
}

type ClusterHeartbeatRequest struct {
	NodeID   string      `json:"nodeId"`
	NodeName string      `json:"nodeName"`
	NodeURL  string      `json:"nodeUrl"`
	Role     ClusterRole `json:"role"`
	Version  string      `json:"version,omitempty"`
}

type ClusterHeartbeatResponse struct {
	OK         bool        `json:"ok"`
	ReceivedAt time.Time   `json:"receivedAt"`
	Registered ClusterNode `json:"registered"`
}

type clusterManager struct {
	mu         sync.RWMutex
	config     ClusterConfig
	nodes      map[string]*ClusterNode
	proxyCache map[string]*httputil.ReverseProxy
}

var clusterManagerStore = newClusterManager(loadClusterConfigFromEnv())

func loadClusterConfigFromEnv() ClusterConfig {
	role := ClusterRoleMaster
	masterURL := strings.TrimSpace(os.Getenv("AGENT_CLUSTER_MASTER_URL"))
	account := strings.TrimSpace(os.Getenv("AGENT_CLUSTER_ACCOUNT"))
	password := strings.TrimSpace(os.Getenv("AGENT_CLUSTER_PASSWORD"))
	if masterURL != "" && account != "" && password != "" {
		role = ClusterRoleSlave
	}

	hostname, _ := os.Hostname()

	return ClusterConfig{
		Role:      role,
		MasterURL: normalizeClusterURL(masterURL),
		NodeURL:   normalizeClusterURL(strings.TrimSpace(os.Getenv("AGENT_CLUSTER_NODE_URL"))),
		NodeID:    strings.TrimSpace(os.Getenv("AGENT_CLUSTER_NODE_ID")),
		NodeName:  strings.TrimSpace(os.Getenv("AGENT_CLUSTER_NODE_NAME")),
		Account:   account,
		Password:  password,
		Hostname:  hostname,
	}
}

func normalizeClusterURL(raw string) string {
	raw = strings.TrimSpace(raw)
	return strings.TrimRight(raw, "/")
}

func newClusterManager(config ClusterConfig) *clusterManager {
	return &clusterManager{
		config:     config,
		nodes:      make(map[string]*ClusterNode),
		proxyCache: make(map[string]*httputil.ReverseProxy),
	}
}

func (m *clusterManager) ConfigurePort(port int) {
	if port <= 0 {
		return
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	if m.config.NodeURL == "" {
		m.config.NodeURL = fmt.Sprintf("http://127.0.0.1:%d", port)
	}
	if m.config.NodeID == "" {
		host := sanitizeClusterHostname(m.config.Hostname)
		if host == "" {
			host = "node"
		}
		m.config.NodeID = fmt.Sprintf("%s-%d", host, port)
	}
	if m.config.NodeName == "" {
		if m.config.Hostname != "" {
			m.config.NodeName = m.config.Hostname
		} else {
			m.config.NodeName = m.config.NodeID
		}
	}

	m.nodes[m.config.NodeID] = &ClusterNode{
		ID:       m.config.NodeID,
		Name:     m.config.NodeName,
		URL:      m.config.NodeURL,
		Role:     m.config.Role,
		Status:   "online",
		LastSeen: time.Now().UTC(),
		IsLocal:  true,
		Version:  clusterVersion,
	}
}

func sanitizeClusterHostname(host string) string {
	host = strings.TrimSpace(host)
	host = strings.ToLower(host)
	if host == "" {
		return ""
	}
	var b strings.Builder
	for _, r := range host {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		case r == '-' || r == '_':
			b.WriteRune(r)
		default:
			b.WriteRune('-')
		}
	}
	return strings.Trim(b.String(), "-_")
}

func (m *clusterManager) ConfigSnapshot() ClusterConfig {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.config
}

func (m *clusterManager) Role() ClusterRole {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if m.config.Role == "" {
		return ClusterRoleMaster
	}
	return m.config.Role
}

func (m *clusterManager) IsMaster() bool {
	return m.Role() == ClusterRoleMaster
}

func (m *clusterManager) IsSlave() bool {
	return m.Role() == ClusterRoleSlave
}

func (m *clusterManager) localNodeLocked() ClusterNode {
	return ClusterNode{
		ID:       m.config.NodeID,
		Name:     m.config.NodeName,
		URL:      m.config.NodeURL,
		Role:     m.config.Role,
		Status:   "online",
		LastSeen: time.Now().UTC(),
		IsLocal:  true,
		Version:  clusterVersion,
	}
}

func (m *clusterManager) LocalNode() ClusterNode {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.localNodeLocked()
}

func (m *clusterManager) StateSnapshot() ClusterStateResponse {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return ClusterStateResponse{
		Role:               m.config.Role,
		MasterURL:          m.config.MasterURL,
		NodeURL:            m.config.NodeURL,
		NodeID:             m.config.NodeID,
		NodeName:           m.config.NodeName,
		AccountConfigured:  strings.TrimSpace(m.config.Account) != "",
		PasswordConfigured: strings.TrimSpace(m.config.Password) != "",
		LocalNode:          m.localNodeLocked(),
	}
}

func (m *clusterManager) SnapshotNodes() []ClusterNode {
	m.mu.RLock()
	defer m.mu.RUnlock()

	nodes := make([]ClusterNode, 0, len(m.nodes)+1)
	nodes = append(nodes, m.localNodeLocked())
	for id, node := range m.nodes {
		if node == nil || id == m.config.NodeID {
			continue
		}
		snapshot := *node
		if time.Since(snapshot.LastSeen) > clusterOfflineAfter {
			snapshot.Status = "stale"
		} else {
			snapshot.Status = "online"
		}
		nodes = append(nodes, snapshot)
	}
	sort.Slice(nodes, func(i, j int) bool {
		if nodes[i].IsLocal != nodes[j].IsLocal {
			return nodes[i].IsLocal
		}
		if nodes[i].LastSeen.Equal(nodes[j].LastSeen) {
			return nodes[i].Name < nodes[j].Name
		}
		return nodes[i].LastSeen.After(nodes[j].LastSeen)
	})
	return nodes
}

func (m *clusterManager) upsertHeartbeat(req ClusterHeartbeatRequest) ClusterNode {
	m.mu.Lock()
	defer m.mu.Unlock()

	if req.NodeID == "" {
		req.NodeID = m.config.NodeID
	}
	if req.NodeURL == "" {
		req.NodeURL = m.config.NodeURL
	}
	if req.NodeName == "" {
		req.NodeName = req.NodeID
	}
	node := ClusterNode{
		ID:       req.NodeID,
		Name:     req.NodeName,
		URL:      normalizeClusterURL(req.NodeURL),
		Role:     req.Role,
		Status:   "online",
		LastSeen: time.Now().UTC(),
		IsLocal:  false,
		Version:  req.Version,
	}
	if node.Version == "" {
		node.Version = clusterVersion
	}
	m.nodes[node.ID] = &node
	return node
}

func (m *clusterManager) authMatches(c *gin.Context, requireProxy bool) bool {
	m.mu.RLock()
	account := strings.TrimSpace(m.config.Account)
	password := strings.TrimSpace(m.config.Password)
	m.mu.RUnlock()
	if account == "" || password == "" {
		return false
	}
	if requireProxy && strings.TrimSpace(c.GetHeader(clusterProxyHeader)) == "" {
		return false
	}

	reqAccount := strings.TrimSpace(c.GetHeader(clusterAccountHeader))
	reqPassword := strings.TrimSpace(c.GetHeader(clusterPasswordHeader))
	if reqAccount == "" || reqPassword == "" {
		user, pass, ok := c.Request.BasicAuth()
		if ok {
			reqAccount = strings.TrimSpace(user)
			reqPassword = strings.TrimSpace(pass)
		}
	}
	if reqAccount == "" || reqPassword == "" {
		return false
	}

	return subtle.ConstantTimeCompare([]byte(reqAccount), []byte(account)) == 1 &&
		subtle.ConstantTimeCompare([]byte(reqPassword), []byte(password)) == 1
}

func clusterRequestAuthAllowed(c *gin.Context) bool {
	return clusterManagerStore.authMatches(c, true)
}

func clusterControlAuthAllowed(c *gin.Context) bool {
	return clusterManagerStore.authMatches(c, false)
}

// ---- merged from visualllmparseplugin.go ----

func parseVisualBlocksLLMContent(content string) (*visualBlocksLLMCompileResponse, error) {
	jsonPayload := extractJSONObject(content)
	if jsonPayload == "" {
		return nil, errors.New("LLM response did not contain JSON")
	}

	var raw map[string]any
	if err := json.Unmarshal([]byte(jsonPayload), &raw); err != nil {
		return nil, err
	}

	trigger := normalizeVisualLLMTrigger(extractLLMString(raw, "trigger", "hook", "entry"))
	action := normalizeVisualLLMAction(extractLLMString(raw, "action", "response", "decision"))
	mapMode, mapKey, mapLimit := extractVisualLLMMap(raw)
	warnings := extractLLMStrings(raw, "warnings", "warning", "notes")

	conditionsRaw, ok := raw["conditions"]
	if !ok {
		conditionsRaw = firstPresent(raw, "conditionTree", "logic", "rules")
	}
	conditionCount := 0
	conditions, err := normalizeVisualLLMLogicNode(conditionsRaw, true, 0, &conditionCount)
	if err != nil {
		return nil, err
	}
	if conditionCount == 0 {
		conditions = defaultVisualLLMConditions()
		conditionCount = 1
	}
	if conditionCount > 8 {
		return nil, fmt.Errorf("LLM returned %d conditions; maximum is 8", conditionCount)
	}

	if trigger != "socket_connect" && visualLogicTreeUsesField(conditions, "port", "ipv4") {
		return nil, errors.New("LLM returned port/ipv4 conditions for a non-socket trigger")
	}
	if trigger == "unlink" && action == "BLOCK" {
		action = "ALERT"
		warnings = append(warnings, "unlink 走 kprobe/do_unlinkat，不能直接返回 EACCES，已将 BLOCK 调整为 ALERT")
	}
	if trigger == "unlink" && visualLogicTreeUsesField(conditions, "basename") {
		return nil, errors.New("LLM returned basename condition for unlink, but unlink kprobe has no safe basename context in this UI")
	}

	return &visualBlocksLLMCompileResponse{
		Trigger:    trigger,
		Action:     action,
		Conditions: conditions,
		MapMode:    mapMode,
		MapKey:     mapKey,
		MapLimit:   mapLimit,
		Reasoning:  strings.TrimSpace(extractLLMString(raw, "reasoning", "explanation", "analysis")),
		Warnings:   compactStrings(warnings, 6),
	}, nil
}

func firstPresent(raw map[string]any, keys ...string) any {
	for _, key := range keys {
		if val, ok := raw[key]; ok {
			return val
		}
	}
	return nil
}

func extractVisualLLMMap(raw map[string]any) (string, string, int) {
	mapMode := extractLLMString(raw, "mapMode", "map_mode")
	mapKey := extractLLMString(raw, "mapKey", "map_key")
	mapLimit := int(extractLLMFloat(raw, "mapLimit", "map_limit", "limit"))
	if nested, ok := raw["map"].(map[string]any); ok {
		if mapMode == "" {
			mapMode = extractLLMString(nested, "mode", "mapMode", "map_mode")
		}
		if mapKey == "" {
			mapKey = extractLLMString(nested, "key", "mapKey", "map_key")
		}
		if mapLimit == 0 {
			mapLimit = int(extractLLMFloat(nested, "limit", "mapLimit", "map_limit"))
		}
	}
	if mapLimit <= 0 {
		mapLimit = 10
	}
	return normalizeVisualLLMMapMode(mapMode), normalizeVisualLLMMapKey(mapKey), clampInt(mapLimit, 1, 100000)
}

func normalizeVisualLLMLogicNode(raw any, root bool, depth int, count *int) (visualBlocksLogicNode, error) {
	if depth > 5 {
		return visualBlocksLogicNode{}, errors.New("LLM condition tree is nested deeper than 5")
	}
	if raw == nil {
		if root {
			return defaultVisualLLMConditions(), nil
		}
		return visualBlocksLogicNode{}, errors.New("condition node is empty")
	}

	switch val := raw.(type) {
	case []any:
		children := make([]visualBlocksLogicNode, 0, len(val))
		for _, childRaw := range val {
			child, err := normalizeVisualLLMLogicNode(childRaw, false, depth+1, count)
			if err != nil {
				return visualBlocksLogicNode{}, err
			}
			children = append(children, child)
		}
		return visualBlocksLogicNode{ID: visualNodeID("group", root, depth, *count), Type: "AND", Children: children}, nil
	case map[string]any:
		typeName := strings.ToUpper(strings.TrimSpace(extractLLMString(val, "type", "kind")))
		if typeName == "" && val["field"] != nil {
			typeName = "CONDITION"
		}
		if typeName == "CONDITION" || val["field"] != nil {
			*count = *count + 1
			field := normalizeVisualLLMConditionField(extractLLMString(val, "field", "key"))
			operator := normalizeVisualLLMOperator(extractLLMString(val, "operator", "op"))
			value := sanitizeVisualLLMValue(valueToVisualString(firstPresent(val, "value", "match", "text")))
			if value == "" {
				return visualBlocksLogicNode{}, fmt.Errorf("condition %d has empty value", *count)
			}
			id := strings.TrimSpace(extractLLMString(val, "id"))
			if id == "" {
				id = fmt.Sprintf("cond-llm-%d", *count)
			}
			return visualBlocksLogicNode{ID: sanitizeVisualNodeID(id, "cond"), Type: "CONDITION", Field: field, Operator: operator, Value: value}, nil
		}

		groupType := "AND"
		if typeName == "OR" || strings.EqualFold(extractLLMString(val, "operator", "op"), "OR") {
			groupType = "OR"
		}
		childrenRaw, ok := firstPresent(val, "children", "conditions", "rules").([]any)
		if !ok || len(childrenRaw) == 0 {
			return visualBlocksLogicNode{}, errors.New("logic group has no children")
		}
		children := make([]visualBlocksLogicNode, 0, len(childrenRaw))
		for _, childRaw := range childrenRaw {
			child, err := normalizeVisualLLMLogicNode(childRaw, false, depth+1, count)
			if err != nil {
				return visualBlocksLogicNode{}, err
			}
			children = append(children, child)
		}
		id := strings.TrimSpace(extractLLMString(val, "id"))
		if id == "" || root {
			id = visualNodeID("group", root, depth, *count)
		}
		if root {
			id = "root"
		}
		return visualBlocksLogicNode{ID: sanitizeVisualNodeID(id, "group"), Type: groupType, Children: children}, nil
	default:
		return visualBlocksLogicNode{}, fmt.Errorf("unsupported condition node shape %T", raw)
	}
}

func normalizeVisualLLMTrigger(value string) string {
	key := strings.ToLower(strings.TrimSpace(value))
	key = strings.TrimPrefix(key, "lsm/")
	key = strings.TrimPrefix(key, "kprobe/")
	key = strings.ReplaceAll(key, "-", "_")
	key = strings.TrimPrefix(key, "sys_")
	if mapped, ok := visualLLMAllowedTriggers[key]; ok {
		return mapped
	}
	for k, mapped := range visualLLMAllowedTriggers {
		if strings.Contains(key, k) {
			return mapped
		}
	}
	return "process"
}

func normalizeVisualLLMAction(value string) string {
	s := strings.ToUpper(strings.TrimSpace(value))
	switch s {
	case "KILL", "SIGKILL", "TERMINATE":
		return "KILL"
	case "ALERT", "AUDIT", "LOG", "ALLOW":
		return "ALERT"
	default:
		return "BLOCK"
	}
}

func normalizeVisualLLMMapMode(value string) string {
	s := strings.ToUpper(strings.TrimSpace(value))
	s = strings.ReplaceAll(s, "-", "_")
	switch s {
	case "COUNTER", "RATE_LIMIT", "RATELIMIT":
		return "COUNTER"
	case "BLOCKLIST", "BLACKLIST", "DENYLIST":
		return "BLOCKLIST"
	default:
		return "NONE"
	}
}

func normalizeVisualLLMMapKey(value string) string {
	s := strings.ToLower(strings.TrimSpace(value))
	switch s {
	case "uid", "user":
		return "uid"
	case "comm", "command", "process", "process_name":
		return "comm"
	default:
		return "pid"
	}
}

func normalizeVisualLLMConditionField(value string) string {
	key := strings.ToLower(strings.TrimSpace(value))
	key = strings.ReplaceAll(key, "-", "_")
	if mapped, ok := visualLLMAllowedConditionFields[key]; ok {
		return mapped
	}
	for k, mapped := range visualLLMAllowedConditionFields {
		if strings.Contains(key, k) {
			return mapped
		}
	}
	return "comm"
}

func normalizeVisualLLMOperator(value string) string {
	s := strings.ToLower(strings.TrimSpace(value))
	s = strings.ReplaceAll(s, "-", "_")
	switch s {
	case "!=", "not_equals", "not_equal", "not", "exclude":
		return "!="
	case "starts_with", "prefix", "begins_with":
		return "starts_with"
	case "ends_with", "suffix":
		return "ends_with"
	default:
		return "=="
	}
}

func valueToVisualString(value any) string {
	switch v := value.(type) {
	case string:
		return v
	case json.Number:
		return v.String()
	case float64:
		if v == float64(int64(v)) {
			return fmt.Sprintf("%d", int64(v))
		}
		return fmt.Sprintf("%g", v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	case nil:
		return ""
	default:
		return fmt.Sprint(v)
	}
}

func sanitizeVisualLLMValue(value string) string {
	value = strings.TrimSpace(value)
	value = strings.ReplaceAll(value, "\x00", "")
	value = strings.NewReplacer("\r", " ", "\n", " ", "\t", " ", "\\", "", "\"", "", "'", "").Replace(value)
	value = strings.Join(strings.Fields(value), " ")
	runes := []rune(value)
	if len(runes) > 64 {
		value = string(runes[:64])
	}
	return value
}

func sanitizeVisualNodeID(id, prefix string) string {
	id = strings.ToLower(strings.TrimSpace(id))
	var b strings.Builder
	for _, r := range id {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' {
			b.WriteRune(r)
		} else if r == '_' || r == ' ' || r == '/' {
			b.WriteByte('-')
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return prefix + "-llm"
	}
	if len(out) > 48 {
		out = out[:48]
	}
	return out
}

func visualNodeID(prefix string, root bool, depth, count int) string {
	if root {
		return "root"
	}
	return fmt.Sprintf("%s-llm-%d-%d", prefix, depth, count)
}

func defaultVisualLLMConditions() visualBlocksLogicNode {
	return visualBlocksLogicNode{
		ID:   "root",
		Type: "AND",
		Children: []visualBlocksLogicNode{
			{ID: "cond-llm-default", Type: "CONDITION", Field: "comm", Operator: "==", Value: "nc"},
		},
	}
}

func visualLogicTreeUsesField(node visualBlocksLogicNode, fields ...string) bool {
	if node.Type == "CONDITION" {
		for _, field := range fields {
			if node.Field == field {
				return true
			}
		}
		return false
	}
	for _, child := range node.Children {
		if visualLogicTreeUsesField(child, fields...) {
			return true
		}
	}
	return false
}

func compactStrings(values []string, limit int) []string {
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
		if limit > 0 && len(out) >= limit {
			break
		}
	}
	return out
}

